window.__DICT_CHUNKS__=window.__DICT_CHUNKS__||{};window.__DICT_CHUNKS__["A"]={"1":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ˌeɪ ˈem/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span></div><div class=\"entry-body\"><div class=\"sense\">(ante meridiem) used to talk about times that are after midnight but before midday → p.m.:</div><ul class=\"examples\"><li><em>Work starts at 9 am.</em></li></ul></div>","2":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧ban‧don</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈbændən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to leave someone, especially someone you are responsible for → abandoned:</div><ul class=\"examples\"><li><em>How could she abandon her own child?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to go away from a place, vehicle etc permanently, especially because the situation makes it impossible for you to stay <em>SYN leave</em> → abandoned:</div><ul class=\"examples\"><li><em>We had to abandon the car and walk the rest of the way.</em></li><li><em>Fearing further attacks, most of the population had abandoned the city.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to stop doing something because there are too many problems and it is impossible to continue:</div><ul class=\"examples\"><li><em>The game had to be abandoned due to bad weather.</em></li><li><em>They abandoned their attempt to recapture the castle.</em></li><li><em>Because of the fog they abandoned their idea of driving.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> to stop having a particular idea, belief, or attitude:</div><ul class=\"examples\"><li><em>They were accused of abandoning their socialist principles.</em></li><li><em>Rescuers had abandoned all hope of finding any more survivors.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>abandon yourself to something</strong> <em>literary</em> to feel an emotion so strongly that you let it control you completely:</div><ul class=\"examples\"><li><em>She abandoned herself to grief.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>abandon ship</strong> to leave a ship because it is sinking</div></div>","3":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ab‧bre‧vi‧ate</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈbriːvieɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to make a word or expression shorter by not including letters or using only the first letter of each word <em>SYN shorten</em></div><ul class=\"examples\"><li><strong><em>be abbreviated to something</strong>: ‘Information technology’ is usually abbreviated to ‘IT’.</em></li></ul></div>","4":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ab‧bre‧vi‧a‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /əˌbriːviˈeɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a short form of a word or expression RegisterIn everyday English, people usually say be short for instead of be the abbreviation of/for:· W.H.O. is short for ‘World Health Organization’.</div><ul class=\"examples\"><li><strong><em>abbreviation of/for</strong>: ‘Dr’ is the written abbreviation of ‘Doctor’.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the act of abbreviating something</div></div>","5":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ab‧do‧men</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæbdəmən, æbˈdəʊ- $ -ˈdoʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the part of your body between your chest and legs which contains your stomach, bowels etc</div><div class=\"sense\"><span class=\"snum\">2</span> the end part of an insect’s body, joined to the thorax</div></div>","6":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧bil‧i‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈbɪləti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\">(plural abilities)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> the state of being able to do something</div><ul class=\"examples\"><li><strong><em>ability to do something</strong>: the ability to walk / The health center serves all patients, regardless of their ability to pay.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> someone’s level of skill at doing something:</div><ul class=\"examples\"><li><em>The test measures your mathematical ability.</em></li><li><em>mixed ability classes</em></li><li><strong><em>of high/low etc ability</strong>: students of average ability / There are musicians of all abilities.</em></li><li><strong><em>somebody&#x27;s abilities as something</strong>: He showed his abilities as a leader.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>to the best of your ability</strong> as well as you can:</div><ul class=\"examples\"><li><em>He completed the job to the best of his ability.</em></li></ul></div>","7":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeɪbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>be able to do something</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to have the skill, strength, knowledge etc needed to do something:</div><ul class=\"examples\"><li><em>I’ve always wanted to be able to speak Japanese.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to be in a situation in which it is possible for you to do something:</div><ul class=\"examples\"><li><em>I’d like to do more gardening, but I never seem able to find the time.</em></li><li><em>I haven’t been able to read that report yet.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> clever or good at doing something:</div><ul class=\"examples\"><li><em>one of my more able students</em></li></ul></div>","8":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ab‧norm‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /æbˈnɔːməl $ -ˈnɔːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">very different from usual in a way that seems strange, worrying, wrong, or dangerous <em>OPP normal</em>:</div><ul class=\"examples\"><li><em>abnormal behaviour</em></li><li><em>an abnormal level of cholesterol</em></li><li><em>My parents thought it was abnormal for a boy to be interested in ballet.</em></li></ul></div>","9":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ab‧nor‧mal‧i‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌæbnɔːˈmæləti $ -nər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural abnormalities)</span></div><div class=\"entry-body\"><div class=\"sense\">an abnormal feature, especially something that is wrong with part of someone’s body:</div><ul class=\"examples\"><li><em>tests that can detect genetic abnormalities in the foetus</em></li></ul></div>","10":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">preposition</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧board</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈbɔːd $ əˈbɔːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">on or onto a ship, plane, or train:</div><ul class=\"examples\"><li><em>They finally went aboard the plane.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> on or onto a ship, plane, or train:</div><ul class=\"examples\"><li><em>The plane crashed, killing all 200 people aboard.</em></li><li><em>The boat swayed as he stepped aboard.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>All aboard!</strong> <em>spoken</em> used to tell passengers of a ship, bus, or train that they must get on because it will leave soon</div></div></div>","11":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧bol‧ish</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈbɒlɪʃ $ əˈbɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to officially end a law, system etc, especially one that has existed for a long time:</div><ul class=\"examples\"><li><em>Slavery was abolished in the US in the 19th century.</em></li></ul></div>","12":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧bor‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈbɔːʃən $ əˈbɔːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[countable, uncountable]</span> a medical operation to end a pregnancy so that the baby is not born alive <em>SYN termination</em>:</div><ul class=\"examples\"><li><em>She decided to have an abortion.</em></li><li><em>anti-abortion campaigners</em></li></ul></div>","13":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">preposition</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧bout</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈbaʊt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> concerning or relating to a particular subject:</div><ul class=\"examples\"><li><em>a book about politics</em></li><li><em>She said something about leaving town.</em></li><li><em>He lied about his age.</em></li><li><em>About that car of yours. How much are you selling it for?</em></li><li><em>What’s he on about (=talking about)?</em></li><li><em>It’s about Tommy, doctor. He’s been sick again.</em></li><li><em>Naturally, my mother wanted to know all about it (=all the details relating to it).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to show why someone is angry, happy, upset etc:</div><ul class=\"examples\"><li><em>I’m really worried about Jack.</em></li><li><em>She’s upset about missing the party.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> in many different directions within a particular place, or in different parts of a place <em>SYN around</em> <em>, round</em>:</div><ul class=\"examples\"><li><em>We spent the whole afternoon walking about town.</em></li><li><em>Books were scattered about the room.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> in the nature or character of a person or thing:</div><ul class=\"examples\"><li><em>There’s something really strange about Liza.</em></li><li><em>What I like about the job is that it’s never boring.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>what/how about somebody/something</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to ask a question that directs attention to another person or thing:</div><ul class=\"examples\"><li><em>What about Jack? We can’t just leave him here.</em></li><li><em>I’m feeling hungry. How about you?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to make a suggestion:</div><ul class=\"examples\"><li><em>How about a salad for lunch?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>do something about something</strong> to do something to solve a problem or stop a bad situation:</div><ul class=\"examples\"><li><em>If we don’t do something about it, the problem is going to get worse.</em></li><li><em>What can be done about the rising levels of pollution?</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> if an organization, a job, an activity etc is about something, that is its basic purpose:</div><ul class=\"examples\"><li><em>Leadership is all about getting your team to co-operate.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>it’s all about somebody/something</strong> used to say who or what is important in a situation:</div><ul class=\"examples\"><li><em>It’s all about money, and who’s got the most.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>while you’re about it</strong> <em>spoken</em> used to tell someone to do something while they are doing something else because it would be easier to do both things at the same time:</div><ul class=\"examples\"><li><em>Go and see what’s the matter, and while you’re about it you can fetch me my sweater.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>what was all that about?</strong> <em>spoken</em> used to ask the reason for something that has just happened, especially someone’s angry behaviour</div><div class=\"sense\"><span class=\"snum\">11</span> <em>literary</em> surrounding a person or thing:</div><ul class=\"examples\"><li><em>Jo sensed fear and jealousy all about her.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (also round about<em>spoken</em>) a little more or less than a particular number, amount, or size <em>SYN roughly</em> <em>, approximately</em>: ► see thesaurus at approximate RegisterIn written English, people usually prefer to use approximately, as it sounds more technical:· The cost to taxpayers is approximately $200 billion.</div><ul class=\"examples\"><li><em>I live about 10 miles away.</em></li><li><em>a tiny computer about as big as a postcard</em></li><li><em>We left the restaurant at round about 10.30.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> in many different directions within a place or in different parts of a place <em>SYN around</em>:</div><ul class=\"examples\"><li><em>People were rushing about, trying to find the driver.</em></li><li><em>Cushions were scattered about on the chairs.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> near to you or in the same place as you:</div><ul class=\"examples\"><li><em>Is Derek about? There’s a phone call for him.</em></li><li><em>Quick! Let’s go while there’s no-one about.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>British English</em> <em>spoken</em> existing or available now:</div><ul class=\"examples\"><li><em>I hope she hasn’t caught flu. There’s a lot of it about.</em></li><li><em>She might get temporary work, but there’s not much about.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>informal</em> almost or probably:</div><ul class=\"examples\"><li><em>I was about ready to leave when somebody rang the doorbell.</em></li><li><em>‘Have you finished?’ ‘Just about.’</em></li><li><em>It’s just about the worst mistake anyone could make.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>that’s about it/all</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to tell someone that you have told them everything you know:</div><ul class=\"examples\"><li><em>He was a quiet chap, married with kids. That’s about it, really.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to say that there is nothing else available:</div><ul class=\"examples\"><li><em>There’s some cheese in the fridge and that’s about it.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> so as to face in the opposite direction <em>SYN around</em>:</div><ul class=\"examples\"><li><em>He quickly turned about and walked away.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>be about to do something</strong> if someone is about to do something, or if something is about to happen, they will do it or it will happen very soon:</div><ul class=\"examples\"><li><em>We were just about to leave when Jerry arrived.</em></li><li><em>Work was about to start on a new factory building.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>not be about to do something</strong> <em>informal</em> used to emphasize that you have no intention of doing something:</div><ul class=\"examples\"><li><em>I’ve never smoked in my life and I’m not about to start now.</em></li></ul></div></div>","14":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧bove</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈbʌv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in a higher position than something else <em>SYN over</em> <em>OPP below</em>:</div><ul class=\"examples\"><li><em>Our office is above the hairdresser’s.</em></li><li><em>He had a bruise just above his left eye.</em></li><li><em>I heard a strange noise coming from the room above.</em></li><li><em>The great bird hovered high above our heads.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> more than a particular number, amount, or level <em>OPP below</em>:</div><ul class=\"examples\"><li><em>50 metres above sea level</em></li><li><strong><em>above freezing/zero</strong> (=higher than the temperature at which water freezes): Tonight, temperatures should be just above freezing.</em></li><li><strong><em>and/or above</strong>: free medical care for pensioners aged 65 and above / Prize winners must have gained marks of 80% or above.</em></li><li><em>The salaries we offer are well above (=much higher than) average.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to a greater degree than something else:</div><ul class=\"examples\"><li><em>Many employers value personality above experience or qualifications.</em></li><li><strong><em>above all (else)</strong> (=used to say that something is more important than anything else): Max is hard-working, cheerful, and above all honest.</em></li><li><em>medals awarded for bravery above and beyond the call of duty (=greater than it is your duty to show)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> louder or clearer than other sounds:</div><ul class=\"examples\"><li><em>You can always hear her voice above everybody else’s.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> higher in rank, power, or importance <em>OPP below</em>:</div><ul class=\"examples\"><li><em>He never rose above the rank of corporal.</em></li><li><strong><em>and/or above</strong>: officers of the rank of Major and above</em></li><li><strong><em>from above</strong> (=from people in higher authority): We just obey orders from above.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <em>formal</em> before, in the same piece of writing <em>OPP below</em>:</div><ul class=\"examples\"><li><em>As mentioned above, there is a service charge.</em></li><li><em>Write to the address above for further information.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>not be above (doing) something</strong> to not be too good or honest to do something:</div><ul class=\"examples\"><li><em>Eileen’s not above flirting with the boss when it suits her.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>be above suspicion/reproach/criticism etc</strong> to be so good that no one can doubt or criticize you:</div><ul class=\"examples\"><li><em>Even the king’s closest advisers were not above suspicion.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>get above yourself</strong> to think you are better or more important than you really are</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[only before noun]</span> used in a piece of writing to refer to something mentioned in an earlier part of the same piece of writing:</div><ul class=\"examples\"><li><em>For the above reasons, the management has no choice but to close the factory.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the above</strong> <em>formal</em> something mentioned before in the same piece of writing:</div><ul class=\"examples\"><li><em>If none of the above applies to you, you may be able to reclaim tax.</em></li></ul></div></div>","15":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧broad</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈbrɔːd $ əˈbrɒːd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in or to a foreign country:</div><ul class=\"examples\"><li><em>I’ve never lived abroad before.</em></li><li><em>She often goes abroad on business.</em></li><li><em>We never travelled abroad when we were kids.</em></li><li><em>A lot of goods are imported from abroad.</em></li><li><em>The books about Harry Potter have been very popular, both at home and abroad.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> if a feeling, piece of news etc is abroad, a lot of people feel it or know about it:</div><ul class=\"examples\"><li><em>There were rumours abroad that she was planning to resign.</em></li></ul></div>","16":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧brupt</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈbrʌpt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> sudden and unexpected:</div><ul class=\"examples\"><li><em>an abrupt change of plan</em></li><li><strong><em>come to an abrupt end/halt etc</strong>: The bus came to an abrupt halt.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> seeming rude and unfriendly, especially because you do not waste time in friendly conversation:</div><ul class=\"examples\"><li><em>Sorry, I didn’t mean to be so abrupt.</em></li></ul></div>","17":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧brupt‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈbrʌptli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> suddenly and unexpectedly:</div><ul class=\"examples\"><li><em>She stopped abruptly and looked at him.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in a way that seems rude and unfriendly:</div><ul class=\"examples\"><li><em>He spoke abruptly, as if he wanted to avoid the subject.</em></li></ul></div>","18":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ab‧sence</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæbsəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> when you are not in the place where people expect you to be, or the time that you are away</div><ul class=\"examples\"><li><strong><em>in/during somebody’s absence</strong>: Ms Leighton will be in charge during my absence (=while I am away).</em></li><li><strong><em>absence from</strong>: Her work involved repeated absences from home.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular]</span> the lack of something or the fact that it does not exist <em>OPP presence</em></div><ul class=\"examples\"><li><strong><em>absence of</strong>: a complete absence of any kind of planning</em></li><li><em>In the absence of any evidence, the police had to let Myers go.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>absence makes the heart grow fonder</strong> used to say that being away from someone makes you like them more</div></div>","19":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ab‧sent</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæbsənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not at work, school, a meeting etc, because you are sick or decide not to go <em>OPP present</em> RegisterIn everyday English, if someone is on holiday or on a business trip, people usually say that he/she is away:· He&#x27;s away at the moment. He’s gone to Hawaii.If you want to say that someone is not in a particular place, say not there:· I called in to see her but she wasn&#x27;t there.If you want to say that someone is not with you, say not here:· I&#x27;m afraid he&#x27;s not here at the moment. Can I take a message?</div><ul class=\"examples\"><li><strong><em>absent from</strong>: students who are regularly absent from school</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if someone or something is absent, they are missing or not in the place where they are expected to be</div><ul class=\"examples\"><li><strong><em>absent parent/father</strong>: plans to force absent fathers to pay child maintenance</em></li><li><strong><em>absent from</strong>: Local women were conspicuously absent (=obviously not there) from the meeting.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[only before noun]</span> a look etc that is absent shows you are not paying attention to or thinking about what is happening → absently:</div><ul class=\"examples\"><li><em>The dull, absent look on her face implied boredom.</em></li></ul></div>","20":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ab‧so‧lute</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæbsəluːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> complete or total:</div><ul class=\"examples\"><li><em>I have absolute confidence in her.</em></li><li><em>We don’t know with absolute certainty that the project will succeed.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> <em>especially British English</em> <em>informal</em> used to emphasize your opinion about something or someone:</div><ul class=\"examples\"><li><em>Some of the stuff on TV is absolute rubbish.</em></li><li><em>How did you do that? You’re an absolute genius.</em></li><li><em>That meal last night cost an absolute fortune.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> definite and not likely to change:</div><ul class=\"examples\"><li><em>We need absolute proof that he took the money.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> not restricted or limited:</div><ul class=\"examples\"><li><em>an absolute monarch</em></li><li><em>Parents used to have absolute power over their children.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> true, correct, and not changing in any situation:</div><ul class=\"examples\"><li><em>You have an absolute right to refuse medical treatment.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>in absolute terms</strong> measured by itself, not in comparison with other things:</div><ul class=\"examples\"><li><em>In absolute terms wages have risen, but not in comparison with the cost of living.</em></li></ul></div>","21":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ab‧so‧lute‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæbsəluːtli, ˌæbsəˈluːtli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> completely and in every way:</div><ul class=\"examples\"><li><em>He made his reasons for resigning absolutely clear.</em></li><li><em>Are you absolutely sure?</em></li><li><em>This cake is absolutely delicious.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to emphasize something:</div><ul class=\"examples\"><li><em>The burglars took absolutely everything.</em></li><li><em>Jim knew absolutely nothing about the business when he joined the firm.</em></li><li><em>He has absolutely no experience of marketing.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>absolutely not!</strong> <em>spoken</em> used when you strongly disagree with someone or when you do not want someone to do something:</div><ul class=\"examples\"><li><em>‘Do you let your kids travel alone at night?’ ‘Absolutely not!’</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>absolutely!</strong> <em>spoken</em> used to say that you completely agree with someone</div></div>","22":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ab‧sorb</span><span class=\"meta-item\"><strong>IPA:</strong> /əbˈsɔːb, əbˈzɔːb $ -ɔːrb/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[liquid/gas]</strong> to take in liquid, gas, or another substance from the surface or space around something:</div><ul class=\"examples\"><li><em>Plants absorb nutrients from the soil.</em></li><li><strong><em>absorb something into something</strong>: Water and salts are absorbed into our bloodstream.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[information]</strong> to read or hear a large amount of new information and understand it:</div><ul class=\"examples\"><li><em>Her capacity to absorb information is amazing.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[interest]</strong> to interest someone so much that they do not pay attention to other things:</div><ul class=\"examples\"><li><em>The movement and noise of the machines absorbed him completely.</em></li><li><strong><em>be absorbed in something</strong>: Judith lay on the settee, absorbed in her book.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[become part of something]</strong> to become part of something larger:</div><ul class=\"examples\"><li><em>California absorbs many of the legal immigrants to the US.</em></li><li><strong><em>be absorbed into something</strong>: We were soon absorbed into local village life.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[light/heat/energy/noise]</strong> if something absorbs light, heat, energy, or noise, it takes it in:</div><ul class=\"examples\"><li><em>Darker surfaces absorb heat.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[deal with change/costs]</strong> if something absorbs changes or costs, it accepts them and deals with them successfully:</div><ul class=\"examples\"><li><em>The beer industry had absorbed a doubling of federal tax in 1991.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[money/time]</strong> if something absorbs money, time etc, it uses a lot of it:</div><ul class=\"examples\"><li><em>Defence spending absorbs almost 20% of the country’s wealth.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[force]</strong> to reduce the effect of a sudden violent movement:</div><ul class=\"examples\"><li><em>A well-designed sports shoe should absorb the impact on your feet.</em></li></ul></div>","23":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ab‧stain</span><span class=\"meta-item\"><strong>IPA:</strong> /əbˈsteɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to choose not to vote for or against something:</div><ul class=\"examples\"><li><em>Six countries voted for the change, five voted against, and two abstained.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to not do or have something you enjoy, especially alcohol or sex, usually for reasons of religion or health</div><ul class=\"examples\"><li><strong><em>abstain from</strong>: Pilots must abstain from alcohol for 24 hours before flying.</em></li></ul></div>","24":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ab‧stract</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæbstrækt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> based on general ideas or principles rather than specific examples or real events <em>SYN theoretical</em></div><ul class=\"examples\"><li><strong><em>abstract idea/concept etc</strong>: the ability to translate abstract ideas into words</em></li><li><em>By the age of seven, children are capable of thinking in abstract terms.</em></li><li><em>Human beings are the only creatures capable of abstract thought (=thinking about ideas).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> existing only as an idea or quality rather than as something real that you can see or touch <em>OPP concrete</em>:</div><ul class=\"examples\"><li><em>the abstract nature of beauty</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> abstract paintings, designs etc consist of shapes and patterns that do not look like real people or things</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a painting, design etc which contains shapes or images that do not look like real things or people</div><div class=\"sense\"><span class=\"snum\">2</span> a short written statement containing only the most important ideas in a speech, article etc</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>in the abstract</strong> considered in a general way rather than being based on specific details and examples:</div><ul class=\"examples\"><li><em>Talking about crime in the abstract just isn’t enough.</em></li></ul></div></div>","25":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ab‧surd</span><span class=\"meta-item\"><strong>IPA:</strong> /əbˈsɜːd, -ˈzɜːd $ -ɜːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> completely stupid or unreasonable <em>SYN ridiculous</em> ► see thesaurus at stupid</div><ul class=\"examples\"><li><strong><em>quite/slightly/completely etc absurd</strong>: It seems quite absurd to expect anyone to drive for 3 hours just for a 20-minute meeting.</em></li><li><em>It seems an absurd idea.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the absurd</strong> something that is completely stupid and unreasonable:</div><ul class=\"examples\"><li><em>Some of the stories he tells verge on the absurd.</em></li></ul></div>","26":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧bun‧dance</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈbʌndəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[singular, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a large quantity of something</div><ul class=\"examples\"><li><strong><em>abundance of</strong>: an abundance of wavy red hair</em></li><li><strong><em>in abundance</strong>: One quality the team possessed in abundance was fighting spirit.</em></li></ul></div>","27":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧bun‧dant</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈbʌndənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">something that is abundant exists or is available in large quantities so that there is more than enough <em>OPP scarce</em>:</div><ul class=\"examples\"><li><em>an abundant supply of fresh water</em></li><li><em>abundant opportunities for well-qualified staff</em></li></ul></div>","28":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧buse</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈbjuːs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[plural, uncountable]</span> cruel or violent treatment of someone:</div><ul class=\"examples\"><li><em>several cases of child abuse</em></li><li><strong><em>physical/sexual/racial abuse</strong>: Many children suffer racial abuse at school.</em></li><li><em>An independent committee will look into alleged human rights abuses.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> the use of something in a way that it should not be used <em>SYN misuse</em> → solvent abuse</div><ul class=\"examples\"><li><strong><em>abuse of</strong>: government officials’ abuse of power</em></li><li><em>A self-monitoring tax system is clearly open to abuse (=able to be used wrongly).</em></li><li><strong><em>alcohol/drug abuse</strong> (=the practice of drinking too much or taking illegal drugs)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> rude or offensive things that someone says when they are angry: → a term of abuse at term1(3)</div><ul class=\"examples\"><li><em>vandalism and verbal abuse directed at old people</em></li><li><strong><em>a torrent/stream of abuse</strong> (=a series of rude or angry words)</em></li><li><strong><em>shout/hurl/scream abuse at somebody</strong>: The other driver started hurling abuse at me.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧buse</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈbjuːz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to treat someone in a cruel and violent way, often sexually</div><ul class=\"examples\"><li><strong><em>sexually/physically abused</strong>: She was sexually abused as a child.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to deliberately use something for the wrong purpose or for your own advantage:</div><ul class=\"examples\"><li><em>Williams abused his position as mayor to give jobs to his friends.</em></li><li><em>Morris abused the trust the firm had shown in him.</em></li><li><em>people who abuse the system</em></li><li><strong><em>abuse alcohol/drugs</strong>: The proportion of drinkers who abuse alcohol is actually quite small.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to say rude or offensive things to someone <em>SYN insult</em>:</div><ul class=\"examples\"><li><em>Many soldiers in Belfast are verbally abused.</em></li><li><em>He came to the help of another driver who was being racially abused by three white passengers.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> to treat something so badly that you start to destroy it:</div><ul class=\"examples\"><li><em>James abused his body for years with heroin and cocaine.</em></li></ul></div></div>","29":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧a‧dem‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌækəˈdemɪk◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[usually before noun]</span> relating to education, especially at college or university level <em>OPP non-academic</em>:</div><ul class=\"examples\"><li><em>He possessed no academic qualifications.</em></li><li><em>a program to raise academic standards</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[usually before noun]</span> concerned with studying from books, as opposed to practical work:</div><ul class=\"examples\"><li><em>the study of art as an academic discipline</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> good at studying <em>OPP unacademic</em>:</div><ul class=\"examples\"><li><em>He’s not very academic.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> if a discussion about something is academic, it is a waste of time because the speakers cannot change the existing situation:</div><ul class=\"examples\"><li><em>The question of where we go on holiday is purely academic since we don’t have any money.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a teacher in a college or university</div></div></div>","30":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧cel‧e‧rate</span><span class=\"meta-item\"><strong>IPA:</strong> /əkˈseləreɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> if a process accelerates or if something accelerates it, it happens faster than usual or sooner than you expect:</div><ul class=\"examples\"><li><em>measures to accelerate the rate of economic growth</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> if a vehicle or someone who is driving it accelerates, it starts to go faster <em>OPP decelerate</em>:</div><ul class=\"examples\"><li><em>The car accelerated smoothly away.</em></li></ul></div>","31":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧cel‧e‧ra‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /əkˌseləˈreɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[singular, uncountable]</span> a process in which something happens more and more quickly</div><ul class=\"examples\"><li><strong><em>acceleration in</strong>: an acceleration in the rate of inflation</em></li><li><strong><em>acceleration of</strong>: the rapid acceleration of economic progress in South East Asia</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the rate at which a car or other vehicle can go faster:</div><ul class=\"examples\"><li><em>The latest model has excellent acceleration.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> <em>technical</em> the rate at which the speed of an object increases</div></div>","32":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧cent</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæksənt $ ˈæksent/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the way someone pronounces the words of a language, showing which country or which part of a country they come from → dialect:</div><ul class=\"examples\"><li><em>He had a strong Irish accent.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the accent is on something</strong> if the accent is on a particular quality, feeling etc, special importance is given to it:</div><ul class=\"examples\"><li><em>accommodation with the accent on comfort</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the part of a word that you should emphasize when you say it <em>SYN stress</em></div><ul class=\"examples\"><li><strong><em>accent on</strong>: In the word ‘dinner’ the accent is on the first syllable.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a written mark used above or below particular letters in some languages to show how to pronounce that letter</div></div>","33":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧cept</span><span class=\"meta-item\"><strong>IPA:</strong> /əkˈsept/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[gift/offer/invitation]</strong> <span class=\"gram\">[intransitive, transitive]</span> to take something that someone offers you, or to agree to do something that someone asks you to do <em>OPP refuse</em>: RegisterIn everyday English, when talking about accepting a job, accepting responsibility or blame, or accepting a method of payment, people usually use take: They offered me the job and I accepted. ➔ They offered me the job and I took it.When talking about accepting an offer, people often say take someone up on their offer:· He decided to take her up on her offer.</div><ul class=\"examples\"><li><em>Rick accepted her offer of coffee.</em></li><li><em>He accepted the invitation to stay with us.</em></li><li><em>His school reports said that he is always ready to accept a challenge (=agree to do something difficult).</em></li><li><em>Please accept this small gift.</em></li><li><em>They offered me a job and I accepted.</em></li><li><strong><em>accept something from somebody</strong>: He accepted a glass of water from Helen.</em></li><li><em>He readily accepted her invitation (=accepted it quickly).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[situation/problem etc]</strong> <span class=\"gram\">[transitive]</span> to decide that there is nothing you can do to change a difficult and unpleasant situation or fact and continue with your normal life:</div><ul class=\"examples\"><li><em>He’s not going to change, and you just have to accept it.</em></li><li><strong><em>accept that</strong>: We have to accept that this is not an ideal world.</em></li><li><em>He can&#x27;t accept the fact that his problems are his own fault.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[think somebody/something is good enough]</strong> <span class=\"gram\">[transitive]</span> to decide that someone has the necessary skill or intelligence for a particular job, course etc or that a piece of work is good enough <em>OPP reject</em>:</div><ul class=\"examples\"><li><em>Students accepted by Stanford Law School had very high scores on the LSAT.</em></li><li><strong><em>accept somebody/something as something</strong>: They have accepted him as the representative of the company.</em></li><li><strong><em>accept somebody/something for something</strong>: Random House accepted the book for publication.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[become part of a group]</strong> <span class=\"gram\">[transitive]</span> to allow someone to become part of a group, society, or organization, and to treat them in the same way as the other members <em>OPP reject</em></div><ul class=\"examples\"><li><strong><em>accept somebody as something</strong>: The children gradually began to accept her as one of the family.</em></li><li><strong><em>accept somebody into something</strong>: It often takes years for immigrants to be accepted into the host community.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[agree to take/deal with something]</strong> <span class=\"gram\">[transitive]</span> to agree to take or deal with something that someone gives you, or to say that it is suitable or good enough:</div><ul class=\"examples\"><li><em>The government has accepted the resignation of a senior army commander.</em></li><li><em>Please accept my sincere apologies.</em></li><li><em>Sorry, we don’t accept traveller’s cheques.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[suggestion/advice]</strong> <span class=\"gram\">[transitive]</span> to decide to do what someone suggests or advises you should do:</div><ul class=\"examples\"><li><em>Be prepared to accept the advice of members of staff.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[believe an explanation/statement]</strong> <span class=\"gram\">[transitive]</span> to agree that what someone says is right or true <em>OPP reject</em>: ► see thesaurus at believe GRAMMARIn more formal English, you say it is accepted that when saying what people generally believe is true: · It is accepted that he was sincere in his claim.</div><ul class=\"examples\"><li><em>She has accepted your explanation as to why you didn’t attend the meeting.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>accept responsibility/blame for something</strong> to admit that you were responsible for something bad that happened:</div><ul class=\"examples\"><li><em>The University will not accept responsibility for items lost or stolen.</em></li></ul></div>","34":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧cept‧a‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /əkˈseptəbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> good enough to be used for a particular purpose or to be considered satisfactory ► see thesaurus at satisfactory</div><ul class=\"examples\"><li><strong><em>acceptable to</strong>: an agreement which is acceptable to all sides</em></li><li><em>Students who achieve an acceptable standard will progress to degree studies.</em></li><li><em>How do we reach an acceptable level of data security?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> acceptable behaviour is considered to be morally or socially good enough:</div><ul class=\"examples\"><li><em>Alcohol is not an acceptable way out of your problems.</em></li><li><em>Here, the students set the standards for acceptable behaviour.</em></li><li><strong><em>acceptable (for somebody) to do something</strong>: It is not socially acceptable for parents to leave children unattended at that age. / It is perfectly acceptable to sample the food before you buy.</em></li></ul></div>","35":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧cept‧ance</span><span class=\"meta-item\"><strong>IPA:</strong> /əkˈseptəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> when you officially agree to take something that you have been offered</div><ul class=\"examples\"><li><strong><em>acceptance of</strong>: the formal acceptance of an invitation</em></li><li><em>He wrote a letter of acceptance (=a letter in which you agree to accept a job, university place etc) to the university.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular, uncountable]</span> when people agree that an idea, statement, explanation etc is right or true</div><ul class=\"examples\"><li><strong><em>acceptance of</strong>: the acceptance of Einstein’s theory</em></li><li><strong><em>acceptance that</strong>: There is still not widespread acceptance that fathers can care for children as well as mothers do.</em></li><li><strong><em>gain/find acceptance</strong>: This management style gained acceptance in the 1980s.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> the ability to accept an unpleasant situation which cannot be changed, without getting angry or upset about it</div><ul class=\"examples\"><li><strong><em>acceptance of</strong>: By the end of the trial, Nicolas moved towards acceptance of his fate.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> the process of allowing someone to become part of a group or a society and of treating them in the same way as the other members:</div><ul class=\"examples\"><li><em>Acceptance by their peer group is important to most youngsters.</em></li></ul></div>","36":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧cept‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /əkˈseptɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">considered right or suitable by most people:</div><ul class=\"examples\"><li><em>Having more than one wife is a normal and accepted practice in some countries.</em></li><li><strong><em>generally/widely/universally etc accepted</strong>: generally accepted principles of fairness and justice</em></li></ul></div>","37":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧cess</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈækses/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1 AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the right to enter a place, use something, see someone etc</div><ul class=\"examples\"><li><strong><em>access to</strong>: Access to the papers is restricted to senior management. / Cats should always have access to fresh, clean water.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> how easy or difficult it is for people to enter a public building, to reach a place, or talk to someone</div><ul class=\"examples\"><li><strong><em>access for</strong>: We’re trying to improve access for disabled visitors.</em></li><li><strong><em>access to</strong>: a villa with easy access to the sea</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the way you use to enter a building or reach a place:</div><ul class=\"examples\"><li><em>Access is by means of a small door on the right.</em></li><li><strong><em>access to</strong>: Access to the restrooms is through the foyer.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>have access to a car/computer etc</strong> to have a car, a computer etc that you can use</div><div class=\"sense\"><span class=\"snum\">5</span> <em>British English</em> the legal right to see and spend time with your children, a prisoner, an official etc:</div><ul class=\"examples\"><li><em>My ex-husband has access to the children once a week.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>gain/get access (to something)</strong> to succeed in entering a place or in seeing someone or something:</div><ul class=\"examples\"><li><em>The police managed to gain access through an upstairs window.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to find information, especially on a computer:</div><ul class=\"examples\"><li><em>Users can access their voice mail remotely.</em></li></ul></div></div>","38":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧ces‧si‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /əkˈsesəbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a place, building, or object that is accessible is easy to reach or get into <em>OPP inaccessible</em>:</div><ul class=\"examples\"><li><em>The island is only accessible by boat.</em></li><li><em>There is a church which is easily accessible from my home.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> easy to obtain or use</div><ul class=\"examples\"><li><strong><em>accessible to</strong>: the need for a health service that is accessible to all</em></li><li><strong><em>easily/readily accessible</strong>: Computers should be made readily accessible to teachers and pupils.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> someone who is accessible is easy to meet and talk to, even if they are very important or powerful <em>SYN approachable</em>:</div><ul class=\"examples\"><li><em>I think that you’ll find she’s very accessible.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a book, poem, painting etc that is accessible is easy to understand and enjoy</div><ul class=\"examples\"><li><strong><em>accessible to</strong>: He wants his music to be accessible to everyone.</em></li></ul></div>","39":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧ces‧so‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /əkˈsesəri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural accessories)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[usually plural]</span> something such as a piece of equipment or a decoration that is not necessary, but that makes a machine, car, room etc more useful or more attractive:</div><ul class=\"examples\"><li><em>bathroom accessories such as mirrors and towel-rails</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[usually plural]</span> something such as a bag, belt, or jewellery that you wear or carry because it is attractive:</div><ul class=\"examples\"><li><em>fashion accessories</em></li><li><em>a set of fully matching clothes and accessories</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>law</em> someone who helps a criminal, especially by helping them hide from the police</div><ul class=\"examples\"><li><strong><em>accessory to</strong>: an accessory to murder</em></li><li><strong><em>an accessory before/after the fact</strong> (=someone who helps a criminal before or after the crime)</em></li></ul></div>","40":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧ci‧dent</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæksɪdənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>by accident</strong> in a way that is not planned or intended <em>OPP on purpose</em> <em>, deliberately</em>: GRAMMAR Don’t say: by an accident</div><ul class=\"examples\"><li><em>I met her quite by accident (=completely by accident).</em></li><li><em>The discovery was made almost by accident.</em></li><li><em>The pilot, whether by accident or design (=whether it was planned or not planned), made the plane do a sharp turn.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> an event in which a car, train, plane etc is damaged and often someone is hurt:</div><ul class=\"examples\"><li><em>Over 70,000 people are seriously injured every year in road accidents.</em></li><li><em>The accident happened at the junction of Forest Road and Pine Walk.</em></li><li><em>a train accident</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a situation in which someone is injured or something is damaged without anyone intending them to be:</div><ul class=\"examples\"><li><em>Ken had an accident at work and had to go to hospital.</em></li><li><em>I’m sorry about breaking the vase – it was an accident (=I did not intend to do it).</em></li><li><strong><em>a climbing/skiing/hunting etc accident</strong>: He died in a climbing accident in the Himalayas.</em></li><li><em>She was injured in a freak accident (=an unusual accident) when a wall suddenly collapsed.</em></li><li><em>I had a slight accident with your coffee.</em></li><li><em>They lost their lives in a tragic accident.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable, uncountable]</span> something that happens without anyone planning or intending it:</div><ul class=\"examples\"><li><em>My third baby was an accident.</em></li><li><em>It is no accident that men fill most of the top jobs in nursing, while women remain on the lower grades.</em></li><li><strong><em>an accident of birth/geography/history etc</strong> (=an event or situation caused by chance)</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>accidents (will) happen</strong> <em>spoken</em> used to tell someone who has broken something that they should not worry that it has happened</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>an accident waiting to happen</strong> used about a situation in which an accident is likely to happen because no one is trying to prevent it:</div><ul class=\"examples\"><li><em>The boats are being left to drift; it’s an accident waiting to happen.</em></li></ul></div>","41":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧ci‧den‧tal</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌæksəˈdentl◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">happening without being planned or intended <em>OPP deliberate</em>:</div><ul class=\"examples\"><li><em>an accidental discharge of toxic waste</em></li><li><em>Buy an insurance policy that covers accidental damage.</em></li></ul></div>","42":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧ci‧den‧tal‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌæksəˈdentli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">in a way that was not planned or intended <em>OPP deliberately</em>:</div><ul class=\"examples\"><li><em>She accidentally dropped the vase on her foot.</em></li></ul></div>","43":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧com‧mo‧date</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkɒmədeɪt $ əˈkɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> if a room, building etc can accommodate a particular number of people or things, it has enough space for them:</div><ul class=\"examples\"><li><em>He bought a huge house to accommodate his library.</em></li><li><em>The ballroom can accommodate 400 people.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to provide someone with a place to stay, live, or work:</div><ul class=\"examples\"><li><em>The island was used to accommodate child refugees.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to accept someone’s opinions and try to do what they want, especially when their opinions or needs are different from yours:</div><ul class=\"examples\"><li><em>We’ve made every effort to accommodate your point of view.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive]</span> to get used to a new situation or to make yourself do this</div><ul class=\"examples\"><li><strong><em>accommodate to</strong>: Her eyes took a while to accommodate to the darkness.</em></li></ul></div>","44":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧com‧mo‧da‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /əˌkɒməˈdeɪʃən $ əˌkɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> <em>especially British English</em> (also accommodations<em>American English</em>) a place for someone to stay, live, or work: RegisterIn everyday English, people usually say somewhere to live/stay rather than accommodation:· She’s trying to find somewhere to live.· Have you found anywhere to stay yet?</div><ul class=\"examples\"><li><em>The price for the holiday includes flights and accommodation.</em></li><li><em>living accommodations for the crews</em></li><li><em>travel and hotel accommodations</em></li><li><em>rented accommodation</em></li><li><em>secure accommodation for young offenders</em></li><li><em>Universities have to provide student accommodation for first-year students.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular, uncountable]</span> <em>formal</em> an agreement between people or groups who have different views or opinions, that satisfies everyone:</div><ul class=\"examples\"><li><em>We reached an accommodation between both parties.</em></li><li><em>Neither side was willing to make any kind of accommodation.</em></li></ul></div>","45":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧com‧pa‧ny</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkʌmpəni/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle accompanied, present participle accompanying, third person singular accompanies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to go somewhere with someone: RegisterIn everyday English, people usually say go with or come with someone rather than accompany someone:· Do you want me to go with you to the station?· She came with me to church.</div><ul class=\"examples\"><li><em>Children under 14 must be accompanied by an adult.</em></li><li><em>Wherever her husband went, she would accompany him.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to play a musical instrument while someone sings a song or plays the main tune:</div><ul class=\"examples\"><li><em>Daniel wanted Liz to accompany him on violin.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to happen or exist at the same time as something else GRAMMAR Accompany is usually passive in this meaning.</div><ul class=\"examples\"><li><strong><em>be accompanied by something</strong>: The disease is accompanied by sneezing and fever.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> if a book, document etc accompanies something, it comes with it:</div><ul class=\"examples\"><li><em>Please see accompanying booklet for instructions.</em></li><li><em>Your passport application form should be accompanied by two recent photographs.</em></li></ul></div>","46":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧com‧plish</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkʌmplɪʃ $ əˈkɑːm-, əˈkʌm-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to succeed in doing something, especially after trying very hard <em>SYN achieve</em>: ► see thesaurus at succeed</div><ul class=\"examples\"><li><em>We have accomplished all we set out to do.</em></li><li><em>Mission accomplished (=we have done what we intended to do).</em></li></ul></div>","47":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧com‧plish‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkʌmplɪʃmənt $ əˈkɑːm-, əˈkʌm-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> something successful or impressive that is achieved after a lot of effort and hard work <em>SYN achievement</em></div><ul class=\"examples\"><li><strong><em>impressive/significant/great etc accomplishment</strong>: Cutting the budget was an impressive accomplishment.</em></li><li><em>It was a major accomplishment for a player who had been injured so recently.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the act of finishing or achieving something good</div><ul class=\"examples\"><li><strong><em>accomplishment of</strong>: the accomplishment of policy goals</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> an ability to do something well, or the skill involved in doing something well:</div><ul class=\"examples\"><li><em>Playing the piano is one of her many accomplishments.</em></li></ul></div>","48":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧cord</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkɔːd $ -ɔːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>of somebody’s/something’s own accord</strong> without being asked or forced to do something:</div><ul class=\"examples\"><li><em>He decided to go of his own accord.</em></li><li><em>The door seemed to move of its own accord.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> <em>formal</em> a situation in which two people, ideas, or statements agree with each other</div><ul class=\"examples\"><li><strong><em>be in accord with something</strong>: These results are in accord with earlier research.</em></li><li><strong><em>in perfect/complete accord</strong>: It is important to the success of any firm that its partners should be in complete accord.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a formal agreement between countries or groups:</div><ul class=\"examples\"><li><em>the Helsinki accord on human rights</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>with one accord</strong> <em>formal</em> if two or more people do something with one accord, they do it together or at the same time:</div><ul class=\"examples\"><li><em>There was a silence as the women turned with one accord to stare at Doreen.</em></li></ul></div>","49":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧cord‧ance</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkɔːdəns $ əˈkɔːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><strong>in accordance with something</strong> <em>formal</em> according to a rule, system etc:</div><ul class=\"examples\"><li><em>Article 47 may only be used in accordance with international law.</em></li><li><em>Use this product only in accordance with the manufacturer’s instructions.</em></li></ul></div>","50":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> acˈcording to</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> as shown by something or stated by someone: ► Don’t say ‘according to me’ or ‘according to my opinion/point of view’. Say in my opinion: In my opinion his first book is much better.</div><ul class=\"examples\"><li><em>According to the police, his attackers beat him with a blunt instrument.</em></li><li><em>There is now widespread support for these proposals, according to a recent public opinion poll.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in a way that depends on differences in situations or amounts:</div><ul class=\"examples\"><li><em>You will be paid according to the amount of work you do.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> in a way that agrees with a system or plan, or obeys a set of rules:</div><ul class=\"examples\"><li><em>The game will be played according to rules laid down for the 1992 Cup.</em></li><li><em>Everything went according to plan, and we arrived on time.</em></li></ul></div>","51":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧cord‧ing‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkɔːdɪŋli $ əˈkɔːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in a way that is suitable for a particular situation or that is based on what someone has done or said:</div><ul class=\"examples\"><li><em>Katherine still considered him a child and treated him accordingly.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[sentence adverb]</span> as a result of something <em>SYN therefore</em>:</div><ul class=\"examples\"><li><em>Some of the laws were contradictory. Accordingly, measures were taken to clarify them.</em></li></ul></div>","52":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧count</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkaʊnt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[description]</strong> a written or spoken description that says what happens in an event or process</div><ul class=\"examples\"><li><strong><em>account of</strong>: He was too shocked to give an account of what had happened.</em></li><li><strong><em>blow-by-blow account</strong> (=a description of all the details of an event in the order that they happened): a blow-by-blow account of how England lost to Portugal</em></li><li><em>Chomsky’s account of how children learn their first language</em></li><li><strong><em>eye-witness/first-hand account</strong> (=a description of events by someone who saw them): Eye-witness accounts told of the unprovoked shooting of civilians. / This gives a first-hand account of the war.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[at a bank]</strong> (written abbreviation a/c or acct.) an arrangement in which a bank keeps your money safe so that you can pay more in or take money out: → bank account, checking account, current account, deposit account, profit and loss account, savings account</div><ul class=\"examples\"><li><em>My salary is paid into my bank account.</em></li><li><em>I’ve opened an account with Barclay’s Bank.</em></li><li><em>My husband and I have a joint account (=one that is shared between two people).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>take account of something</strong> (also take something into account) to consider or include particular facts or details when making a decision or judgment about something: GRAMMARYou say: · We will take your views into account. ✗Don’t say: We will take your views in account.</div><ul class=\"examples\"><li><em>These figures do not take account of changes in the rate of inflation.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>on account of something</strong> because of something else, especially a problem or difficulty:</div><ul class=\"examples\"><li><em>She was told to wear flat shoes, on account of her back problem.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>accounts</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[plural]</span> an exact record of the money that a company has received and the money it has spent:</div><ul class=\"examples\"><li><em>The accounts for last year showed a profit of $2 million.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[uncountable]</span> a department in a company that is responsible for keeping records of the amount of money spent and received:</div><ul class=\"examples\"><li><em>Eileen works in accounts.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>on account</strong> if you buy goods on account, you take them away with you and pay for them later</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[with a shop/company]</strong> an arrangement that you have with a shop or company, which allows you to buy goods or use a service now and pay for them later <em>SYN credit account</em>:</div><ul class=\"examples\"><li><em>Can you charge this to my account please?</em></li><li><em>an unlimited-use Internet account</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[bill]</strong> a statement that shows how much money you owe for things you have bought from a shop <em>SYN bill</em></div><ul class=\"examples\"><li><strong><em>pay/settle your account</strong> (=pay what you owe): James left the restaurant, settling his account by credit card.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[arrangement to sell goods]</strong> an arrangement to sell goods and services to another company over a period of time:</div><ul class=\"examples\"><li><em>Our sales manager has secured several big accounts recently.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>by/from all accounts</strong> according to what a lot of people say:</div><ul class=\"examples\"><li><em>It has, from all accounts, been a successful marriage.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>on somebody’s account</strong> if you do something on someone’s account, you do it because you think they want you to:</div><ul class=\"examples\"><li><em>Please don’t change your plans on my account.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>on your own account</strong> by yourself or for yourself:</div><ul class=\"examples\"><li><em>Carrie decided to do a little research on her own account.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>on no account/not on any account</strong> used when saying that someone must not, for any reason, do something:</div><ul class=\"examples\"><li><em>On no account must you disturb me.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>by somebody’s own account</strong> according to what you have said, especially when you have admitted doing something wrong:</div><ul class=\"examples\"><li><em>Bentley was, by his own account, over-sensitive to criticism.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>on that account/on this account</strong> concerning a particular situation:</div><ul class=\"examples\"><li><em>There needn’t be any more worries on that account.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>give a good/poor account of yourself</strong> to do something or perform very well or very badly:</div><ul class=\"examples\"><li><em>Kevin gave a good account of himself in today’s game.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>bring/call somebody to account</strong> <em>formal</em> to force someone who is responsible for a mistake or a crime to explain publicly why they did it and punish them for it if necessary:</div><ul class=\"examples\"><li><em>The people responsible for the accident have never been brought to account.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>put/turn something to good account</strong> <em>formal</em> to use something for a good purpose:</div><ul class=\"examples\"><li><em>Perhaps she could put some of her talents to good account by helping us.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>of no/little account</strong> <em>formal</em> not important:</div><ul class=\"examples\"><li><em>As she grew up, her father was of no account to her.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\">account account 2 ●●○ S3 W3 verb Word Origin Verb Table Examples Thesaurus Collocations Phrases account for something phrasal verb 1 to form a particular amount or part of something: Afro-Americans account for 12% of the US population. 2 to be the reason why something happens SYN explain: Recent pressure at work may account for his behavior. 3 to give a satisfactory explanation of why something has happened or why you did something SYN explain: Can you account for your movements on that night? 4 to say where all the members of a group of people or things are, especially because you are worried that some of them may be lost: Three days after the earthquake, more than 150 people had still to be accounted for.</div></div></div>","53":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧count‧a‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkaʊntəbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[not before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">responsible for the effects of your actions and willing to explain or be criticized for them</div><ul class=\"examples\"><li><strong><em>accountable to</strong>: The government should be accountable to all the people of the country.</em></li><li><strong><em>accountable for</strong>: Managers must be accountable for their decisions.</em></li><li><em>The hospital should be held accountable for the quality of care it gives.</em></li></ul></div>","54":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧coun‧tant</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkaʊntənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone whose job is to keep and check financial accounts, calculate taxes etc</div></div>","55":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧coun‧ting</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkaʊntɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">accountancy</div></div>","56":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧cu‧mu‧late</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkjuːmjəleɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to gradually get more and more money, possessions, knowledge etc over a period of time: ► see thesaurus at collect</div><ul class=\"examples\"><li><em>It is unjust that a privileged few should continue to accumulate wealth.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> to gradually increase in numbers or amount until there is a large quantity in one place:</div><ul class=\"examples\"><li><em>Fat tends to accumulate around the hips and thighs.</em></li></ul></div>","57":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧cu‧ra‧cy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈækjərəsi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the ability to do something in an exact way without making a mistake:</div><ul class=\"examples\"><li><em>He passes the ball with unerring accuracy.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the quality of being correct or true <em>OPP inaccuracy</em></div><ul class=\"examples\"><li><strong><em>accuracy of</strong>: worries about the accuracy of government statistics</em></li></ul></div>","58":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧cu‧rate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈækjərət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[information]</strong> correct and true in every detail <em>OPP inaccurate</em>: ► see thesaurus at right, true</div><ul class=\"examples\"><li><em>The brochure tries to give a fair and accurate description of each hotel.</em></li><li><strong><em>fairly/reasonably accurate</strong>: Police believe Derek gave a reasonably accurate account of what happened.</em></li><li><strong><em>not strictly/entirely/completely accurate</strong>: The evidence she gave to the court was not strictly accurate (=not exactly accurate).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[measurement]</strong> measured or calculated correctly <em>OPP inaccurate</em>:</div><ul class=\"examples\"><li><em>It is difficult to get accurate figures on population numbers.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[machine]</strong> a machine that is accurate is able to do something in an exact way without making a mistake:</div><ul class=\"examples\"><li><em>The cutter is accurate to within ½ a millimetre.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[well-aimed]</strong> an accurate shot, throw etc succeeds in hitting or reaching the thing that it is intended to hit:</div><ul class=\"examples\"><li><em>an accurate shot</em></li><li><em>accurate bowling</em></li></ul></div>","59":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧cu‧sa‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌækjəˈzeɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a statement saying that someone is guilty of a crime or of doing something wrong</div><ul class=\"examples\"><li><strong><em>accusation against</strong>: A number of serious accusations have been made against her.</em></li><li><em>The main accusation levelled against him was that he tried to avoid military service.</em></li><li><strong><em>accusation of</strong>: His administration now faces accusations of corruption.</em></li><li><strong><em>accusation that</strong>: The organizers of the march strongly denied government accusations that they intended to cause trouble.</em></li><li><em>Burton’s enemies had made false accusations against him.</em></li><li><em>She’s made all sorts of wild accusations against me in the past.</em></li><li><em>They fled the country, amid accusations of corruption.</em></li></ul></div>","60":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧cuse</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkjuːz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to say that you believe someone is guilty of a crime or of doing something bad</div><ul class=\"examples\"><li><strong><em>accuse somebody of (doing) something</strong>: He was accused of murder. / Smith accused her of lying.</em></li><li><em>The professor stands accused of (=has been accused of) stealing his student’s ideas and publishing them.</em></li></ul></div>","61":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧cus‧tom</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkʌstəm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to make yourself or another person become used to a situation or place</div><ul class=\"examples\"><li><strong><em>accustom yourself to something</strong>: It took a while for me to accustom myself to all the new rules and regulations.</em></li></ul></div>","62":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /eɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if part of your body aches, you feel a continuous, but not very sharp pain there <em>SYN hurt</em>: ► see thesaurus at hurt RegisterIn everyday English, people usually say they have a headache, have (a) backache, have (a) stomach ache, or have (a) toothache rather than saying that their head, back, etc aches: My head aches terribly. ➔ I have a terrible headache.</div><ul class=\"examples\"><li><em>His feet were aching from standing so long.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to want to do or have something very much</div><ul class=\"examples\"><li><strong><em>ache for</strong>: I’m aching for sleep.</em></li><li><strong><em>ache to do something</strong>: He ached to reach out and hold her close.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to have a strong unhappy feeling</div><ul class=\"examples\"><li><strong><em>ache with</strong>: Sarah ached with sadness that her brother was so ill.</em></li><li><em>Tim’s heart was aching for her.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a continuous pain that is not sharp or very strong: ► see thesaurus at pain</div><ul class=\"examples\"><li><em>a stomach ache</em></li><li><em>A dull ache throbbed at the back of David’s head.</em></li><li><strong><em>aches and pains</strong> (=slight feelings of pain that are not considered to be serious): Apart from the usual aches and pains, she felt all right.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a strong, mostly unhappy, feeling:</div><ul class=\"examples\"><li><em>the ache of his loneliness</em></li></ul></div></div>","63":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧chieve</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈtʃiːv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to successfully complete something or get a good result, especially by working hard: ► see thesaurus at succeed RegisterIn everyday English, people usually say someone gets a result rather than achieves it:· He got good grades in his final exams.</div><ul class=\"examples\"><li><em>She eventually achieved her goal of becoming a professor.</em></li><li><em>Wilson has achieved considerable success as an artist.</em></li><li><em>Frances achieved very good exam results.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> to be successful in a particular kind of job or activity:</div><ul class=\"examples\"><li><em>We want all our students to achieve within their chosen profession.</em></li></ul></div>","64":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧chieve‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈtʃiːvmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> something important that you succeed in doing by your own efforts</div><ul class=\"examples\"><li><strong><em>achievement of</strong>: We try to celebrate the achievements of our students.</em></li><li><em>His great achievement is to make all the players into a united team.</em></li><li><strong><em>somebody’s achievement in (doing) something</strong>: The test measures children’s achievements in reading, spelling, and maths.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> when you achieve something or when people achieve something:</div><ul class=\"examples\"><li><em>Roberts is researching the effect of social class on educational achievement.</em></li><li><em>As we climbed the final few metres, we felt a sense of achievement.</em></li></ul></div>","65":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧id</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæsɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a chemical substance that has a pH of less than 7. Strong acids can burn holes in material or damage your skin:</div><ul class=\"examples\"><li><em>sulphuric acid</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> <em>informal</em> the drug LSD</div></div>","66":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧knowl‧edge</span><span class=\"meta-item\"><strong>IPA:</strong> /əkˈnɒlɪdʒ $ -ˈnɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[admit]</strong> to admit or accept that something is true or that a situation exists: ► see thesaurus at admit GRAMMARIn more formal English, you say it is acknowledged that when saying what people generally agree is true: · It is acknowledged that these letters are genuine.</div><ul class=\"examples\"><li><em>The family acknowledge the need for change.</em></li><li><strong><em>acknowledge that</strong>: He acknowledges that when he’s tired he gets bad-tempered.</em></li><li><em>Claire acknowledged that she was guilty.</em></li><li><em>The government must acknowledge what is happening and do something about it.</em></li><li><em>‘Maybe you are right,’ she acknowledged.</em></li><li><em>This is a fact that most smokers readily acknowledge.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[recognize something’s importance]</strong> if people acknowledge something, they recognize how good or important it is:</div><ul class=\"examples\"><li><em>The Brazilian coach acknowledged the talent of his players.</em></li><li><strong><em>be acknowledged as something</strong>: The film festival is acknowledged as an event of international importance.</em></li><li><strong><em>be widely/generally acknowledged to be something</strong>: The mill produces what is widely acknowledged to be the finest wool in the world.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[accept somebody’s authority]</strong> to accept that someone or something has authority over people:</div><ul class=\"examples\"><li><em>Both defendants refused to acknowledge the authority of the court.</em></li><li><strong><em>acknowledge somebody as something</strong>: Many of the poor acknowledged him as their spiritual leader.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[thank]</strong> to publicly announce that you are grateful for the help that someone has given you:</div><ul class=\"examples\"><li><em>We wish to acknowledge the support of the university.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[show you notice somebody]</strong> to show someone that you have noticed them or heard what they have said:</div><ul class=\"examples\"><li><em>Tom acknowledged her presence by a brief glance.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[say you have received something]</strong> to let someone know that you have received something from them:</div><ul class=\"examples\"><li><em>I would be grateful if you would acknowledge receipt of this letter.</em></li></ul></div>","67":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧knowl‧edge‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /əkˈnɒlɪdʒmənt $ -ˈnɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the act of admitting or accepting that something is true</div><ul class=\"examples\"><li><strong><em>acknowledgement of</strong>: We want an acknowledgement of the existence of the problem.</em></li><li><strong><em>acknowledgement that</strong>: The reduction in their grant is an acknowledgement that they have been paid too much.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular, uncountable]</span> a movement of your body that shows that you have noticed someone or heard what they have said:</div><ul class=\"examples\"><li><em>Basil nodded an acknowledgement as he entered the room.</em></li><li><em>He gave her a faint smile of acknowledgement.</em></li><li><strong><em>in acknowledgement</strong>: Larsen looked over and nodded in acknowledgement.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> the act of publicly thanking someone for something they have done</div><ul class=\"examples\"><li><strong><em>in acknowledgement of something</strong>: She received a special award in acknowledgement of all her hard work.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable, uncountable]</span> a letter written to tell someone that you have received their letter, message etc:</div><ul class=\"examples\"><li><em>Do you want a written acknowledgement?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>acknowledgements</strong> <span class=\"gram\">[plural]</span> a short piece of writing at the beginning or end of a book in which the writer thanks all the people who have helped him or her</div></div>","68":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧cous‧tic</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkuːstɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relating to sound and the way people hear things</div><div class=\"sense\"><span class=\"snum\">2</span> an acoustic guitar or other musical instrument does not have its sound made louder electronically → electric</div></div>","69":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧quaint‧ance</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkweɪntəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[somebody you know]</strong> <span class=\"gram\">[countable]</span> someone you know, but who is not a close friend: ► see thesaurus at friend RegisterIn everyday English, people usually say someone I know rather than an acquaintance:· I got the job through someone I know.</div><ul class=\"examples\"><li><em>She was a casual acquaintance of my family in Vienna.</em></li><li><em>He heard about the job through a mutual acquaintance (=someone you and another person both know).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[relationship]</strong> <span class=\"gram\">[singular, uncountable]</span> a relationship with someone you know, but who is not a close friend:</div><ul class=\"examples\"><li><em>They developed an acquaintance over the Internet.</em></li><li><em>You can’t judge her on such short acquaintance (=when you have not known her long).</em></li><li><em>My uncle did not improve on further acquaintance (=when you knew him better).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>make somebody’s acquaintance</strong> <em>formal</em> to meet someone for the first time:</div><ul class=\"examples\"><li><em>I should be delighted to make Mrs McGough’s acquaintance.</em></li><li><em>At the hotel, I made the acquaintance of a young American actor.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[knowledge]</strong> <span class=\"gram\">[uncountable]</span> <em>formal</em> knowledge or experience of a particular subject</div><ul class=\"examples\"><li><strong><em>acquaintance with</strong>: The practice of a lawyer requires acquaintance with court procedures.</em></li><li><strong><em>have a passing/nodding acquaintance with something</strong> (=have only slight knowledge or experience of something): He has a passing acquaintance with a lot of different subjects.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>of your acquaintance</strong> <em>formal</em> a person of your acquaintance is someone that you know:</div><ul class=\"examples\"><li><em>The poems were written by various women of her acquaintance.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>on first acquaintance</strong> <em>formal</em> when you meet someone for the first time:</div><ul class=\"examples\"><li><em>Most people are nicer than you think on first acquaintance.</em></li></ul></div>","70":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧quaint‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkweɪntɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[not before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if you are acquainted with someone, you have met them a few times but do not know them very well</div><ul class=\"examples\"><li><strong><em>acquainted with</strong>: Were you acquainted with a friend of mine, Daniel Green?</em></li><li><em>We would like to get better acquainted.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be acquainted with something</strong> <em>formal</em> to know about something, because you have seen it, read it, used it etc:</div><ul class=\"examples\"><li><em>She was well acquainted with classical literature.</em></li></ul></div>","71":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧quire</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkwaɪə $ əˈkwaɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>formal</em> to obtain something by buying it or being given it: ► see thesaurus at buy</div><ul class=\"examples\"><li><em>Manning hoped to acquire valuable works of art as cheaply as possible.</em></li><li><em>The council acquired the land using a compulsory purchase order.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to get or gain something: RegisterIn everyday English, people usually say get rather than acquire:· Where did you get that tie?· He soon got a reputation for being unfriendly.</div><ul class=\"examples\"><li><em>The college acquired a reputation for very high standards.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to gain knowledge or learn a skill: ► see thesaurus at get</div><ul class=\"examples\"><li><em>He spent years acquiring his skills as a surgeon.</em></li><li><em>Elsie acquired a good knowledge of Chinese.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>acquire a taste for something</strong> to begin to like something:</div><ul class=\"examples\"><li><em>She had acquired a taste for European beer.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>an acquired taste</strong> something that people only begin to like after they have tried it a few times</div></div>","72":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧cre</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeɪkə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a unit for measuring area, equal to 4,840 square yards or 4,047 square metres:</div><ul class=\"examples\"><li><em>They own 200 acres of farmland.</em></li><li><em>a 200-acre wood</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>acres of space/room</strong> <em>British English</em> <em>informal</em> a large amount of space</div></div>","73":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧ri‧mo‧ni‧ous</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌækrəˈməʊniəs◂ $ -ˈmoʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">an acrimonious meeting or discussion is one in which people argue a lot and get very angry <em>SYN bitter</em>:</div><ul class=\"examples\"><li><em>The meeting ended in an acrimonious dispute.</em></li></ul></div>","74":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧cross</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkrɒs $ əˈkrɒːs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> from one side of something to the other:</div><ul class=\"examples\"><li><em>the first flight across the Atlantic</em></li><li><em>They ran straight across the road (=without stopping).</em></li><li><em>We’ll have to swim across.</em></li><li><em>We’d got halfway across before Philip realized he’d left his money at home.</em></li><li><em>We gazed across the valley.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> towards someone or something on the other side of an area:</div><ul class=\"examples\"><li><em>There’s Brendan. Why don’t you go across and say hello?</em></li><li><strong><em>across to/at</strong>: The referee looked across at his linesman before awarding the penalty. / He walked across to where I was sitting.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to say that something exists or reaches from one side of an area to the other:</div><ul class=\"examples\"><li><em>a deep crack across the ceiling</em></li><li><em>the only bridge across the river</em></li><li><em>Do you think this shirt is too tight across the shoulders?</em></li><li><em>Someone’s parked right across the entrance to the driveway.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> on the opposite side of something:</div><ul class=\"examples\"><li><em>My best friend lives across the road.</em></li><li><em>He knew that just across the border lay freedom.</em></li><li><strong><em>across (something) from somebody/something</strong>: Across the street from where we’re standing, you can see the old churchyard. / the woman sitting across from me (=opposite me) on the train</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> in every part of a country, organization etc:</div><ul class=\"examples\"><li><em>a TV series that became popular across five continents</em></li><li><em>Teachers are expected to teach a range of subjects right across the curriculum.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> used to show how wide something is</div><ul class=\"examples\"><li><strong><em>ten feet/five metres etc across</strong>: The river is 2 kilometres across.</em></li></ul></div>","75":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ækt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[action]</strong> <span class=\"gram\">[countable]</span> one thing that you do: RegisterIn everyday English, people usually say a thoughtless/kind/stupid etc thing to do rather than a thoughtless/kind/stupid etc act.</div><ul class=\"examples\"><li><em>The new president’s first act should be to end the war.</em></li><li><em>a thoughtless act</em></li><li><strong><em>act of (doing) something</strong>: an act of violence / her many acts of kindness / The act of writing a list can help to calm you down.</em></li><li><strong><em>in the act of doing something</strong> (=at the moment that you are doing something): Lindsay paused in the act of putting down the phone.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[law]</strong> (also Act) <span class=\"gram\">[countable]</span> a law that has been officially accepted by Parliament or Congress:</div><ul class=\"examples\"><li><em>the Housing and Community Development Act of 1977</em></li><li><em>an act of Parliament</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[pretending]</strong> <span class=\"gram\">[singular]</span> insincere behaviour in which you pretend to have a particular kind of feeling or to be a particular kind of person:</div><ul class=\"examples\"><li><em>Mike played the loving husband in front of the children but it was all an act.</em></li><li><em>Be natural. Don’t feel you have to put on an act.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>get your act together</strong> <em>informal</em> to become more organized and behave in a more effective way, especially in order to achieve something:</div><ul class=\"examples\"><li><em>You need to get your act together if you’re going to find the right house to buy.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[play]</strong> <span class=\"gram\">[countable]</span> one of the main parts into which a stage play, opera etc is divided:</div><ul class=\"examples\"><li><em>I arrived at the theatre late and missed the first act.</em></li><li><em>the beginning of Act 3</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[performance]</strong> <span class=\"gram\">[countable]</span> a short performance on stage or television by someone who plays music or tells jokes:</div><ul class=\"examples\"><li><em>The argument was just part of their act.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[performer]</strong> <span class=\"gram\">[countable]</span> a performer or a group of performers who perform together:</div><ul class=\"examples\"><li><em>The band is one of many acts that have been booked for the concert.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>a hard/tough etc act to follow</strong> someone who does such an excellent job that it would be difficult for someone doing the same job after them to be as good:</div><ul class=\"examples\"><li><em>He has been a very successful captain and will be a hard act to follow.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>get in on the act</strong> <em>informal</em> to take part in an activity that someone else has started, especially in order to get a share of the advantages for yourself</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>act of God</strong> an event that is caused by natural forces, such as a storm, flood, or fire, which you cannot prevent or control</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>act of worship</strong> an occasion when people pray together and show their respect for God</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>balancing/juggling act</strong> a situation in which you are trying to do several different types of work at the same time</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>do a disappearing/vanishing act</strong> to be impossible to find when you are needed</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[do something]</strong> <span class=\"gram\">[intransitive]</span> to do something in a particular way or for a particular reason: RegisterIn everyday English, people often use expressions like do the right thing or do a brave thing rather than use act with an adverb such as correctly or bravely: They acted correctly in telling her. ➔ They did the right thing in telling her.When act is used alone to mean ‘take action’, in everyday English people usually just say do something:· We have to do something now.</div><ul class=\"examples\"><li><em>The company acted correctly in sacking him.</em></li><li><em>The jury decided that Walker had acted in self-defence.</em></li><li><strong><em>act to do something</strong>: The UN must act now to restore democracy.</em></li><li><em>Politicians will only act when enough people demand that they do something.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[behave]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to behave in a particular way:</div><ul class=\"examples\"><li><em>They acted unreasonably when they turned down Jill’s application.</em></li><li><em>He’s been acting strangely ever since his mom died.</em></li><li><strong><em>act as if</strong>: Pip acted as if he was better than everyone else.</em></li><li><strong><em>act like</strong>: Stop acting like a baby.</em></li><li><strong><em>act with</strong>: She acted with dignity.</em></li><li><strong><em>act your age</strong> (=used to tell someone to behave in a more adult way, suitable for someone of their age)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[pretend]</strong> <span class=\"gram\">[intransitive, transitive]</span> to pretend to have feelings, qualities etc that are different from your true ones: ► see thesaurus at pretend</div><ul class=\"examples\"><li><em>When he’s angry, he acts the fool.</em></li><li><em>That guy is acting crazy.</em></li><li><strong><em>act a part/role</strong>: Stella felt unnatural in their company, as if she was acting a part.</em></li><li><strong><em>act as if/like</strong>: Why does he act as if he was stupid?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[play/film]</strong> <span class=\"gram\">[intransitive, transitive]</span> to perform in a play or film:</div><ul class=\"examples\"><li><em>I first started acting when I was 12 years old.</em></li><li><strong><em>act a part/role</strong>: She is acting the role of Lady Macbeth six evenings a week.</em></li><li><em>The movie is very well acted.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[have an effect]</strong> <span class=\"gram\">[intransitive]</span> to have an effect or use</div><ul class=\"examples\"><li><strong><em>act as</strong>: The padding acts as a cushion if the player falls or is hit by the ball.</em></li><li><strong><em>act on</strong>: Disinfectants act on bacteria in two main ways.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>act for somebody/act on somebody’s behalf</strong> to represent someone, especially in a court of law or by doing business for them: → acting1</div><ul class=\"examples\"><li><em>Makin, a solicitor, is acting for the young people in their case against the county council.</em></li><li><em>I am acting on behalf of the bank.</em></li></ul></div></div>","76":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈækʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[doing something]</strong> <span class=\"gram\">[uncountable]</span> the process of doing something, especially in order to achieve a particular thing:</div><ul class=\"examples\"><li><em>The government must take action (=do something) now to stop the rise in violent crime.</em></li><li><strong><em>action on</strong>: Environmental groups want tougher action on pollution from cars.</em></li><li><em>She was looking forward to putting her ideas into action (=doing the things she had planned).</em></li><li><em>Ambulance crews are ready to spring into action (=suddenly start doing something) if anything goes wrong during the race.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[something done]</strong> <span class=\"gram\">[countable]</span> something that someone does</div><ul class=\"examples\"><li><strong><em>quick/swift/prompt action</strong>: Her prompt actions probably saved my life.</em></li><li><em>The child could not be held responsible for his actions (=he was too young to be blamed for them).</em></li><li><strong><em>defend/justify your action(s)</strong>: The chief of police tried to justify his actions.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in action</strong> someone or something that is in action is doing the job or activity they are trained or designed to do:</div><ul class=\"examples\"><li><em>photos of ski jumpers in action</em></li><li><strong><em>see/watch something/somebody in action</strong>: I’d like to see the new computer system in action.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>out of action</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> broken and not working:</div><ul class=\"examples\"><li><em>The photocopier is out of action again.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> injured and unable to do anything</div><ul class=\"examples\"><li><strong><em>put/keep somebody out of action</strong>: The injury will keep him out of action for a month.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[fighting]</strong> <span class=\"gram\">[uncountable]</span> fighting during a war: ► see thesaurus at war</div><ul class=\"examples\"><li><em>There have been reports of widespread enemy action in the area.</em></li><li><strong><em>killed/wounded in action</strong> (=killed or wounded while fighting): His father was killed in action in Vietnam.</em></li><li><em>530 servicemen were reported missing in action (=they were never seen again after a battle).</em></li><li><em>The men were sent into action with little or no training.</em></li><li><em>He had seen action (=been involved in fighting) in Korea.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[legal]</strong> <span class=\"gram\">[countable, uncountable]</span> a legal or formal process to decide whether someone has done something wrong:</div><ul class=\"examples\"><li><em>They are threatening to take legal action against the hospital (=start a court case against them).</em></li><li><em>The director faces disciplinary action (=official action to punish him).</em></li><li><em>The matter is now the subject of a court action (=a court case).</em></li><li><em>The students agreed to drop their action (=decided not to continue with a court case or an official complaint).</em></li><li><em>The sisters brought a libel action against the newspaper (=started a court case).</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[excitement]</strong> <span class=\"gram\">[uncountable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>informal</em> exciting things that are happening:</div><ul class=\"examples\"><li><em>There hasn’t been much action around here for months.</em></li><li><em>New York is where all the action is.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> an action film has a lot of exciting scenes in it, in which people fight, chase, and kill each other:</div><ul class=\"examples\"><li><em>Gibson became famous in action movies.</em></li><li><em>a TV action hero</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[the events in a story/film etc]</strong> <strong>the action</strong> the events in a story, film, play etc:</div><ul class=\"examples\"><li><em>Most of the action takes place in San Francisco.</em></li><li><em>The action opens (=starts) in a barbershop.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[movement]</strong> <span class=\"gram\">[countable, uncountable]</span> the way something moves or works</div><ul class=\"examples\"><li><strong><em>action of</strong>: the action of the heart</em></li><li><em>a smooth braking action</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[effect]</strong> <span class=\"gram\">[uncountable]</span> the effect that a substance, especially a chemical, has on something</div><ul class=\"examples\"><li><strong><em>action of</strong>: The drug blocks the action of the cancer gene.</em></li><li><strong><em>action on/upon</strong>: the action of alcohol on the liver</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>action group/committee etc</strong> a group formed to change a social or political situation – often used in names:</div><ul class=\"examples\"><li><em>the Child Poverty Action Group</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>a piece/slice of the action</strong> <em>informal</em> an opportunity to be involved in an event or activity, especially one that will be enjoyable or will make money:</div><ul class=\"examples\"><li><em>If you want a slice of the action, tickets may still be available.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>actions speak louder than words</strong> used to say that you are judged by what you do, and not by what you say</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>action!</strong> used by film directors to give the instruction to begin filming:</div><ul class=\"examples\"><li><em>Lights, camera, action!</em></li></ul></div>","77":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæktɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[busy]</strong> always busy doing things, especially physical or mental activities <em>OPP inactive</em>:</div><ul class=\"examples\"><li><em>games for active youngsters</em></li><li><em>She’s over 80, but is still very active.</em></li><li><strong><em>active life/lifestyle</strong>: My father always led a very active life.</em></li><li><strong><em>active mind/imagination</strong>: a child with a very active imagination</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[involved]</strong> involved in an organization or activity and doing lots of practical things to achieve your aims:</div><ul class=\"examples\"><li><em>He became politically active at college.</em></li><li><strong><em>be active in (doing) something</strong>: The Bureau is active in promoting overseas investment.</em></li><li><strong><em>take/play an active part/role in something</strong>: Encourage students to take an active part in discussions.</em></li><li><em>She took an active interest in local charities.</em></li><li><strong><em>active participation/involvement</strong>: the importance of active participation by elderly people in the life of the community</em></li><li><em>We’re taking active steps (=doing practical things) to deal with the problem.</em></li><li><em>We maintain active links with other European universities.</em></li><li><strong><em>active member/supporter</strong>: He is an active member of the Labour Party.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[functioning]</strong> operating in a way that is normal or expected <em>OPP inactive</em>:</div><ul class=\"examples\"><li><em>The virus is active even at low temperatures.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[doing something]</strong> doing something regularly:</div><ul class=\"examples\"><li><em>sexually active teenagers</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[volcano]</strong> an active volcano is likely to erupt (=explode) at any time:</div><ul class=\"examples\"><li><em>The volcano became active last year with a series of eruptions.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[grammar]</strong> an active verb or sentence has the person or thing doing the action as its subject. In ‘The boy kicked the ball’, the verb ‘kick’ is active → passive1(2)</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[chemical]</strong> producing a chemical reaction:</div><ul class=\"examples\"><li><em>nicotine, the active ingredient in tobacco</em></li></ul></div>","78":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧tive‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæktɪvli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">in a way that involves doing a lot of practical things:</div><ul class=\"examples\"><li><em>Carol was actively involved in running the group.</em></li><li><em>The school actively encourages students to do their best.</em></li></ul></div>","79":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧tiv‧ist</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæktɪvɪst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who works hard doing practical things to achieve social or political change</div><ul class=\"examples\"><li><strong><em>political/gay/animal rights etc activist</em></strong></li></ul></div>","80":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧tiv‧i‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ækˈtɪvəti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\">(plural activities)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> things that people do, especially in order to achieve a particular aim:</div><ul class=\"examples\"><li><em>Everyone is free to engage in peaceful political activity.</em></li><li><em>fund-raising activities</em></li><li><em>Regular physical activity helps to control your weight.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable usually plural]</span> something that you do because you enjoy it:</div><ul class=\"examples\"><li><em>leisure activities</em></li><li><em>outdoor activities such as hiking or climbing</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> a situation in which a lot of things are happening or a lot of things are being done:</div><ul class=\"examples\"><li><em>The office was suddenly full of frantic activity.</em></li><li><em>The farm was always a hive of activity at this time of year.</em></li></ul></div>","81":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧tor</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæktə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who performs in a play or film</div><ul class=\"examples\"><li><strong><em>leading/principal actor</strong>: She has starred with many leading actors.</em></li><li><strong><em>character actor</strong> (=an actor who takes unusual or interesting roles)</em></li></ul></div>","82":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧tress</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæktrɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a woman who performs in a play or film ► see thesaurus at actor</div></div>","83":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧tu‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæktʃuəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to emphasize that something is real or exact: ► Do not use actual to mean ‘at the present time’. Use current or present: the current (NOT actual) economic policy</div><ul class=\"examples\"><li><em>I’m not joking. Those were his actual words.</em></li><li><em>I know Germany won, but I can’t tell you the actual score.</em></li><li><em>Interest is only charged on the actual amount borrowed.</em></li><li><em>In actual fact (=really), there is little evidence to support the allegations.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the actual something</strong> used to introduce the most important part of an event or activity:</div><ul class=\"examples\"><li><em>The programme starts at 8.00 but the actual film doesn’t start until 8.30.</em></li></ul></div>","84":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ac‧tu‧al‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæktʃuəli, -tʃəli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[sentence adverb]</span> <em>spoken</em> used to add new information to what you have just said, to give your opinion, or to start a new conversation:</div><ul class=\"examples\"><li><em>I’ve known Barbara for years. Since we were babies, actually.</em></li><li><em>Actually, on second thoughts, I don’t think I want to go out tonight.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to emphasize the real or exact truth of a situation, rather than what people may think:</div><ul class=\"examples\"><li><em>What time are you actually leaving?</em></li><li><em>Labor costs have actually fallen.</em></li><li><em>‘Disappointed?’ ‘No, actually I’m rather glad.’</em></li></ul></div>","85":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧cute</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkjuːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[problem]</strong> an acute problem is very serious: ► see thesaurus at serious</div><ul class=\"examples\"><li><em>The housing shortage is more acute than first thought.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[feeling]</strong> an acute feeling is very strong:</div><ul class=\"examples\"><li><em>acute pain</em></li><li><em>acute embarrassment</em></li><li><em>acute anxiety</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[illness]</strong> <em>technical</em> an acute illness or disease quickly becomes very serious <em>OPP chronic</em>:</div><ul class=\"examples\"><li><em>acute arthritis</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[senses]</strong> acute senses such as hearing, taste, touch etc are very good and sensitive:</div><ul class=\"examples\"><li><em>Young children have a particularly acute sense of smell.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[intelligent]</strong> quick to notice and understand things <em>SYN sharp</em>:</div><ul class=\"examples\"><li><em>Simon’s vague manner concealed an acute mind.</em></li><li><em>an acute analysis of Middle Eastern politics</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[mathematics]</strong> <em>technical</em> an acute angle is less than 90° → obtuse</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[punctuation]</strong> an acute accent (=a mark used to show pronunciation) is a small mark written above a vowel. In ‘café’, the letter ‘e’ has an acute accent. → grave, circumflex</div></div>","86":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧cute‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkjuːtli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">feeling or noticing something very strongly</div><ul class=\"examples\"><li><strong><em>acutely aware/conscious (of/that)</strong>: Students are becoming acutely aware that they need more than just paper qualifications.</em></li><li><em>acutely embarrassed</em></li></ul></div>","87":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ˌeɪ ˈdiː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">(Anno Domini) used to show that a date is a particular number of years after the birth of Christ <em>SYN CE</em> → BC:</div><ul class=\"examples\"><li><em>the first century AD</em></li><li><em>54 AD</em></li></ul></div>","88":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /æd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>informal</em> an advertisement → classified ad ► see thesaurus at advertisement</div></div>","89":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧dapt</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈdæpt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to gradually change your behaviour and attitudes in order to be successful in a new situation</div><ul class=\"examples\"><li><strong><em>adapt to</strong>: The children are finding it hard to adapt to the new school. / flowers which are well adapted to harsh winters</em></li><li><em>The ability to adapt is a definite asset in this job.</em></li><li><strong><em>adapt yourself/itself etc (to something)</strong>: How do these insects adapt themselves to new environments?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to change something to make it suitable for a different purpose</div><ul class=\"examples\"><li><strong><em>adapt something to do something</strong>: The car has been adapted to take unleaded gas.</em></li><li><strong><em>adapt something for somebody</strong>: These teaching materials can be adapted for older children.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> if a book or play is adapted for film, television etc, it is changed so that it can be made into a film, television programme etc → adaptation GRAMMAR Adapt is usually passive in this meaning.</div><ul class=\"examples\"><li><strong><em>be adapted for something</strong>: Many children buy books after they have been adapted for television.</em></li></ul></div>","90":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ˌæd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[put with something else]</strong> <span class=\"gram\">[transitive]</span> to put something with something else or with a group of other things:</div><ul class=\"examples\"><li><em>If the mixture seems dry, add water.</em></li><li><strong><em>add something to something</strong>: Do you want to add your name to the list? / Suzuki has added extra doors to its sports off-roader. / Material about recent research has been added to this new edition.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[count]</strong> <span class=\"gram\">[intransitive, transitive]</span> if you add numbers or amounts together, you calculate their total → subtract</div><ul class=\"examples\"><li><strong><em>add something and something (together)</strong>: Add 7 and 5 to make 12. / For tax purposes, your pension and earnings are added together.</em></li><li><strong><em>add something to something</strong>: Add £2.20 to the cost for postage.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[increase]</strong> <span class=\"gram\">[intransitive, transitive]</span> to increase the amount or cost of something</div><ul class=\"examples\"><li><strong><em>add (something) to something</strong>: Spell-checking your document adds time to the process. / Sales tax adds to the price.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[say more]</strong> <span class=\"gram\">[transitive]</span> to say more about something that has just been said: ► see thesaurus at say</div><ul class=\"examples\"><li><em>‘And I don’t care what you think,’ she added defiantly.</em></li><li><em>Is there anything you’d like to add, David?</em></li><li><strong><em>add that</strong>: Everyone will be invited to vote, he said, adding that voting is likely to be via the Web.</em></li><li><em>I was refused accommodation – not, I hasten to add, on account of my appearance (=used to explain more about what you have just said).</em></li><li><em>She was trying to entertain us – unsuccessfully, I might add (=used to comment on what you have just said).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[give a quality]</strong> <span class=\"gram\">[transitive]</span> to give a particular quality to something</div><ul class=\"examples\"><li><strong><em>add something to something</strong>: We’ve added value to the information by organizing it.</em></li><li><strong><em>add a touch of glamour/class (to something)</strong>: Champagne always adds a touch of glamour to the occasion.</em></li><li><em>Coloured glass can be added for effect.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>add(ed) to that/this</strong> used to introduce another fact that supports your opinion:</div><ul class=\"examples\"><li><em>Our hospitals are short of cash. Add to that the long hours doctors work, and you have a recipe for disaster.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>add weight to something</strong> if something adds weight to an argument, idea etc, it makes it stronger</div><ul class=\"examples\"><li><strong><em>add weight to the suggestion/idea etc</strong>: Recent research adds weight to the theory that the climate is changing.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>to add insult to injury</strong> to make a bad situation worse for someone who has already been treated badly:</div><ul class=\"examples\"><li><em>She not only deceived him but, to add insult to injury, allowed him to pay for her meal.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>add fuel to the fire/flames</strong> to make an argument or disagreement worse:</div><ul class=\"examples\"><li><em>Rather than providing a solution, their statements merely added fuel to the fire.</em></li></ul></div>","91":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧ded</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈædɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">in addition to what is usual or expected <em>SYN extra</em>:</div><ul class=\"examples\"><li><em>cereal with added vitamins</em></li><li><em>no added sugar</em></li><li><strong><em>added advantage/bonus/benefit etc</strong>: The system has the added advantage of recordable DVD drives. / Include people in your picture for added interest.</em></li><li><strong><em>added difficulty/problem etc</strong>: Our yard is only small, and has the added disadvantage of facing north. / It may not be necessary to go to the added expense of updating your anti-virus software.</em></li></ul></div>","92":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧dict</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈædɪkt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who is unable to stop taking drugs</div><ul class=\"examples\"><li><strong><em>drug/heroin/morphine etc addict</strong>: a recovering heroin addict</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who is very interested in something and spends a lot of time doing it</div><ul class=\"examples\"><li><strong><em>TV/sports etc addict</strong>: My nephew is a complete video game addict.</em></li></ul></div>","93":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧dic‧ted</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈdɪktɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> unable to stop taking a harmful substance, especially a drug</div><ul class=\"examples\"><li><strong><em>addicted to</strong>: Fifty million Americans are addicted to nicotine.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> liking something so much that you do not want to stop doing it or having it</div><ul class=\"examples\"><li><strong><em>addicted to</strong>: kids addicted to surfing the Net</em></li></ul></div>","94":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧dic‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈdɪkʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the need to take a harmful drug regularly, without being able to stop</div><ul class=\"examples\"><li><strong><em>drug/heroin/alcohol etc addiction</em></strong></li><li><strong><em>addiction to</strong>: addiction to alcohol</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a strong desire to do or have something regularly</div></div>","95":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧dic‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈdɪktɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if a substance, especially a drug, is addictive, your body starts to need it regularly and you are unable to stop taking it:</div><ul class=\"examples\"><li><em>Tobacco is highly addictive.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an activity that is addictive is so enjoyable that you do not want to stop:</div><ul class=\"examples\"><li><em>It started as a hobby, but it got so addictive I had to keep on doing it.</em></li><li><em>addictive arcade games</em></li></ul></div>","96":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧di‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈdɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>in addition</strong> used to add another piece of information to what you have just said:</div><ul class=\"examples\"><li><em>The company provides cheap Internet access. In addition, it makes shareware freely available.</em></li><li><strong><em>in addition to something</strong>: In addition to his movie work, Redford is known as a champion of environmental causes.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the act of adding something to something else</div><ul class=\"examples\"><li><strong><em>the addition of something</strong>: The addition of networking facilities will greatly enhance the system.</em></li><li><strong><em>with the addition of something</strong>: Turn sparkling wine into Buck’s Fizz with the addition of chilled orange juice.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> something that is added to something else, often in order to improve it</div><ul class=\"examples\"><li><strong><em>addition to</strong>: This excellent book will be a welcome addition to the library of any student.</em></li><li><strong><em>latest/new/recent addition</strong>: the latest addition to our designer range</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> the process of adding numbers or amounts to make a total → subtraction</div><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> <em>American English</em> an extra room that is added to a building:</div><ul class=\"examples\"><li><em>They built a big addition onto the back of the house.</em></li></ul></div>","97":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧di‧tion‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈdɪʃənəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2</span></div><div class=\"entry-body\"><div class=\"sense\">more than what was agreed or expected <em>SYN extra</em>: ► see thesaurus at more RegisterIn everyday English, people usually say extra rather than additional:· He gets extra money from his parents.</div><ul class=\"examples\"><li><em>Additional information can be obtained from the centre.</em></li><li><strong><em>additional costs/expenditure etc</strong>: An additional charge is made on baggage exceeding the weight allowance.</em></li></ul></div>","98":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧di‧tion‧al‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈdɪʃənəli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[sentence adverb]</span></span></div><div class=\"entry-body\"><div class=\"sense\">in addition <em>SYN also</em>:</div><ul class=\"examples\"><li><em>A new contract is in place. Additionally, staff will be offered a bonus scheme.</em></li></ul></div>","99":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧dress</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈdres $ əˈdres, ˈædres/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the details of the place where someone lives or works, which you use to send them letters etc:</div><ul class=\"examples\"><li><em>What’s your new address?</em></li><li><em>I can give you the address of a good attorney.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the series of letters and other symbols that you put when sending email to a particular person, or that is the name of a website:</div><ul class=\"examples\"><li><em>They have changed the address of their website.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a formal speech that someone makes to a group of people ► see thesaurus at speech</div><ul class=\"examples\"><li><strong><em>address to</strong>: an address to the European Parliament</em></li><li><strong><em>presidential/inaugural etc address</strong>: The new president delivered his inaugural address in Creole.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>form/mode/style of address</strong> the correct title or name that you should use when speaking or writing to someone</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧dress</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈdres/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if you address an envelope, package etc, you write on it the name and address of the person you are sending it to</div><ul class=\"examples\"><li><strong><em>address something to somebody</strong>: That letter was addressed to me.</em></li><li><em>Send a stamped, self-addressed envelope (=with your address on it so it can be sent back to you).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> if you address a problem, you start trying to solve it</div><ul class=\"examples\"><li><strong><em>address a problem/question/issue etc</strong>: Our products address the needs of real users.</em></li><li><strong><em>address yourself to something</strong>: Marlowe now addressed himself to the task of searching the room.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>formal</em> to speak to someone directly:</div><ul class=\"examples\"><li><em>She turned to address the man on her left.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>formal</em> if you address remarks, complaints etc to someone, you say or write them directly to that person:</div><ul class=\"examples\"><li><em>You will have to address your comments to our Head Office.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> to make a formal speech to a large group of people</div><ul class=\"examples\"><li><strong><em>address a meeting/conference etc</strong>: He addressed an audience of 10,000 supporters.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> to use a particular title or name when speaking or writing to someone</div><ul class=\"examples\"><li><strong><em>address somebody as something</strong>: The president should be addressed as ‘Mr. President’.</em></li></ul></div></div>","100":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧e‧quate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈædɪkwət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> enough in quantity or of a good enough quality for a particular purpose <em>SYN sufficient</em> <em>OPP inadequate</em>: ► see thesaurus at enough</div><ul class=\"examples\"><li><em>Farmers have been slow to make adequate provision for their retirement.</em></li><li><em>Some creams we tested failed to give adequate protection against UV light.</em></li><li><em>The standard of his work is barely adequate.</em></li><li><em>The company has yet to provide an adequate explanation for its actions.</em></li><li><strong><em>adequate for</strong>: Are the parking facilities adequate for 50 cars?</em></li><li><strong><em>adequate to do something</strong>: The lunchtime menu is more than adequate to satisfy the biggest appetite.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> fairly good but not excellent → satisfactory: ► see thesaurus at satisfactory</div><ul class=\"examples\"><li><em>Her performance was adequate but lacked originality.</em></li></ul></div>","101":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧e‧quate‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈædɪkwətli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">in a way that is enough for a particular purpose <em>SYN sufficiently</em> <em>OPP inadequately</em>:</div><ul class=\"examples\"><li><em>Students need to be adequately prepared for the world of work.</em></li><li><em>She wasn’t adequately insured.</em></li></ul></div>","102":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧here</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈhɪə $ -ˈhɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to stick firmly to something</div><ul class=\"examples\"><li><strong><em>adhere to</strong>: The eggs of these fish adhere to plant leaves.</em></li></ul></div>","103":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧ja‧cent</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈdʒeɪsənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">a room, building, piece of land etc that is adjacent to something is next to it:</div><ul class=\"examples\"><li><em>We stayed in adjacent rooms.</em></li><li><strong><em>adjacent to</strong>: the building adjacent to the library</em></li></ul></div>","104":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧jec‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈædʒəktɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●●</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a word that describes a noun or pronoun. In the phrase ‘black hat’, ‘black’ is an adjective and in the sentence ‘It makes her happy’, ‘happy’ is an adjective.</div></div>","105":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧journ</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈdʒɜːn $ -ɜːrn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> if a meeting, parliament, law court etc adjourns, or if the person in charge adjourns it, it stops for a short time:</div><ul class=\"examples\"><li><em>It was almost noon when the meeting adjourned.</em></li><li><strong><em>adjourn for/until</strong>: Congress has adjourned for the November elections. / His trial was adjourned until May.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>adjourn to something</strong> to finish an activity and go somewhere – often used humorously:</div><ul class=\"examples\"><li><em>The rest of us adjourned to a nearby pub for some refreshments.</em></li></ul></div>","106":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧just</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈdʒʌst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to gradually become familiar with a new situation <em>SYN adapt</em>: RegisterIn everyday English, people usually say get used to rather than adjust (to): You’ll soon adjust. ➔ You’ll soon get used to it.</div><ul class=\"examples\"><li><em>They’ll soon settle in – kids are very good at adjusting.</em></li><li><strong><em>adjust to</strong>: It took a few seconds for her eyes to adjust to the darkness.</em></li><li><strong><em>adjust to doing something</strong>: My parents had trouble adjusting to living in an apartment.</em></li><li><strong><em>adjust yourself to something</strong>: It took time to adjust myself to motherhood.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to change or move something slightly to improve it or make it more suitable for a particular purpose: RegisterIn everyday English, people usually say turn up or turn down the temperature, volume etc rather than adjust it.</div><ul class=\"examples\"><li><em>Check and adjust the brakes regularly.</em></li><li><em>Taste the soup and adjust the seasoning.</em></li><li><em>If your employment status changes, your tax code will be adjusted accordingly.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> if you adjust something you are wearing, you move it slightly so that it is neater, more comfortable etc:</div><ul class=\"examples\"><li><em>He paused to adjust his spectacles.</em></li></ul></div>","107":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧just‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈdʒʌstmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a small change made to a machine, system, or calculation</div><ul class=\"examples\"><li><strong><em>adjustment for</strong>: Once we make the adjustments for inflation, the fall in interest rates is quite small.</em></li><li><strong><em>adjustment to</strong>: a slight adjustment to the mechanism</em></li><li><strong><em>minor/slight adjustment</strong>: It just needs a few minor adjustments.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a change in the way that someone behaves or thinks:</div><ul class=\"examples\"><li><em>a period of adjustment</em></li><li><strong><em>adjustment to</strong>: her adjustment to her new role</em></li></ul></div>","108":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧min‧is‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈmɪnɪstə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to manage the work or money of a company or organization: GRAMMAR Administer is often passive in this meaning.</div><ul class=\"examples\"><li><em>The money will be administered by local charities.</em></li><li><em>Our office administers the affairs of the Society.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to provide or organize something officially as part of your job</div><ul class=\"examples\"><li><strong><em>administer justice/punishment etc</strong>: It is not the job of the police to administer justice; that falls to the courts.</em></li><li><strong><em>administer to</strong>: Pillai had responsibility for administering to the needs of half a million people.</em></li><li><strong><em>administer something to somebody</strong>: The test was administered to all 11-year-olds.</em></li><li><strong><em>administer an oath</strong> (=be the official person who listens to it)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> <em>formal</em> to give someone a medicine or medical treatment</div><ul class=\"examples\"><li><strong><em>administer something to somebody</strong>: Painkillers were administered to the boy.</em></li><li><em>This unit teaches students how to administer first aid.</em></li></ul></div>","109":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧min‧is‧tra‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˌmɪnəˈstreɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the activities that are involved in managing the work of a company or organization:</div><ul class=\"examples\"><li><em>We’re looking for someone with experience in administration.</em></li><li><em>The health service spends too much on administration.</em></li><li><strong><em>the administration</strong> (=the people who do this work): the college administration</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> the government of a country at a particular time: ► see thesaurus at government</div><ul class=\"examples\"><li><em>the Kennedy Administration</em></li><li><em>The problem has been ignored by successive administrations.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> the act of administering something, especially a law, test, or medicine</div><ul class=\"examples\"><li><strong><em>administration of</strong>: the administration of justice / the administration of sedatives</em></li></ul></div>","110":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧min‧is‧tra‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈmɪnəstrətɪv $ -streɪtɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\">relating to the work of managing a company or organization:</div><ul class=\"examples\"><li><em>The job is mainly administrative.</em></li><li><strong><em>administrative staff/duties/job etc</strong>: the administrative costs of health care systems / an administrative assistant / staff who provide technical and administrative support to the college</em></li></ul></div>","111":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧min‧is‧tra‧tor</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈmɪnəstreɪtə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone whose job involves managing the work of a company or organization</div></div>","112":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧mi‧ra‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈædmərəbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">having many good qualities that you respect and admire:</div><ul class=\"examples\"><li><em>an admirable achievement</em></li></ul></div>","113":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧mi‧ra‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌædməˈreɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a feeling of great respect and liking for something or someone:</div><ul class=\"examples\"><li><em>Daniel gazed at her in admiration.</em></li><li><strong><em>admiration for</strong>: I wanted to express my admiration for the way the crew handled the crisis.</em></li><li><strong><em>admiration of</strong>: Her riding soon drew the admiration of the older girls.</em></li></ul></div>","114":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧mire</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈmaɪə $ -ˈmaɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to respect and like someone because they have done something that you think is good, or to respect their qualities or skills:</div><ul class=\"examples\"><li><em>I really admire the way she brings up those kids all on her own.</em></li><li><strong><em>admire somebody for (doing) something</strong>: Lewis was much admired for his work on medieval literature.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to look at something and think how beautiful or impressive it is:</div><ul class=\"examples\"><li><em>We stopped halfway to admire the view.</em></li><li><em>Sal stood back to admire her work.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>admire somebody from afar</strong> <em>literary</em> to be attracted to someone, without letting them know</div></div>","115":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧mir‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈmaɪərə $ -ˈmaɪrər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>literary</em> someone who likes a person and thinks that they are attractive:</div><ul class=\"examples\"><li><em>a beautiful woman with many admirers</em></li><li><em>a secret admirer</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who respects a famous person, especially because they like their work <em>SYN fan</em>:</div><ul class=\"examples\"><li><em>a crowd of fervent admirers</em></li><li><strong><em>admirer of</strong>: ‘I’m a great admirer of yours,’ she managed to stammer.</em></li></ul></div>","116":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧mis‧sion</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈmɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a statement in which you admit that something is true or that you have done something wrong <em>SYN confession</em></div><ul class=\"examples\"><li><strong><em>admission that</strong>: The Senator’s admission that he had lied to Congress shocked many Americans.</em></li><li><strong><em>admission of guilt/defeat/failure etc</strong>: Silence is often interpreted as an admission of guilt.</em></li><li><em>Reese, by his own admission, lacks the necessary experience.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> permission given to someone to enter a building or place, or to become a member of a school, club etc:</div><ul class=\"examples\"><li><em>No admission after 10 pm.</em></li><li><em>The young men tried to enter a nightclub but were refused admission.</em></li><li><em>Women gained admission to the club only recently.</em></li><li><strong><em>admission to</strong>: those applying for admission to university</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>admissions</strong> <span class=\"gram\">[plural]</span> the process of allowing people to enter a university, institution etc, or the number of people who can enter</div><ul class=\"examples\"><li><strong><em>university/college/school admissions</em></strong></li><li><strong><em>admissions policy/procedures etc</strong>: The college has a very selective admissions policy. / the admissions officer</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable, uncountable]</span> the process of taking someone into a hospital for treatment, tests, or care:</div><ul class=\"examples\"><li><em>There are 13,000 hospital admissions annually due to playground accidents.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[uncountable]</span> the cost of entrance to a concert, sports event, cinema etc → admittance:</div><ul class=\"examples\"><li><em>Admission: $10 for adults, $5 for children.</em></li><li><em>The cost includes free admission to the casinos.</em></li><li><em>The Museum has no admission charge.</em></li></ul></div>","117":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧mit</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈmɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\">(past tense and past participle admitted, present participle admitting)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[accept truth]</strong> <span class=\"gram\">[intransitive, transitive]</span> to agree unwillingly that something is true or that someone else is right:</div><ul class=\"examples\"><li><em>‘Okay, so maybe I was a little bit scared,’ Jenny admitted.</em></li><li><strong><em>admit (that)</strong>: You may not like her, but you have to admit that she’s good at her job.</em></li><li><strong><em>admit to somebody (that)</strong>: Paul admitted to me that he sometimes feels jealous of my friendship with Stanley.</em></li><li><em>I must admit, I didn’t actually do anything to help her.</em></li><li><em>Admit it! I’m right, aren’t I?</em></li><li><strong><em>admit (to) doing something</strong>: Dana admitted feeling hurt by what I had said.</em></li><li><strong><em>freely/openly/frankly etc admit</strong> (=admit without being ashamed): Phillips openly admits to having an alcohol problem.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[accept blame]</strong> <span class=\"gram\">[intransitive, transitive]</span> to say that you have done something wrong, especially something criminal <em>SYN confess</em> <em>OPP deny</em> ► see thesaurus at admit</div><ul class=\"examples\"><li><strong><em>admit doing something</strong>: Greene admitted causing death by reckless driving.</em></li><li><strong><em>admit to (doing) something</strong>: A quarter of all workers admit to taking time off when they are not ill. / After questioning, he admitted to the murder.</em></li><li><em>No organization has admitted responsibility for the bombing.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[allow to enter]</strong> <span class=\"gram\">[transitive]</span> to allow someone to enter a public place to watch a game, performance etc → admittance, admission RegisterIn everyday English, people usually say let someone in rather than admit someone:· They won’t let you in without a ticket.</div><ul class=\"examples\"><li><strong><em>admit somebody to/into something</strong>: Only ticket-holders will be admitted into the stadium.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[allow to join]</strong> <span class=\"gram\">[transitive]</span> to allow someone to join an organization, club etc</div><ul class=\"examples\"><li><strong><em>admit somebody to/into something</strong>: Drake was admitted into the club in 1997.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[hospital]</strong> <span class=\"gram\">[transitive]</span> if people at a hospital admit someone, that person is taken in to be given treatment, tests, or care:</div><ul class=\"examples\"><li><em>What time was she admitted?</em></li><li><strong><em>be admitted to hospital<em>British English</em></strong> <strong>, be admitted to the hospital</em>American English</strong>**</li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>admit defeat</strong> to stop trying to do something because you realize you cannot succeed:</div><ul class=\"examples\"><li><em>For Haskill, selling the restaurant would be admitting defeat.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>admit evidence</strong> to allow a particular piece of evidence to be used in a court of law:</div><ul class=\"examples\"><li><em>Courts can refuse to admit evidence obtained illegally by police.</em></li></ul></div>","118":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧mit‧ted‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈmɪtɪdli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[sentence adverb]</span></span></div><div class=\"entry-body\"><div class=\"sense\">used when you are admitting that something is true:</div><ul class=\"examples\"><li><em>This has led to financial losses, though admittedly on a fairly small scale.</em></li></ul></div>","119":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧o‧les‧cence</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌædəˈlesəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the time, usually between the ages of 12 and 18, when a young person is developing into an adult</div></div>","120":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧o‧les‧cent</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌædəˈlesənt◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a young person, usually between the ages of 12 and 18, who is developing into an adult ► see thesaurus at child, young</div></div>","121":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧dopt</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈdɒpt $ əˈdɑːpt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[child]</strong> <span class=\"gram\">[intransitive, transitive]</span> to take someone else’s child into your home and legally become its parent → foster:</div><ul class=\"examples\"><li><em>Sally was adopted when she was four.</em></li><li><em>The couple are unable to have children of their own, but hope to adopt.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>adopt an approach/policy/attitude etc</strong> to start to deal with or think about something in a particular way:</div><ul class=\"examples\"><li><em>The courts were asked to adopt a more flexible approach to young offenders.</em></li><li><em>The store recently adopted a drug testing policy for all new employees.</em></li><li><em>California has adopted a tough stance on the issue.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[style/manner]</strong> <span class=\"gram\">[transitive]</span> to use a particular style of speaking, writing, or behaving, especially one that you do not usually use:</div><ul class=\"examples\"><li><em>Kim adopts a southern accent when speaking to family back home.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[law/rule]</strong> <span class=\"gram\">[transitive]</span> to formally approve a proposal, amendment etc, especially by voting:</div><ul class=\"examples\"><li><em>Congress finally adopted the law after a two-year debate.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[name/country etc]</strong> <span class=\"gram\">[transitive]</span> to choose a new name, country, custom etc, especially to replace a previous one:</div><ul class=\"examples\"><li><em>Stevens became a Muslim and adopted the name Yusuf Islam.</em></li><li><em>Becoming a member of a society means adopting its values.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[election]</strong> <span class=\"gram\">[transitive]</span> <em>British English</em> to officially choose someone to represent a political party in an election</div></div>","122":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧dore</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈdɔː $ əˈdɔːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to love someone very much and feel very proud of them: ► see thesaurus at love</div><ul class=\"examples\"><li><em>Betty adores her grandchildren.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>informal</em> to like something very much: ► see thesaurus at like</div><ul class=\"examples\"><li><em>I simply adore chocolate.</em></li></ul></div>","123":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧ult</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈædʌlt, əˈdʌlt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a fully-grown person, or one who is considered to be legally responsible for their actions → child:</div><ul class=\"examples\"><li><em>Some children find it difficult to talk to adults.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a fully-grown animal:</div><ul class=\"examples\"><li><em>The adults have white bodies and grey backs.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[only before noun]</span> fully grown or developed:</div><ul class=\"examples\"><li><em>an adult lion</em></li><li><em>the adult population</em></li><li><em>He lived most of his adult life in Scotland.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> typical of an adult’s behaviour or of the things adults do:</div><ul class=\"examples\"><li><em>dealing with problems in an adult way</em></li><li><em>That wasn’t very adult of you.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[only before noun]</span> adult films, magazines etc are about sex or related to sex:</div><ul class=\"examples\"><li><em>The film is rated R for language and adult themes.</em></li></ul></div></div>","124":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧vance</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈvɑːns $ ədˈvæns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>in advance (of something)</strong> before something happens or is expected to happen:</div><ul class=\"examples\"><li><em>I should warn you in advance that I’m not a very good dancer.</em></li><li><em>Many thanks, in advance, for your help.</em></li><li><strong><em>six months/a year etc in advance</strong>: Book tickets 21 days in advance.</em></li><li><em>Could you distribute copies well in advance of the meeting?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be in advance of somebody/something</strong> to be more developed or modern than someone or something else:</div><ul class=\"examples\"><li><em>Their aircraft were in advance of those used by the US.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[development/improvement]</strong> <span class=\"gram\">[countable]</span> a change, discovery, or invention that brings progress ► see thesaurus at progress</div><ul class=\"examples\"><li><strong><em>technological/scientific/medical etc advance</strong>: one of the great technological advances of the 20th century</em></li><li><em>a major advance</em></li><li><strong><em>advance in</strong>: Recent advances in genetics have raised moral questions.</em></li><li><strong><em>advance on</strong>: an advance on previous treatments</em></li><li><em>the advances made in the understanding of mental handicap</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[forward movement]</strong> <span class=\"gram\">[countable]</span> forward movement or progress of a group of people – used especially to talk about soldiers</div><ul class=\"examples\"><li><strong><em>advance on</strong>: the enemy’s advance on St. Petersburg</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[money]</strong> <span class=\"gram\">[countable usually singular]</span> money paid to someone before the usual time, especially someone’s salary:</div><ul class=\"examples\"><li><em>a $500 advance</em></li><li><strong><em>advance on</strong>: Krebs decided to ask for an advance on his salary.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>advances</strong> <span class=\"gram\">[plural]</span> <em>formal</em> an attempt to start a sexual relationship with someone:</div><ul class=\"examples\"><li><em>She accused her boss of making advances to her.</em></li><li><em>The witness said that he ‘went berserk’ when she rejected his sexual advances.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[increase]</strong> <span class=\"gram\">[countable]</span> an increase in the price or value of something – used especially when talking about the stock exchange</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[move forward]</strong> <span class=\"gram\">[intransitive]</span> to move towards someone or something, especially in a slow and determined way – used especially to talk about soldiers:</div><ul class=\"examples\"><li><em>A line of US tanks slowly advanced.</em></li><li><strong><em>advance on</strong>: Troops advanced on the rebel stronghold (=moved towards it in order to attack it).</em></li><li><strong><em>advance across/through/towards</strong>: The army advanced across the plain.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[develop]</strong> <span class=\"gram\">[intransitive, transitive]</span> if scientific or technical knowledge advances, or if something advances it, it develops and improves:</div><ul class=\"examples\"><li><em>Our understanding of human genetics has advanced considerably.</em></li><li><em>The group’s research has done much to advance our knowledge of the HIV virus.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[money]</strong> <span class=\"gram\">[transitive]</span> to give someone money before they have earned it</div><ul class=\"examples\"><li><strong><em>advance somebody something</strong>: Will they advance you some money until you get your first paycheck?</em></li><li><strong><em>advance something to somebody</strong>: I advanced $1,500 to Kramer last Thursday.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>advance your career/a cause/your interests etc</strong> to do something that will help you achieve an advantage or success for yourself or someone else:</div><ul class=\"examples\"><li><em>Jameson agreed to the deal in an effort to advance his political career.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[price]</strong> <span class=\"gram\">[intransitive]</span> if the price or value of something advances, it increases – used especially when talking about the stock exchange</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[time/date]</strong> <span class=\"gram\">[transitive]</span> <em>formal</em> to change the time or date when an event should happen to an earlier time or date:</div><ul class=\"examples\"><li><em>The meeting has been advanced to ten o&#x27;clock.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[machine]</strong> <span class=\"gram\">[intransitive, transitive]</span> <em>formal</em> if you advance a film, clock, musical recording etc, or if it advances, it goes forward</div></div></div>","125":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧vanced</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈvɑːnst $ ədˈvænst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> very modern:</div><ul class=\"examples\"><li><em>advanced weapon systems</em></li><li><em>advanced technology</em></li><li><em>high levels of unemployment in the advanced industrial societies</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> studying or dealing with a school subject at a difficult level:</div><ul class=\"examples\"><li><em>advanced learners of English</em></li><li><em>advanced physics</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> having reached a late point in time or development:</div><ul class=\"examples\"><li><em>The disease was too far advanced to be treated.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>advanced age/years</strong> used to talk about the age of someone who is old:</div><ul class=\"examples\"><li><em>Despite his advanced age, he often travelled abroad.</em></li></ul></div>","126":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧van‧tage</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈvɑːntɪdʒ $ ədˈvæn-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> something that helps you to be more successful than others, or the state of having this <em>OPP disadvantage</em></div><ul class=\"examples\"><li><strong><em>advantage over</strong>: Her experience meant that she had a big advantage over her opponent.</em></li><li><em>Younger workers tend to be at an advantage (=have an advantage) when applying for jobs.</em></li><li><em>It might be to your advantage (=it might help you) to take a computer course of some kind.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> a good or useful feature that something has</div><ul class=\"examples\"><li><strong><em>advantage of</strong>: One of the many advantages of living in New York is that you can eat out at almost any time of day.</em></li><li><strong><em>advantage over</strong>: This printer has several advantages over conventional printers.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>take advantage of somebody</strong> to treat someone unfairly in order to get what you want, especially someone who is generous or easily persuaded:</div><ul class=\"examples\"><li><em>Don’t lend them the car – they’re taking advantage of you!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>take advantage of something (to do something)</strong> to use a particular situation to do or get what you want:</div><ul class=\"examples\"><li><em>I took advantage of the good weather to paint the shed.</em></li><li><em>You’ll want to take full advantage of the beach-front clubs.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>use/turn something to your/good advantage</strong> to use something that you have or that happens in order to achieve something:</div><ul class=\"examples\"><li><em>How could he turn the situation to his advantage?</em></li><li><em>Burns used his family connections to good advantage.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>show something to (good/great) advantage</strong> to make the best features of someone or something very noticeable:</div><ul class=\"examples\"><li><em>Her dress showed her tanned skin to great advantage.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>advantage somebody</strong> used in tennis to show that the person named has won the next point after the score was 40–40</div></div>","127":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧van‧ta‧geous</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌædvənˈteɪdʒəs, ˌædvæn-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">helpful and likely to make you successful <em>OPP disadvantageous</em>:</div><ul class=\"examples\"><li><em>He was now in a more advantageous position.</em></li><li><strong><em>advantageous to</strong>: terms advantageous to foreign companies</em></li></ul></div>","128":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧vent</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈædvent/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><strong>the advent of something</strong> the time when something first begins to be widely used <em>SYN coming</em>:</div><ul class=\"examples\"><li><em>the advent of the computer</em></li></ul></div>","129":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧ven‧ture</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈventʃə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an exciting experience in which dangerous or unusual things happen:</div><ul class=\"examples\"><li><em>a great adventure</em></li><li><em>Ahab’s adventures at sea</em></li><li><em>an adventure story</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>sense/spirit of adventure</strong> willingness to try new things, take risks etc:</div><ul class=\"examples\"><li><em>Come on – where’s your sense of adventure?</em></li></ul></div>","130":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧ven‧tur‧ous</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈventʃərəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not afraid of taking risks or trying new things: ► see thesaurus at brave</div><ul class=\"examples\"><li><em>Andy isn’t a very adventurous cook.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also adventuresome<em>American English</em>) eager to go to new places and do exciting or dangerous things</div></div>","131":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧verb</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈædvɜːb $ -vɜːrb/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●●</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a word that adds to the meaning of a verb, an adjective, another adverb, or a whole sentence, such as ‘slowly’ in ‘He ran slowly’, ‘very’ in ‘It’s very hot’, or ‘naturally’ in ‘Naturally, we want you to come.’</div></div>","132":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧ver‧sa‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈædvəsəri $ ˈædvərseri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural adversaries)</span></div><div class=\"entry-body\"><div class=\"sense\"><em>formal</em> a country or person you are fighting or competing against <em>SYN opponent</em>:</div><ul class=\"examples\"><li><em>his old adversary</em></li></ul></div>","133":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧verse</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈædvɜːs $ -ɜːrs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not good or favourable:</div><ul class=\"examples\"><li><em>They fear it could have an adverse effect on global financial markets.</em></li><li><em>Miller’s campaign has received a good deal of adverse publicity.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>adverse conditions</strong> conditions that make it difficult for something to happen or exist:</div><ul class=\"examples\"><li><em>The expedition was abandoned because of adverse weather conditions.</em></li></ul></div>","134":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧vert</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈædvɜːt $ -ɜːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>British English</em> an advertisement ► see thesaurus at advertisement</div></div>","135":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧ver‧tise</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈædvətaɪz $ -ər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to tell the public about a product or service in order to persuade them to buy it:</div><ul class=\"examples\"><li><em>They no longer advertise alcohol or cigarettes at sporting events.</em></li><li><strong><em>advertise (something) on television/in a newspaper etc</strong>: Many companies will only advertise in the Sunday paper.</em></li><li><strong><em>be advertised as something</strong>: The inn is advertised as being from the early 16th century.</em></li><li><em>Colleges and universities have found that it pays to advertise (=advertising brings good results).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make an announcement, for example in a newspaper or on a poster, that a job is available, an event is going to happen etc:</div><ul class=\"examples\"><li><em>a poster advertising the concert</em></li><li><strong><em>advertise for</strong>: I see they’re advertising for a new Sales Director.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>advertise the fact (that)</strong> to let people know something about yourself:</div><ul class=\"examples\"><li><em>Don’t advertise the fact that you’re looking for another job.</em></li></ul></div>","136":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧ver‧tise‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈvɜːtəsmənt $ ˌædvərˈtaɪz-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (also ad<em>informal</em>, advert<em>British English</em>) a picture, set of words, or a short film, which is intended to persuade people to buy a product or use a service, or that gives information about a job that is available, an event that is going to happen etc</div><ul class=\"examples\"><li><strong><em>advertisement for</strong>: The Sunday papers are full of advertisements for cars. / She saw an advertisement for a ski vacation in Vermont.</em></li><li><em>They put an advertisement in ‘The Morning News’, offering a high salary for the right person.</em></li><li><em>The organizers of the concert had taken out a full page advertisement in ‘The New York Times’.</em></li><li><em>Only a handful of people answered the advertisement.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be an advertisement for something</strong> to be a good example of something or show how effective it can be:</div><ul class=\"examples\"><li><em>He’s a very good advertisement for the benefits of regular exercise.</em></li></ul></div>","137":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧ver‧tis‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈædvətaɪzɪŋ $ -ər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the activity or business of advertising things on television, in newspapers etc:</div><ul class=\"examples\"><li><em>advertising aimed at 18–25 year olds</em></li><li><em>a career in advertising</em></li><li><strong><em>television/radio/newspaper advertising</strong>: Both candidates are spending millions on television advertising.</em></li><li><strong><em>advertising campaign/strategy</strong>: a major advertising campaign / the advertising slogan ‘Come alive with Pepsi’</em></li></ul></div>","138":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧vice</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈvaɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">an opinion you give someone about what they should do:</div><ul class=\"examples\"><li><em>You should have followed my advice.</em></li><li><strong><em>advice on/about</strong>: advice on saving energy / I need some advice about my computer.</em></li><li><strong><em>on somebody’s advice</strong>: On her doctor’s advice (=because her doctor advised her) Smith decided to take early retirement.</em></li></ul></div>","139":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧vise</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈvaɪz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to tell someone what you think they should do, especially when you know more than they do about something:</div><ul class=\"examples\"><li><em>She needed someone to advise her.</em></li><li><strong><em>advise somebody to do something</strong>: Evans advised him to leave London. / You are strongly advised to take out medical insurance when visiting China.</em></li><li><strong><em>advise somebody against (doing) something</strong>: I’d advise you against saying anything to the press.</em></li><li><strong><em>advise that</strong>: Experts advise that you should avoid being in strong sunlight for long periods.</em></li><li><strong><em>advise caution/patience/restraint etc</strong> (=advise people to be careful, patient etc): The makers advise extreme caution when handling this material.</em></li><li><strong><em>I/we would advise somebody to do something</strong> (=used when advising someone what to do): I would advise you to speak to a doctor.</em></li><li><strong><em>‘ …,’ somebody advised</strong>: ‘Make sure that you keep the documents in a safe place,’ Otley advised him.</em></li><li><strong><em>somebody can advise</strong>: If you need more information, I’m sure your lawyer can advise.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to be employed to give advice on a subject about which you have special knowledge or skill</div><ul class=\"examples\"><li><strong><em>advise somebody on/about something</strong>: He advises us on tax matters.</em></li><li><strong><em>advise on something</strong>: She’s been asked to advise on training the new sales team.</em></li><li><strong><em>advise somebody on something</strong>: He advises us on tax matters.</em></li><li><strong><em>advise somebody (on) how/where/what/when</strong>: Matthew advises people how to invest their money.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> <em>formal</em> to tell someone about something</div><ul class=\"examples\"><li><strong><em>advise somebody of something</strong>: We’ll advise you of any changes in the delivery dates.</em></li><li><em>Keep us advised of (=continue to tell us about) any new developments.</em></li><li><strong><em>advise somebody that</strong>: They advised him that the tour would proceed.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>you would be well/ill advised to do something</strong> used to tell someone that it is wise or unwise to do something:</div><ul class=\"examples\"><li><em>You would be well advised to stay in bed and rest.</em></li></ul></div>","140":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧vis‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈvaɪzə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone whose job is to give advice because they know a lot about a subject, especially in business, law, or politics:</div><ul class=\"examples\"><li><em>a financial adviser</em></li></ul></div>","141":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧vi‧so‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ədˈvaɪzəri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">having the purpose of giving advice</div><ul class=\"examples\"><li><strong><em>advisory committee/body</strong>: the Environmental Protection Advisory Committee</em></li><li><strong><em>advisory role/capacity</strong>: He was employed in a purely advisory role.</em></li></ul></div>","142":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧vo‧cate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈædvəkeɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to publicly support a particular way of doing something: ► see thesaurus at recommend</div><ul class=\"examples\"><li><em>Extremists were openly advocating violence.</em></li><li><strong><em>advocate for<em>American English</em></strong>: Those who advocate for doctor-assisted suicide say the terminally ill should not have to suffer.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ad‧vo‧cate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈædvəkət, -keɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who publicly supports someone or something <em>SYN proponent</em></div><ul class=\"examples\"><li><strong><em>advocate of</strong>: She’s a passionate advocate of natural childbirth.</em></li><li><strong><em>advocate for</strong>: an advocate for the disabled</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a lawyer who speaks in a court of law, especially in Scotland</div></div></div>","143":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> aer‧i‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeəriəl $ ˈer-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> from a plane:</div><ul class=\"examples\"><li><em>an aerial attack</em></li><li><em>aerial photographs</em></li><li><em>an aerial view of the Three Gorges Dam project</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in or moving through the air</div></div>","144":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> aes‧thet‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /iːsˈθetɪk, es- $ es-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">connected with beauty and the study of beauty:</div><ul class=\"examples\"><li><em>From an esthetic point of view, it’s a nice design.</em></li><li><em>a work of great aesthetic appeal</em></li></ul></div>","145":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> af‧fair</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈfeə $ əˈfer/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[public/political activities]</strong> <strong>affairs</strong> <span class=\"gram\">[plural]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> public or political events and activities:</div><ul class=\"examples\"><li><em>Are you interested in world affairs?</em></li><li><em>the Ministry of Foreign Affairs</em></li><li><em>Women had little role in public affairs.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> things connected with your personal life, your financial situation etc: → state of affairs at state1(8)</div><ul class=\"examples\"><li><em>I am not prepared to discuss my financial affairs with the press.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[event]</strong> ► see thesaurus at event</div><div class=\"subsense\"><span class=\"subnum\">a)</span> an event or set of related events, especially one that is impressive or shocking:</div><ul class=\"examples\"><li><em>the Watergate affair</em></li><li><em>The whole affair was a disaster.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used when describing an event:</div><ul class=\"examples\"><li><em>The party was a very grand affair.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[relationship]</strong> a secret sexual relationship between two people, when at least one of them is married to someone else <em>SYN love affair</em></div><ul class=\"examples\"><li><strong><em>affair with</strong>: He had an affair with his boss that lasted six years.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[object]</strong> <em>informal</em> <em>old-fashioned</em> used when describing an object, machine etc:</div><ul class=\"examples\"><li><em>The computer was one of those little portable affairs.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be somebody’s affair</strong> if something is your affair, it only concerns you and you do not want anyone else to get involved in it:</div><ul class=\"examples\"><li><em>What I do in my free time is my affair.</em></li></ul></div>","146":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> af‧fect</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈfekt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to do something that produces an effect or change in something or in someone’s situation:</div><ul class=\"examples\"><li><em>the areas affected by the hurricane</em></li><li><em>a disease that affects the central nervous system</em></li><li><em>decisions which affect our lives</em></li><li><em>Trading has been adversely affected by the downturn in consumer spending.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make someone feel strong emotions: GRAMMAR Affect is often passive in this meaning.</div><ul class=\"examples\"><li><em>We were all deeply affected by her death.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>formal</em> to pretend to have a particular feeling, way of speaking etc:</div><ul class=\"examples\"><li><em>As usual, Simon affected complete boredom.</em></li><li><em>He used to affect a foreign accent.</em></li></ul></div>","147":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> af‧fec‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈfekʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[singular, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a feeling of liking or love and caring <em>SYN fondness</em></div><ul class=\"examples\"><li><strong><em>affection for</strong>: Bart had a deep affection for the old man.</em></li><li><em>She looked back on those days with affection.</em></li><li><em>Their father never showed them much affection.</em></li><li><em>The church was held in great affection (=loved and cared about a lot) by the local residents.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>somebody’s affections</strong> the feelings of love and caring that someone has:</div><ul class=\"examples\"><li><em>Africa has always had a special place in my affections.</em></li></ul></div>","148":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> af‧fec‧tion‧ate</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈfekʃənət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">showing in a gentle way that you love someone and care about them <em>SYN loving</em></div><ul class=\"examples\"><li><strong><em>affectionate towards</strong>: Jo is very affectionate towards her.</em></li><li><em>an affectionate hug</em></li></ul></div>","149":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> af‧fin‧i‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈfɪnəti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(plural affinities)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[singular]</span> a strong feeling that you like and understand someone or something</div><ul class=\"examples\"><li><strong><em>affinity with/for/between</strong>: his remarkable affinity with animals</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> a close relationship between two things because of qualities or features that they share</div><ul class=\"examples\"><li><strong><em>affinity with/between</strong>: the affinity between Christian and Chinese concepts of the spirit</em></li></ul></div>","150":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> af‧firm</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈfɜːm $ -ɜːrm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to state publicly that something is true <em>SYN confirm</em>:</div><ul class=\"examples\"><li><em>The general affirmed rumors of an attack.</em></li><li><strong><em>affirm that</strong>: A spokesman for the company affirmed that a merger was likely.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to strengthen a feeling, belief, or idea:</div><ul class=\"examples\"><li><em>He claims that modern physics affirms his Christian beliefs.</em></li></ul></div>","151":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> af‧flict</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈflɪkt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to affect someone or something in an unpleasant way, and make them suffer GRAMMAR Afflict is often passive in this meaning.</div><ul class=\"examples\"><li><strong><em>be afflicted with/by something</strong>: a country afflicted by famine</em></li></ul></div>","152":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> af‧flu‧ent</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæfluənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">having plenty of money, nice houses, expensive things etc <em>SYN wealthy</em>: ► see thesaurus at rich</div><ul class=\"examples\"><li><em>affluent families</em></li><li><strong><em>an affluent society/area etc</strong>: the affluent Côte d&#x27;Azur</em></li></ul></div>","153":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> af‧ford</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈfɔːd $ -ɔːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>can/could afford</strong> <span class=\"gram\">[usually negative]</span> GRAMMARAfford is followed by an infinitive with ‘to’: · I can’t afford to buy a car. ✗Don’t say: can’t afford buying | can’t afford buyGrammar guide ‒ VERBS</div><div class=\"subsense\"><span class=\"subnum\">a)</span> to have enough money to buy or pay for something</div><ul class=\"examples\"><li><strong><em>afford (to do) something</strong>: We can’t afford to go on vacation this year.</em></li><li><em>I couldn’t afford the rent on my own.</em></li><li><em>How can she afford to eat out every night?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to have enough time to do something:</div><ul class=\"examples\"><li><em>Dad can’t afford any more time off work.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> if you cannot afford to do something, you must not do it because it could cause serious problems for you</div><ul class=\"examples\"><li><strong><em>afford to do something</strong>: We can’t afford to wait any longer or we’ll miss the plane.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> to provide something or allow something to happen:</div><ul class=\"examples\"><li><em>The room affords a beautiful view over the city.</em></li><li><strong><em>afford (somebody) an opportunity/chance</strong>: It afforded her the opportunity to improve her tennis skills.</em></li><li><em>The new law will afford protection to employees.</em></li></ul></div>","154":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> af‧ford‧a‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈfɔːdəbəl $ -ɔːrd-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">cheap enough for most people to afford:</div><ul class=\"examples\"><li><em>affordable housing</em></li><li><em>This is a top-quality product at a very affordable price.</em></li></ul></div>","155":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧fraid</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈfreɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[not before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> frightened because you think that you may get hurt or that something bad may happen <em>SYN scared</em> ► see thesaurus at frightened RegisterIn everyday English, people often say scared rather than afraid:· I’m scared of heights.</div><ul class=\"examples\"><li><strong><em>be/feel afraid</strong>: There’s no need to be afraid.</em></li><li><strong><em>afraid of something</strong>: Many children are afraid of the dark.</em></li><li><strong><em>afraid of somebody</strong>: I was a little afraid of him when I first met him.</em></li><li><strong><em>afraid of doing something</strong>: Some old people are afraid of going out alone.</em></li><li><strong><em>afraid to do something</strong>: Zoe was afraid to go back into the house.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> worried that something bad will happen as a result of your actions</div><ul class=\"examples\"><li><strong><em>afraid (that)</strong>: He was afraid that the other kids would laugh at him. / She was half afraid that he would say no (=a little afraid).</em></li><li><strong><em>afraid of doing something</strong>: I didn’t tell her because I was afraid of upsetting her.</em></li><li><strong><em>afraid of something</strong>: The government was afraid of the reaction from the public.</em></li><li><strong><em>afraid to do something</strong>: Don’t be afraid to ask for help.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>afraid for somebody/something</strong> worried that something bad may happen to a particular person or thing:</div><ul class=\"examples\"><li><em>Her father looked ill and she was suddenly afraid for him.</em></li><li><em>Many of us were afraid for our jobs.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>I’m afraid</strong> <em>spoken</em> used to politely tell someone something that may annoy, upset, or disappoint them:</div><ul class=\"examples\"><li><em>That’s the most we can offer you, I’m afraid.</em></li><li><strong><em>afraid (that)</strong>: I’m afraid you’ve come to the wrong address.</em></li><li><em>‘Is she very ill?’ ‘I’m afraid so (=yes).’</em></li><li><em>‘Did you see him?’ ‘I’m afraid not (=no).’</em></li></ul></div>","156":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> af‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːftə $ ˈæftər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> when a particular event or time has happened, or when someone has done something <em>OPP before</em>:</div><ul class=\"examples\"><li><em>After the war many soldiers stayed in France.</em></li><li><em>I go swimming every day after work.</em></li><li><em>Do you believe in life after death?</em></li><li><em>The first attack started just after midnight.</em></li><li><em>David went to bed straight after (=immediately after) supper.</em></li><li><em>After you’d called the police, what did you do?</em></li><li><em>Zimmerman changed his name after he left Germany.</em></li><li><em>People still remember the 1958 revolution and what came after (=happened after it).</em></li><li><strong><em>after doing something</strong>: After leaving school, Mackay worked in a restaurant for a year.</em></li><li><strong><em>two days/three weeks etc after (something)</strong>: Ten years after he bought the painting, Carswell discovered that it was a fake.</em></li><li><strong><em>the day/week/year etc after (something)</strong> (=the next day, week etc): His car was outside your house the morning after Bob’s engagement party. / I’ll see you again tomorrow or the day after. / She retired from politics the year after she received the Nobel Prize.</em></li><li><strong><em>soon/not long/shortly after (something)</strong>: Not long after the wedding, his wife became ill. / The family moved to Hardingham in June 1983, and Sarah’s first child was born soon after.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> when a particular amount of time has passed <em>OPP before</em>:</div><ul class=\"examples\"><li><em>After ten minutes remove the cake from the oven.</em></li><li><em>You’ll get used to it after a while.</em></li><li><em>After months of negotiation, an agreement was finally reached.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> following someone or something else in a list or a piece of writing, or in order of importance:</div><ul class=\"examples\"><li><em>Whose name is after yours on the list?</em></li><li><em>The date should be written after the address.</em></li><li><em>After football, tennis is my favourite sport.</em></li><li><em>The UK is the world’s third largest arms producer, after the USA and Russia.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>American English</em> used when telling the time to say how many minutes have passed since a particular hour SYN past<em>British English</em>:</div><ul class=\"examples\"><li><em>The movie starts at a quarter (=fifteen minutes) after seven.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>day after day/year after year etc</strong> continuously for a very long time:</div><ul class=\"examples\"><li><em>He’s worked in that same office week after week, year after year, since he was 18.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> following someone in order to stop or speak to them:</div><ul class=\"examples\"><li><em>Go after him and apologize.</em></li><li><em>I heard someone running after me, and a voice called my name.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> in the direction of someone who has just left:</div><ul class=\"examples\"><li><em>‘Good luck,’ she called after me as I left.</em></li><li><em>Harry stood in the doorway gazing after her.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> when someone has left a place or has finished doing something:</div><ul class=\"examples\"><li><em>Remember to close the door after you.</em></li><li><em>I spend all day cleaning up after the kids.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> because of something that happened earlier:</div><ul class=\"examples\"><li><em>I’m not surprised he walked out, after the way she treated him.</em></li><li><em>After your letter, I didn’t think I’d ever see you again.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> in spite of something that was done in the past:</div><ul class=\"examples\"><li><em>How can you treat me like this after all I’ve done for you?</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> when you have passed a particular place or travelled a certain distance along a road:</div><ul class=\"examples\"><li><em>Turn left after the hotel.</em></li><li><em>After a mile you will come to a crossroads.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>be after somebody/something</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be looking for someone or something:</div><ul class=\"examples\"><li><em>That boy’s always in trouble – the police are after him again.</em></li><li><em>‘Were you after anything in particular?’ ‘No, we’re just looking.’</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>informal</em> to want to have something that belongs to someone else:</div><ul class=\"examples\"><li><em>I think Chris is after my job.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>one after another/one after the other</strong> if a series of events or actions happen one after another, each one happens soon after the previous one:</div><ul class=\"examples\"><li><em>Ever since we moved here it’s been one problem after another.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>after all</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> in spite of what you thought was true or expected to happen:</div><ul class=\"examples\"><li><em>He wrote to say they couldn’t give me a job after all.</em></li><li><em>Union leaders announced that they would, after all, take part in the national conference.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to say that something should be remembered or considered, because it helps to explain what you have just said:</div><ul class=\"examples\"><li><em>Prisoners should be treated with respect – they are human beings after all.</em></li><li><em>I don’t know why you’re so concerned – it isn’t your problem after all.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <em>especially British English</em> used to say who or what first had the name that someone or something has been given:</div><ul class=\"examples\"><li><em>His name is Alessandro, after his grandfather.</em></li><li><em>It was named Waterloo Bridge, after the famous battle.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <em>formal</em> in the same style as a particular painter, musician etc:</div><ul class=\"examples\"><li><em>a painting after Rembrandt</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> <strong>after you</strong> <em>spoken</em> used to say politely that someone else can use or do something before you do:</div><ul class=\"examples\"><li><em>‘Do you need the copier?’ ‘After you.’</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>after you with something</strong> used to ask someone if you can have or use something after they have finished:</div><ul class=\"examples\"><li><em>After you with that knife, please.</em></li></ul></div>","157":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈafter-efˌfect</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːftərɪfekt $ ˈæf-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable usually plural]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a bad effect that continues for a long time after the thing that caused it</div><ul class=\"examples\"><li><strong><em>the after-effects (of something)</strong>: the after-effects of his illness</em></li></ul></div>","158":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> af‧ter‧math</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːftəmæθ $ ˈæftər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[singular]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the period of time after something such as a war, storm, or accident when people are still dealing with the results</div><ul class=\"examples\"><li><strong><em>aftermath of</strong>: the danger of disease in the aftermath of the earthquake</em></li></ul></div>","159":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> af‧ter‧noon</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɑːftəˈnuːn◂ $ ˌæftər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the part of the day after the morning and before the evening → morning, evening:</div><ul class=\"examples\"><li><em>There’s a meeting on Thursday afternoon.</em></li><li><em>It was very hot in the afternoon.</em></li><li><em>See you tomorrow afternoon.</em></li><li><em>Are you going into town this afternoon?</em></li><li><em>We met in the early afternoon.</em></li><li><em>By late afternoon, Micky had changed his mind.</em></li><li><em>He was having his afternoon nap.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>afternoons</strong> during the afternoon every day:</div><ul class=\"examples\"><li><em>She only works afternoons.</em></li></ul></div>","160":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> af‧ter‧wards</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːftəwədz $ ˈæftərwərdz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\">after an event or time that has already been mentioned: ► see thesaurus at after</div><ul class=\"examples\"><li><em>Charles arrived shortly afterwards.</em></li><li><strong><em>days/weeks etc afterwards</strong>: The experience haunted me for years afterwards.</em></li><li><em>She died not long afterwards.</em></li><li><em>Afterwards, I was asked to write a book.</em></li></ul></div>","161":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧gain</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈɡen, əˈɡeɪn $ əˈɡen/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> one more time – used when something has happened or been done before:</div><ul class=\"examples\"><li><em>Can you say that again? I didn’t hear.</em></li><li><em>I’ll never go there again.</em></li><li><em>Mr Khan’s busy. Can you try again later?</em></li><li><strong><em>once again/yet again</strong> (=used to emphasize that something has happened several or many times before): In 1997, the family moved house yet again. / Once again, Drew was under arrest.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> back to the same state or situation that you were in before:</div><ul class=\"examples\"><li><em>She stayed and nursed him back to health again.</em></li><li><em>It’s great to have you home again.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>all over again</strong> if you do something all over again, you repeat it from the beginning:</div><ul class=\"examples\"><li><em>I had to write the essay all over again.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>as much/as many/the same again</strong> the same amount or number as you have just had, said etc:</div><ul class=\"examples\"><li><em>What a fantastic lunch. I could eat the same again.</em></li><li><em>Nearly as many again died from pneumonia.</em></li><li><em>The amount of crime is about half as much again (=the same in addition to half that amount) as it was in 1973.</em></li><li><em>‘Another drink?’ ‘Yes, same again (=the same drink again), please.’</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>spoken</em> used to give a fact or opinion that explains or adds to something you have just said:</div><ul class=\"examples\"><li><em>And again, these workshops will benefit the community widely.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>then/there again</strong> <em>spoken</em> used to introduce an idea or fact that is different from something you have just said, or makes it seem less likely to be true:</div><ul class=\"examples\"><li><em>She says she’s thirty-five. But then again she might be lying.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>again and again/time and (time) again/over and over again</strong> very often – used to show disapproval:</div><ul class=\"examples\"><li><em>I’ve told you again and again, don’t do that!</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <em>spoken</em> used when you want someone to repeat information that they have already given you:</div><ul class=\"examples\"><li><em>What did you say your name was again?</em></li></ul></div>","162":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧gainst</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈɡenst, əˈɡeɪnst $ əˈɡenst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to say that someone opposes or disagrees with something:</div><ul class=\"examples\"><li><em>Every council member voted against the proposal.</em></li><li><em>those who are campaigning against the new road</em></li><li><em>He advised me against travelling.</em></li><li><em>Mr Howard has declared that he is against all forms of racism.</em></li><li><em>the fight against terrorism</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to say that an action is not wanted or approved of by someone:</div><ul class=\"examples\"><li><em>They got married against her parents’ wishes (=although they knew her parents did not want them to).</em></li><li><em>She has been kept in the house against her will (=she does not want to stay in the house).</em></li><li><em>The use of certain drugs is against the law (=illegal).</em></li><li><em>It’s against my principles to borrow money (=I do not believe it is right).</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> used to say that something is not allowed by a law or rule:</div><ul class=\"examples\"><li><em>There ought to be a law against it.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to say who someone is competing with or trying to defeat in a game, battle etc:</div><ul class=\"examples\"><li><em>Gambotti was injured in last Saturday’s game against the Lions.</em></li><li><em>We’ll be competing against the best companies in Europe.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to say who is harmed, threatened, or given a disadvantage:</div><ul class=\"examples\"><li><em>violence against elderly people</em></li><li><em>crimes against humanity</em></li><li><em>discrimination against women</em></li><li><em>There had been death threats against prison staff.</em></li><li><em>Your lack of experience could count against you.</em></li><li><em>The regulations tend to work against smaller companies.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used to say that something touches, hits, or rubs a surface:</div><ul class=\"examples\"><li><em>the sound of the rain drumming against my window</em></li><li><em>The car skidded and we could hear the crunch of metal against metal.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> next to and touching an upright surface, especially for support:</div><ul class=\"examples\"><li><em>There was a ladder propped up against the wall.</em></li><li><em>The younger policeman was leaning against the bureau with his arms folded.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> in the opposite direction to the movement or flow of something <em>OPP with</em>:</div><ul class=\"examples\"><li><em>sailing against the wind</em></li><li><em>She dived down and swam out strongly against the current.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> seen with something else behind or as a background:</div><ul class=\"examples\"><li><em>He could see a line of figures silhouetted against the sky.</em></li><li><em>It is important to know what colours look good against your skin.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> used to show that you are considering particular events in relation to other events that are happening at the same time:</div><ul class=\"examples\"><li><em>The reforms were introduced against a background of social unrest.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> used to say what you are comparing something with:</div><ul class=\"examples\"><li><em>The pound has fallen 10% against the dollar.</em></li><li><em>She checked the contents of the box against the list.</em></li><li><em>The cost of the proposed research needs to be balanced against its benefits.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> used to say who or what you are trying to protect someone or something from:</div><ul class=\"examples\"><li><em>insurance against accident and sickness</em></li><li><em>a cream to protect against sunburn</em></li><li><em>a vaccine which is effective against pneumonia</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> used to say who is said or shown to have done something wrong:</div><ul class=\"examples\"><li><em>He has always emphatically denied the allegations against him.</em></li><li><em>The evidence against you is overwhelming.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>be/come up against somebody/something</strong> to have to deal with a difficult opponent or problem:</div><ul class=\"examples\"><li><em>You see, this is what we’re up against – the suppliers just aren’t reliable.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>have something against somebody/something</strong> to dislike or disapprove of someone or something:</div><ul class=\"examples\"><li><em>I don’t have anything against babies. I just don’t feel very comfortable with them.</em></li></ul></div>","163":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /eɪdʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[how old]</strong> <span class=\"gram\">[countable, uncountable]</span> the number of years someone has lived or something has existed → old: RegisterIn everyday English, people usually use the expression how old …? rather than using the noun age: What age is your brother? ➔ How old is your brother? | They asked me my age. ➔ They asked me how old I was.</div><ul class=\"examples\"><li><em>Francis is the same age as me.</em></li><li><em>Experts disagree over the age of the drawings.</em></li><li><em>Dad retired at the age of 56.</em></li><li><strong><em>at age 5/18 etc</strong>: In Britain, schooling starts at age 5.</em></li><li><strong><em>4/15 etc years of age</strong> (=4, 15 etc years old): She was just over 16 years of age.</em></li><li><strong><em>at my/your etc age</strong> (=when you are as old as me etc): At my age, it’s quite difficult getting up the stairs.</em></li><li><strong><em>over/under the age of 5/18 etc</strong>: people over the age of 65</em></li><li><strong><em>for his/her etc age</strong> (=compared with other people of the same age): She’s tall for her age, isn’t she?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[legal age]</strong> <span class=\"gram\">[uncountable]</span> the age when you are legally old enough to do something:</div><ul class=\"examples\"><li><em>What’s the minimum age for getting a driver’s license?</em></li><li><em>You’re not allowed to buy alcohol. You’re under age (=too young by law).</em></li><li><em>The normal retirement age is 65.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[period of life]</strong> <span class=\"gram\">[countable, uncountable]</span> one of the particular periods of someone’s life:</div><ul class=\"examples\"><li><em>When you get to old age, everything seems to take longer.</em></li><li><em>The early teens are often a difficult age.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[being old]</strong> <span class=\"gram\">[uncountable]</span> the state of being old → youth</div><ul class=\"examples\"><li><strong><em>with age</strong>: High blood pressure increases with age. / Some of the furniture was showing signs of age.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[period of history]</strong> <span class=\"gram\">[countable usually singular]</span> a particular period of history <em>SYN era</em>: → in this day and age at day(6) ► see thesaurus at period</div><ul class=\"examples\"><li><em>We are living in the age of technology.</em></li><li><em>Molecular biology is pushing medicine into a new age.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>ages</strong> <span class=\"gram\">[plural]</span> (also an age) <em>especially British English</em> <em>informal</em> a long time:</div><ul class=\"examples\"><li><em>Simon! I haven’t seen you for ages.</em></li><li><em>That recipe takes ages.</em></li><li><strong><em>it’s ages since/before/until etc something</strong>: It’s ages since we’ve played that game.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>come of age</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to reach the age when you are legally considered to be a responsible adult</div><div class=\"subsense\"><span class=\"subnum\">b)</span> if something comes of age, it reaches a stage of development at which people accept it as being important, valuable etc:</div><ul class=\"examples\"><li><em>During this period the movies really came of age as an art form.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(present participle aging or ageing British English)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to start looking older or to make someone or something look older:</div><ul class=\"examples\"><li><em>He was worried to see how much she’d aged.</em></li><li><em>The experience had aged him in advance of his years.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> to become older:</div><ul class=\"examples\"><li><em>The buildings are ageing, and some are unsafe.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive]</span> to improve and develop in taste over a period of time, or to allow food or alcohol to do this <em>SYN mature</em>:</div><ul class=\"examples\"><li><em>Cheddar cheese ages well.</em></li><li><em>The whisky is aged for at least ten years.</em></li></ul></div></div>","164":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /eɪdʒd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><strong>aged 5/25 etc</strong> 5 etc years old</div><ul class=\"examples\"><li><strong><em>aged between</strong>: Police are looking for a man aged between 30 and 35.</em></li><li><em>The course is open to children aged 12 and over.</em></li></ul></div>","165":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧gen‧cy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeɪdʒənsi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural agencies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a business that provides a particular service for people or organizations → dating agency, news agency</div><ul class=\"examples\"><li><strong><em>an advertising/employment/travel etc agency</strong>: a local housing agency</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an organization or department, especially within a government, that does a specific job:</div><ul class=\"examples\"><li><em>a UN agency responsible for helping refugees</em></li><li><em>the Environmental Protection Agency</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>by/through the agency of somebody</strong> <em>formal</em> being done as the result of someone’s help</div></div>","166":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧gen‧da</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈdʒendə/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a list of problems or subjects that a government, organization etc is planning to deal with</div><ul class=\"examples\"><li><strong><em>be high on the agenda/be top of the agenda</strong> (=be one of the most important problems to deal with): Measures to combat terrorism will be high on the agenda. / The government set an agenda for constitutional reform.</em></li><li><strong><em>political/economic/legislative/domestic etc agenda</strong>: Our Centre has limited its research agenda to four areas.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the ideas that a political party thinks are important and the things that party aims to achieve:</div><ul class=\"examples\"><li><em>The Republicans have stuck to their conservative agenda.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a list of the subjects to be discussed at a meeting:</div><ul class=\"examples\"><li><em>the next item (=subject) on the agenda</em></li></ul></div>","167":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧gent</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeɪdʒənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a person or company that represents another person or company, especially in business: → estate agent, land agent, real estate agent, travel agent</div><ul class=\"examples\"><li><em>Our agent in Rio deals with all our Brazilian business.</em></li><li><strong><em>agent for</strong>: We’re acting as agents for Mr Watson.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who finds work for actors, musicians etc, or who finds someone to publish a writer’s work:</div><ul class=\"examples\"><li><em>My agent has a new script for me to look at.</em></li><li><em>a literary agent</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> someone who works for a government or police department, especially in order to get secret information about another country or organization: → secret agent, double agent</div><ul class=\"examples\"><li><em>an intelligence agent</em></li><li><em>an FBI agent</em></li><li><em>an undercover (=secret) agent</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>technical</em> a chemical or substance that is used for a particular purpose or that has a particular effect:</div><ul class=\"examples\"><li><em>Soap is a cleansing agent.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> someone or something that affects or changes a situation → free agent</div><ul class=\"examples\"><li><strong><em>agent for/of change</strong>: Technological advances are the chief agents of change.</em></li></ul></div>","168":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ag‧gra‧vate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæɡrəveɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make a bad situation, an illness, or an injury worse <em>OPP improve</em>:</div><ul class=\"examples\"><li><em>Their money problems were further aggravated by a rise in interest rates.</em></li><li><em>Building the new road will only aggravate the situation.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make someone angry or annoyed <em>SYN irritate</em>:</div><ul class=\"examples\"><li><em>What really aggravates me is the way she won’t listen.</em></li></ul></div>","169":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ag‧gres‧sion</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈɡreʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> angry or threatening behaviour or feelings that often result in fighting:</div><ul class=\"examples\"><li><em>Television violence can encourage aggression in children.</em></li><li><strong><em>aggression towards</strong>: Our dogs have never shown aggression towards other dogs.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the act of attacking a country, especially when that country has not attacked first:</div><ul class=\"examples\"><li><em>an unprovoked act of aggression</em></li><li><strong><em>aggression against</strong>: Athenian aggression against Persia</em></li></ul></div>","170":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ag‧gres‧sive</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈɡresɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> behaving in an angry threatening way, as if you want to fight or attack someone:</div><ul class=\"examples\"><li><em>Jim’s voice became aggressive.</em></li><li><em>Teachers apparently expect a certain amount of aggressive behaviour from boys.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> very determined to succeed or get what you want:</div><ul class=\"examples\"><li><em>A successful businessman has to be aggressive.</em></li><li><em>an aggressive marketing campaign</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> an aggressive disease spreads quickly in the body:</div><ul class=\"examples\"><li><em>an aggressive form of breast cancer</em></li></ul></div>","171":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧gile</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈædʒaɪl $ ˈædʒəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> able to move quickly and easily:</div><ul class=\"examples\"><li><em>Dogs are surprisingly agile.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who has an agile mind is able to think very quickly and intelligently:</div><ul class=\"examples\"><li><em>He was physically strong and mentally agile.</em></li></ul></div>","172":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧go</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈɡəʊ $ əˈɡoʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\">used to show how far back in the past something happened</div><ul class=\"examples\"><li><strong><em>5 minutes/an hour/20 years etc ago</strong>: Her husband died 14 years ago.</em></li><li><strong><em>long ago/a long time ago</strong>: He should have finished at university long ago, but he kept taking extra courses.</em></li><li><strong><em>a minute/moment ago</strong>: The little girl you saw a moment ago was my niece.</em></li><li><strong><em>a little/short while ago</strong>: Tom got a letter from him just a little while ago.</em></li><li><em>They moved to a new house some time ago (=a fairly long time ago).</em></li><li><em>We had our bicentenary celebrations not that long ago.</em></li></ul></div>","173":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ag‧o‧ny</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæɡəni/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural agonies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> very severe pain: ► see thesaurus at pain</div><ul class=\"examples\"><li><em>the agony of arthritis</em></li><li><strong><em>in agony</strong>: I was in agony. / He groaned in agony.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a very sad, difficult, or unpleasant experience:</div><ul class=\"examples\"><li><em>It was agony not knowing if she would live.</em></li><li><strong><em>agony of</strong>: He was in agonies of remorse.</em></li></ul></div>","174":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧gree</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈɡriː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[same opinion]</strong> <span class=\"gram\">[intransitive, transitive]</span> to have or express the same opinion about something as someone else <em>OPP disagree</em>:</div><ul class=\"examples\"><li><em>Teenagers and their parents rarely agree.</em></li><li><strong><em>agree with</strong>: If she felt he was right, she would agree with him.</em></li><li><strong><em>agree that</strong>: Most people nowadays would agree that a good pub is one of our best traditions.</em></li><li><strong><em>agree on/about</strong>: We don’t agree on everything, of course.</em></li><li><strong><em>I quite agree/I couldn’t agree more</strong> (=I agree completely): ‘We have to talk.’ ‘Absolutely,’ Meredith replied. ‘I couldn’t agree more.’</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[say yes]</strong> <span class=\"gram\">[intransitive, transitive]</span> to say yes to an idea, plan, suggestion etc <em>OPP refuse</em>:</div><ul class=\"examples\"><li><em>I suggested we go somewhere for the weekend and she agreed at once.</em></li><li><strong><em>agree to do something</strong>: No one really knows why he agreed to do the film.</em></li><li><strong><em>agree to</strong>: My sister won’t agree to our mother going into a nursing home.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[decide together]</strong> <span class=\"gram\">[intransitive, transitive]</span> to make a decision with someone after a discussion with them GRAMMARIn more formal English, you say it was agreed that when saying what people agreed: · It was agreed that the post would be advertised.</div><ul class=\"examples\"><li><strong><em>agree to do something</strong>: We agreed to meet again the following Monday.</em></li><li><strong><em>agree on</strong>: They managed to agree on a date for the wedding.</em></li><li><strong><em>agree that</strong>: We agreed that elections would be held in May.</em></li><li><strong><em>agree a price/plan/strategy etc</strong>: We agreed a new four-year contract.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[be the same]</strong> <span class=\"gram\">[intransitive]</span> if two pieces of information agree with each other, they match or are the same</div><ul class=\"examples\"><li><strong><em>agree with</strong>: Your story doesn’t agree with what the police have told us.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>agree to differ/disagree</strong> if two people agree to differ, they accept that they have different opinions about something and stop arguing about it</div></div>","175":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧greed</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈɡriːd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an agreed plan, price, arrangement etc is one that people have discussed and accepted:</div><ul class=\"examples\"><li><em>The important thing is to have agreed objectives.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be agreed</strong> if people are agreed, they have discussed something and agree about what to do</div><ul class=\"examples\"><li><strong><em>agreed on</strong>: All parties are now agreed on the plan.</em></li><li><strong><em>be agreed that</strong>: We’re all agreed that we cannot spend what we have not earned.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>Agreed</strong> used to check if someone agrees, or to show that you agree:</div><ul class=\"examples\"><li><em>‘Let’s just forget it ever happened. Agreed?’ ‘Agreed.’</em></li></ul></div>","176":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧gree‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈɡriːmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> an arrangement or promise to do something, made by two or more people, companies, organizations etc</div><ul class=\"examples\"><li><strong><em>agreement that</strong>: They had made an agreement that they would share the profits equally.</em></li><li><strong><em>agreement with</strong>: Haydon came to an agreement with his creditors.</em></li><li><strong><em>agreement on</strong>: an agreement on arms reduction</em></li><li><strong><em>under an agreement</strong>: Under the agreement, most agricultural prices will remain at the same level.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> when people have the same opinion as each other <em>OPP disagreement</em></div><ul class=\"examples\"><li><strong><em>agreement that</strong>: There is general agreement that copyright is a good idea.</em></li><li><strong><em>agreement on</strong>: There is widespread agreement on the need for prison reform.</em></li><li><strong><em>be in agreement</strong>: A decision will not be made until everyone is in agreement.</em></li><li><em>It is easier for two parties to reach agreement than for three.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> when someone says yes to an idea, plan, suggestion etc</div><ul class=\"examples\"><li><strong><em>agreement to do something</strong>: Would their discussion result in his agreement to visit his stepmother?</em></li><li><strong><em>agreement of</strong>: Such arrangements cannot be altered without the agreement of the bank.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> an official document that people sign to show that they have agreed to something:</div><ul class=\"examples\"><li><em>Please read the agreement and sign it.</em></li><li><em>a hire purchase agreement</em></li></ul></div>","177":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ag‧ri‧cul‧ture</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæɡrɪˌkʌltʃə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the practice or science of farming:</div><ul class=\"examples\"><li><em>More than 75% of the land is used for agriculture.</em></li></ul></div>","178":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧head</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈhed/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[in front]</strong> a short distance in front of someone or something <em>OPP behind</em>:</div><ul class=\"examples\"><li><em>He kept his gaze fixed on the car ahead.</em></li><li><strong><em>ahead of</strong>: A hill loomed ahead of them.</em></li><li><em>We could see the lights of Las Vegas up ahead.</em></li><li><strong><em>some/a little/a long way ahead</strong>: The clinic was now in sight, some way ahead.</em></li><li><strong><em>straight/dead ahead</strong> (=straight in front): The river is eight miles away dead ahead.</em></li><li><em>Henry hurried on ahead (=went in front of the others).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[forward]</strong> if someone or something looks or moves ahead, they look or move forward:</div><ul class=\"examples\"><li><em>He stared straight ahead.</em></li><li><em>The ship forged ahead through the thin ice.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[before somebody else]</strong> before someone else</div><ul class=\"examples\"><li><strong><em>ahead of</strong>: There were four people ahead of me at the doctor’s.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[future]</strong> in the future</div><ul class=\"examples\"><li><strong><em>ahead of</strong>: You have a long trip ahead of you.</em></li><li><em>Problems may lie ahead.</em></li><li><strong><em>the years/days/months etc ahead</strong>: We do not foresee any major changes in the years ahead.</em></li><li><em>Unless we plan ahead (=plan for the future) we are going to be in a mess.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[before an event]</strong> before an event happens <em>SYN in advance</em>:</div><ul class=\"examples\"><li><em>I cook rice two or three hours ahead.</em></li><li><em>Can you tell me ahead of time if you’re coming?</em></li><li><strong><em>ahead of</strong>: He’s giving a series of concerts in London ahead of his international tour.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>ahead of schedule</strong> earlier than planned or arranged:</div><ul class=\"examples\"><li><em>I arrived at Jack’s suite half an hour ahead of schedule.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[progress/success]</strong> making progress and being successful in your job, education etc</div><ul class=\"examples\"><li><strong><em>get/keep/stay ahead</strong>: Getting ahead at work is the most important thing to her at the moment.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[advanced]</strong> ideas, achievements etc that are ahead of others have made more progress or are more developed:</div><ul class=\"examples\"><li><em>This design is light years ahead (=much more advanced) in performance and comfort.</em></li><li><strong><em>ahead of your/its time</strong> (=very advanced or new, and not understood or accepted): Coleridge was in many ways far ahead of his time.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[WINNING]</strong> winning in a competition or election:</div><ul class=\"examples\"><li><em>Two shots from Gardner put the Giants 80–75 ahead.</em></li><li><em>We are 10 points ahead in the polls.</em></li><li><strong><em>ahead of</strong>: At this stage, Smith appeared to be ahead of his rivals.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>go ahead</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>spoken</em> used to tell someone they can do something:</div><ul class=\"examples\"><li><em>‘Can I have the sports section?’ ‘Yeah, go ahead, I’ve read it.’</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to do something that was planned, especially in spite of a problem</div><ul class=\"examples\"><li><strong><em>ahead with</strong>: Frank’ll be late but we’ll go ahead with the meeting anyway.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> to take place: → go-ahead1</div><ul class=\"examples\"><li><em>Tests of anti-cancer drugs are to go ahead this year.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>ahead of the game/curve</strong> <em>informal</em> in a position where you are more advanced or more successful than your competitors:</div><ul class=\"examples\"><li><em>Belmont city leaders have never been ahead of the curve in environmental matters.</em></li></ul></div>","179":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /eɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> help, such as money or food, given by an organization or government to a country or to people who are in a difficult situation:</div><ul class=\"examples\"><li><em>Foreign aid from many countries poured into the famine area.</em></li><li><em>convoys delivering humanitarian aid</em></li><li><em>a substantial aid programme</em></li><li><em>He has been granted legal aid (=free legal services).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> help that you need to do a particular thing</div><ul class=\"examples\"><li><strong><em>with/without the aid of something</strong>: Father Poole walked painfully, with the aid of a stick.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in aid of something</strong> in order to help a charity:</div><ul class=\"examples\"><li><em>We’re collecting money in aid of cancer research.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> help or advice that is given to someone who needs it</div><ul class=\"examples\"><li><strong><em>come/go to somebody’s aid</strong> (=help someone): I didn’t speak any French, but a nice man came to my aid.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> something such as a machine or tool that helps someone do something:</div><ul class=\"examples\"><li><em>A video is a useful aid in the classroom.</em></li><li><em>a hearing aid</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>what’s this in aid of?</strong> <em>British English</em> <em>spoken</em> used to ask what something is used for or why someone is doing something:</div><ul class=\"examples\"><li><em>What’s this meeting tomorrow in aid of, then?</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> an American spelling of aide</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to help someone do something: ► see thesaurus at help</div><ul class=\"examples\"><li><em>an index to aid the reader</em></li><li><strong><em>aid somebody in/with (doing) something</strong>: Mrs Coxen was aided in looking after the children by her niece.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make something happen more quickly or easily:</div><ul class=\"examples\"><li><em>Welfare spending aids economic development in three ways.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>aid and abet</strong> <em>law</em> to help someone do something illegal</div></div></div>","180":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /eɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone whose job is to help someone who has an important job, especially a politician:</div><ul class=\"examples\"><li><em>a presidential aide</em></li></ul></div>","181":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ail‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeɪlmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">an illness that is not very serious: ► see thesaurus at illness</div><ul class=\"examples\"><li><em>minor ailments</em></li></ul></div>","182":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /eɪm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> something you hope to achieve by doing something ► see thesaurus at purpose</div><ul class=\"examples\"><li><strong><em>aim of</strong>: The aim of the research is to find new food sources.</em></li><li><em>The main aim of the course is to improve your writing.</em></li><li><strong><em>with the aim of doing something</strong>: a campaign with the aim of helping victims of crime</em></li><li><em>Teamwork is required in order to achieve these aims.</em></li><li><em>a policy which sets out the school’s aims and objectives</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>take aim</strong> to point a gun or weapon at someone or something you want to shoot</div><ul class=\"examples\"><li><strong><em>aim at</strong>: Alan took aim at the target.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>take aim at somebody/something</strong> <em>American English</em> to criticize someone or something:</div><ul class=\"examples\"><li><em>Critics took aim at the president.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> someone’s ability to hit what they are aiming at when they throw or shoot something:</div><ul class=\"examples\"><li><em>Val’s aim was very good.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to try or intend to achieve something</div><ul class=\"examples\"><li><strong><em>aim to do something</strong>: We aim to finish by Friday.</em></li><li><strong><em>be aimed at doing something</strong>: an initiative aimed at reducing road accidents</em></li><li><strong><em>aim for something</strong>: We’re aiming for a big improvement.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>aim something at somebody</strong> to say or do something that is intended for a particular person or group of people:</div><ul class=\"examples\"><li><em>The anti-smoking campaign is aimed at teenagers.</em></li><li><em>The criticism wasn’t aimed at you.</em></li><li><em>He aimed his attacks at his opponent, calling him a &quot;political dinosaur.&quot;</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive]</span> to choose the place, person etc that you want to hit or reach and point a weapon or another object towards them:</div><ul class=\"examples\"><li><em>Denver aimed his gun but did not shoot.</em></li><li><strong><em>aim at/for</strong>: The pilot was aiming for the runway but came down in a nearby field.</em></li></ul></div></div>","183":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /eə $ er/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[gas]</strong> <span class=\"gram\">[uncountable]</span> the mixture of gases around the Earth, that we breathe: → a breath of fresh air at breath(2)</div><ul class=\"examples\"><li><em>Let’s go outside and get some fresh air.</em></li><li><em>You need to put some air in the tyres.</em></li><li><strong><em>in the air</strong>: There was a strong smell of burning in the air.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[space above the ground]</strong> <strong>the air</strong> the space above the ground or around things</div><ul class=\"examples\"><li><strong><em>into the air</strong>: Flames leapt into the air.</em></li><li><strong><em>through the air</strong>: He fell 2,000 metres through the air without a parachute.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[planes]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <strong>by air</strong> travelling by, or using, a plane:</div><ul class=\"examples\"><li><em>I’d prefer to travel by air.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> relating to or involving planes:</div><ul class=\"examples\"><li><em>the victims of Britain’s worst air disaster</em></li><li><em>Air travel was growing rapidly.</em></li><li><em>air traffic congestion</em></li><li><em>His brother died in an air crash.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be in the air</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if a feeling is in the air, a lot of people feel it at the same time:</div><ul class=\"examples\"><li><em>There was a sense of excitement in the air.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to be going to happen very soon:</div><ul class=\"examples\"><li><em>Change is in the air.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[appearance]</strong> <span class=\"gram\">[singular]</span> if something or someone has an air of confidence, mystery etc, they seem confident, mysterious etc</div><ul class=\"examples\"><li><strong><em>air of</strong>: She had an air of quiet confidence.</em></li><li><em>She looked at him with a determined air.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be up in the air</strong> if something is up in the air, no decision has been made about it yet:</div><ul class=\"examples\"><li><em>Our trip is still very much up in the air.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>be on/off (the) air</strong> to be broadcasting on the radio or television at the present moment, or to stop broadcasting:</div><ul class=\"examples\"><li><em>We’ll be on air in three minutes.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[music]</strong> <span class=\"gram\">[countable]</span> a simple tune, often used in the title of a piece of classical music</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>airs</strong> <span class=\"gram\">[plural]</span> a way of behaving that shows someone thinks they are more important than they really are</div><ul class=\"examples\"><li><strong><em>put on airs/give yourself airs</strong>: Trudy is always putting on airs.</em></li><li><em>an actor with no airs and graces</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>be walking/floating on air</strong> to feel very happy</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[opinion]</strong> <span class=\"gram\">[transitive]</span> to express your opinions publicly ► see thesaurus at say</div><ul class=\"examples\"><li><strong><em>air your views/grievances/complaints etc</strong>: Staff will get a chance to ask questions and air their views.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[tv/radio]</strong> <span class=\"gram\">[intransitive, transitive]</span> to broadcast a programme on television or radio:</div><ul class=\"examples\"><li><em>KPBS airs such popular children’s programs as ‘Barney’ and ‘Sesame Street’.</em></li><li><em>The program is due to air next month.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[room]</strong> <span class=\"gram\">[transitive]</span> <em>especially British English</em>, air something out<em>American English</em> to let fresh air into a room, especially one that has been closed for a long time</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[clothes]</strong> <span class=\"gram\">[intransitive, transitive]</span> <em>especially British English</em>, air (something) out<em>American English</em> to put a piece of clothing in a place that is warm or has a lot of air, so that it smells clean:</div><ul class=\"examples\"><li><em>I’ve left my sweater outside to air.</em></li></ul></div></div>","184":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈair force</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the part of a country’s military organization that uses planes to fight → army, navy</div></div>","185":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> air‧craft</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeəkrɑːft $ ˈerkræft/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural aircraft)</span></div><div class=\"entry-body\"><div class=\"sense\">a plane or other vehicle that can fly</div></div>","186":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> air‧line</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeəlaɪn $ ˈer-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a company that takes passengers and goods to different places by plane:</div><ul class=\"examples\"><li><em>an airline pilot</em></li></ul></div>","187":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> air‧port</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeəpɔːt $ ˈerpɔːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a place where planes take off and land, with buildings for passengers to wait in → airfield:</div><ul class=\"examples\"><li><em>The plane landed at Heathrow Airport.</em></li><li><em>Her family went to see her off at the airport.</em></li></ul></div>","188":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /aɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a long passage between rows of seats in a church, plane, theatre etc, or between rows of shelves in a shop:</div><ul class=\"examples\"><li><em>Would you like a window seat or an aisle seat (=seat next to the aisle)?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>go/walk down the aisle</strong> <em>informal</em> to get married</div></div>","189":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧jar</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈdʒɑː $ əˈdʒɑːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[not before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a door that is ajar is slightly open</div></div>","190":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧larm</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈlɑːm $ əˈlɑːrm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a piece of equipment that makes a loud noise to warn you of danger:</div><ul class=\"examples\"><li><em>I forgot to set the burglar alarm.</em></li><li><em>Car alarms are always going off in the street.</em></li><li><em>a sophisticated alarm system</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> a feeling of fear or worry because something bad or dangerous might happen ► see thesaurus at fear</div><ul class=\"examples\"><li><strong><em>alarm at</strong>: There is growing alarm at the increase in crime.</em></li><li><strong><em>in alarm</strong>: She looked up in alarm.</em></li><li><em>Scientists have said there is no cause for alarm.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> an alarm clock:</div><ul class=\"examples\"><li><em>I’ve set the alarm for 7 o&#x27;clock.</em></li><li><em>I was still asleep when the alarm went off.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>raise/sound the alarm</strong> <em>especially British English</em> to warn people that something bad is happening:</div><ul class=\"examples\"><li><em>Neighbours raised the alarm when they smelled smoke.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>alarm bells ring</strong> if alarm bells ring, you feel worried that something bad may be happening:</div><ul class=\"examples\"><li><em>Alarm bells started to ring when he failed to return home.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to make someone feel worried or frightened:</div><ul class=\"examples\"><li><em>I don’t want to alarm you, but I can’t find the key.</em></li></ul></div></div>","191":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧larmed</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈlɑːmd $ -ɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> worried or frightened ► see thesaurus at frightened</div><ul class=\"examples\"><li><strong><em>alarmed by/at</strong>: Environmentalists are alarmed by the increase in pollution.</em></li><li><strong><em>alarmed to see/hear etc</strong>: He was alarmed to discover that his car was gone.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> protected by an alarm:</div><ul class=\"examples\"><li><em>The whole building is alarmed.</em></li></ul></div>","192":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧larm‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈlɑːmɪŋ $ -ɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">making you feel worried or frightened <em>SYN disturbing</em>:</div><ul class=\"examples\"><li><em>an alarming increase in violent crime</em></li><li><em>The rainforest is disappearing at an alarming rate.</em></li></ul></div>","193":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧be‧it</span><span class=\"meta-item\"><strong>IPA:</strong> /ɔːlˈbiːɪt $ ɒːl-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">used to add information that reduces the force or importance of what you have just said <em>SYN although</em>:</div><ul class=\"examples\"><li><em>He accepted the job, albeit with some hesitation.</em></li><li><em>Chris went with her, albeit reluctantly.</em></li></ul></div>","194":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧bum</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈælbəm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a group of songs or pieces of music on a record, CD, download etc:</div><ul class=\"examples\"><li><em>The band plan to release their new album next week.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a book that you put photographs, stamps etc in:</div><ul class=\"examples\"><li><em>a photograph album</em></li></ul></div>","195":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧co‧hol</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈælkəhɒl $ -hɒːl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> drinks such as beer or wine that contain a substance which can make you drunk:</div><ul class=\"examples\"><li><em>I don’t drink alcohol anymore.</em></li><li><em>alcohol abuse (=when someone drinks too much)</em></li><li><em>people with alcohol problems (=people who drink too much)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> the chemical substance in alcoholic drinks that can make you drunk, which is also used in other types of products:</div><ul class=\"examples\"><li><em>low alcohol drinks</em></li></ul></div>","196":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧co‧hol‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌælkəˈhɒlɪk◂ $ -ˈhɒː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relating to alcohol or containing alcohol <em>OPP nonalcoholic</em>:</div><ul class=\"examples\"><li><em>alcoholic drinks</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> caused by drinking alcohol:</div><ul class=\"examples\"><li><em>an alcoholic stupor</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who regularly drinks too much alcohol and has difficulty stopping</div></div></div>","197":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧lert</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈlɜːt $ -ɜːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> giving all your attention to what is happening, being said etc:</div><ul class=\"examples\"><li><em>The animal raised its head, suddenly alert.</em></li><li><em>Taking notes is one of the best ways to stay alert in lectures.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> able to think quickly and clearly:</div><ul class=\"examples\"><li><em>Jack was as mentally alert as a man half his age.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be alert to something</strong> to know about or understand something, especially a possible danger or problem:</div><ul class=\"examples\"><li><em>The authorities should have been alert to the possibility of invasion.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to officially warn someone about a problem or danger so that they are ready to deal with it: ► see thesaurus at warn</div><ul class=\"examples\"><li><em>The school immediately alerted the police.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make someone realize something important or dangerous</div><ul class=\"examples\"><li><strong><em>alert somebody to something</strong>: campaigns to alert the public to the dangers of HIV</em></li></ul></div></div>","198":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧i‧bi</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæləbaɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something that proves that someone was not where a crime happened and therefore could not have done it</div><ul class=\"examples\"><li><strong><em>a perfect/cast-iron/unshakeable etc alibi</strong>: He had a perfect alibi and the police let him go.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an excuse for something you have failed to do or have done wrong</div></div>","199":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧li‧en</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeɪliən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> very different from what you are used to, especially in a way that is difficult to understand or accept <em>SYN strange</em>:</div><ul class=\"examples\"><li><em>the alien environment of the city</em></li><li><strong><em>be alien to somebody</strong>: a way of life that is totally alien to us</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> belonging to another country or race <em>SYN foreign</em>:</div><ul class=\"examples\"><li><em>alien cultures</em></li><li><em>an alien multiracial society</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[only before noun]</span> relating to creatures from another world:</div><ul class=\"examples\"><li><em>alien beings from another planet</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who is not a legal citizen of the country they are living or working in: RegisterAlien is used in official contexts. In everyday English, foreigner is used, but can sound disapproving or unfriendly. To avoid this, people often use the expression people from other countries instead:· In those days people from other countries rarely came to Japan.</div><ul class=\"examples\"><li><em>illegal aliens entering the country</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in stories, a creature from another world</div></div></div>","200":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧li‧en‧ate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeɪliəneɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to do something that makes someone unfriendly or unwilling to support you:</div><ul class=\"examples\"><li><em>The latest tax proposals will alienate many voters.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make it difficult for someone to belong to a particular group or to feel comfortable with a particular person</div><ul class=\"examples\"><li><strong><em>alienate somebody from something</strong>: He felt that his experiences had alienated him from society.</em></li></ul></div>","201":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧light</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈlaɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[not before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> burning: RegisterAlight is mostly used in journalism or in literature. In everyday English, people usually say on fire:· The car had been deliberately set on fire.</div><ul class=\"examples\"><li><em>The car was set alight and pushed over a hill.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>literary</em> someone whose face or eyes are alight looks excited, happy, etc</div><ul class=\"examples\"><li><strong><em>alight with excitement/pleasure/laughter etc</strong>: Jed’s face was alight with excitement.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>literary</em> bright with light or colour</div></div>","202":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧lign</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈlaɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to publicly support a political group, country, or person that you agree with</div><ul class=\"examples\"><li><strong><em>align yourself with somebody/something</strong>: Church leaders have aligned themselves with the opposition.</em></li><li><em>a country closely aligned with the West</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to arrange things so that they form a line or are parallel to each other, or to be in a position that forms a line etc:</div><ul class=\"examples\"><li><em>The desks were neatly aligned in rows.</em></li><li><em>Make sure that all the holes align.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to organize or change something so that it has the right relationship to something else GRAMMAR Align is usually passive in this meaning.</div><ul class=\"examples\"><li><strong><em>be aligned with something</strong>: This policy is closely aligned with the goals of the organization.</em></li></ul></div>","203":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧lign‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈlaɪnmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the state of being arranged in a line with something or parallel to something</div><ul class=\"examples\"><li><strong><em>alignment of</strong>: the geometrical alignment of the Sun, Moon, and Earth at the eclipse</em></li><li><strong><em>out of/into alignment</strong>: The wheels were out of alignment.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> support given by one country or group to another in politics, defence etc</div><ul class=\"examples\"><li><strong><em>alignment with</strong>: their military alignment with the US</em></li></ul></div>","204":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧like</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈlaɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[not before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">very similar: ► see thesaurus at similar</div><ul class=\"examples\"><li><em>My mother and I are alike in many ways.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in a similar way: → great minds think alike at great1(15)</div><ul class=\"examples\"><li><em>The twins were dressed alike.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to emphasize that you mean both the people, groups, or things that you have just mentioned:</div><ul class=\"examples\"><li><em>I learned a lot from teachers and students alike.</em></li></ul></div></div>","205":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧live</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈlaɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[not before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[not dead]</strong> still living and not dead:</div><ul class=\"examples\"><li><em>It was a bad accident – they’re lucky to be alive.</em></li><li><em>My grandparents are still alive.</em></li><li><em>We stayed alive by eating berries.</em></li><li><em>He was kept alive on a life-support machine.</em></li><li><em>Apparently he’s alive and well and living in Brazil.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[still existing]</strong> continuing to exist:</div><ul class=\"examples\"><li><em>Ancient traditions are very much alive in rural areas.</em></li><li><em>Christianity is alive and well in Asia.</em></li><li><em>The sport is still very much alive and kicking in this country.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[cheerful]</strong> full of energy, happiness, activity etc:</div><ul class=\"examples\"><li><em>It was the kind of morning when you wake up and feel really alive.</em></li><li><strong><em>alive with</strong>: Her face was alive with excitement. / The whole house was alive with activity.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>come alive</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if a subject or event comes alive, it becomes interesting and seems real:</div><ul class=\"examples\"><li><em>Hopefully, we can make history come alive for the children.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if someone comes alive, they suddenly become happy and interested in what is happening:</div><ul class=\"examples\"><li><em>She only came alive when she sat down at the piano.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> if a town, city etc comes alive, it becomes busy:</div><ul class=\"examples\"><li><em>seaside resorts that come alive in the summer</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be alive to a fact/possibility/danger etc</strong> to know that a particular fact etc exists and that it is important:</div><ul class=\"examples\"><li><em>The company is alive to the threat posed by foreign imports.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be alive with something</strong> to be full of living things that are moving:</div><ul class=\"examples\"><li><em>The pond was alive with fish.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>bring something alive</strong> to make something interesting and real:</div><ul class=\"examples\"><li><em>The way he describes his characters really brings them alive.</em></li></ul></div>","206":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">determiner</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ɔːl $ ɒːl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the whole of an amount, thing, or type of thing:</div><ul class=\"examples\"><li><em>Have you done all your homework?</em></li><li><strong><em>all your life/all day/all year etc</strong> (=during the whole of your life, a day, a year etc): He had worked all his life in the mine. / The boys played video games all day.</em></li><li><em>They were quarrelling all the time (=very often or continuously).</em></li><li><em>Hannah didn’t say a single word all the way back home (=during the whole of the journey).</em></li><li><strong><em>all of</strong>: Almost all of the music was from Italian operas.</em></li><li><em>I’ve heard it all before.</em></li><li><em>She’d given up all hope of having a child.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> every one of a number of people or things, or every thing or person of a particular type:</div><ul class=\"examples\"><li><em>Someone’s taken all my books!</em></li><li><em>Will all the girls please stand over here.</em></li><li><em>All children should be taught to swim.</em></li><li><em>Sixteen per cent of all new cars sold in Western Europe these days are diesel-engined.</em></li><li><em>They all speak excellent English.</em></li><li><strong><em>all of</strong>: important changes that will affect all of us</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the only thing or things:</div><ul class=\"examples\"><li><em>All you need is a hammer and some nails.</em></li><li><em>All I’m asking for is a little respect.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>formal</em> everything:</div><ul class=\"examples\"><li><em>I’m doing all I can to help her.</em></li><li><em>I hope all is well with you.</em></li><li><em>All was dark and silent down by the harbour wall.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> used to emphasize that you mean the greatest possible amount of the quality you are mentioning:</div><ul class=\"examples\"><li><em>Can any of us say in all honesty that we did everything we could?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>at all</strong> used in negative statements and questions to emphasize what you are saying:</div><ul class=\"examples\"><li><em>They’ve done nothing at all to try and put the problem right.</em></li><li><em>He’s not looking at all well.</em></li><li><em>‘Do you mind if I stay a little longer?’ ‘No, not at all.’</em></li><li><em>Has the situation improved at all?</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>all sorts/kinds/types of something</strong> many different kinds of something:</div><ul class=\"examples\"><li><em>Social workers have to deal with all kinds of problems.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>of all people/things/places etc</strong> used to emphasize that your statement is true of one particular person, thing, or place more than any other:</div><ul class=\"examples\"><li><em>You shouldn’t have done it. You of all people should know that.</em></li><li><em>She did not want to quarrel with Maria today, of all days.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>all in all</strong> used to show that you are considering every part of a situation:</div><ul class=\"examples\"><li><em>All in all, it had been one of the most miserable days of Henry’s life.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>for all something</strong> in spite of a particular fact:</div><ul class=\"examples\"><li><em>For all his faults, he’s a kind-hearted old soul.</em></li><li><em>For all my love of landscape, nothing could persuade me to spend another day in the Highlands.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>in all</strong> including every thing or person:</div><ul class=\"examples\"><li><em>In all, there were 215 candidates.</em></li><li><em>We received £1,550 in cash and promises of another £650, making £2,200 in all.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>and all</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> including the thing or things just mentioned:</div><ul class=\"examples\"><li><em>They ate the whole fish – head, bones, tail, and all.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>spoken</em> <em>informal</em> used to emphasize a remark that you have just added:</div><ul class=\"examples\"><li><em>And you can take that smelly old coat out of here, and all!</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>all of 50p/20 minutes etc</strong> <em>spoken</em> used to emphasize how large or small an amount actually is:</div><ul class=\"examples\"><li><em>The game lasted all of 58 seconds.</em></li><li><em>The repairs are going to cost all of £15,000.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>it’s all or nothing</strong> used to say that unless something is done completely, it is not acceptable:</div><ul class=\"examples\"><li><em>Half-heartedness won’t do – it’s got to be all or nothing.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>give your all</strong> to make the greatest possible effort in order to achieve something:</div><ul class=\"examples\"><li><em>The coach expects every player to give their all in every game.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>it was all I could do to do something</strong> used to say that you only just succeeded in doing something:</div><ul class=\"examples\"><li><em>It was all I could do to stop them hitting each other.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>when all’s said and done</strong> <em>spoken</em> used to remind someone about an important point that needs to be considered:</div><ul class=\"examples\"><li><em>When all’s said and done, he’s only a kid.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>all sorts/kinds of wrong/crazy etc</strong> <em>informal</em> wrong, crazy etc in many ways, or very wrong, crazy etc:</div><ul class=\"examples\"><li><em>Her beach outfit is all sorts of wrong.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[always + adjective/adverb/preposition]</span> completely:</div><ul class=\"examples\"><li><em>You shouldn’t be sitting here by yourself, all alone.</em></li><li><em>a strange woman, dressed all in black</em></li><li><em>If people want more freedom of choice, then I’m all for it (=I strongly support it).</em></li><li><em>‘It was a dreadful experience.’ ‘Never mind, it’s all over (=completely finished) now.’</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>all over (something)</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> everywhere on an object or surface:</div><ul class=\"examples\"><li><em>There were bits of paper all over the floor.</em></li><li><em>He has cuts all over his legs.</em></li><li><em>She ached all over (=her whole body ached).</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> everywhere in a place:</div><ul class=\"examples\"><li><em>Antique clocks from all over the world are on display.</em></li><li><em>People came from all over the country.</em></li><li><em>They’re putting up new offices all over the place.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>all the better/easier/more etc</strong> used to emphasize how much better, easier etc something is than it would be in a different situation:</div><ul class=\"examples\"><li><em>Clayton’s achievement is all the more remarkable when you consider his poor performance last season.</em></li><li><em>The job was made all the easier by having the proper tools.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>all but</strong> almost completely:</div><ul class=\"examples\"><li><em>Britain’s coal industry has all but disappeared.</em></li><li><em>His left arm was all but useless.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>all too</strong> used to mean ‘very’ when talking about a bad situation:</div><ul class=\"examples\"><li><em>All too often it’s the mother who gets blamed for her children’s behaviour.</em></li><li><em>In these conditions it was all too easy to make mistakes.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>all along</strong> <em>informal</em> all the time from the beginning while something was happening:</div><ul class=\"examples\"><li><em>Chapman had known all along that the plan wouldn’t work.</em></li><li><em>We had to admit that Dad had been right all along.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>all round</strong> <em>British English</em>, all around<em>American English</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to say that you are describing the general quality or effect of something:</div><ul class=\"examples\"><li><em>All round it’s not a bad car.</em></li><li><em>It was a nasty business all round.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> from everyone, for everyone, or involving everyone:</div><ul class=\"examples\"><li><em>There were smiles all round.</em></li><li><em>He paid for drinks all round.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>one-all/two-all etc</strong> used when giving the score of a game in which both players or teams have scored the same number of points:</div><ul class=\"examples\"><li><em>The game ended one-all.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>all told</strong> including everything or everyone:</div><ul class=\"examples\"><li><em>a project costing £10,000, all told</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>it’s all up (with somebody)</strong> <em>British English</em> <em>informal</em> used to say that someone’s success or happiness has ended:</div><ul class=\"examples\"><li><em>If someone tells the police, then it’ll be all up with me.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>be not all there</strong> <em>informal</em> someone who is not all there seems stupid or slightly crazy</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>be all smiles/innocence/sweetness etc</strong> to be showing a lot of a particular quality or type of behaviour:</div><ul class=\"examples\"><li><em>The mayor and mayoress were all smiles and kisses during the grand ceremony.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>be all over somebody</strong> <em>informal</em> to be trying to kiss someone and touch them, especially in a sexual way:</div><ul class=\"examples\"><li><em>Before I could speak, he was all over me.</em></li></ul></div></div>","207":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> all ˈright</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[not before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[good]</strong> satisfactory, but not excellent <em>SYN okay</em>:</div><ul class=\"examples\"><li><em>‘What’s the food like?’ ‘It’s all right, but the place on campus is better.’</em></li><li><em>‘How’s school going, Steve?’ ‘Oh, all right, I guess.’</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[no problems]</strong> not ill, hurt, or upset or not having any problems <em>SYN okay</em>:</div><ul class=\"examples\"><li><em>Kate looks really unhappy – I’d better make sure she’s all right.</em></li><li><em>Are you feeling all right?</em></li><li><em>The kids seem to be getting on all right at school.</em></li><li><em>Tony was worried about the meeting but it went all right (=happened with no problems).</em></li><li><em>Don’t worry, it’ll turn out all right.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>do all right (for yourself/herself etc)</strong> to be successful in your job, life etc:</div><ul class=\"examples\"><li><em>She’s doing all right – she’s got a job with Microsoft.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[suitable]</strong> used to say whether something is suitable or convenient <em>SYN okay</em></div><ul class=\"examples\"><li><strong><em>all right with/by/for</strong>: Is Thursday morning all right with you?</em></li><li><em>We’ll eat at eight. Does that sound all right to you?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>it’s all right</strong> used to make someone feel less afraid or worried:</div><ul class=\"examples\"><li><em>It’s all right, Mommy’s here.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>it’s/that’s all right</strong> used to reply to someone who thanks you or says they are sorry about something:</div><ul class=\"examples\"><li><em>‘Thanks for all your help!’ ‘That’s quite all right.’</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[permission]</strong> used to ask or give permission for something <em>SYN okay</em>:</div><ul class=\"examples\"><li><em>Would it be all right if I left early?</em></li><li><strong><em>be all right to do something</strong>: Is it all right to bring my dog?</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[agreement]</strong> used to agree with someone’s suggestion, although you may be slightly unwilling <em>SYN okay</em>:</div><ul class=\"examples\"><li><em>‘Why not come along?’ ‘Oh, all right.’</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[understanding]</strong> <span class=\"gram\">[sentence adverb]</span> used to check that someone understands what you have said, or to show that you understand <em>SYN okay</em>:</div><ul class=\"examples\"><li><em>I’ll leave a key with the neighbours, all right?</em></li><li><em>‘The train leaves at 5.30.’ ‘All right, I’m coming!’</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[threaten]</strong> used when asking in a threatening or angry way what someone’s intentions are <em>SYN okay</em>:</div><ul class=\"examples\"><li><em>All right, you two. What are you doing in my room?</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[change/end subject]</strong> used to introduce a new subject or to end a conversation <em>SYN okay</em>:</div><ul class=\"examples\"><li><em>All right, now I’d like to introduce our first speaker.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>it’s all right for somebody</strong> <em>British English</em> <em>informal</em> used to say that someone else does not have the problems that you have, or that you are jealous because someone else is luckier than you:</div><ul class=\"examples\"><li><em>‘I get eight weeks’ holiday a year.‘ ’Well, it’s all right for some.&#x27;</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[emphasize]</strong> <em>informal</em> used to emphasize that you are certain about something:</div><ul class=\"examples\"><li><em>‘Are you sure it was Bill?’ ‘Oh, yes, it was him all right.’</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[happy]</strong> <em>American English</em> <em>informal</em> used to say you are happy about something you have just been told:</div><ul class=\"examples\"><li><em>You passed? All right!</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>[like]</strong> <em>British English</em> used to describe someone you like or approve of:</div><ul class=\"examples\"><li><em>‘The new boss isn’t too bad, is she?’ ‘No, she’s all right.’</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>[greeting]</strong> <em>especially British English</em> <em>informal</em> used as a greeting when you meet someone you know well, or reply to a greeting:</div><ul class=\"examples\"><li><em>‘How are you, John?’ ‘Oh, all right – can’t complain.’</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>I’m all right Jack</strong> <em>British English</em> <em>informal</em> used to describe someone’s attitude when they do not care about other people as long as they themselves are happy, comfortable etc</div><div class=\"sense\"><span class=\"snum\">18</span> <strong>it’ll be all right on the night</strong> <em>British English</em> <em>informal</em> used to say that something will be successful, even though there have been lots of problems:</div><ul class=\"examples\"><li><em>Workmen have yet to finish the new complex, but the organisers are confident it will be all right on the night.</em></li></ul></div>","208":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧le‧ga‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌælɪˈɡeɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable usually plural]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a statement that someone has done something wrong or illegal, but that has not been proved ► see thesaurus at claim</div><ul class=\"examples\"><li><strong><em>allegations of corruption/fraud/misconduct etc</strong>: Mr Singh has strongly denied the allegations of sexual harassment.</em></li><li><strong><em>allegation that</strong>: an allegation that senior government figures were involved</em></li><li><strong><em>allegation against</strong>: The teacher made serious allegations against a colleague.</em></li><li><strong><em>allegation of</strong>: A committee will investigate allegations of racial discrimination.</em></li></ul></div>","209":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧lege</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈledʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to say that something is true or that someone has done something wrong, although it has not been proved ► see thesaurus at accuse</div><ul class=\"examples\"><li><strong><em>it is alleged (that)</strong>: It was alleged that the policeman had accepted bribes.</em></li><li><strong><em>allege that</strong>: The prosecution alleged that the man had been responsible for an act of terrorism.</em></li><li><strong><em>be alleged to be/do something</strong>: The water is alleged to be polluted with mercury.</em></li></ul></div>","210":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧leg‧ed‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈledʒɪdli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[sentence adverb]</span></span></div><div class=\"entry-body\"><div class=\"sense\">used when reporting something that people say is true, although it has not been proved:</div><ul class=\"examples\"><li><em>a sports car, allegedly stolen in Manchester</em></li></ul></div>","211":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧le‧giance</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈliːdʒəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">loyalty to a leader, country, belief etc</div><ul class=\"examples\"><li><strong><em>allegiance to</strong>: You owe allegiance (=have a duty to give allegiance) to your king.</em></li><li><strong><em>swear/pledge allegiance</strong>: I pledge allegiance to the flag of the United States of America.</em></li><li><em>an oath of allegiance</em></li><li><strong><em>switch/transfer allegiance</strong> (=start to support a different person, group etc)</em></li><li><em>The people here have strong political allegiances.</em></li></ul></div>","212":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧ler‧gic</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈlɜːdʒɪk $ -ɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> having an allergy</div><ul class=\"examples\"><li><strong><em>allergic to</strong>: I’m allergic to penicillin.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> caused by an allergy:</div><ul class=\"examples\"><li><em>an allergic reaction to nuts</em></li><li><em>an allergic rash</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be allergic to something</strong> <em>informal</em> if you are allergic to something, you do not like it and try to avoid it – used humorously:</div><ul class=\"examples\"><li><em>Most men are allergic to housework!</em></li></ul></div>","213":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧ler‧gy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈælədʒi $ -ər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural allergies)</span></div><div class=\"entry-body\"><div class=\"sense\">a medical condition in which you become ill or in which your skin becomes red and painful because you have eaten or touched a particular substance</div><ul class=\"examples\"><li><strong><em>allergy to</strong>: I have an allergy to cats.</em></li><li><em>a food allergy</em></li></ul></div>","214":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧le‧vi‧ate</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈliːvieɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to make something less painful or difficult to deal with</div><ul class=\"examples\"><li><strong><em>alleviate the problem/situation/suffering etc</strong>: a new medicine to alleviate the symptoms of flu</em></li><li><em>measures to alleviate poverty</em></li></ul></div>","215":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧ley</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> (also alleyway) a narrow street between or behind buildings, not usually used by cars:</div><ul class=\"examples\"><li><em>The alley led to the railway bridge.</em></li><li><em>She found the side alley where the stage door was located.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>right up/down somebody’s alley</strong> very suitable for someone:</div><ul class=\"examples\"><li><em>The job sounds right up your alley.</em></li></ul></div>","216":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧li‧ance</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈlaɪəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an arrangement in which two or more countries, groups etc agree to work together to try to change or achieve something</div><ul class=\"examples\"><li><strong><em>alliance with</strong>: Britain’s military alliance with her NATO partners</em></li><li><strong><em>alliance between</strong>: the possibility of a political alliance between the two parties</em></li><li><strong><em>make/enter into/form/forge an alliance</strong> (=agree to work together): The companies have formed an alliance to market the product.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a group of two or more countries, groups etc who work together to achieve something:</div><ul class=\"examples\"><li><em>independent organizations and alliances</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in alliance (with somebody/something)</strong> if two groups, countries etc are in alliance, they work together to achieve something or protect each another:</div><ul class=\"examples\"><li><em>Relief workers in alliance with local charities are trying to help the victims.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>formal</em> a close relationship, especially a marriage, between people</div></div>","217":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧lied</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈælaɪd, əˈlaɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> usually Allied <span class=\"gram\">[only before noun]</span> belonging or relating to the countries that fought with Britain, the US etc in the First or Second World War:</div><ul class=\"examples\"><li><em>an Allied bombing raid</em></li><li><em>Allied forces</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>(be) allied to/with something</strong> <em>formal</em> to be related to something or to be very similar:</div><ul class=\"examples\"><li><em>Anthropology is closely allied to the field of psychology.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>allied industries/organizations/trades etc</strong> connected with each other because of being similar to or dependent on each other:</div><ul class=\"examples\"><li><em>agriculture and allied industries</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> joined by the same political, military, or economic aims:</div><ul class=\"examples\"><li><em>loosely allied guerilla groups</em></li></ul></div>","218":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧lo‧cate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæləkeɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to use something for a particular purpose, give something to a particular person etc, especially after an official decision has been made</div><ul class=\"examples\"><li><strong><em>allocate something to somebody/something</strong>: the importance of allocating resources to local communities / You should allocate the same amount of time to each question.</em></li><li><strong><em>allocate something for something</strong>: One million dollars was allocated for disaster relief.</em></li><li><strong><em>allocate somebody/something something</strong>: Several patients were waiting to be allocated a bed.</em></li></ul></div>","219":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧lo‧ca‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌæləˈkeɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> the amount or share of something that has been allocated for a particular purpose:</div><ul class=\"examples\"><li><em>Twelve hours a week seemed a generous allocation of your time.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the decision to allocate something, or the act of allocating it</div><ul class=\"examples\"><li><strong><em>allocation of</strong>: the allocation of funds to universities</em></li></ul></div>","220":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧low</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈlaʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[can do something]</strong> to let someone do or have something, or let something happen <em>SYN permit</em></div><ul class=\"examples\"><li><strong><em>allow somebody to do something</strong>: My parents wouldn’t allow me to go to the party. / Students are not allowed to eat in class.</em></li><li><strong><em>something is allowed</strong> (=something is officially permitted): Are dictionaries allowed in the exam?</em></li><li><strong><em>allow somebody something</strong>: Passengers are allowed one item of hand luggage each. / How much time are we allowed?</em></li><li><strong><em>allow yourself something</strong>: He allowed himself the occasional glass of wine.</em></li><li><strong><em>allow something</strong>: We don’t allow diving in the pool.</em></li><li><strong><em>allow somebody in/out/up etc</strong>: I don’t allow the cat in the bedroom. / The audience is not allowed backstage.</em></li><li><strong><em>somebody should be allowed to do something</strong>: Students should be allowed to make their own decisions.</em></li><li><strong><em>allow something to do something</strong>: Don’t allow your problems to dominate your life.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[make something possible]</strong> to make it possible for something to happen or for someone to do something, especially something helpful or useful <em>SYN permit</em></div><ul class=\"examples\"><li><strong><em>allow for something</strong>: Our new system will allow for more efficient use of resources.</em></li><li><strong><em>allow somebody to do something</strong>: A 24-hour ceasefire allowed the two armies to reach an agreement.</em></li><li><strong><em>allow somebody something</strong>: a seat belt that allows the driver greater freedom of movement</em></li><li><strong><em>allow something</strong>: This adjustment of the figures allows a fairer comparison.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[have enough of something]</strong> to be sure that you have enough time, money, food etc available for a particular purpose</div><ul class=\"examples\"><li><strong><em>allow somebody something</strong>: Allow yourselves plenty of time to get to the airport.</em></li><li><strong><em>allow something for somebody/something</strong>: I’ve allowed half a bottle of wine for each person.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[correct/permitted]</strong> <em>formal</em> to accept that something is correct or true, or that something is acceptable according to the rules or law:</div><ul class=\"examples\"><li><em>The judge allowed the evidence.</em></li><li><strong><em>allow that</strong>: I allow that there may have been a mistake.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>allow me</strong> <em>formal</em> used as a polite way of offering to help someone do something:</div><ul class=\"examples\"><li><em>‘Allow me,’ the waiter said, opening the door.</em></li></ul></div>","221":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧low‧ance</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈlaʊəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable usually singular]</span> an amount of money that you are given regularly or for a special purpose</div><ul class=\"examples\"><li><strong><em>a monthly/annual etc allowance</strong>: His father gives him a monthly allowance of £200.</em></li><li><strong><em>allowance for</strong>: Do you get an allowance for clothes?</em></li><li><em>Sales staff get a generous mileage allowance or a company car.</em></li><li><em>If you are entitled to sickness allowance, you must claim it from your employer.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable usually singular]</span> an amount of something that is acceptable or safe:</div><ul class=\"examples\"><li><em>the recommended daily allowance of Vitamin C</em></li><li><em>Passengers’ baggage allowance is 75 pounds per person.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> <em>British English</em> an amount of money that you can earn without paying tax on it:</div><ul class=\"examples\"><li><em>a new tax allowance</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable usually singular]</span> <em>especially American English</em> a small amount of money that a parent regularly gives to a child SYN pocket money<em>British English</em></div><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable, uncountable]</span> something that you consider when deciding what is likely to happen, what you should expect etc</div><ul class=\"examples\"><li><strong><em>allowance for</strong>: There is always an allowance in insurance premiums for whether someone smokes or not.</em></li><li><strong><em>make (an) allowance/make allowances (for something)</strong>: The budget makes allowances for extra staff when needed.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>make allowance/allowances (for somebody)</strong> to let someone behave in a way you do not normally approve of, because you know there are special reasons for their behaviour:</div><ul class=\"examples\"><li><em>Dad’s under pressure – you have to make allowances.</em></li></ul></div>","222":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧lude</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈluːd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">allude al‧lude / əˈluːd / ●○○ verb Word Origin Verb Table Examples Thesaurus allude to somebody/something phrasal verb formal to mention something or someone indirectly: Rick didn’t want to discuss his past, though he alluded darkly to ‘some bad things that happened.’</div></div>","223":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈælaɪ $ ˈælaɪ, əˈlaɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural allies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a country that agrees to help or support another country in a war:</div><ul class=\"examples\"><li><em>a meeting of the European allies</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the Allies</strong> the group of countries including Britain and the US that fought together in the First and Second World Wars</div><div class=\"sense\"><span class=\"snum\">3</span> someone who helps and supports you when other people are trying to oppose you:</div><ul class=\"examples\"><li><em>Ridley was one of the Queen’s closest allies.</em></li><li><em>a staunch ally (=very close ally) of President Soares</em></li><li><em>a network of political allies</em></li><li><em>She knew she had found an ally in Ted.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> something that helps you succeed in a difficult situation:</div><ul class=\"examples\"><li><em>Exercise is an important ally in your campaign to lose weight.</em></li></ul></div>","224":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧might‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ɔːlˈmaɪti $ ɒːl-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>the Almighty/Almighty God/Almighty Father</strong> expressions used to talk about God that emphasize His power</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>God/Christ Almighty</strong> an expression used when you are angry or upset. Some people consider this use offensive.</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>almighty din/crash/row etc</strong> <em>British English</em> <em>old-fashioned</em> <em>informal</em> a very loud noise, argument etc:</div><ul class=\"examples\"><li><em>There was an almighty bang and the car came to a halt.</em></li></ul></div>","225":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧most</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɔːlməʊst $ ˈɒːlmoʊst, ɒːlˈmoʊst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\">nearly, but not completely or not quite:</div><ul class=\"examples\"><li><em>Have you almost finished?</em></li><li><em>Supper’s almost ready.</em></li><li><em>It was almost midnight.</em></li><li><em>Almost nothing was done to improve the situation.</em></li><li><em>The story is almost certainly true.</em></li><li><em>He’s almost as old as I am.</em></li><li><strong><em>almost all/every/everything</strong>: Marsha visits her son almost every day.</em></li></ul></div>","226":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧lone</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈləʊn $ əˈloʊn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[not before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if you are alone in a place, there is no one with you <em>SYN by yourself</em>: RegisterIn everyday English, people often say by yourself or on your own rather than alone:· She lives by herself/on her own.</div><ul class=\"examples\"><li><em>She lives alone.</em></li><li><em>You shouldn’t leave a child alone in the house.</em></li><li><em>My wife and I like to spend time alone together away from the kids.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> without any friends or people you know:</div><ul class=\"examples\"><li><em>It was scary being all alone in a strange city.</em></li><li><em>She was all alone in the world (=she had no family or friends to help her or look after her).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> feeling unhappy and lonely:</div><ul class=\"examples\"><li><em>I cried like a child because I felt so alone.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> without any help from other people:</div><ul class=\"examples\"><li><em>He was left to raise their two children alone.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> without including anything else:</div><ul class=\"examples\"><li><em>The case will cost thousands of pounds in legal fees alone.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>you/he etc alone</strong> used to emphasize that there is only one person who knows, can do something etc:</div><ul class=\"examples\"><li><em>Julie alone knew the truth.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>go it alone</strong> to start working or living on your own, especially after working or living with other people:</div><ul class=\"examples\"><li><em>After years of working for a big company I decided to go it alone.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>leave somebody alone</strong> (also let somebody alone<em>old-fashioned</em>) to stop annoying or interrupting someone:</div><ul class=\"examples\"><li><em>‘Leave me alone!’ she screamed.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>leave something alone</strong> (also let something alone<em>old-fashioned</em>) to stop touching an object or changing something:</div><ul class=\"examples\"><li><em>Leave those cakes alone. They’re for the guests.</em></li><li><strong><em>leave well (enough) alone</strong> (=not change something that is satisfactory): In economic matters, they should leave well alone.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>be yours/hers/his etc alone</strong> used to emphasize that something belongs to someone:</div><ul class=\"examples\"><li><em>The responsibility is yours and yours alone.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>not be alone in (doing) something</strong> to not be the only person to do something:</div><ul class=\"examples\"><li><em>You’re not alone in feeling upset, believe me.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>stand alone</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be strong and independent:</div><ul class=\"examples\"><li><em>the courage to stand alone</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to be at a distance from other objects or buildings:</div><ul class=\"examples\"><li><em>The house stood alone at the end of the road.</em></li></ul></div>","227":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧long</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈlɒŋ $ əˈlɒːŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> going forward:</div><ul class=\"examples\"><li><em>I was driving along, thinking about Chris.</em></li><li><em>a group of children walking along in a line</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>go/come along</strong> to go or come to a place where something is happening:</div><ul class=\"examples\"><li><em>You’re welcome to come along if you like.</em></li><li><em>I think I’ll go along and watch the game.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>take/bring somebody/something along</strong> to take someone or something with you to a place:</div><ul class=\"examples\"><li><em>Mandy brought some of her friends along.</em></li><li><em>Why don’t you take your guitar along?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be/come along</strong> to arrive:</div><ul class=\"examples\"><li><em>Another bus should be along in a minute.</em></li><li><em>Every so often, a band comes along that changes music history.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>come/go/get along</strong> to improve, develop, or make progress:</div><ul class=\"examples\"><li><em>After a five-hour operation, Wendy is coming along just fine.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>along with somebody/something</strong> together with someone or something else:</div><ul class=\"examples\"><li><em>Dunne was murdered, along with three guards.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>all along</strong> all the time from the beginning, while something was happening:</div><ul class=\"examples\"><li><em>They should have known all along that she was lying.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">preposition</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> from one place on something such as a line, road, or edge towards the other end of it:</div><ul class=\"examples\"><li><em>We were driving along Follyfoot Road.</em></li><li><em>She glanced anxiously along the line of faces.</em></li><li><em>He slid his hand along her arm.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> forming a line beside something long:</div><ul class=\"examples\"><li><em>The palm trees along the shore swayed in the wind.</em></li><li><em>the toolbar along the top of your screen</em></li><li><em>There were cheering crowds all along Pennsylvania Avenue.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a particular distance away, on or beside something long such as a line, road, edge etc:</div><ul class=\"examples\"><li><em>Hugo’s house was about two hundred yards away along the main street.</em></li><li><em>The bathroom is just along (=a short distance along) the corridor.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>along the way/line</strong> during a process or experience, or during someone’s life:</div><ul class=\"examples\"><li><em>I’ve been lucky, but I’ve had my share of heartbreak along the way.</em></li></ul></div></div>","228":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧long‧side</span><span class=\"meta-item\"><strong>IPA:</strong> /əˌlɒŋˈsaɪd $ əˌlɒːŋ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> next to the side of something:</div><ul class=\"examples\"><li><em>A car drew up alongside.</em></li><li><em>Children’s prices are shown alongside adult prices.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to say that people or things do something or exist together at the same time:</div><ul class=\"examples\"><li><em>Charles spent a week working alongside the miners.</em></li><li><em>Organized crime continued to flourish alongside the mainstream economy.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> in comparison with something:</div><ul class=\"examples\"><li><em>His achievement may seem small alongside the great triumphs of 20th-century technology.</em></li><li><em>Athletics should rank alongside (=be equal to) soccer and cricket as a major sport.</em></li></ul></div>","229":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧loud</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈlaʊd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\">if you read, laugh, say something etc aloud, you read etc so that people can hear you <em>SYN out loud</em> ► Do not use aloud to mean ‘in a loud voice’. Use loudly: You need to speak quite loudly for the people at the back.</div><ul class=\"examples\"><li><strong><em>read/say something aloud</strong>: Joanne, would you read the poem aloud?</em></li><li><strong><em>laugh/groan/cry etc aloud</strong>: The pain made him cry aloud. / She could have laughed aloud.</em></li><li><strong><em>think aloud</strong> (=say the things you are thinking): ‘What did you say?’ ‘ Sorry, I was just thinking aloud.’</em></li></ul></div>","230":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧pha‧bet</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈælfəbet/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a set of letters, arranged in a particular order, and used in writing</div><ul class=\"examples\"><li><strong><em>the Greek/Roman etc alphabet</strong>: the international phonetic alphabet</em></li></ul></div>","231":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧pha‧bet‧i‧cal</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌælfəˈbetɪkəl◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span></div><div class=\"entry-body\"><div class=\"sense\">relating to the alphabet:</div><ul class=\"examples\"><li><em>The files are arranged in alphabetical order.</em></li></ul></div>","232":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧read‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ɔːlˈredi $ ɒːl-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> before now, or before a particular time:</div><ul class=\"examples\"><li><em>The design of the new house is similar to those that have already been built.</em></li><li><em>The performance had already started when we arrived.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to say that something has been done before and does not need doing again:</div><ul class=\"examples\"><li><em>You already told me that.</em></li><li><em>‘Fancy a coffee?’ ‘No thanks, I already have one.’</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to say that something has happened too soon or before the expected time:</div><ul class=\"examples\"><li><em>Have you eaten all that food already?</em></li><li><em>Is it 5 o&#x27;clock already?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used to say that a situation exists and it might get worse, greater etc:</div><ul class=\"examples\"><li><em>Hurry up, we’re already late.</em></li></ul></div>","233":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧so</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɔːlsəʊ $ ˈɒːlsoʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in addition to something else that you have mentioned → as well, too: RegisterIn written English, avoid starting a sentence with also. Use furthermore or moreover instead, or put also before the main verb: Also, it costs more. ➔ Furthermore, it costs more.It also costs more.</div><ul class=\"examples\"><li><em>Information is also available on women’s health care.</em></li><li><em>She sings beautifully and also plays the flute and piano.</em></li><li><em>The system was not only complicated but also ineffective.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to say that the same thing is true about another person or thing:</div><ul class=\"examples\"><li><em>My girlfriend was also called Helen.</em></li></ul></div>","234":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧tar</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɔːltə $ ˈɒːltər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a holy table or surface used in religious ceremonies:</div><ul class=\"examples\"><li><em>a crucifix above the high altar (=the main altar in a church)</em></li><li><em>The victim was tied to a sacrificial altar.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the area furthest from the entrance of a church, where the priest or minister stands</div></div>","235":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɔːltə $ ˈɒːltər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to change, or to make someone or something change:</div><ul class=\"examples\"><li><em>Her face hadn’t altered much over the years.</em></li><li><em>The city centre has altered beyond recognition (=changed very much).</em></li><li><em>Nothing can alter the fact that the refugees are our responsibility.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to make a piece of clothing longer, wider etc so that it fits</div><ul class=\"examples\"><li><strong><em>have/get something altered</strong>: She had the dress altered for the wedding.</em></li></ul></div>","236":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧ter‧a‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɔːltəˈreɪʃən $ ˌɒːl-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a small change that makes someone or something slightly different, or the process of this change</div><ul class=\"examples\"><li><strong><em>alteration to</strong>: If you make alterations to the Windows setup, save the new settings before closing.</em></li><li><strong><em>alteration in</strong>: Have you noticed any alteration in the patient’s behaviour?</em></li><li><strong><em>minor/major etc alterations</strong>: The King’s Arms pub is to undergo extensive alterations.</em></li></ul></div>","237":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧ter‧nate</span><span class=\"meta-item\"><strong>IPA:</strong> /ɔːlˈtɜːnət $ ˈɒːltər-, ˈæl-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[usually before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if something happens on alternate days, weeks etc, it happens on one day etc and not the next, and continues in this pattern → every other RegisterIn everyday English, instead of alternate days/Fridays/weeks etc, people usually use the phrase every other day/Friday/week etc: We meet on alternate Saturdays. ➔ We meet every other Saturday.</div><ul class=\"examples\"><li><strong><em>alternate Mondays/weekends etc</strong>: The service runs on alternate days.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> two alternate things are placed one after the other in a regular pattern:</div><ul class=\"examples\"><li><em>alternate blue and red stripes</em></li><li><em>Arrange the leeks and noodles in alternate layers.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to replace another thing of the same type <em>SYN alternative</em>:</div><ul class=\"examples\"><li><em>the appointment of an alternate director</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧ter‧nate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɔːltəneɪt $ ˈɒːltər-, ˈæl-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">if two things alternate, or if you alternate them, they happen one after the other in a repeated pattern</div><ul class=\"examples\"><li><strong><em>alternate between</strong>: She alternated between outrage and sympathy.</em></li><li><strong><em>alternate with</strong>: Periods of depression alternate with excited behavior.</em></li><li><strong><em>alternate something and/with something</strong>: Twist your body, alternating right and left stretches.</em></li></ul></div></div>","238":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧ter‧na‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ɔːlˈtɜːnətɪv $ ɒːlˈtɜːr-, æl-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[only before noun]</span> an alternative idea, plan etc is different from the one you have and can be used instead</div><ul class=\"examples\"><li><strong><em>alternative ways/approach/methods etc</strong>: alternative approaches to learning / Have you any alternative suggestions?</em></li><li><em>An alternative route is along the Via Unione.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> deliberately different from what is usual, expected, or traditional</div><ul class=\"examples\"><li><strong><em>alternative music/theatre etc</strong>: Tucson’s alternative radio station</em></li><li><em>sources of alternative energy (=energy produced by the sun, wind etc rather than by gas, coal etc)</em></li><li><em>tolerance of alternative lifestyles</em></li><li><strong><em>alternative medicine/therapies</strong> (=medical treatment that is not based on the usual western methods): Acupuncture is widely used by practitioners of alternative medicine.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">something you can choose to do or use instead of something else</div><ul class=\"examples\"><li><strong><em>alternative to</strong>: Is there a viable alternative to the present system?</em></li><li><em>If payment is not received, legal action will be our only alternative.</em></li><li><em>I had no alternative but to report him to the police.</em></li><li><em>He quickly assessed the alternatives open to him.</em></li></ul></div></div>","239":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧ter‧na‧tive‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ɔːlˈtɜːnətɪvli $ ɒːlˈtɜːr-, æl-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[sentence adverb]</span></span></div><div class=\"entry-body\"><div class=\"sense\">used for suggesting something different:</div><ul class=\"examples\"><li><em>You can relax on the beach or alternatively visit the bustling town centre.</em></li></ul></div>","240":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧though</span><span class=\"meta-item\"><strong>IPA:</strong> /ɔːlˈðəʊ $ ɒːlˈðoʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to introduce a statement that makes your main statement seem surprising or unlikely <em>SYN though</em>:</div><ul class=\"examples\"><li><em>Although in poor health, she continued to carry out her duties.</em></li><li><em>We decided to take rooms in Longwood House, although we knew we could not really afford the rent.</em></li><li><em>Although I can’t help admiring the man’s courage, I do not approve of his methods.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to add a statement that balances or reduces the effect of what you have just said <em>SYN but</em>: ► see thesaurus at but</div><ul class=\"examples\"><li><em>You can copy down my answers, although I’m not sure they’re right.</em></li><li><em>No, this is my responsibility, although I appreciate your offer.</em></li></ul></div>","241":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧ti‧tude</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæltɪtjuːd $ -tuːd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[countable]</span> the height of an object or place above the sea</div><ul class=\"examples\"><li><strong><em>altitude of</strong>: We’re flying at an altitude of 40,000 feet.</em></li><li><strong><em>high/low altitudes</strong>: At high altitudes it is difficult to get enough oxygen.</em></li></ul></div>","242":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧to‧geth‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɔːltəˈɡeðə◂ $ ˌɒːltəˈɡeðər◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to emphasize that something has been done completely or has finished completely:</div><ul class=\"examples\"><li><em>an old custom that has vanished altogether</em></li><li><em>Congress could ban the procession altogether.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[+adjective/adverb]</span> used to emphasize that the way you describe something is completely true:</div><ul class=\"examples\"><li><em>In Canada, the situation is altogether different.</em></li><li><em>This latest problem is altogether more serious.</em></li><li><strong><em>not altogether</strong> (=not completely): I wasn’t altogether happy about Mike staying over. / The results were not altogether surprising.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to show that you are referring to the total amount:</div><ul class=\"examples\"><li><em>There were five people altogether.</em></li><li><em>How much do I owe you altogether?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used to make a final statement about several things you have just mentioned <em>SYN all in all</em>:</div><ul class=\"examples\"><li><em>Lots of sunshine, wonderful food, and amazing nightlife – altogether a great vacation!</em></li></ul></div>","243":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧u‧min‧i‧um</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌæləˈmɪniəm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a silver-white metal that is very light and is used to make cans, cooking pans, window frames etc. It is a chemical element: symbol Al:</div><ul class=\"examples\"><li><em>recycled aluminium cans</em></li></ul></div>","244":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> al‧ways</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɔːlwəz, -weɪz $ ˈɒːl-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> all the time, at all times, or every time:</div><ul class=\"examples\"><li><em>Always lock your bicycle to something secure.</em></li><li><em>She’d always assumed that Gabriel was a girl’s name.</em></li><li><em>He hadn’t always been a butler.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> for a very long time:</div><ul class=\"examples\"><li><em>I’ve always wanted to go to Paris.</em></li><li><em>John’s always been keen on music.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> for ever:</div><ul class=\"examples\"><li><em>I’ll always remember that day.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> if someone or something is always doing something, they do it often, especially in an annoying way:</div><ul class=\"examples\"><li><em>That woman next door’s always complaining.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>always assuming/supposing (that) something</strong> <em>British English</em> used to say that one important fact has to be accepted as true for something else to happen, be true etc:</div><ul class=\"examples\"><li><em>We’ll leave on Tuesday – always assuming the car’s repaired by then.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>as always</strong> as is usual or expected:</div><ul class=\"examples\"><li><em>The truth, as always, is more complicated.</em></li><li><em>As always, Deborah was the last to arrive.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>can/could always do something</strong> (also there’s always something) <em>spoken</em> used to make a polite suggestion:</div><ul class=\"examples\"><li><em>You could always try ringing again.</em></li><li><em>If you can’t get it locally, there’s always the Internet.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>somebody always was lucky/untidy etc</strong> used to say you are not surprised by what someone has done because it is typical of them:</div><ul class=\"examples\"><li><em>You always were a stubborn creature.</em></li><li><em>He’s a troublemaker! Always was and always will be!</em></li></ul></div>","245":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> am‧a‧teur</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈamətə, -tʃʊə, -tʃə, ˌæməˈtɜː $ ˈæmətʃʊr, -tər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who does an activity just for pleasure, not as their job <em>OPP professional</em>:</div><ul class=\"examples\"><li><em>a gifted amateur</em></li><li><em>Mickelson won his first major golf tournament while still an amateur.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>informal</em> someone who you think is not very skilled at something:</div><ul class=\"examples\"><li><em>You English are a bunch of amateurs when it comes to romance.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> doing something for pleasure, or done for pleasure, and not as a job <em>OPP professional</em>:</div><ul class=\"examples\"><li><em>an amateur golfer</em></li><li><em>amateur dramatics</em>British English<em> (=producing or acting in plays for pleasure)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> amateurish:</div><ul class=\"examples\"><li><em>It was a very amateur performance.</em></li></ul></div></div>","246":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧maze</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈmeɪz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to surprise someone very much <em>SYN astonish</em>:</div><ul class=\"examples\"><li><em>Dave amazed his friends by suddenly getting married.</em></li><li><strong><em>it amazes somebody how/what/that</strong>: It still amazes me how much she has improved.</em></li><li><em>It never ceased to amaze him that women were attracted to Sam.</em></li></ul></div>","247":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧mazed</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈmeɪzd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\">very surprised <em>SYN astonished</em> ► see thesaurus at surprised</div><ul class=\"examples\"><li><strong><em>amazed (that)/how</strong>: I’m amazed you’ve never heard of the Rolling Stones. / You’d be amazed how much money you can save.</em></li><li><strong><em>amazed at/by</strong>: We were absolutely amazed at his rapid recovery.</em></li><li><strong><em>amazed to see/find/discover something</strong>: Visitors are often amazed to discover how little the town has changed.</em></li></ul></div>","248":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧maze‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈmeɪzmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a feeling of great surprise <em>SYN astonishment</em></div><ul class=\"examples\"><li><strong><em>do something in amazement</strong>: Ralph gasped in amazement.</em></li><li><strong><em>to somebody’s amazement</strong>: To everyone’s amazement, the goal was disallowed.</em></li></ul></div>","249":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧maz‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈmeɪzɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> very good, especially in an unexpected way: ► see thesaurus at good</div><ul class=\"examples\"><li><em>He’s an amazing player to watch.</em></li><li><em>an amazing bargain</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> so surprising you can hardly believe it: ► see thesaurus at surprising</div><ul class=\"examples\"><li><em>It’s amazing how often you see drivers using mobile phones.</em></li></ul></div>","250":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> am‧bas‧sa‧dor</span><span class=\"meta-item\"><strong>IPA:</strong> /æmˈbæsədə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an important official who represents his or her government in a foreign country</div><ul class=\"examples\"><li><strong><em>ambassador to</strong>: the US ambassador to Spain</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who represents a particular sport, business etc because they behave in a way that people admire</div><ul class=\"examples\"><li><strong><em>ambassador for</strong>: He has made some good films and he is a good ambassador for the industry.</em></li></ul></div>","251":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> am‧bi‧gu‧i‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌæmbɪˈɡjuːəti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural ambiguities)</span></div><div class=\"entry-body\"><div class=\"sense\">the state of being unclear, confusing, or not certain, or things that produce this effect</div><ul class=\"examples\"><li><strong><em>ambiguity in</strong>: There was an element of ambiguity in the president’s reply.</em></li><li><em>legal ambiguities</em></li></ul></div>","252":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> am‧big‧u‧ous</span><span class=\"meta-item\"><strong>IPA:</strong> /æmˈbɪɡjuəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">something that is ambiguous is unclear, confusing, or not certain, especially because it can be understood in more than one way <em>OPP unambiguous</em>:</div><ul class=\"examples\"><li><em>The language in the Minister’s statement is highly ambiguous.</em></li><li><em>His role in the affair is ambiguous.</em></li></ul></div>","253":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> am‧bi‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /æmˈbɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a strong desire to achieve something ► see thesaurus at aim</div><ul class=\"examples\"><li><strong><em>an ambition to do something</strong>: She had always had an ambition to be a pilot.</em></li><li><strong><em>somebody’s ambitions of doing something</strong>: An injury ended his ambitions of becoming a professional footballer.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> determination to be successful, rich, powerful etc:</div><ul class=\"examples\"><li><em>He was young and full of ambition.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>have no ambition to do something</strong> used when saying that you definitely do not want to do something:</div><ul class=\"examples\"><li><em>I have no ambition to go back there again.</em></li></ul></div>","254":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> am‧bi‧tious</span><span class=\"meta-item\"><strong>IPA:</strong> /æmˈbɪʃəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> determined to be successful, rich, powerful etc:</div><ul class=\"examples\"><li><em>Alfred was intensely ambitious, obsessed with the idea of becoming rich.</em></li><li><strong><em>ambitious for</strong>: mothers who are highly ambitious for their children (=who want their children to be successful)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an ambitious plan, idea etc shows a desire to do something good but difficult:</div><ul class=\"examples\"><li><em>an ambitious engineering project</em></li><li><em>an over-ambitious health reform program</em></li></ul></div>","255":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> am‧bu‧lance</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæmbjələns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a special vehicle that is used to take people who are ill or injured to hospital:</div><ul class=\"examples\"><li><em>the ambulance service</em></li><li><strong><em>ambulance staff/crew/worker</strong>: The ambulance crew removed him from the wreckage.</em></li><li><em>the ambulance driver</em></li><li><strong><em>by ambulance</strong>: Mike had to be taken by ambulance to hospital.</em></li><li><em>Do you think we need to call an ambulance (=phone to ask an ambulance to come)?</em></li></ul></div>","256":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> am‧bush</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæmbʊʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a sudden attack on someone by people who have been hiding and waiting for them, or the place where this happens: ► see thesaurus at attack</div><ul class=\"examples\"><li><em>The soldiers were killed in an ambush.</em></li><li><em>In winter the danger of ambush is much reduced.</em></li><li><strong><em>lie/wait in ambush</strong>: Armed police lay in ambush behind the hedge.</em></li></ul></div>","257":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧mend</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈmend/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to correct or make small changes to something that is written or spoken:</div><ul class=\"examples\"><li><em>The law was amended to include women.</em></li><li><em>The defendant later amended his evidence.</em></li><li><em>‘Steve stole it – or rather borrowed it,’ he amended.</em></li></ul></div>","258":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧mend‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈmendmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[countable, uncountable]</span> a small change, improvement, or addition that is made to a law or document, or the process of doing this:</div><ul class=\"examples\"><li><em>constitutional amendments</em></li><li><strong><em>amendment to</strong>: an amendment to the resolution</em></li></ul></div>","259":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧me‧ni‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈmiːnəti $ əˈme-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable usually plural]</span></span><span class=\"meta-item\">(plural amenities)</span></div><div class=\"entry-body\"><div class=\"sense\">something that makes a place comfortable or easy to live in:</div><ul class=\"examples\"><li><em>The hotel is in the city centre, close to shops and local amenities.</em></li><li><em>houses that lack basic amenities (=basic things that people need, such as heat and running water)</em></li></ul></div>","260":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> am‧i‧ca‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæmɪkəbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">an amicable agreement, relationship etc is one in which people feel friendly towards each other and do not want to quarrel:</div><ul class=\"examples\"><li><em>Their relationship hasn’t always been amicable.</em></li><li><strong><em>amicable settlement/agreement</strong>: The two parties have reached an amicable settlement.</em></li></ul></div>","261":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧mid</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈmɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> while noisy, busy, or confused events are happening – used in writing or news reports:</div><ul class=\"examples\"><li><em>The dollar has fallen in value amid rumors of weakness in the US economy.</em></li><li><em>Demonstrators ripped up the national flag amid shouts of ‘Death to the tyrants!’</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>literary</em> among or surrounded by things:</div><ul class=\"examples\"><li><em>He sat amid the trees.</em></li></ul></div>","262":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> am‧mu‧ni‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌæmjəˈnɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> bullets, shells (shell) etc that are fired from guns</div><div class=\"sense\"><span class=\"snum\">2</span> information that you can use to criticize someone or win an argument against them</div><ul class=\"examples\"><li><strong><em>give somebody ammunition/provide somebody with ammunition</strong>: His mistakes provided political opponents with even more ammunition.</em></li></ul></div>","263":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> am‧nes‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæmnəsti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural amnesties)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an official order by a government that allows a particular group of prisoners to go free</div><ul class=\"examples\"><li><strong><em>amnesty for</strong>: The government granted an amnesty for all former terrorists.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a period of time when you can admit to doing something illegal without being punished</div><ul class=\"examples\"><li><strong><em>amnesty on</strong>: an amnesty on illegal handguns</em></li></ul></div>","264":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧mong</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈmʌŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in or through the middle of a group of people or things: → between</div><ul class=\"examples\"><li><em>The girl quickly disappeared among the crowd.</em></li><li><em>I could hear voices coming from somewhere among the bushes.</em></li><li><em>We walked among the chestnut woods on the mountain slopes.</em></li><li><em>She began rummaging among the books on her desk.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> with a particular group of people:</div><ul class=\"examples\"><li><em>Jim relaxed, knowing he was among friends.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to say that many people in a group have the same feeling or opinion, or that something affects many people in a group:</div><ul class=\"examples\"><li><em>The problem is causing widespread concern among scientists.</em></li><li><em>The general opinion among police officers was that the law should be tightened.</em></li><li><em>The changes will mean 7,000 job losses among railway workers.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used to talk about a particular person, thing, or group as belonging to a larger group:</div><ul class=\"examples\"><li><em>She was the eldest among them.</em></li><li><em>Innocent civilians were among the casualties.</em></li><li><em>My grandfather had among his possessions a portrait by Matisse.</em></li><li><em>Representatives were chosen by the students from among themselves.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>among other things/places/factors etc</strong> used to say that you are only mentioning one or two people or things out of a much larger group:</div><ul class=\"examples\"><li><em>At the meeting they discussed, among other things, recent events in Japan.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> if something is divided or shared among a group of people, each person is given a part of it:</div><ul class=\"examples\"><li><em>A father’s property was divided among his heirs.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>among yourselves/ourselves/themselves</strong> with each other:</div><ul class=\"examples\"><li><em>The allies found it hard to agree among themselves.</em></li></ul></div>","265":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧mount</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈmaʊnt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a quantity of something such as time, money, or a substance</div><ul class=\"examples\"><li><strong><em>amount of</strong>: They spend equal amounts of time in California and New York.</em></li><li><strong><em>a considerable/large/enormous etc amount</strong>: a considerable amount of money</em></li><li><strong><em>a small/tiny etc amount</strong>: a tiny amount of dirt</em></li><li><em>Please pay the full amount (=of money) by the end of the month.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to talk about how much there is of a feeling or quality</div><ul class=\"examples\"><li><strong><em>a large/considerable etc amount of something</strong>: Her case has attracted an enormous amount of public sympathy.</em></li><li><strong><em>a certain/fair amount of something</strong>: Dina encountered a fair amount of envy among her colleagues.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>no amount of something can/will etc do something</strong> used to say that something has no effect:</div><ul class=\"examples\"><li><em>No amount of persuasion could make her change her mind.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>any amount of something</strong> used to say that there is plenty of something, and no more is needed:</div><ul class=\"examples\"><li><em>The school has any amount of resources and equipment.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">amount amount 2 ●○○ verb Word Origin Verb Table Examples Thesaurus Collocations Phrases amount to something phrasal verb 1 if figures, sums etc amount to a particular total, they equal that total when they are added together: Time lost through illness amounted to 1,357 working days. 2 if an attitude, remark, situation etc amounts to something, it has the same effect: The court’s decision amounts to a not guilty verdict. Ultimately, their ideas amount to the same thing. 3 not amount to much/anything/a great deal etc to not be important, valuable, or successful: Her academic achievements don’t amount to much. Jim’s never going to amount to much.</div></div></div>","266":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> am‧ple</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæmpəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> more than enough <em>SYN sufficient</em> <em>OPP insufficient</em> ► see thesaurus at enough</div><ul class=\"examples\"><li><strong><em>ample time/evidence/opportunity</strong>: You’ll have ample time for questions later. / There is ample evidence that climate patterns are changing.</em></li><li><strong><em>ample room/space etc</strong>: She found ample room for her things in the wardrobe.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>literary</em> large in a way that is attractive or pleasant:</div><ul class=\"examples\"><li><em>an ample bosom</em></li></ul></div>","267":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧muse</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈmjuːz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make someone laugh or smile: RegisterIn everyday English, people usually say they think something is funny rather than say that it amuses them: The joke really amused them. ➔ They thought the joke was really funny.</div><ul class=\"examples\"><li><em>He made funny faces to amuse the children.</em></li><li><em>The question seemed to amuse him in some way.</em></li><li><strong><em>it amuses somebody that/how/to do</strong>: It amused me to think back to my life in London.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make time pass in an enjoyable way for someone, so that they do not get bored <em>SYN entertain</em>:</div><ul class=\"examples\"><li><em>Doing jigsaws would amuse Amy for hours on end.</em></li><li><em>The kids amused themselves playing hide-and-seek.</em></li></ul></div>","268":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧mused</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈmjuːzd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if you are amused by something, you think it is funny and you smile or laugh</div><ul class=\"examples\"><li><strong><em>amused at/by</strong>: Ellen seemed amused by the whole situation.</em></li><li><em>I could see she was highly amused (=very amused).</em></li><li><em>The man looked a little amused.</em></li><li><em>He won’t be very amused (=he will be annoyed) when he finds out what’s happened to his garden.</em></li><li><strong><em>an amused smile/look/expression etc</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>keep somebody amused</strong> to entertain or interest someone for a long time so that they do not get bored:</div><ul class=\"examples\"><li><em>There were puzzles and games to keep the children amused.</em></li></ul></div>","269":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧muse‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈmjuːzmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the feeling you have when you think something is funny</div><ul class=\"examples\"><li><strong><em>with/in amusement</strong>: Her eyes sparkled with amusement. / She looked at him in amusement.</em></li><li><em>Steve couldn’t hide his amusement.</em></li><li><strong><em>to somebody’s amusement</strong> (=in a way that makes someone laugh or smile): They were dancing and singing in the car, much to the amusement of passers-by.</em></li><li><em>The cats are a constant source of amusement to us.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>amusements</strong> <span class=\"gram\">[plural]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> things that entertain you and make time pass in an enjoyable way:</div><ul class=\"examples\"><li><em>childhood amusements</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>British English</em> special machines or games that are intended to entertain people, for example at a fair:</div><ul class=\"examples\"><li><em>The kids can ride on the amusements.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> the process of getting or providing pleasure and enjoyment:</div><ul class=\"examples\"><li><em>What do you do for amusement in this town?</em></li></ul></div>","270":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧mus‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈmjuːzɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">funny and entertaining: ► see thesaurus at funny</div><ul class=\"examples\"><li><em>I don’t find his jokes at all amusing.</em></li><li><em>a highly amusing (=very amusing) film</em></li><li><strong><em>an amusing story/anecdote/incident etc</strong>: The book is full of amusing stories about his childhood.</em></li><li><strong><em>mildly/vaguely amusing</strong> (=a little amusing, but not very): a mildly amusing spectacle</em></li></ul></div>","271":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ən; strong æn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\">used when the following word begins with a vowel sound → a:</div><ul class=\"examples\"><li><em>an orange</em></li><li><em>an X-ray</em></li></ul></div>","272":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧aes‧thet‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌænəsˈθetɪk◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a drug that stops you feeling pain</div><ul class=\"examples\"><li><strong><em>under anaesthetic</strong>: The operation will have to be done under anaesthetic (=using anaesthetic). / Eye surgery is often performed using a local anaesthetic (=one that only affects a particular area of your body). / You will need to have a general anaesthetic (=one that makes you completely unconscious).</em></li></ul></div>","273":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧a‧gram</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈænəɡræm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a word or phrase that is made by changing the order of the letters in another word or phrase:</div><ul class=\"examples\"><li><em>‘Silent’ is an anagram of ‘listen’.</em></li></ul></div>","274":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧nal‧o‧gous</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈnæləɡəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">similar to another situation or thing so that a comparison can be made</div><ul class=\"examples\"><li><strong><em>analogous to/with</strong>: The report’s findings are analogous with our own.</em></li></ul></div>","275":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧nal‧o‧gy</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈnælədʒi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural analogies)</span></div><div class=\"entry-body\"><div class=\"sense\">something that seems similar between two situations, processes etc</div><ul class=\"examples\"><li><strong><em>analogy with/to/between</strong>: analogies between human and animal behaviour</em></li><li><strong><em>draw/make an analogy</strong> (=make a comparison): She drew an analogy between childbirth and the creative process.</em></li><li><strong><em>by analogy with</strong>: Dr Wood explained the movement of light by analogy with (=using the analogy of) the movement of water.</em></li></ul></div>","276":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧a‧lyse</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈænəl-aɪz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to examine or think about something carefully, in order to understand it: ► see thesaurus at examine</div><ul class=\"examples\"><li><em>She still needs to analyse the data.</em></li><li><em>You need to sit down and analyse why you feel so upset.</em></li><li><em>Joe had never tried to analyze their relationship.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to examine a substance to see what it is made of:</div><ul class=\"examples\"><li><em>The cell samples are analyzed by a lab.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to examine someone’s mental or emotional problems by using psychoanalysis</div></div>","277":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧nal‧y‧sis</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈnælɪsɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3 AWL</span><span class=\"meta-item\">(plural analyses /-siːz/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a careful examination of something in order to understand it better</div><ul class=\"examples\"><li><strong><em>analysis of</strong>: a detailed analysis of the week’s news</em></li><li><em>Further analysis of the data is needed.</em></li><li><strong><em>do/carry out/conduct an analysis</strong>: They were doing some type of statistical analysis.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the way in which someone describes a situation or problem, and says what causes it to happen</div><ul class=\"examples\"><li><strong><em>analysis of</strong>: Do you agree with Marx’s analysis of the failure of free-market capitalism?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span></div><ul class=\"examples\"><li>a careful examination of a substance to see what it is made of</li><li><strong><em>analysis of</strong>: analysis of genetic material</em></li><li><strong><em>for analysis</strong>: Blood samples were sent for analysis.</em></li><li><em>You’ll get the results when the analysis is complete.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> a process in which a doctor makes someone talk about their past experiences, relationships etc in order to help them with mental or emotional problems <em>SYN psychoanalysis</em> → therapy:</div><ul class=\"examples\"><li><em>She’s been in analysis for three years.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>in the final/last analysis</strong> used when giving the most basic or important facts about a situation:</div><ul class=\"examples\"><li><em>In the final analysis, profit is the motive.</em></li></ul></div>","278":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧a‧lyst</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈænəl-ɪst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone whose job is to think about something carefully in order to understand it, and often to advise other people about it:</div><ul class=\"examples\"><li><em>Political analysts expect the Conservatives to win.</em></li><li><strong><em>investment/financial/business analyst</strong>: Cleary has been working as a computer analyst in Winchester.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a doctor who helps people who have mental or emotional problems by making them talk about their experiences and relationships <em>SYN psychoanalyst</em></div></div>","279":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧a‧lyt‧ical</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌænəlˈɪtɪkəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> thinking about things in a detailed and intelligent way, so that you can examine and understand things:</div><ul class=\"examples\"><li><em>She’s got an analytical mind.</em></li><li><strong><em>analytical method/techniques/approach/skills</strong>: During the course, students will develop their analytical skills.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> using scientific analysis to examine something:</div><ul class=\"examples\"><li><em>analytical chemistry</em></li></ul></div>","280":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧ar‧chy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈænəki $ -ər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a situation in which there is no effective government in a country or no order in an organization or situation:</div><ul class=\"examples\"><li><em>The prison is close to anarchy.</em></li><li><em>The classroom was in a constant state of anarchy.</em></li><li><strong><em>slide/fall/descend into anarchy</strong>: The nation is in danger of falling into anarchy.</em></li></ul></div>","281":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧nat‧o‧my</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈnætəmi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(plural anatomies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the scientific study of the structure of human or animal bodies:</div><ul class=\"examples\"><li><em>a professor of anatomy</em></li><li><strong><em>human/animal anatomy</strong>: Knowledge of human anatomy is essential to figure drawing.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable usually singular]</span> the structure of a body, or of a part of a body</div><ul class=\"examples\"><li><strong><em>anatomy of</strong>: the anatomy of the nervous system</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> your body – often used in a humorous way:</div><ul class=\"examples\"><li><em>You could see a part of his anatomy that I’d rather not mention.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the/an anatomy of something</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a study or examination of an organization, process etc in order to understand and explain how it works:</div><ul class=\"examples\"><li><em>Elkind’s book is an anatomy of one man’s discussion with his son about life.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the structure of an organization, process etc or the way it works:</div><ul class=\"examples\"><li><em>For the first time, we have the chance to examine the anatomy of a secret government operation.</em></li></ul></div>","282":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧ces‧tor</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈænsəstə, -ses- $ -sestər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a member of your family who lived a long time ago → descendant: ► see thesaurus at relative</div><ul class=\"examples\"><li><em>My ancestors were French.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an animal that lived in the past, that modern animals have developed from:</div><ul class=\"examples\"><li><em>Lions and house cats evolved from a common ancestor (=the same ancestor).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the form in which a modern machine, vehicle etc first existed <em>SYN forerunner</em></div><ul class=\"examples\"><li><strong><em>ancestor of</strong>: Babbage’s invention was the ancestor of the modern computer.</em></li></ul></div>","283":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧cient</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeɪnʃənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> belonging to a time long ago in history, especially thousands of years ago <em>OPP modern</em>:</div><ul class=\"examples\"><li><em>the ancient civilizations of Asia</em></li><li><strong><em>ancient Greece/Egypt/Rome</strong>: the religion of ancient Egypt</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> having existed for a very long time <em>OPP new</em>:</div><ul class=\"examples\"><li><em>an ancient walled city</em></li><li><em>an ancient forest</em></li><li><em>the ancient art of calligraphy</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> very old – used humorously: ► see thesaurus at old</div><ul class=\"examples\"><li><em>That photo makes me look ancient!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>ancient history</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the history of ancient societies, such as Greece or Rome:</div><ul class=\"examples\"><li><em>a professor of ancient history</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>informal</em> if you say that something is ancient history, you mean that it happened a long time ago and is not important now:</div><ul class=\"examples\"><li><em>It’s all ancient history and I’m not upset anymore.</em></li></ul></div>","284":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ənd, ən; strong ænd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to join two words, phrases etc referring to things that are related in some way:</div><ul class=\"examples\"><li><em>He’s gone to get some fish and chips.</em></li><li><em>The film starred Jack Lemmon and Shirley Maclaine.</em></li><li><em>We’ve dealt with items one, two, and eleven.</em></li><li><em>He was tall, dark, and handsome.</em></li><li><em>He plays the guitar and sings folk songs.</em></li><li><em>She didn’t speak to anyone and nobody spoke to her.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to say that one action or event follows another:</div><ul class=\"examples\"><li><em>Sit down and tell me all about it.</em></li><li><em>She picked up the kitten and put it in the box.</em></li><li><em>He knocked on the door and went in.</em></li><li><em>You’ll have to wait and see what happens.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to say that something is caused by something else:</div><ul class=\"examples\"><li><em>I missed supper and I’m starving!</em></li><li><em>She fell downstairs and broke her leg.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used when adding numbers:</div><ul class=\"examples\"><li><em>Six and four is ten.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>especially British English</em> used after verbs such as ‘go’, ‘come’, and ‘try’ to show what your intention is:</div><ul class=\"examples\"><li><em>Shall we go and have a cup of coffee?</em></li><li><em>I’ll see if I can try and persuade her to come.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <em>spoken</em> used to introduce a statement, remark, question etc: RegisterIn written English, avoid starting a sentence with and: And now we come onto the issue of homelessness. ➔ We now come onto the issue of homelessness.</div><ul class=\"examples\"><li><em>And now I’d like to introduce our next speaker, Mrs Thompson.</em></li><li><em>‘She’s getting married in June.’ ‘And who’s the lucky man?’</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> used between repeated words to emphasize what you are saying:</div><ul class=\"examples\"><li><em>More and more people are losing their jobs.</em></li><li><em>We waited for hours and hours!</em></li><li><em>That was years and years ago.</em></li><li><em>We ran and ran.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> used before saying the part of a large number which is less than 100:</div><ul class=\"examples\"><li><em>a hundred and four</em></li><li><em>five hundred and seventy-six</em></li><li><em>by the year two thousand and ten</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used when saying a number which consists of a whole number followed by a fraction:</div><ul class=\"examples\"><li><em>three and three-quarters</em></li><li><em>in about two and a half hours’ time</em></li><li><em>five and a quarter per cent</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> used between repeated plural nouns to say that some things of a particular kind are much better than others:</div><ul class=\"examples\"><li><em>‘They said this guy was an expert.’ ‘Yes, but there are experts and experts.’</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>and?</strong> <em>spoken</em> used when you want someone to add something to what they have just said:</div><ul class=\"examples\"><li><em>‘I’m sorry.’ ‘And?’ ‘And I promise it won’t happen again.’</em></li></ul></div>","285":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧ec‧dote</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈænɪkdəʊt $ -doʊt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a short story based on your personal experience:</div><ul class=\"examples\"><li><em>The book is full of amusing anecdotes about his life in Japan.</em></li></ul></div>","286":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧gel</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeɪndʒəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a spirit who is God’s servant in heaven, and who is often shown as a person dressed in white with wings:</div><ul class=\"examples\"><li><em>the angel Gabriel</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who is very kind, very good, or very beautiful:</div><ul class=\"examples\"><li><em>That little girl of theirs is an angel.</em></li><li><em>Sam is no angel (=often behaves badly).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>old-fashioned</em> <em>spoken</em> used when asking someone to help you or when thanking someone for helping you:</div><ul class=\"examples\"><li><em>Thanks for mailing those letters, you’re an angel.</em></li><li><em>Be an angel and get me my glasses, will you?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> (also business angel, angel investor) someone who gives new businesses money, often in exchange for a share of the company</div></div>","287":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧ger</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæŋɡə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a strong feeling of wanting to hurt or criticize someone because they have done something bad to you or been unkind to you:</div><ul class=\"examples\"><li><em>There is growing anger among the people against the government.</em></li><li><strong><em>anger at</strong>: She struggled to control her anger at her son’s disobedience.</em></li><li><strong><em>in anger</strong>: ‘That’s a lie!’ he shouted in anger.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>do/use something in anger</strong> to do or use something for the first time, or in a real situation:</div><ul class=\"examples\"><li><em>He joined the club last month, but has yet to kick a ball in anger.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to make someone angry <em>SYN annoy</em>: RegisterIn everyday English, people usually say something makes them angry rather than say that it angers them: I didn’t want to anger him. ➔ I didn’t want to make him angry.</div><ul class=\"examples\"><li><em>What angered me most was his total lack of remorse.</em></li><li><strong><em>be angered by/at something</strong>: Environmental groups were disappointed and angered by the president’s decision.</em></li></ul></div></div>","288":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧gle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæŋɡəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the space between two straight lines or surfaces that join each other, measured in degrees → right angle</div><ul class=\"examples\"><li><strong><em>an angle of something</strong>: an angle of 45°</em></li><li><strong><em>angle of</strong>: the angles of a triangle</em></li><li><em>You didn’t measure the angle accurately.</em></li><li><strong><em>angle between</strong>: the angle between walls and ceiling</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a way of considering a problem or situation:</div><ul class=\"examples\"><li><em>We’re approaching the issue from many different angles.</em></li><li><em>Look at every angle of the situation.</em></li><li><strong><em>angle to</strong>: There’s another angle to this question.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a position from which you look at something or photograph it</div><ul class=\"examples\"><li><strong><em>from a... angle</strong>: This drawing of the monastery was done from an unusual angle. / Some of the pictures have strange camera angles.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>at an angle</strong> leaning to one side and not straight or upright:</div><ul class=\"examples\"><li><em>The portrait was hanging at an angle.</em></li><li><strong><em>at a slight/steep angle</strong>: The sign leaned over at a slight angle.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> the shape formed when two lines or surfaces join</div><ul class=\"examples\"><li><strong><em>angle of</strong>: My head struck the angle of the shelf.</em></li></ul></div>","289":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧gry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæŋɡri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\">(comparative angrier, superlative angriest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> feeling strong emotions which make you want to shout at someone or hurt them because they have behaved in an unfair, cruel, offensive etc way, or because you think that a situation is unfair, unacceptable etc → annoyed:</div><ul class=\"examples\"><li><em>I was angry because he hadn’t told me his plans.</em></li><li><em>He was beginning to get angry.</em></li><li><em>His comments brought an angry response from opposition politicians.</em></li><li><em>‘Calm down,’ she said, looking at his angry face.</em></li><li><em>Jesse laughed, which made me even angrier.</em></li><li><strong><em>angry with</strong>: ‘Please don’t be angry with me,’ she said.</em></li><li><strong><em>angry at</strong>: They are angry at the way they have been treated.</em></li><li><strong><em>angry about/over</strong>: Kate’s still so angry about the whole thing.</em></li><li><strong><em>angry (that)</strong>: The workers are angry that they haven’t been paid for the week.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>angry with/at yourself</strong> feeling strongly that you wish you had done something or had not done something:</div><ul class=\"examples\"><li><em>David was angry with himself for letting the others see his true feelings.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>literary</em> an angry sky or cloud looks dark and stormy</div><div class=\"sense\"><span class=\"snum\">4</span> <em>literary</em> an angry wound etc is painful and red and looks infected <em>SYN inflamed</em></div></div>","290":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧guish</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæŋɡwɪʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">mental or physical suffering caused by extreme pain or worry:</div><ul class=\"examples\"><li><em>the anguish of not knowing what had happened to her</em></li></ul></div>","291":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧i‧mal</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈænəməl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a living creature such as a dog or cat, that is not an insect, plant, bird, fish, or person:</div><ul class=\"examples\"><li><em>furry little animals</em></li><li><strong><em>wild/domestic/farm animals</strong>: cattle, sheep, and other domestic animals</em></li><li><em>The cosmetics have not been tested on animals.</em></li><li><em>Beth is an animal lover (=someone who likes animals).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> any living creature that is not a plant or a person:</div><ul class=\"examples\"><li><em>He can’t stand cruelty to animals of any sort.</em></li><li><em>the animal welfare movement in Britain</em></li><li><em>the enormous diversity of the animal kingdom</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> any living creature, including people:</div><ul class=\"examples\"><li><em>Man is a highly intelligent animal.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>informal</em> someone who behaves in a cruel, violent, or very rude way:</div><ul class=\"examples\"><li><em>Football hooligans are just animals.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>a (very/completely/entirely) different animal</strong> <em>informal</em> something that is very different from the thing you have mentioned:</div><ul class=\"examples\"><li><em>Writing email is a very different animal from all other forms of writing.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>a political/social etc animal</strong> <em>informal</em> someone who is interested in politics, in meeting other people etc:</div><ul class=\"examples\"><li><em>He is simply not a social animal.</em></li></ul></div>","292":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧i‧mos‧i‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌænəˈmɒsəti $ -ˈmɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural animosities)</span></div><div class=\"entry-body\"><div class=\"sense\">strong dislike or hatred <em>SYN hostility</em></div><ul class=\"examples\"><li><strong><em>animosity between</strong>: There is no personal animosity between the party leaders.</em></li><li><strong><em>animosity towards/against</strong>: She felt a certain amount of animosity towards him.</em></li></ul></div>","293":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧kle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæŋkəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the joint between your foot and your leg</div><ul class=\"examples\"><li><strong><em>break/twist/sprain your ankle</strong>: Janet slipped on the stairs and twisted her ankle.</em></li><li><em>slender ankles</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>ankle socks/boots</strong> socks or boots that only come up to your ankle</div></div>","294":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧ni‧ver‧sa‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌænəˈvɜːsəri $ -ɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural anniversaries)</span></div><div class=\"entry-body\"><div class=\"sense\">a date on which something special or important happened in a previous year:</div><ul class=\"examples\"><li><em>Jack and Kim celebrated their twentieth wedding anniversary in January.</em></li><li><strong><em>anniversary of</strong>: A huge parade was held on the anniversary of the 1959 revolution.</em></li></ul></div>","295":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧nounce</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈnaʊns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to officially tell people about something, especially about a plan or a decision: ► see thesaurus at tell</div><ul class=\"examples\"><li><em>They announced their engagement in ‘The Times’.</em></li><li><strong><em>announce a decision/intention/plan</strong>: The government has announced plans to create 10,000 new jobs.</em></li><li><strong><em>announce that</strong>: A government spokesman announced that the hostages had been released.</em></li><li><em>At the end of their meeting, it was announced that an agreement had been reached.</em></li><li><strong><em>announce something to somebody</strong>: Cordon announced his resignation to staff members on Wednesday.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to say something, especially something that other people will not like, in a loud and confident way <em>SYN state</em>: ► see thesaurus at say</div><ul class=\"examples\"><li><em>‘I’m not going to their party,’ Maggie announced.</em></li><li><strong><em>announce (that)</strong>: He stood up and announced that he was ready to go.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to give information to people using a loudspeaker or microphone, especially at an airport or railway station:</div><ul class=\"examples\"><li><em>We arrived just as they were announcing the arrival of Flight 207 from Minneapolis.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>announce somebody/yourself</strong> to officially tell people that someone has arrived at a particular place:</div><ul class=\"examples\"><li><em>All visitors to the apartment building must be announced.</em></li><li><em>After announcing himself at the reception desk, James was led upstairs.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> to introduce a programme on television or radio</div></div>","296":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧nounce‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈnaʊnsmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> an important or official statement:</div><ul class=\"examples\"><li><em>The minister made the announcement at a news conference.</em></li><li><strong><em>announcement about</strong>: an important announcement about tax increases</em></li><li><strong><em>announcement that</strong>: They heard the announcement that the mayor was resigning.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the act of telling people that something important is going to happen</div><ul class=\"examples\"><li><strong><em>announcement of</strong>: the announcement of the company’s annual results</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a small advertisement or statement in a newspaper:</div><ul class=\"examples\"><li><em>a wedding announcement in the local paper</em></li></ul></div>","297":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧noy</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈnɔɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to make someone feel slightly angry and unhappy about something <em>SYN irritate</em>: RegisterIn everyday English, people also often use the phrase get on someone&#x27;s nerves:· She got on his nerves with her stupid questions.</div><ul class=\"examples\"><li><em>What annoyed him most was that he had received no apology.</em></li><li><em>She annoyed him with her stupid questions.</em></li><li><strong><em>it annoys somebody when/how/that</strong>: It really annoys me when I see people dropping litter.</em></li></ul></div>","298":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧noyed</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈnɔɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\">slightly angry <em>SYN irritated</em> → angry: ► see thesaurus at angry</div><ul class=\"examples\"><li><em>I’ll be annoyed if we don’t finish by eight.</em></li><li><strong><em>be annoyed at/with somebody</strong>: She was annoyed with Duncan for forgetting to phone.</em></li><li><strong><em>be annoyed about/by something</strong>: He was annoyed by her apparent indifference.</em></li><li><strong><em>annoyed that</strong>: Mr Davies was annoyed that the books were missing.</em></li></ul></div>","299":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧noy‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈnɔɪ-ɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\">making you feel slightly angry <em>SYN irritating</em>:</div><ul class=\"examples\"><li><em>an annoying habit of interrupting</em></li><li><em>The annoying thing is he’s usually right.</em></li><li><em>It’s annoying that we didn’t know about this before.</em></li></ul></div>","300":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧nu‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈænjuəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> happening once a year <em>SYN yearly</em>:</div><ul class=\"examples\"><li><em>The school trip has become an annual event.</em></li><li><strong><em>annual report/meeting/conference</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> based on or calculated over a period of one year <em>SYN yearly</em></div><ul class=\"examples\"><li><strong><em>annual budget/income/cost etc</strong>: a household with an annual income of $60,000</em></li></ul></div>","301":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧nu‧al‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈænjuəli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">once every year:</div><ul class=\"examples\"><li><em>The jazz festival is held annually in July.</em></li></ul></div>","302":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧nom‧a‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈnɒməli $ əˈnɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural anomalies)</span></div><div class=\"entry-body\"><div class=\"sense\">something that is noticeable because it is different from what is usual:</div><ul class=\"examples\"><li><em>In those days, a woman professor was still an anomaly.</em></li><li><strong><em>anomaly in</strong>: various anomalies in the tax system</em></li></ul></div>","303":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧non‧y‧mous</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈnɒnɪməs $ əˈnɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> unknown by name:</div><ul class=\"examples\"><li><em>the anonymous author of a collection of poems</em></li><li><strong><em>anonymous donor/benefactor</strong>: the anonymous donor of a large sum of money</em></li><li><em>According to one employee, who wishes to remain anonymous, the company engaged in illegal activities.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> done, sent, or given by someone who does not want their name to be known:</div><ul class=\"examples\"><li><em>an anonymous donation of $5,000</em></li><li><strong><em>anonymous phone call/letter etc</strong> (=one that is often unpleasant or contains threats)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>written</em> uninteresting in features or qualities – used to show disapproval:</div><ul class=\"examples\"><li><em>grey, anonymous housing estates</em></li></ul></div>","304":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧oth‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈnʌðə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[additional]</strong> one more person or thing of the same type:</div><ul class=\"examples\"><li><em>I’m going to have another cup of coffee.</em></li><li><em>There’ll be another bus along in a few minutes.</em></li><li><em>Buy two CDs and get another completely free.</em></li><li><strong><em>another of</strong>: Is this another of your schemes to make money?</em></li><li><em>Not another word was spoken.</em></li><li><em>Oh look, there’s another one of those birds.</em></li><li><em>This misunderstanding is yet another example of bad communication (=there have already been several).</em></li><li><strong><em>another 2/10/100 etc</strong> (=an additional amount or number): We’ll have to wait another three weeks for the results. / There’s still another £100 to pay.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[a different one]</strong> not the same thing, person etc, but a different one:</div><ul class=\"examples\"><li><em>They must have returned by another route.</em></li><li><em>We finally moved to another apartment.</em></li><li><em>I’m busy right now. Could you come back another time?</em></li><li><em>Helen resigned from her last job and has yet to find another.</em></li><li><strong><em>another of</strong>: The gold watch was a present from another of his girlfriends.</em></li><li><strong><em>from one... to another</strong>: She spends the day rushing from one meeting to another.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>one another</strong> used to say that two or more people or things do the same thing to each other or share a relationship:</div><ul class=\"examples\"><li><em>They seem to love one another very much.</em></li><li><em>The streets are all at right angles to one another.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>one... or another</strong> used to say that there are many different types of something, or many possibilities, rather than being specific:</div><ul class=\"examples\"><li><em>All the kids in this class have learning difficulties of one sort or another.</em></li><li><em>people who, for one reason or another, can’t have children</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>one after another</strong> used to talk about a series of similar things or events:</div><ul class=\"examples\"><li><em>Small businesses have been collapsing one after another.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>not another...!</strong> <em>spoken</em> used when a series of bad or annoying things have happened and something of the same type seems to have just happened again:</div><ul class=\"examples\"><li><em>Oh no! Not another accident!</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>be another thing/matter</strong> used to suggest that something may not be true, possible, easy etc, after mentioning something that is:</div><ul class=\"examples\"><li><em>It is true that his programme is original, though whether it is funny is quite another matter.</em></li><li><em>It is one thing to talk about ‘involving the students’; it is quite another thing to actually do this.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>and another thing</strong> <em>spoken</em> used to introduce something additional that you want to say to someone about a different subject:</div><ul class=\"examples\"><li><em>And another thing. You were late for work again this morning.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[similar person/thing]</strong> used with the name of a well-known person, thing, event etc to mean someone or something else that is similar because they have the same good or bad qualities:</div><ul class=\"examples\"><li><em>warnings that not enough has been done to prevent another Chernobyl</em></li><li><em>There’ll never be another Elvis Presley.</em></li></ul></div>","305":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧swer</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːnsə $ ˈænsər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[reply]</strong> <span class=\"gram\">[countable, uncountable]</span> something you say when you reply to a question that someone has asked you <em>SYN response</em>:</div><ul class=\"examples\"><li><em>You don’t have to give them an answer now.</em></li><li><em>Every time I ask him about it, I get a different answer.</em></li><li><strong><em>answer to</strong>: These are important questions, and we want answers to them.</em></li><li><em>She’s still waiting for an answer from the school.</em></li><li><em>The honest answer was that I didn’t know.</em></li><li><em>He was never able to get a straight answer about why it happened.</em></li><li><em>It’s impossible for me to give you a definite answer at this time.</em></li><li><em>The short answer is that it can’t be done.</em></li><li><em>In answer to your question, yes, you can go.</em></li><li><em>If it’s money you want, the answer is no!</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[test/competition etc]</strong> <span class=\"gram\">[countable]</span> something that you write or say in reply to a question in a test or competition</div><ul class=\"examples\"><li><strong><em>answer to</strong>: What was the answer to question 4?</em></li><li><strong><em>the right/wrong/correct/incorrect answer</strong>: Score two points for each correct answer.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[invitation/letter etc]</strong> <span class=\"gram\">[countable]</span> a written reply to a letter, invitation, advertisement etc</div><ul class=\"examples\"><li><strong><em>answer to</strong>: Did you ever get an answer to your letter?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[problem]</strong> <span class=\"gram\">[countable]</span> a way of dealing with a problem <em>SYN solution</em></div><ul class=\"examples\"><li><strong><em>simple/easy/obvious answer</strong>: There is no simple answer.</em></li><li><strong><em>answer to</strong>: The police do not have an answer to rising crime.</em></li><li><em>Some people think cars should be banned from the city, but I don’t think that’s the answer.</em></li><li><strong><em>be the answer to somebody’s problems/worries etc</strong>: If he could get a job, it’d be the answer to all his worries.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[on the phone]</strong> <span class=\"gram\">[singular, uncountable usually in negative]</span> if you get an answer when you call someone on the phone, they pick up the phone and talk to you:</div><ul class=\"examples\"><li><em>I tried calling him all day but couldn’t get an answer.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[at the door]</strong> <span class=\"gram\">[singular, uncountable usually in negative]</span> if you get an answer when you knock on a door, someone opens it and talks to you:</div><ul class=\"examples\"><li><em>I tried knocking on her door, but there was no answer.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>have/know all the answers</strong> <em>informal</em> to be very sure that you know everything about a situation, especially when you do not:</div><ul class=\"examples\"><li><em>He acts like he has all the answers.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>somebody’s answer to something</strong> <em>written</em> someone or something that is considered to be just as good as a more famous person or thing:</div><ul class=\"examples\"><li><em>The Space Needle is Seattle’s answer to the Eiffel Tower.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[reply]</strong> <span class=\"gram\">[intransitive, transitive]</span> to say something to someone as a reply when they have asked you a question, made a suggestion etc:</div><ul class=\"examples\"><li><em>She thought for a moment before answering.</em></li><li><em>He still hadn’t answered my question.</em></li><li><em>‘Why don’t you just leave?’ ‘I’d like to,’ she answered, ‘but I have nowhere else to go.’</em></li><li><strong><em>answer (that)</strong>: When questioned, Hughes answered that he knew nothing about the robbery.</em></li><li><em>How much was it? Come on, answer me.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[test]</strong> <span class=\"gram\">[intransitive, transitive]</span> to write or say the answer to a question in a test or competition:</div><ul class=\"examples\"><li><em>Answer as many questions as possible in the time provided.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>answer the phone/a call/the door</strong> to pick up the telephone and speak when it rings or open the door when someone knocks or rings the bell</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[letter]</strong> <span class=\"gram\">[transitive]</span> if you answer a letter or advertisement, you write a letter to the person who has written it:</div><ul class=\"examples\"><li><em>Simon got the job by answering an advert in the paper.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>answer criticism/charges/accusations etc</strong> to explain why you did something when people are criticizing you – used in news reports:</div><ul class=\"examples\"><li><em>How do you answer the criticism that your government has done nothing to help the homeless?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[react to something]</strong> <span class=\"gram\">[intransitive, transitive]</span> to do something as a reaction to criticism or an attack <em>SYN respond</em>:</div><ul class=\"examples\"><li><em>The army answered by firing into the crowd.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[deal with a problem]</strong> <span class=\"gram\">[transitive]</span> to be a way of dealing with or solving a problem:</div><ul class=\"examples\"><li><em>‘You can borrow my car if you like.’ ‘Well, that answers one problem.’</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>answer a need</strong> to provide something that is needed:</div><ul class=\"examples\"><li><em>Our transportation system is designed to answer the needs of the city’s commuters.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>answer a description</strong> if someone answers a description, they match that description:</div><ul class=\"examples\"><li><em>A man answering the police’s description was seen entering the building.</em></li></ul></div></div>","306":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ænt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a small insect that lives in large groups</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>have ants in your pants</strong> <em>spoken</em> to be so excited or full of energy that you are unable to sit or stand still – used humorously</div></div>","307":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧them</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈænθəm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a formal or religious song → national anthem</div><div class=\"sense\"><span class=\"snum\">2</span> a song that a particular group of people consider to be very important:</div><ul class=\"examples\"><li><em>The Rolling Stones’ ‘Satisfaction’ was an anthem for a generation.</em></li></ul></div>","308":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧thol‧o‧gy</span><span class=\"meta-item\"><strong>IPA:</strong> /ænˈθɒlədʒi $ ænˈθɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural anthologies)</span></div><div class=\"entry-body\"><div class=\"sense\">a set of stories, poems, songs etc by different people collected together in one book <em>SYN collection</em>:</div><ul class=\"examples\"><li><em>an anthology of American literature</em></li></ul></div>","309":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧ti‧bi‧ot‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌæntɪbaɪˈɒtɪk◂ $ -ˈɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable usually plural]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a drug that is used to kill bacteria and cure infections</div></div>","310":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧tic‧i‧pate</span><span class=\"meta-item\"><strong>IPA:</strong> /ænˈtɪsəpeɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to expect that something will happen and be ready for it:</div><ul class=\"examples\"><li><em>Sales are better than anticipated.</em></li><li><strong><em>anticipate changes/developments</strong>: The schedule isn’t final, but we don’t anticipate many changes.</em></li><li><strong><em>anticipate problems/difficulties</strong>: We don’t anticipate any problems.</em></li><li><em>A good speaker is able to anticipate an audience’s needs and concerns.</em></li><li><strong><em>anticipate (that)</strong>: This year, we anticipate that our expenses will be 15% greater. / It is anticipated that the research will have many different practical applications.</em></li><li><strong><em>anticipate doing something</strong>: I didn’t anticipate having to do the cooking myself!</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to think about something that is going to happen, especially something pleasant <em>SYN look forward to</em>:</div><ul class=\"examples\"><li><em>Daniel was eagerly anticipating her arrival.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to do something before someone else:</div><ul class=\"examples\"><li><em>Copernicus anticipated in part the discoveries of the 17th and 18th centuries.</em></li></ul></div>","311":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧tic‧i‧pa‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ænˌtɪsəˈpeɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> when you are expecting something to happen:</div><ul class=\"examples\"><li><em>She waited in eager anticipation for Robert to arrive.</em></li><li><em>Taylor was excited and full of anticipation at the prospect of the trip.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>do something in anticipation of something</strong> to do something because you expect something to happen:</div><ul class=\"examples\"><li><em>The workers have called off their strike in anticipation of a pay offer.</em></li></ul></div>","312":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧ti‧dote</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæntɪdəʊt $ -doʊt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a substance that stops the effects of a poison</div><ul class=\"examples\"><li><strong><em>antidote to</strong>: There is no known antidote to a bite from this snake.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> something that makes an unpleasant situation better:</div><ul class=\"examples\"><li><em>laughter, the antidote to stress</em></li></ul></div>","313":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧tique</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌænˈtiːk◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[usually before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">antique furniture, jewellery etc is old and often valuable: ► see thesaurus at old</div><ul class=\"examples\"><li><em>an antique rosewood desk</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a piece of furniture, jewellery etc that was made a very long time ago and is therefore valuable:</div><ul class=\"examples\"><li><em>The palace is full of priceless antiques.</em></li><li><em>They bought the clock at an antique shop in Bath.</em></li><li><em>an antique dealer (=someone who buys and sells antiques)</em></li></ul></div></div>","314":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧to‧nym</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæntənɪm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a word that means the opposite of another word → synonym:</div><ul class=\"examples\"><li><em>a dictionary of synonyms and antonyms</em></li></ul></div>","315":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> anx‧i‧e‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /æŋˈzaɪəti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\">(plural anxieties)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the feeling of being very worried about something <em>SYN concern</em></div><ul class=\"examples\"><li><strong><em>anxiety about/over</strong>: There is considerable anxiety among staff about job losses. / There is growing public anxiety over levels of air pollution in our cities.</em></li><li><strong><em>deep/acute/great anxiety</strong>: The fear of unemployment can be a source of deep anxiety to people.</em></li><li><em>his feelings of anxiety</em></li><li><em>A high level of anxiety was created by the introduction of cameras into the factory.</em></li><li><em>It can help if you discuss your anxieties with someone.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> a feeling of wanting to do something very much</div><ul class=\"examples\"><li><strong><em>anxiety to do something</strong>: I nearly fell in my anxiety to get downstairs quickly.</em></li></ul></div>","316":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> anx‧ious</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæŋkʃəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> worried about something ► see thesaurus at worried GRAMMAR: Prepositions with anxious• You are anxious about something: · She is anxious about the interview. ✗Don’t say: She is anxious for the interview.• You are anxious for another person (=worried that something bad might have happened to them): · They are anxious for their son.</div><ul class=\"examples\"><li><strong><em>anxious about</strong>: He was a bit anxious about the safety of the machinery.</em></li><li><strong><em>anxious for</strong>: We were anxious for you.</em></li><li><strong><em>anxious (that)</strong>: She was anxious that it might be cancer.</em></li><li><strong><em>an anxious look/expression</strong>: She gave me an anxious look.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an anxious time or situation is one in which you feel nervous or worried <em>SYN worrying</em>:</div><ul class=\"examples\"><li><em>We had an anxious couple of weeks waiting for the test results.</em></li><li><em>There was an anxious moment when the plane suddenly dropped.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> feeling strongly that you want to do something or want something to happen <em>SYN keen</em></div><ul class=\"examples\"><li><strong><em>anxious to do something</strong>: The company is anxious to improve its image. / He seemed most anxious to speak to me alone. / The president is anxious not to have another crisis.</em></li><li><strong><em>anxious for somebody to do something</strong>: Why was she so anxious for me to stay?</em></li><li><strong><em>anxious for</strong>: We were all anxious for news.</em></li><li><strong><em>anxious (that)</strong>: Both sides were anxious that the agreement should be signed as quickly as possible.</em></li></ul></div>","317":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">determiner</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeni/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[usually in questions and negatives]</span> some or even the smallest amount or number:</div><ul class=\"examples\"><li><em>Have you got any money?</em></li><li><em>Do you need any further information?</em></li><li><strong><em>any of</strong>: Are any of the paintings for sale? / They didn’t invite any of us.</em></li><li><em>Are there any other questions?</em></li><li><em>They haven’t shown any interest at all in my research.</em></li><li><em>The universities have shown few if any signs of a willingness to change.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to refer to a person or thing of a particular type when what you are saying is true of all people or things of that type:</div><ul class=\"examples\"><li><em>Any child who breaks the rules will be punished.</em></li><li><em>Always check the details carefully before you sign any written agreement.</em></li><li><em>I can see you any time on Monday.</em></li><li><em>If I can help in any way, let me know.</em></li><li><strong><em>any of</strong>: You can choose any of the books on the list.</em></li><li><em>This excuse was as good as any other.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> as much as possible:</div><ul class=\"examples\"><li><em>They’re going to need any help they can get.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>not just any (old) man/woman/job etc</strong> used to say that someone or something is special:</div><ul class=\"examples\"><li><em>She’s not just any actress, she’s one of the best.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[usually in questions and negatives]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used before the comparative form of an adjective to mean ‘even a small amount’:</div><ul class=\"examples\"><li><em>I can’t run any faster.</em></li><li><em>Are you feeling any better?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>not anymore/any longer</strong> if something does not happen anymore or any longer, it used to happen but does not happen now:</div><ul class=\"examples\"><li><em>It used to be quite cheap to fly there, but not anymore.</em></li><li><em>He was told he wasn’t wanted any longer.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>American English</em> <em>spoken</em> used with a verb to mean ‘at all’:</div><ul class=\"examples\"><li><em>We tried talking to him but that didn’t help any.</em></li></ul></div></div>","318":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧y‧bod‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeniˌbɒdi, ˈenibədi $ -ˌbɑːdi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W3</span></div><div class=\"entry-body\"><div class=\"sense\">anyone</div></div>","319":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧y‧how</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈenihaʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[sentence adverb]</span> <em>informal</em> anyway:</div><ul class=\"examples\"><li><em>The scandal could damage her reputation but the press reported it anyhow.</em></li><li><em>I’ve never been to a circus, not recently anyhow.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in a careless or untidy way:</div><ul class=\"examples\"><li><em>The cupboard would hardly close, with all the shoes thrown in anyhow.</em></li></ul></div>","320":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧y‧more</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌeniˈmɔː $ -ˈmɔːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><strong>not anymore</strong> used when something used to happen or be true in the past but does not happen or is not true now <em>SYN no longer</em>:</div><ul class=\"examples\"><li><em>Nick doesn’t live here anymore.</em></li><li><em>I don&#x27;t really like her anymore.</em></li><li><em>You&#x27;re describing a world that just doesn&#x27;t exist anymore.</em></li></ul></div>","321":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧y‧one</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeniwʌn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to refer to any person, when it is not important to say exactly who:</div><ul class=\"examples\"><li><em>Anyone could win tonight.</em></li><li><em>They offer help and advice to anyone interested in becoming a teacher.</em></li><li><em>If anyone sees Lisa, ask her to call me.</em></li><li><em>Anyone else who is interested in going on the trip should see me at the end of this lesson.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used in questions to mean ‘someone’:</div><ul class=\"examples\"><li><em>Does anyone want a drink?</em></li><li><em>Is there anyone new coming to tonight’s meeting?</em></li><li><em>Do you know anyone else who wants a ticket?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used in negative sentences to mean no person:</div><ul class=\"examples\"><li><em>I went to the bar but there wasn’t anyone there.</em></li><li><em>I haven’t spoken to anyone all day.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>anyone?</strong> used after mentioning something to show that you think it is not a good thing:</div><ul class=\"examples\"><li><em>I think people are dressing way too casually. I mean, shorts in the office, anyone?</em></li></ul></div>","322":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧y‧thing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeniθɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> any thing, event, situation etc, when it is not important to say exactly which:</div><ul class=\"examples\"><li><em>You can buy anything you want.</em></li><li><em>He was prepared to do anything to make a bit of money.</em></li><li><em>Anything would be better than staying at home!</em></li><li><em>You can write about swimming, skiing, or anything else you enjoy doing.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used in questions to mean ‘something’:</div><ul class=\"examples\"><li><em>Is there anything I can do to help?</em></li><li><em>Do you want anything from the shops?</em></li><li><em>Would you like anything else to eat?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used in negative sentences to mean no thing, event etc:</div><ul class=\"examples\"><li><em>We didn’t have anything to eat for three days.</em></li><li><em>Don’t do anything until we get there.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>anything but</strong> used to emphasize that someone or something does not have a particular quality:</div><ul class=\"examples\"><li><em>Maria is anything but stupid!</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>anything like somebody/something</strong> similar in any way to someone or something else:</div><ul class=\"examples\"><li><em>You don’t look anything like your mother.</em></li><li><em>If you’re anything like me, you’ll want to be where the action is.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>not anything like/near</strong> <em>spoken</em> used to emphasize a negative sentence:</div><ul class=\"examples\"><li><em>We don’t have anything like enough money to buy a new car.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>as important/clear/big etc as anything</strong> <em>informal</em> extremely important, clear etc:</div><ul class=\"examples\"><li><em>He was as nice as anything to me.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>or anything</strong> <em>spoken</em> or something that is similar:</div><ul class=\"examples\"><li><em>Would you like a drink or anything?</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>anything goes</strong> <em>informal</em> used to say that anything someone says or does is acceptable:</div><ul class=\"examples\"><li><em>From what other people were wearing, it looked like anything goes.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>for anything</strong> <em>informal</em> if you will not do something for anything, you will definitely not do it:</div><ul class=\"examples\"><li><em>I wouldn’t go back there for anything.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>like anything</strong> <em>informal</em> if you do something like anything, you do it a lot:</div><ul class=\"examples\"><li><em>We all encouraged him like anything.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>if anything</strong> <em>spoken</em> used when you are adding something to emphasize what you have just said:</div><ul class=\"examples\"><li><em>Sam didn’t seem too disappointed at losing. If anything, he seemed relieved that it was all over.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>anything you say</strong> <em>spoken</em> used to tell someone you agree with what they suggest:</div><ul class=\"examples\"><li><em>Yes, of course, anything you say.</em></li></ul></div>","323":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧y‧time</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈenitaɪm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\">at any time:</div><ul class=\"examples\"><li><em>Call me anytime. I’m always home.</em></li><li><em>They should arrive anytime between noon and 3 p.m.</em></li></ul></div>","324":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧y‧way</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeniweɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[sentence adverb]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in spite of the fact that you have just mentioned:</div><ul class=\"examples\"><li><em>Catherine wasn’t sure the book was the right one, but she bought it anyway.</em></li><li><em>This idea probably won’t work, but let’s try it anyway.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used when adding a remark which shows that the fact just mentioned is not important:</div><ul class=\"examples\"><li><em>They didn’t have any trainers in my size, and anyway I’d already decided I’d rather save the money.</em></li><li><em>‘I hope you haven’t told anyone.’ ‘No. Who would believe me anyway?’</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used when adding something that corrects or slightly changes what you have just said:</div><ul class=\"examples\"><li><em>Let’s think about it for a while, for a few days anyway.</em></li><li><em>There seems to have been a technical problem – anyway, that’s what they told me.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>spoken</em> used when you are ignoring details so that you can talk immediately about the most important thing:</div><ul class=\"examples\"><li><em>He got lost and spent hours looking for the station, and anyway it was past midnight by the time he got home.</em></li><li><em>Anyway, why didn’t you call the police?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>spoken</em> used when you are changing the subject of a conversation or returning to a previous subject:</div><ul class=\"examples\"><li><em>Anyway, let’s leave that for the moment and look at this month’s profit figures.</em></li><li><em>Anyway, how are you?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <em>spoken</em> used when you want to end a conversation or leave a place:</div><ul class=\"examples\"><li><em>Anyway, I must be going now.</em></li></ul></div>","325":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> an‧y‧where</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeniweə $ -wer/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in or to any place:</div><ul class=\"examples\"><li><em>Sit anywhere you like.</em></li><li><em>You can buy clothes like these anywhere.</em></li><li><em>I don’t want to live in London, but I’d be happy living anywhere else.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used in questions to mean ‘somewhere’:</div><ul class=\"examples\"><li><em>Do you need anywhere to stay for the night?</em></li><li><em>Did you go anywhere exotic on vacation this year?</em></li><li><em>Have you been anywhere else in Spain?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used in negative sentences to mean no place:</div><ul class=\"examples\"><li><em>I can’t find my passport anywhere.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>not anywhere near</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> not at all near:</div><ul class=\"examples\"><li><em>I wasn’t anywhere near him when he fell.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> not at all:</div><ul class=\"examples\"><li><em>I don’t think these figures are anywhere near accurate.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>anywhere between one and ten/anywhere from one to ten etc</strong> used to mean any age, number, amount etc between the ones that you say:</div><ul class=\"examples\"><li><em>She could have been anywhere between 45 and 60 years of age.</em></li><li><em>We can accommodate anywhere between 60 and 300 people.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>not get anywhere</strong> <em>informal</em> to not be successful at all:</div><ul class=\"examples\"><li><em>You won’t get anywhere without qualifications.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>not get somebody anywhere</strong> <em>informal</em> if something does not get you anywhere, it does not change a situation or help you to achieve something:</div><ul class=\"examples\"><li><em>You can try writing to complain, but I don’t think it will get you anywhere.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>not be going anywhere</strong> <em>informal</em> to not be achieving success in your life:</div><ul class=\"examples\"><li><em>He’s a nice enough lad, but he’s not going anywhere.</em></li></ul></div>","326":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧part</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpɑːt $ -ɑːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[not close/touching]</strong> if things are apart, they are not close to each other or touching each other</div><ul class=\"examples\"><li><strong><em>two miles/six feet etc apart</strong>: Place the two posts 6 metres apart.</em></li><li><em>They have offices in countries as far apart as India and Peru.</em></li><li><em>The police try to keep rival supporters apart at all matches.</em></li><li><em>A couple of men started fighting and we had to pull them apart.</em></li><li><em>Joel stood apart from the group, frowning.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[in different pieces]</strong> if something comes apart, or you take it apart, it is separated into different pieces:</div><ul class=\"examples\"><li><em>The whole thing comes apart so that you can clean it.</em></li><li><em>They took the engine apart to see what was wrong.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[separate]</strong> if you keep things apart, you keep them separate from each other:</div><ul class=\"examples\"><li><em>I try to keep my work and private life as far apart as possible.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[not at same time]</strong> if things are a particular time apart, they do not happen at the same time but have that much time between them</div><ul class=\"examples\"><li><strong><em>two days/three weeks/five years etc apart</strong>: Our birthdays are exactly a month apart.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[people]</strong> if people are apart, they are not together in the same place, or not having a relationship with each other:</div><ul class=\"examples\"><li><em>The children have never been apart before.</em></li><li><em>My wife and I are living apart at the moment.</em></li><li><strong><em>apart from</strong>: He’s never been apart from his mother.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>fall apart</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if something falls apart, it breaks into different pieces:</div><ul class=\"examples\"><li><em>It just fell apart in my hands!</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if something is falling apart, it is in very bad condition:</div><ul class=\"examples\"><li><em>He drives around in an old car that’s falling apart.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> if something falls apart, it fails completely:</div><ul class=\"examples\"><li><em>He lost his job and his marriage fell apart.</em></li><li><em>The country’s economy is in danger of falling apart.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>be torn apart</strong> if a marriage, family etc is torn apart, it can no longer continue because of serious difficulties:</div><ul class=\"examples\"><li><em>The play portrays a good marriage torn apart by external forces.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>be worlds/poles apart</strong> if people, beliefs, or ideas are worlds or poles apart, they are completely different from each other:</div><ul class=\"examples\"><li><em>I realized we were still worlds apart.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>grow/drift apart</strong> if people drift or grow apart, their relationship slowly becomes less close:</div><ul class=\"examples\"><li><em>Lewis and his father drifted apart after he moved to New York.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>joking apart</strong> used to say that you want to say something seriously:</div><ul class=\"examples\"><li><em>Joking apart, they did do quite a good job for us.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>somebody/something apart</strong> except for someone or something:</div><ul class=\"examples\"><li><em>The car industry apart, most industries are now seeing an improvement in their economic performance.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>set somebody/something apart</strong> to make someone or something different from other people or things:</div><ul class=\"examples\"><li><em>Her unusual lifestyle set her apart as a child.</em></li></ul></div>","327":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧part‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpɑːtmənt $ -ɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>especially American English</em> a set of rooms on one floor of a large building, where someone lives SYN flat<em>British English</em>:</div><ul class=\"examples\"><li><em>She lives in a small apartment.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[usually plural]</span> a room or set of rooms used by an important person such as a president:</div><ul class=\"examples\"><li><em>I had never been in the prince’s private apartments before.</em></li><li><em>the presidential apartments</em></li></ul></div>","328":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧a‧thet‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌæpəˈθetɪk◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">not interested in something, and not willing to make any effort to change or improve things:</div><ul class=\"examples\"><li><em>She felt too apathetic even to move.</em></li><li><strong><em>apathetic about</strong>: How can you be so apathetic about the world and its problems?</em></li></ul></div>","329":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧a‧thy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæpəθi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the feeling of not being interested in something, and not willing to make any effort to change or improve things:</div><ul class=\"examples\"><li><em>The campaign failed because of public apathy.</em></li></ul></div>","330":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /eɪp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an animal that is similar to a monkey but has no tail or only a very short tail</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>go ape</strong> <em>informal</em> to suddenly become very angry</div></div>","331":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧pol‧o‧get‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /əˌpɒləˈdʒetɪk◂ $ əˌpɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">showing or saying that you are sorry that something has happened, especially because you feel guilty or embarrassed about it</div><ul class=\"examples\"><li><strong><em>apologetic about</strong>: The manager was very apologetic about everything.</em></li><li><em>She gave me an apologetic smile.</em></li><li><strong><em>look/sound apologetic</strong>: Dan came in looking very apologetic.</em></li></ul></div>","332":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧pol‧o‧gize</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpɒlədʒaɪz $ əˈpɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to tell someone that you are sorry that you have done something wrong → apologetic: RegisterIn everyday English, people often use the phrases say (you are) sorry or tell someone you are sorry, rather than apologize (to somebody): I&#x27;ve already apologized to him. ➔ I’ve already told him I&#x27;m sorry.</div><ul class=\"examples\"><li><em>I’m so sorry, I do apologize.</em></li><li><strong><em>apologize to</strong>: I think you should apologize to your brother.</em></li><li><strong><em>apologize for (doing) something</strong>: He later apologized for his behaviour. / I apologize for losing my temper.</em></li></ul></div>","333":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧pol‧o‧gy</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpɒlədʒi $ əˈpɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\">(plural apologies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> something that you say or write to show that you are sorry for doing something wrong</div><ul class=\"examples\"><li><strong><em>apology for</strong>: The minister had to issue a formal public apology for his remarks.</em></li><li><strong><em>apology from</strong>: She finally received an apology from the company.</em></li><li><strong><em>apology to</strong>: an apology to passengers for any inconvenience caused</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>apologies</strong> <span class=\"gram\">[plural]</span> a message that you send to a meeting to say that you will not be able to come to the meeting:</div><ul class=\"examples\"><li><em>Edward can’t be here today, but he sends his apologies.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>make your apologies</strong> to say that you are sorry but you have to leave:</div><ul class=\"examples\"><li><em>I quickly made my apologies and left.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>make no apology for something</strong> to not say that you are sorry for something, because you do not regret it and you think it is the right thing to do:</div><ul class=\"examples\"><li><em>We make no apology for defending our members’ interests – that is our job.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> <em>literary</em> a statement in which you defend something you believe in after it has been criticized by other people</div><ul class=\"examples\"><li><strong><em>apology for</strong>: an apology for Christianity</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>an apology for something</strong> a very bad example of something:</div><ul class=\"examples\"><li><em>They served us up an apology for a meal.</em></li></ul></div>","334":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧pal</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpɔːl $ əˈpɒːl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to make someone feel very shocked and upset <em>SYN horrify</em>:</div><ul class=\"examples\"><li><em>The way we kill animals appals a lot of people.</em></li><li><em>The decision to execute the two men has appalled many politicians.</em></li></ul></div>","335":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧palled</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpɔːld $ əˈpɒːld/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">very shocked and upset by something very bad or unpleasant ► see thesaurus at shocked</div><ul class=\"examples\"><li><strong><em>appalled by</strong>: I was appalled by what I saw.</em></li><li><strong><em>appalled at</strong>: He was appalled at how dirty the place was.</em></li><li><em>When I heard what had happened I was absolutely appalled.</em></li></ul></div>","336":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧pal‧ling</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpɔːlɪŋ $ əˈpɒː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> very unpleasant and shocking <em>SYN terrible</em>:</div><ul class=\"examples\"><li><em>She suffered appalling injuries.</em></li><li><em>He was kept in appalling conditions in prison.</em></li><li><em>an appalling famine</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> very bad <em>SYN atrocious</em>: ► see thesaurus at bad</div><ul class=\"examples\"><li><em>The weather was absolutely appalling.</em></li></ul></div>","337":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧pa‧ra‧tus</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌæpəˈreɪtəs $ -ˈræ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the set of tools and machines that you use for a particular scientific, medical, or technical purpose <em>SYN equipment</em>:</div><ul class=\"examples\"><li><em>Astronauts have special breathing apparatus.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> the way in which a lot of people are organized to work together to do a job or control a company or country <em>SYN machinery</em>:</div><ul class=\"examples\"><li><em>The tax will require a massive administrative apparatus.</em></li><li><em>The state apparatus has become corrupt.</em></li><li><em>the apparatus of government</em></li></ul></div>","338":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧par‧ent</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpærənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> easy to notice <em>SYN obvious</em></div><ul class=\"examples\"><li><strong><em>it is apparent (that)</strong>: It soon became apparent that we had a major problem.</em></li><li><strong><em>it is apparent from something that</strong>: It is apparent from scientific studies that the drug has some fairly nasty side effects.</em></li><li><strong><em>it is apparent to somebody that</strong>: It was apparent to everyone that he was seriously ill.</em></li><li><em>The difference in quality was immediately apparent.</em></li><li><em>He left suddenly, for no apparent reason.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> seeming to have a particular feeling or attitude, although this may not be true:</div><ul class=\"examples\"><li><em>He did well in his exams, despite his apparent lack of interest in his work.</em></li></ul></div>","339":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧par‧ent‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpærəntli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[sentence adverb]</span> used to say that you have heard that something is true, although you are not completely sure about it:</div><ul class=\"examples\"><li><em>Apparently the company is losing a lot of money.</em></li><li><em>I wasn’t there, but apparently it went well.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> according to the way someone looks or a situation appears, although you cannot be sure:</div><ul class=\"examples\"><li><em>She turned to face him, her anger apparently gone.</em></li></ul></div>","340":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧peal</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpiːl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[request]</strong> <span class=\"gram\">[countable]</span> an urgent request for something important</div><ul class=\"examples\"><li><strong><em>appeal for</strong>: The police have issued a new appeal for information.</em></li><li><strong><em>appeal to</strong>: All the organizations involved have sent urgent appeals to the government, asking for extra funding.</em></li><li><em>The girl’s family have made a public appeal for help to try and catch her killer.</em></li><li><strong><em>appeal to somebody to do something</strong>: an appeal to the army to not use too much force</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[request for money]</strong> <span class=\"gram\">[countable]</span> an attempt to persuade people to give money in order to help people who need something:</div><ul class=\"examples\"><li><em>The appeal has nearly reached its target of £100,000.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[request to change decision]</strong> <span class=\"gram\">[countable, uncountable]</span> a formal request to a court or to someone in authority asking for a decision to be changed</div><ul class=\"examples\"><li><strong><em>appeal to</strong>: an appeal to the European Court of Human Rights</em></li><li><strong><em>on appeal</strong>: The sentence was reduced to three years on appeal.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[being attractive]</strong> <span class=\"gram\">[uncountable]</span> a quality that makes people like something or someone:</div><ul class=\"examples\"><li><em>What is the particular appeal of this island?</em></li><li><em>The programme has a very wide appeal.</em></li><li><strong><em>appeal for</strong>: The film has great appeal for young audiences.</em></li><li><em>She’s definitely got sex appeal (=she is sexually attractive).</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[ask]</strong> <span class=\"gram\">[intransitive]</span> to make a serious public request for help, money, information etc</div><ul class=\"examples\"><li><strong><em>appeal for</strong>: Church and community leaders have appealed for calm.</em></li><li><strong><em>appeal to</strong>: Farmers have appealed to the government for help.</em></li><li><strong><em>appeal to somebody to do something</strong>: The police have appealed to anyone with information to come forward and talk to them.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[ask to change decision]</strong> <span class=\"gram\">[intransitive, transitive]</span> to make a formal request to a court or someone in authority asking for a decision to be changed:</div><ul class=\"examples\"><li><em>She is not happy with the decision and plans to appeal.</em></li><li><strong><em>appeal against</strong>: Both men intend to appeal against their convictions.</em></li><li><strong><em>appeal to</strong>: Appealing to the referee does not often result in a decision being changed.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[be attractive]</strong> <span class=\"gram\">[intransitive]</span> if someone or something appeals to you, they seem attractive and interesting</div><ul class=\"examples\"><li><strong><em>appeal to</strong>: The programme appeals to young children.</em></li><li><em>The idea of working abroad really appeals to me.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>appeal to somebody’s better nature/sense of justice etc</strong> to try to persuade someone to do something by reminding them that it is a good or fair thing to do:</div><ul class=\"examples\"><li><em>You could always try appealing to his better nature.</em></li></ul></div></div>","341":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧pear</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpɪə $ əˈpɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[seem]</strong> <span class=\"gram\">[linking verb]</span> used when saying how someone or something seems. Appear is more formal than seem GRAMMARLinking verbsAppear is a linking verb. This type of verb links the subject of the sentence with an adjective or noun: · His explanation appears unlikely.· This appears a good solution.Using the progressiveAppear is not used in the progressive in this meaning. You say: · He appears to be unhappy. ✗Don’t say: He is appearing to be unhappy.Grammar guide ‒ VERBS</div><ul class=\"examples\"><li><strong><em>appear to be something</strong>: The diamonds appeared to be genuine.</em></li><li><strong><em>appear to do something</strong>: The research appears to show that the drug is effective in most cases.</em></li><li><strong><em>appear to somebody</strong>: He didn&#x27;t appear to me to be a violent man.</em></li><li><strong><em>it appears (that)</strong> (=used when saying what you think has happened or is true): It appears that all the files have been deleted.</em></li><li><strong><em>there appear(s) to be something</strong> (=used when saying what you think has happened or is true): There appears to be some kind of problem.</em></li><li><em>Police have found what appear to be human remains.</em></li><li><em>He tried to make it appear that she had committed suicide.</em></li><li><em>It may be less useful than it first appears.</em></li><li><strong><em>appear + adj</strong>: During the interview she appeared calm and relaxed. / I don’t want to appear rude.</em></li><li><strong><em>so it would appear</strong> (=used when saying that something seems to be true, although you are not completely sure): ‘Have they gone?’ ‘So it would appear.’</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[start to be seen]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to start to be seen, to arrive, or to exist in a place, especially suddenly:</div><ul class=\"examples\"><li><em>Two faces appeared at our window.</em></li><li><em>A man suddenly appeared from behind a tree.</em></li><li><em>Small cracks appeared in the wall.</em></li><li><em>It was nearly an hour before Sweeney appeared in the pub.</em></li><li><strong><em>appear from nowhere/out of nowhere</strong> (=appear suddenly and unexpectedly): The car seemed to appear from nowhere.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[film/tv programme etc]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to take part in a film, play, concert, television programme etc</div><ul class=\"examples\"><li><strong><em>appear in a film/play</strong>: She has already appeared in a number of films.</em></li><li><strong><em>appear on television/stage</strong>: He appeared on national television to deny the claims.</em></li><li><strong><em>appear at a theatre etc</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[book/newspaper etc]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to be written or shown on a list, in a book or newspaper, in a document etc:</div><ul class=\"examples\"><li><em>The story appeared in all the national newspapers.</em></li><li><em>Some of the material used has appeared in print before (=has been published).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[available/known]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to become widely available or known about:</div><ul class=\"examples\"><li><em>The new range will be appearing in shops in the autumn.</em></li><li><em>New courses are appearing every year.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[law court/meeting]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to go to a law court or other official meeting to give information, answer questions etc:</div><ul class=\"examples\"><li><em>The three men are due to appear in court tomorrow.</em></li><li><strong><em>appear before a court/judge/committee etc</strong>: She appeared before Colchester magistrates charged with attempted murder.</em></li><li><strong><em>appear for somebody/on behalf of somebody</strong> (=to be the legal representative for someone): Sir Nicholas Gammon QC appeared on behalf of the defendant.</em></li></ul></div>","342":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧pear‧ance</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpɪərəns $ əˈpɪr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[way somebody/something looks]</strong> <span class=\"gram\">[countable, uncountable]</span> the way someone or something looks to other people:</div><ul class=\"examples\"><li><em>He was always criticising his wife’s appearance.</em></li><li><strong><em>appearance of</strong>: They’ve changed the appearance of the whole building.</em></li><li><em>We are often attracted to somebody first by their physical appearance.</em></li><li><em>Women, in general, tend to be more concerned than men about their personal appearance.</em></li><li><em>She had an outward appearance of calm, but deep down she was really worried.</em></li><li><em>The metal posts spoiled the appearance of the garden.</em></li><li><em>A garnish helps to enhance the appearance of any dish.</em></li><li><em>She’s the kind of woman who takes pride in her appearance.</em></li><li><em>You shouldn’t judge by appearances.</em></li><li><em>They work hard at school without giving the appearance of being particularly hard-working.</em></li><li><em>The case had all the appearances of a straightforward murder.</em></li><li><em>The pupils looked angelic – but appearances can be deceptive.</em></li><li><em>He was, to all appearances, a respectable, successful businessman.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[somebody takes part in a public event]</strong> <span class=\"gram\">[countable]</span> when a famous person takes part in a film, concert, or other public event:</div><ul class=\"examples\"><li><em>It was his first public appearance since the election.</em></li><li><em>He made his last appearance for the club in the Cup Final.</em></li><li><strong><em>appearance money/fee</strong> (=money paid to a famous person to attend an event)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[something new starts to exist]</strong> <span class=\"gram\">[singular]</span> when something new begins to exist or starts being used</div><ul class=\"examples\"><li><strong><em>appearance of</strong>: The industry has changed greatly with the appearance of new technologies. / the appearance of buds on the trees</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[arrival]</strong> <span class=\"gram\">[countable usually singular]</span> the unexpected or sudden arrival of someone or something</div><ul class=\"examples\"><li><strong><em>appearance of</strong>: Eileen was deep in concentration, and the sudden appearance of her daughter startled her.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>keep up appearances</strong> to dress and behave in the way in which people expect you to, especially to hide your true situation:</div><ul class=\"examples\"><li><em>She just wanted to keep up appearances for the kids.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>for appearances’ sake/for the sake of appearances</strong> if you do something for appearances’ sake, you are trying to behave how people expect you to, especially to hide your true situation or feelings</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>put in an appearance/make an appearance</strong> to go to an event for a short time, because you think you should rather than because you want to:</div><ul class=\"examples\"><li><em>At least Marc managed to put in an appearance at the party.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[at a law court/meeting]</strong> <span class=\"gram\">[countable]</span> an occasion when someone goes to a court of law or official meeting to give information, answer questions etc:</div><ul class=\"examples\"><li><em>He is due to make another court appearance on Monday.</em></li></ul></div>","343":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧pen‧dix</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpendɪks/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (plural appendixes) a small organ near your bowel, which has little or no use:</div><ul class=\"examples\"><li><em>Christine had to go into hospital to have her appendix out (=have it removed).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (plural appendices /-dəsiːz/) a part at the end of a book containing additional information:</div><ul class=\"examples\"><li><em>See Appendix 2.6.</em></li></ul></div>","344":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧pe‧tite</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæpətaɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable usually singular, uncountable]</span> a desire for food:</div><ul class=\"examples\"><li><em>Her husband always had a huge appetite.</em></li><li><em>Symptoms include tiredness and loss of appetite.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a desire or liking for a particular activity</div><ul class=\"examples\"><li><strong><em>appetite for</strong>: She has an amazing appetite for knowledge.</em></li><li><em>People seem to have an insatiable appetite (=always wanting more of something) for news of any kind.</em></li><li><em>a loss of sexual appetite</em></li></ul></div>","345":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧pe‧tiz‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæpətaɪzɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">food that is appetizing smells or looks very good, making you want to eat it <em>OPP unappetizing</em>:</div><ul class=\"examples\"><li><em>an appetizing aroma</em></li><li><em>The food wasn’t particularly appetizing.</em></li></ul></div>","346":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧plaud</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈplɔːd $ əˈplɒːd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to hit your open hands together, to show that you have enjoyed a play, concert, speaker etc <em>SYN clap</em>: RegisterIn everyday English, people usually say clap rather than applaud:· Everyone was clapping and cheering.</div><ul class=\"examples\"><li><em>The audience applauded loudly.</em></li><li><em>A crowd of 300 supporters warmly applauded her speech.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> <em>formal</em> to express strong approval of an idea, plan etc: ► see thesaurus at praise</div><ul class=\"examples\"><li><em>I applaud the decision to install more security cameras.</em></li><li><strong><em>applaud somebody for something</strong>: She should be applauded for her honesty.</em></li></ul></div>","347":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧plause</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈplɔːz $ əˈplɒːz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the sound of many people hitting their hands together and shouting, to show that they have enjoyed something:</div><ul class=\"examples\"><li><em>She got a round of applause (=a short period of applause) when she finished.</em></li><li><strong><em>rapturous/enthusiastic applause</strong>: He left the stage to rapturous applause.</em></li><li><strong><em>loud/thunderous applause</em></strong></li></ul></div>","348":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧ple</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæpəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a hard round fruit that has red, light green, or yellow skin and is white inside: → cooking apple, eating apple</div><ul class=\"examples\"><li><em>apple pie</em></li><li><em>an apple tree</em></li><li><em>roast pork and apple sauce (=a thick sauce made from cooked apples)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be the apple of somebody’s eye</strong> to be loved very much by someone:</div><ul class=\"examples\"><li><em>Ben was always the apple of his father’s eye.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>bob/dunk/dip for apples</strong> to play a game in which you must use your teeth to pick up apples floating in water</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>be as American as apple pie</strong> used to describe something that is typically American</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>the apple doesn’t fall far from the tree</strong> <em>American English</em> used to say that children are usually similar to their parents, especially in a bad way</div></div>","349":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧pli‧cant</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæplɪkənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who has formally asked, usually in writing, for a job, university place etc → apply</div><ul class=\"examples\"><li><strong><em>applicant for</strong>: He was one of 30 applicants for the manager’s job.</em></li><li><strong><em>successful/unsuccessful applicant</strong> (=someone who is accepted or not accepted for a job etc): Successful applicants will be expected to travel extensively.</em></li></ul></div>","350":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧pli‧ca‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌæplɪˈkeɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[written request]</strong> <span class=\"gram\">[countable, uncountable]</span> a formal, usually written, request for something such as a job, place at university, or permission to do something</div><ul class=\"examples\"><li><strong><em>application for</strong>: an application for a grant</em></li><li><strong><em>application from</strong>: The university welcomes applications from overseas students.</em></li><li><em>We receive hundreds of job applications each year.</em></li><li><em>I filled in the application form and sent it off.</em></li><li><em>You have to submit your application before the end of the month.</em></li><li><em>I’ve put in an application for a transfer.</em></li><li><em>He received a letter saying that his application had been rejected.</em></li><li><em>It can take a long time for your visa application to be processed.</em></li><li><em>The Council is currently reviewing the way it deals with planning applications.</em></li><li><em>Thank you for your letter of application, which we received yesterday.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[practical use]</strong> <span class=\"gram\">[countable, uncountable]</span> the practical purpose for which a machine, idea etc can be used, or a situation when this is used</div><ul class=\"examples\"><li><strong><em>application of/to/in</strong>: the applications of genetic engineering in agriculture</em></li><li><em>The research has many practical applications.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[computers]</strong> <span class=\"gram\">[countable]</span> a piece of computer software which does a particular job:</div><ul class=\"examples\"><li><em>We received training on a number of spreadsheet and database applications.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[paint/liquid]</strong> <span class=\"gram\">[countable, uncountable]</span> when you put something such as paint, liquid, medicine etc onto a surface</div><ul class=\"examples\"><li><strong><em>application of</strong>: The application of fertilizer increased the size of the plants.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[effort]</strong> <span class=\"gram\">[uncountable]</span> attention or effort over a long period of time:</div><ul class=\"examples\"><li><em>Making your new business successful requires luck, patience, and application.</em></li></ul></div>","351":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧plied</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈplaɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><strong>applied science/physics/linguistics etc</strong> science etc that has a practical use</div></div>","352":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧ply</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈplaɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense and past participle applied, present participle applying, third person singular applies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[request]</strong> <span class=\"gram\">[intransitive]</span> to make a formal request, usually written, for something such as a job, a place at a university, or permission to do something</div><ul class=\"examples\"><li><strong><em>apply for</strong>: She applied for a job with the local newspaper.</em></li><li><em>We need to apply for planning permission to build a garage.</em></li><li><strong><em>apply to</strong>: I applied to four universities and was accepted by all of them.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[affect]</strong> <span class=\"gram\">[intransitive, transitive not in progressive]</span> to have an effect on or to concern a particular person, group, or situation</div><ul class=\"examples\"><li><strong><em>apply to</strong>: Do the same rules apply to part-time workers? / The offer only applies to flights from London and Manchester.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[use]</strong> <span class=\"gram\">[transitive]</span> to use something such as a method, idea, or law in a particular situation, activity, or process ► see thesaurus at use</div><ul class=\"examples\"><li><strong><em>apply something to something</strong>: New technology is being applied to almost every industrial process.</em></li><li><em>These ideas are often difficult to apply in practice.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>apply yourself</strong> to work hard at something, especially with a lot of attention for a long time:</div><ul class=\"examples\"><li><em>Stephen would do well if only he applied himself.</em></li><li><strong><em>apply to</strong>: Over the next months, he applied himself to improving the technique.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[make something work]</strong> <span class=\"gram\">[transitive]</span> to make something such as a piece of equipment operate, usually by pushing or pressing something:</div><ul class=\"examples\"><li><em>apply the brakes</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[spread paint/liquid etc]</strong> <span class=\"gram\">[transitive]</span> to put or spread something such as paint, liquid, or medicine onto a surface:</div><ul class=\"examples\"><li><em>Apply the cream evenly over the skin.</em></li><li><strong><em>apply make-up/lipstick etc</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>apply force/pressure</strong> to push on something</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>[use a word]</strong> <span class=\"gram\">[transitive]</span> to use a particular word or name to describe something or someone:</div><ul class=\"examples\"><li><em>The term ‘mat’ can be applied to any small rug.</em></li></ul></div>","353":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧point</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpɔɪnt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to choose someone for a position or a job:</div><ul class=\"examples\"><li><em>officials appointed by the government</em></li><li><strong><em>appoint somebody to something</strong>: He’s been appointed to the State Supreme Court.</em></li><li><strong><em>appoint somebody to do something</strong>: A committee was appointed to consider the plans.</em></li><li><strong><em>appoint (somebody) as something</strong>: O&#x27;Connell was appointed as chairman.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> to arrange or decide a time or place for something to happen:</div><ul class=\"examples\"><li><em>The committee appointed a day in June for celebrations.</em></li><li><em>Everyone assembled in the hall at the appointed time (=at the time that had been arranged).</em></li></ul></div>","354":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧point‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpɔɪntmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> an arrangement for a meeting at an agreed time and place, for a particular purpose</div><ul class=\"examples\"><li><strong><em>an appointment to do something</strong>: I’d like to make an appointment to see the doctor.</em></li><li><strong><em>appointment with</strong>: He has an appointment with a client at 10.30.</em></li><li><em>All consultations are by appointment only.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> when someone is chosen for a position or job</div><ul class=\"examples\"><li><strong><em>appointment of</strong>: Other changes included the appointment of a new Foreign Minister.</em></li><li><strong><em>appointment as</strong>: They congratulated him on his appointment as chairman.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a job or position, usually involving some responsibility ► see thesaurus at job</div><ul class=\"examples\"><li><strong><em>appointment as</strong>: He has taken up an appointment as Professor of Chemistry.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>by appointment to the Queen</strong> <em>British English</em> a phrase that can be used by a business that sells goods or services to the Queen</div></div>","355":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧prais‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpreɪzəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a statement or opinion judging the worth, value, or condition of something</div><ul class=\"examples\"><li><strong><em>appraisal of</strong>: It needed a calmer appraisal of her situation. / a critical appraisal of the existing facilities</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a meeting between a manager and a worker to discuss the quality of someone’s work and how well they do their job</div></div>","356":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧pre‧ci‧ate</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpriːʃieɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to understand how serious or important a situation or problem is or what someone’s feelings are <em>SYN realize</em></div><ul class=\"examples\"><li><strong><em>appreciate the significance/importance/value of something</strong>: He did not fully appreciate the significance of signing the contract.</em></li><li><strong><em>appreciate that</strong>: We appreciate that caring for children is an important job.</em></li><li><strong><em>appreciate what/how/why</strong>: It is difficult to appreciate how bad the situation had become.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> used to thank someone in a polite way or to say that you are grateful for something they have done:</div><ul class=\"examples\"><li><em>Thanks ever so much for your help, I really appreciate it.</em></li><li><em>I appreciate your concern, but honestly, I’m fine.</em></li><li><em>I’d appreciate it if you let me get on with my job.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to understand how good or useful someone or something is:</div><ul class=\"examples\"><li><em>Her abilities are not fully appreciated by her employer.</em></li><li><em>I’m not an expert, but I appreciate fine works of art.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive]</span> <em>technical</em> to gradually become more valuable over a period of time <em>OPP depreciate</em>:</div><ul class=\"examples\"><li><em>Most investments are expected to appreciate at a steady rate.</em></li></ul></div>","357":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧pre‧ci‧a‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /əˌpriːʃiˈeɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> pleasure you feel when you realize something is good, useful, or well done</div><ul class=\"examples\"><li><strong><em>appreciation of</strong>: It helps children to develop an appreciation of poetry and literature.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> a feeling of being grateful for something someone has done</div><ul class=\"examples\"><li><strong><em>show/express your appreciation</strong>: The chairman asked me to express our appreciation of all your hard work.</em></li><li><em>He was presented with a watch in appreciation of his long service.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> an understanding of the importance or meaning of something</div><ul class=\"examples\"><li><strong><em>appreciation of</strong>: a realistic appreciation of the situation</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[singular, uncountable]</span> a rise in value, especially of land or possessions <em>OPP depreciation</em>:</div><ul class=\"examples\"><li><em>an appreciation of 50% in property values</em></li></ul></div>","358":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧pre‧hen‧sion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌæprɪˈhenʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> anxiety about the future, especially about dealing with something unpleasant or difficult <em>SYN anxiety</em>:</div><ul class=\"examples\"><li><em>a feeling of apprehension</em></li><li><em>I woke before the alarm, filled with apprehension.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> <em>formal</em> the act of apprehending a criminal <em>SYN arrest</em></div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> <em>old-fashioned</em> understanding</div></div>","359":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧pre‧hen‧sive</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌæprɪˈhensɪv◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">worried or nervous about something that you are going to do, or about the future ► see thesaurus at worried</div><ul class=\"examples\"><li><strong><em>apprehensive about/of</strong>: We’d been a little apprehensive about their visit.</em></li><li><strong><em>apprehensive that</strong>: I was apprehensive that something would go wrong.</em></li><li><em>Some had apprehensive looks on their faces.</em></li></ul></div>","360":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧pren‧tice</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈprentɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who works for an employer for a fixed period of time in order to learn a particular skill or job:</div><ul class=\"examples\"><li><em>She works in the hairdresser’s as an apprentice.</em></li><li><em>an apprentice electrician</em></li></ul></div>","361":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /əˈprəʊtʃ $ əˈproʊtʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[method]</strong> <span class=\"gram\">[countable]</span> a method of doing something or dealing with a problem ► see thesaurus at method, way</div><ul class=\"examples\"><li><strong><em>approach to</strong>: a new approach to teaching languages</em></li><li><em>He decided to adopt a different approach and teach the Bible through story-telling.</em></li><li><em>This book takes an unorthodox approach to art criticism.</em></li><li><em>organizations which take a positive approach to creative thinking</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[ask]</strong> <span class=\"gram\">[countable]</span> a request from someone, asking you to do something for them:</div><ul class=\"examples\"><li><em>They made a direct approach to the minister of education.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the approach of something</strong> the approach of a particular time or event is the fact that it is getting closer:</div><ul class=\"examples\"><li><em>the approach of autumn</em></li><li><em>It’s a sign of the approach of middle age.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[movement towards]</strong> <span class=\"gram\">[uncountable]</span> movement towards or near to something:</div><ul class=\"examples\"><li><em>Our approach frightened the birds.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[path/road]</strong> <span class=\"gram\">[countable]</span> a road, path etc that leads to a place, and is the main way of reaching it:</div><ul class=\"examples\"><li><em>Soldiers were guarding the approaches to the city.</em></li><li><em>an approach road</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[aircraft]</strong> <span class=\"gram\">[countable]</span> the final part of a plane’s flight, before it lands at an airport:</div><ul class=\"examples\"><li><em>It was clear to land so we made our approach.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧proach</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[move towards]</strong> <span class=\"gram\">[intransitive, transitive]</span> to move towards or nearer to someone or something:</div><ul class=\"examples\"><li><em>As I approached the house, I noticed a light on upstairs.</em></li><li><em>She heard footsteps approaching.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[ask]</strong> <span class=\"gram\">[transitive]</span> to ask someone for something, or ask them to do something, especially when you are asking them for the first time or when you are not sure if they will do it → approachable</div><ul class=\"examples\"><li><strong><em>approach somebody for something</strong>: Students should be able to approach teachers for advice.</em></li><li><strong><em>approach somebody/something about (doing) something</strong>: The charity approached several stores about giving food aid.</em></li><li><em>I have already been approached by several other companies (=offered a job, work etc).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[future event]</strong> <span class=\"gram\">[intransitive, transitive]</span> if an event or a particular time approaches, or you approach it, it is coming nearer and will happen soon:</div><ul class=\"examples\"><li><em>She was then approaching the end of her career.</em></li><li><em>The time is fast approaching when we will have to make a decision.</em></li><li><em>With winter approaching, many animals are storing food.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[deal with]</strong> <span class=\"gram\">[transitive]</span> to begin to deal with a situation or problem in a particular way or with a particular attitude</div><ul class=\"examples\"><li><strong><em>approach a problem/task/matter etc</strong>: It might be possible to approach the problem in a different way.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[almost]</strong> <span class=\"gram\">[intransitive, transitive]</span> to be almost equal to something:</div><ul class=\"examples\"><li><em>temperatures approaching 35° C</em></li><li><em>He’s never had anything approaching a normal life.</em></li></ul></div></div>","362":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧pro‧pri‧ate</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈprəʊpri-ət $ əˈproʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1 AWL</span></div><div class=\"entry-body\"><div class=\"sense\">correct or suitable for a particular time, situation, or purpose <em>OPP inappropriate</em> ► see thesaurus at suitable</div><ul class=\"examples\"><li><strong><em>appropriate for</strong>: clothes appropriate for a job interview</em></li><li><strong><em>appropriate to</strong>: an education system which is more appropriate to the needs of the students</em></li><li><strong><em>it is appropriate (for somebody) to do something</strong>: It would not be appropriate for me to discuss that now.</em></li><li><strong><em>it is appropriate (that)</strong>: It seemed somehow appropriate that we should begin our journey here.</em></li><li><strong><em>appropriate time/place etc</strong>: I didn’t feel that this was an appropriate time to mention the subject of money.</em></li><li><strong><em>highly/entirely/wholly appropriate</strong>: I thought his remark was highly appropriate, given the circumstances.</em></li><li><em>The timing of the announcement was particularly appropriate.</em></li><li><em>Where appropriate, I delegate as much work as possible.</em></li><li><em>Mark box 1 or 2, as appropriate.</em></li><li><em>I can assure you that appropriate action will be taken.</em></li></ul></div>","363":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧pro‧pri‧ate‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈprəʊpri-ətli $ əˈproʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">correctly or suitably for a particular time, situation, or purpose <em>SYN suitably</em> <em>OPP inappropriately</em>:</div><ul class=\"examples\"><li><em>The painters met, appropriately enough, in an art gallery (=used to emphasize that something is very appropriate).</em></li><li><em>appropriately dressed</em></li></ul></div>","364":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧prov‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpruːvəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> when a plan, decision, or person is officially accepted:</div><ul class=\"examples\"><li><em>The president has already given his approval to the plan.</em></li><li><em>It is just three months since we received official approval to go ahead with the project.</em></li><li><em>A company cannot be sold without the approval of the shareholders.</em></li><li><em>The bill will be submitted for approval by Congress.</em></li><li><em>The president would appoint the Council of Ministers, subject to the approval of the National Assembly.</em></li><li><em>The IMF has given its seal of approval to the government’s economic strategy.</em></li><li><em>appointments requiring parliamentary approval</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> <em>formal</em> when someone likes something or someone and thinks that they are good <em>OPP disapproval</em>:</div><ul class=\"examples\"><li><em>A murmur of approval passed through the crowd.</em></li><li><strong><em>nod/smile/clap etc in approval</strong>: They clapped their hands in approval.</em></li><li><em>His ideas have won widespread public approval (=many people agree with them and think they are good).</em></li><li><em>Does the design meet with your approval (=do you like it?)?</em></li><li><em>Children are always seeking approval from their parents.</em></li><li><em>She looked to Greg for approval.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>on approval</strong> if you buy something on approval, you have the right to return it to the shop if you decide you do not want it</div></div>","365":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧prove</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈpruːv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to officially accept a plan, proposal etc: ► see thesaurus at agree</div><ul class=\"examples\"><li><em>The conference approved a proposal for a referendum.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> to think that someone or something is good, right, or suitable <em>OPP disapprove</em></div><ul class=\"examples\"><li><strong><em>approve of</strong>: Catherine’s parents now approve of her marriage. / I don’t approve of cosmetic surgery.</em></li></ul></div>","366":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧prox‧i‧mate</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈprɒksəmət $ əˈprɑːk-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\">an approximate number, amount, or time is close to the exact number, amount etc, but could be a little bit more or less than it <em>SYN rough</em> <em>OPP exact</em>: RegisterIn everyday English, people usually say rough rather than approximate:· Can you give me a rough idea of how much it would cost?</div><ul class=\"examples\"><li><em>What is the approximate number of students in each class?</em></li><li><em>These percentages are only approximate.</em></li></ul></div>","367":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧prox‧i‧mate‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈprɒksəmətli $ əˈprɑːk-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\">more or less than a number or amount <em>SYN roughly</em>:</div><ul class=\"examples\"><li><em>The plane will be landing in approximately 20 minutes.</em></li><li><em>How much do you think it will cost, approximately?</em></li></ul></div>","368":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ap‧prox‧i‧ma‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /əˌprɒksəˈmeɪʃən $ əˌprɑːk-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a number, amount etc that is not exact, but is almost correct <em>SYN estimate</em></div><ul class=\"examples\"><li><strong><em>approximation of</strong>: an approximation of the total</em></li><li><strong><em>a rough/crude approximation</strong> (=one that is not very exact): Could you give us a rough approximation of the cost?</em></li><li><strong><em>a good/close/reasonable approximation</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> something that is similar to another thing, but not exactly the same</div><ul class=\"examples\"><li><strong><em>approximation of/to</strong>: It was the nearest approximation to a crisis she’d ever experienced.</em></li></ul></div>","369":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> A‧pril</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeɪprəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the fourth month of the year, between March and May</div><ul class=\"examples\"><li><strong><em>next/last April</strong>: I’m going to Cuba next April.</em></li><li><strong><em>in April</strong>: Our new office opened in April 2001.</em></li><li><strong><em>on April 6th</strong>: The meeting will be on April 6th.</em></li><li><strong><em>on 6th April<em>British English</em></strong>: I arrived on 6th April.</em></li><li><strong><em>April 6<em>American English</em></strong>: Jim’s birthday’s April 6.</em></li></ul></div>","370":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧pron</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeɪprən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a piece of clothing that covers the front part of your clothes and is tied around your waist, worn to keep your clothes clean, especially while cooking</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>apron strings</strong> <em>informal</em> the relationship between a child and its mother, especially if the mother controls an adult son or daughter too much:</div><ul class=\"examples\"><li><em>You’re 25 years old, and you still haven’t cut the apron strings.</em></li><li><em>Jeff is still tied to his mother’s apron strings.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>technical</em> the hard surface in an airport on which planes are turned around, loaded, unloaded etc</div><div class=\"sense\"><span class=\"snum\">4</span> <em>technical</em> (also apron stage) the part of the stage in a theatre that is in front of the curtain</div></div>","371":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /æpt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>be apt to do something</strong> to have a natural tendency to do something <em>SYN tend to</em>:</div><ul class=\"examples\"><li><em>Some of the staff are apt to arrive late on Mondays.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> exactly right for a particular situation or purpose <em>SYN appropriate</em>:</div><ul class=\"examples\"><li><em>‘Love at first sight’ is a very apt description of how he felt when he saw her.</em></li><li><strong><em>apt for</strong>: The punishment should be apt for the crime.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>an apt pupil/student</strong> <em>formal</em> a student who is quick to learn and understand <em>SYN able</em></div></div>","372":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧quar‧i‧um</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈkweəriəm $ əˈkwer-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural aquariums or aquaria /-riə/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a clear glass or plastic container for fish and other water animals</div><div class=\"sense\"><span class=\"snum\">2</span> a building where people go to look at fish and other water animals</div></div>","373":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧bi‧tra‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːbətrəri, -tri $ ˈɑːrbətreri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">decided or arranged without any reason or plan, often unfairly:</div><ul class=\"examples\"><li><em>an arbitrary decision</em></li><li><em>the arbitrary arrests of political opponents</em></li></ul></div>","374":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ɑːk $ ɑːrk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a curved shape or line:</div><ul class=\"examples\"><li><em>the arc of a rainbow</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> part of a curved line or a circle:</div><ul class=\"examples\"><li><em>The Sun moves across the sky in an arc.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a flash of light formed by the flow of electricity between two points</div></div>","375":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ɑːtʃ $ ɑːrtʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a structure with a curved top and straight sides that supports the weight of a bridge or building</div><div class=\"sense\"><span class=\"snum\">2</span> a curved structure above a door, window etc</div><div class=\"sense\"><span class=\"snum\">3</span> a curved structure of bones in the middle of your foot</div><div class=\"sense\"><span class=\"snum\">4</span> something with a curved top and straight sides</div></div>","376":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧chae‧ol‧o‧gy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɑːkiˈɒlədʒi $ ˌɑːrkiˈɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the study of ancient societies by examining what remains of their buildings, graves, tools etc</div></div>","377":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧chi‧tect</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːkətekt $ ˈɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone whose job is to design buildings</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>the architect of something</strong> the person who originally thought of an important and successful idea:</div><ul class=\"examples\"><li><em>Tinoco was one of the architects of the government’s economic reforms.</em></li></ul></div>","378":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧chi‧tec‧ture</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːkətektʃə $ ˈɑːrkətektʃər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the style and design of a building or buildings</div><ul class=\"examples\"><li><strong><em>architecture of</strong>: the architecture of Venice</em></li><li><strong><em>modern/classical/medieval etc architecture</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the art and practice of planning and designing buildings:</div><ul class=\"examples\"><li><em>He studied architecture at university.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> the structure of something:</div><ul class=\"examples\"><li><em>the architecture of DNA</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable, uncountable]</span> <em>technical</em> the structure of a computer system and the way it works</div></div>","379":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧chive</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːkaɪv $ ˈɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a place where a large number of historical records are stored, or the records that are stored:</div><ul class=\"examples\"><li><em>an archive of the writer’s unpublished work</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>technical</em> copies of a computer’s files that are stored on a disk or in the computer’s memory in a way that uses less space than usual, so that the computer can keep them for a long time</div></div>","380":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧e‧a</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈeəriə $ ˈeriə/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a particular part of a country, town etc:</div><ul class=\"examples\"><li><em>Only cheeses made in this area may be labelled ‘Roquefort’.</em></li><li><em>Crime rates are much higher in urban areas.</em></li><li><strong><em>area of</strong>: Many areas of Africa have suffered severe drought this year.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a part of a house, office, garden etc that is used for a particular purpose:</div><ul class=\"examples\"><li><em>a no-smoking area</em></li><li><em>Their apartment has a large kitchen area.</em></li><li><em>Come through into the dining area.</em></li><li><em>the reception area of the hotel</em></li><li><em>a storage area on the ground floor</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a particular subject, range of activities, or group of related subjects:</div><ul class=\"examples\"><li><em>The course covers three main subject areas.</em></li><li><em>This study has clearly identified a major problem area for the National Health Service.</em></li><li><em>We’re funding research into new areas such as law enforcement technology.</em></li><li><strong><em>area of</strong>: reforms in the key areas of health and education</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> the amount of space that a flat surface or shape covers ► see thesaurus at size</div><ul class=\"examples\"><li><strong><em>area of</strong>: an area of 2,000 square miles / a formula to calculate the area of a circle</em></li></ul></div>","381":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧re‧na</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈriːnə/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a building with a large flat central area surrounded by seats, where sports or entertainments take place:</div><ul class=\"examples\"><li><em>a sports arena</em></li><li><em>an indoor arena</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the political/international/public etc arena</strong> all the activities and people connected with politics, public life etc:</div><ul class=\"examples\"><li><em>Women are entering the political arena in larger numbers.</em></li><li><em>American economic activity in the international arena</em></li></ul></div>","382":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧gu‧a‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːɡjuəbəl $ ˈɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not certain, or not definitely true or correct, and therefore easy to doubt <em>SYN debatable</em>:</div><ul class=\"examples\"><li><em>Whether or not Webb is the best person for the job is arguable.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>it is arguable that</strong> used in order to give good reasons why something might be true:</div><ul class=\"examples\"><li><em>It’s arguable that the legislation has had little effect on young people’s behaviour.</em></li></ul></div>","383":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧gu‧a‧bly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːɡjuəbli $ ˈɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[sentence adverb]</span></span></div><div class=\"entry-body\"><div class=\"sense\">used when giving your opinion to say that there are good reasons why something might be true:</div><ul class=\"examples\"><li><em>Senna was arguably the greatest racing driver of all time.</em></li></ul></div>","384":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧gue</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːɡjuː $ ˈɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive]</span> to disagree with someone in words, often in an angry way: GRAMMARReciprocal verbsArgue is a reciprocal verb. This type of verb is used when saying that two or more people do something that involves both or all of them: · He and the waiter started arguing. You can also say: · He and the waiter started arguing with each other.· He started arguing with the waiter.Patterns with argue• You argue with someone: · I wish you two would stop arguing with each other!• You argue about something or over something: · Let’s not argue about/over small details.</div><ul class=\"examples\"><li><em>We could hear the neighbours arguing.</em></li><li><strong><em>argue with</strong>: Gallacher continued to argue with the referee throughout the game.</em></li><li><strong><em>argue about</strong>: They were arguing about how to spend the money.</em></li><li><strong><em>argue over</strong>: The children were arguing over which TV programme to watch.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to state, giving clear reasons, that something is true, should be done etc</div><ul class=\"examples\"><li><strong><em>argue that</strong>: Croft argued that a date should be set for the withdrawal of troops. / It could be argued that a dam might actually increase the risk of flooding.</em></li><li><strong><em>argue for/against (doing) something</strong>: Baker argued against cutting the military budget.</em></li><li><em>She argued the case for changing the law.</em></li><li><em>The researchers put forward a well-argued case for banning the drug.</em></li><li><em>They argued the point (=discussed it) for hours without reaching a conclusion.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>argue somebody into/out of doing something</strong> <em>British English</em> to persuade someone to do or not do something:</div><ul class=\"examples\"><li><em>Joyce argued me into buying a new jacket.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> <em>formal</em> to show that something clearly exists or is true:</div><ul class=\"examples\"><li><em>The statement argues a change of attitude by the management.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>argue the toss</strong> <em>British English</em> <em>informal</em> to continue to argue about a decision that has been made and cannot be changed:</div><ul class=\"examples\"><li><em>There was no point arguing the toss after the goal had been disallowed.</em></li></ul></div>","385":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧gu‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːɡjəmənt $ ˈɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a situation in which two or more people disagree, often angrily</div><ul class=\"examples\"><li><strong><em>argument with</strong>: She had a big argument with her husband.</em></li><li><strong><em>argument about/over</strong>: There have been a lot of arguments about who was responsible for the accident.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a set of reasons that show that something is true or untrue, right or wrong etc:</div><ul class=\"examples\"><li><em>We need to provide a convincing argument as to why the system should be changed.</em></li><li><strong><em>argument for/against</strong>: a powerful argument against smoking / A good argument can be made for comparing the IT revolution with the invention of writing itself.</em></li><li><strong><em>argument in favour of</strong>: the arguments in favour of banning tobacco advertising</em></li><li><strong><em>argument that</strong>: the familiar argument that the costs outweigh the benefits</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> when you disagree with something or question whether it is right</div><ul class=\"examples\"><li><strong><em>do something without (further) argument</strong>: Ian accepted the suggestion without argument.</em></li><li><strong><em>for the sake of argument</strong> (=in order to discuss all the possibilities): If, for the sake of argument, you aren’t offered the job, what will you do?</em></li></ul></div>","386":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧gu‧men‧ta‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɑːɡjəˈmentətɪv◂ $ ˌɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">someone who is argumentative often argues or likes arguing:</div><ul class=\"examples\"><li><em>He quickly becomes argumentative after a few drinks.</em></li></ul></div>","387":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧rise</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈraɪz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span><span class=\"meta-item\">(past tense arose /əˈrəʊz $ əˈroʊz/, past participle arisen /əˈrɪzən/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if a problem or difficult situation arises, it begins to happen: ► see thesaurus at happen RegisterIn everyday English, people usually say that a problem or difficult situation comes up rather than arises:· The same problems come up every time.</div><ul class=\"examples\"><li><em>A crisis has arisen in the Foreign Office.</em></li><li><em>More problems like those at the nuclear power plant are certain to arise.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if something arises from or out of a situation, event etc, it is caused or started by that situation etc:</div><ul class=\"examples\"><li><em>Several important legal questions arose in the contract negotiations.</em></li><li><strong><em>arise from/out of</strong>: Can we begin by discussing matters arising from the last meeting?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>when/if the need arises</strong> (also should the need arise<em>formal</em>) when or if it is necessary:</div><ul class=\"examples\"><li><em>Should the need arise for extra staff, we will contact you.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>literary</em> to get out of bed, or stand up</div><div class=\"sense\"><span class=\"snum\">5</span> <em>literary</em> if a group of people arise, they fight for or demand something they want</div><div class=\"sense\"><span class=\"snum\">6</span> <em>literary</em> if something arises when you are moving towards it, you are gradually able to see it as you move closer</div></div>","388":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧rith‧me‧tic</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈrɪθmətɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the science of numbers involving adding, multiplying etc → mathematics</div></div>","389":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ɑːm $ ɑːrm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[body]</strong> one of the two long parts of your body between your shoulders and your hands:</div><ul class=\"examples\"><li><em>Dave has a broken arm.</em></li><li><strong><em>left/right arm</strong>: He had a tattoo on his left arm.</em></li><li><em>Tim’s mother put her arms around him.</em></li><li><em>Pat was carrying a box under his arm.</em></li><li><em>He had a pile of books in his arms.</em></li><li><em>They walked along the beach arm in arm (=with their arms bent around each other’s).</em></li><li><strong><em>take somebody by the arm</strong> (=lead someone somewhere by holding their arm): She took him by the arm and pushed him out of the door.</em></li><li><strong><em>take somebody in your arms</strong> (=gently hold someone with your arms): Gerry took Fiona in his arms and kissed her.</em></li><li><strong><em>cross/fold your arms</strong> (=bend your arms so that they are resting on top of each other against your body): He folded his arms and leaned back in his chair.</em></li><li><em>The old lady rushed to greet him, arms outstretched.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[weapons]</strong> <strong>arms</strong> <span class=\"gram\">[plural]</span> weapons used for fighting wars: → small arms at small1(15)</div><ul class=\"examples\"><li><em>Sales of arms to the Middle East have dramatically increased.</em></li><li><strong><em>nuclear arms</em></strong></li><li><em>the arms trade</em></li><li><em>an arms dealer</em></li><li><em>The government is cutting arms expenditure.</em></li><li><em>The United Nations will lift its arms embargo against the country.</em></li><li><strong><em>take up arms (against somebody)</strong> (=get weapons and fight): Boys as young as 13 are taking up arms to defend the city.</em></li><li><em>He appealed for the rebels to lay down their arms (=stop fighting).</em></li><li><strong><em>under arms</strong> (=with weapons and ready to fight): All available forces are under arms.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[furniture]</strong> the part of a chair, sofa etc that you rest your arms on</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[clothing]</strong> the part of a piece of clothing that covers your arm <em>SYN sleeve</em></div><div class=\"sense\"><span class=\"snum\">5</span> <strong>be up in arms</strong> to be very angry and ready to argue or fight:</div><ul class=\"examples\"><li><em>Residents are up in arms about plans for a new road along the beach.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>with open arms</strong> if you do something with open arms, you show that you are happy to see someone or eager to accept an idea, plan etc:</div><ul class=\"examples\"><li><em>We welcomed Henry’s offer with open arms.</em></li><li><em>My new in-laws accepted me with open arms.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>somebody would give their right arm to do something</strong> used to say that someone would be willing to do anything to get or do something because they want it very much:</div><ul class=\"examples\"><li><em>I’d give my right arm to be 21 again.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>hold something at arm’s length</strong> to hold something away from your body</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>keep/hold somebody at arm’s length</strong> to avoid developing a relationship with someone:</div><ul class=\"examples\"><li><em>Petra keeps all men at arm’s length to avoid getting hurt.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>as long as your arm</strong> <em>informal</em> a list or written document that is as long as your arm is very long:</div><ul class=\"examples\"><li><em>I’ve got a list of things to do as long as your arm.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[part of group]</strong> a part of a large group that is responsible for a particular type of activity:</div><ul class=\"examples\"><li><em>the political arm of a terrorist organization</em></li><li><em>Epson America is the US marketing arm of a Japanese company.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[object/machine]</strong> a long part of an object or piece of equipment:</div><ul class=\"examples\"><li><em>the arm of a record player</em></li><li><em>There is a 15-foot arm supporting the antenna.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>on somebody’s arm</strong> <em>old-fashioned</em> if a man has a woman on his arm, she is walking beside him holding his arm</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>[design]</strong> <strong>arms</strong> <span class=\"gram\">[plural]</span> a set of pictures or patterns, usually painted on a shield, that is used as the special sign of a family, town, university etc <em>SYN coat of arms</em></div></div>","390":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> arm‧chair</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːmtʃeə, ˌɑːmˈtʃeə $ ˈɑːrmtʃer, ˌɑːrmˈtʃer/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a comfortable chair with sides that you can rest your arms on</div></div>","391":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ɑːmd $ ɑːrmd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> carrying weapons, especially a gun <em>OPP unarmed</em>:</div><ul class=\"examples\"><li><em>Armed police raided the building.</em></li><li><em>The Minister was kidnapped by armed men on his way to the airport.</em></li><li><em>The prisoners were kept under armed guard.</em></li><li><strong><em>armed with</strong>: The suspect is armed with a shotgun.</em></li><li><em>She got ten years in prison for armed robbery (=stealing using a gun).</em></li><li><em>The president fears that armed conflict (=a war) is possible.</em></li><li><em>There is very little support for an armed struggle (=fighting with weapons) against the government.</em></li><li><em>a heavily armed battleship</em></li><li><em>Many of the gangs are armed to the teeth (=carrying a lot of weapons).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> having the knowledge, skills, or equipment you need to do something</div><ul class=\"examples\"><li><strong><em>armed with</strong>: She came to the meeting armed with all the facts and figures to prove us wrong. / I went out, armed with my binoculars, to see what I could find in the fields.</em></li></ul></div>","392":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧mour</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːmə $ ˈɑːrmər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> metal or leather clothing that protects your body, worn by soldiers in battles in past times:</div><ul class=\"examples\"><li><em>a knight wearing a suit of armour</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a strong metal layer that protects military vehicles:</div><ul class=\"examples\"><li><em>armour-clad warships</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a strong layer or shell that protects some plants and animals</div></div>","393":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧my</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːmi $ ˈɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(plural armies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>the army</strong> the part of a country’s military force that is trained to fight on land in a war:</div><ul class=\"examples\"><li><em>The army are helping to clear up after the floods.</em></li><li><em>an army officer</em></li><li><em>Army units launched attacks on bases near Jounieh port.</em></li><li><em>He joined the army when he was 17.</em></li><li><strong><em>in the army</strong>: My son is in the army.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a large organized group of people trained to fight on land in a war:</div><ul class=\"examples\"><li><em>Rebel armies have taken control of the radio station.</em></li><li><strong><em>raise an army</strong> (=collect together and organize an army to fight a battle): The Slovenians say they can raise an army of 20,000 men.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a large number of people involved in the same activity</div><ul class=\"examples\"><li><strong><em>army of</strong>: The village hall is maintained by an army of volunteers.</em></li></ul></div>","394":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧ro‧ma</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈrəʊmə $ əˈroʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a strong pleasant smell: ► see thesaurus at smell</div><ul class=\"examples\"><li><em>the aroma of fresh coffee</em></li></ul></div>","395":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧round</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈraʊnd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> surrounding or on all sides of something or someone SYN round<em>British English</em>:</div><ul class=\"examples\"><li><em>The whole family was sitting around the dinner table.</em></li><li><em>The Romans built a defensive wall around the city.</em></li><li><em>She wore a beautiful silk shawl around her shoulders.</em></li><li><em>People crowded around to see what was happening.</em></li><li><em>We would hear the birds singing all around us.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> moving in a circle SYN round<em>British English</em>:</div><ul class=\"examples\"><li><em>A helicopter was circling around, looking for somewhere to land.</em></li><li><em>They danced around the bonfire.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> in or to many places or parts of an area SYN about<em>British English</em>:</div><ul class=\"examples\"><li><em>He wandered around the streets, looking in shop windows.</em></li><li><em>There are over 40 radio stations dotted around the country.</em></li><li><em>When I finished college, I travelled around for a while.</em></li><li><em>Since it’s your first day here, would you like me to show you around?</em></li><li><em>We started looking around for somewhere to live.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>British English</em> in an area near a place or person <em>SYN round</em>:</div><ul class=\"examples\"><li><em>Is there a bank around here?</em></li><li><em>When you’ve been around a person long enough, you start to know how they’ll react.</em></li><li><em>the new housing areas in and around Dublin</em></li><li><em>Catherine was the most beautiful girl for miles around.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if someone or something is around, they are somewhere in the place where you are:</div><ul class=\"examples\"><li><em>Why is there never a policeman around when you need one?</em></li><li><em>Jake went down to the bar, but there was no one around that he knew.</em></li><li><em>Is your dad around?</em></li><li><em>The list is somewhere around.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>British English</em> on the other side of something, or to the other side of it without going through it or over it <em>SYN round</em>:</div><ul class=\"examples\"><li><em>If the gate’s locked, you’ll have to go around the side of the house.</em></li><li><em>There’s a door around the back.</em></li><li><em>She ran around the corner and straight into the arms of John Delaney.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> used to say that someone or something turns so that they face in the opposite direction SYN round<em>British English</em>:</div><ul class=\"examples\"><li><em>Rex spun around and kicked the gun from her hand.</em></li><li><em>Slowly he turned the boat around towards the open sea.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> (also around about) used when guessing a number, amount, time etc, without being exact: ► see thesaurus at approximate</div><ul class=\"examples\"><li><em>There must have been around 40,000 people in the stadium.</em></li><li><em>The whole project will probably cost around $3 million.</em></li><li><em>Most guests started to make their way home around about ten o&#x27;clock.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> existing SYN about<em>British English</em>:</div><ul class=\"examples\"><li><em>That joke’s been around for years.</em></li><li><em>Manson has a reputation as one of the most stylish designers around.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> if something is organized around a particular person or thing, it is organized according to their needs, wishes, ideas etc:</div><ul class=\"examples\"><li><em>Why does everything have to be arranged around what Callum wants to do?</em></li><li><em>Their whole society was built around their religious beliefs.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> used to show that someone spends time in a place without doing anything useful SYN about<em>British English</em>:</div><ul class=\"examples\"><li><em>I’ve been waiting around all morning.</em></li><li><em>They could be seen hanging around street corners, watching the girls go by.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> a way around a difficult situation or problem is a way to solve it or avoid it SYN round<em>British English</em>:</div><ul class=\"examples\"><li><em>We must find a way around these difficulties.</em></li><li><em>The company is expected to get around this problem by borrowing from the banks.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> to other people or positions SYN round<em>British English</em>:</div><ul class=\"examples\"><li><em>Write your name on this list and pass it around.</em></li><li><em>Someone’s been moving the furniture around.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>have been around</strong> (also have been around the block a few times) <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to have had experience of many different situations so that you can deal with new situations confidently:</div><ul class=\"examples\"><li><em>You could tell this guy had been around a bit by the knowing way he talked.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to have had many sexual experiences – used humorously</div><div class=\"sense\"><span class=\"snum\">14</span> <em>American English</em> used to show the length of a line surrounding something:</div><ul class=\"examples\"><li><em>Redwood trees can measure 30 or 40 feet around.</em></li></ul></div>","396":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧rouse</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈraʊz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>arouse interest/expectations etc</strong> to make you become interested, expect something etc:</div><ul class=\"examples\"><li><em>Matt’s behavior was arousing the interest of the neighbors.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>arouse hostility/suspicion/resentment/anger etc</strong> to make someone feel very unfriendly and angry, or suspicious:</div><ul class=\"examples\"><li><em>A great deal of anger was aroused by Campbell’s decision.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to make someone feel sexually excited <em>SYN excite</em>:</div><ul class=\"examples\"><li><em>She felt aroused by the pressure of his body so close to hers.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>literary</em> to wake someone</div><ul class=\"examples\"><li><strong><em>arouse from</strong>: Anne had to be aroused from a deep sleep.</em></li></ul></div>","397":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧range</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈreɪndʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to organize or make plans for something such as a meeting, party, or trip:</div><ul class=\"examples\"><li><em>Contact your local branch to arrange an appointment.</em></li><li><em>I’d like to arrange a business loan.</em></li><li><strong><em>arrange to do something</strong>: Have you arranged to meet Mark this weekend?</em></li><li><strong><em>arrange something with somebody</strong>: Beth arranged a meeting with the marketing director.</em></li><li><strong><em>arrange when/where/how etc</strong>: We still have to arrange how to get home.</em></li><li><strong><em>arrange that</strong>: We had arranged that I would go for the weekend.</em></li><li><em>Matthew arrived at 2 o&#x27;clock as arranged.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to make it possible for someone to have or do something</div><ul class=\"examples\"><li><strong><em>arrange for something</strong>: The company will arrange for a taxi to meet you at the airport.</em></li><li><strong><em>arrange for somebody to do something</strong>: Dave arranged for someone to drive him home.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to put a group of things or people in a particular order or position:</div><ul class=\"examples\"><li><em>Ben arranged the flowers in a vase.</em></li><li><em>The list is arranged alphabetically.</em></li><li><strong><em>arrange something in pairs/groups etc</strong>: The children were arranged in lines according to height.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> to write or change a piece of music so that it is suitable for a particular instrument</div><ul class=\"examples\"><li><strong><em>arrange something for something</strong>: a symphony arranged for the piano</em></li></ul></div>","398":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧range‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈreɪndʒmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[plan]</strong> <span class=\"gram\">[countable usually plural]</span> plans and preparations that you must make so that something can happen:</div><ul class=\"examples\"><li><em>Have you made all your travel arrangements?</em></li><li><strong><em>arrangement for</strong>: I’ve agreed to help with arrangements for the party. / The family made arrangements for his body to be flown back.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[agreement]</strong> <span class=\"gram\">[countable, uncountable]</span> something that has been organized or agreed on <em>SYN agreement</em></div><ul class=\"examples\"><li><strong><em>arrangement between</strong>: An arrangement between the two couples ensured there was always someone to look after the children.</em></li><li><strong><em>arrangement with</strong>: The school has an arrangement with local businesses.</em></li><li><strong><em>an arrangement to do something</strong>: Maxine cancelled our arrangement to meet.</em></li><li><strong><em>come to an/some arrangement (with somebody)</strong> (=make an agreement that is acceptable to everyone): It would usually cost $500, but I’m sure we can come to some kind of arrangement.</em></li><li><em>Pets are permitted at the resort by prior arrangement.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[way something is organized]</strong> <span class=\"gram\">[countable usually plural]</span> the way in which something is organized:</div><ul class=\"examples\"><li><em>The airport is currently reviewing its security arrangements.</em></li><li><em>domestic arrangements</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[position]</strong> <span class=\"gram\">[countable, uncountable]</span> a group of things that are put in a particular position, or the process of doing this</div><ul class=\"examples\"><li><strong><em>arrangement of</strong>: the traditional arrangement of desks in rows</em></li><li><em>a beautiful flower arrangement</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[music]</strong> <span class=\"gram\">[countable]</span> a piece of music that has been written or changed for a particular instrument:</div><ul class=\"examples\"><li><em>a piano arrangement of an old folk song</em></li></ul></div>","399":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧ray</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈreɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[usually singular]</span> a group of people or things, especially one that is large or impressive</div><ul class=\"examples\"><li><strong><em>array of</strong>: a dazzling array of flowers</em></li><li><em>a bewildering array of options</em></li><li><strong><em>a vast/impressive/wide array</strong>: There was a vast array of colours to choose from.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>technical</em> a set of numbers or signs, or of computer memory units, arranged in lines across or down</div></div>","400":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧rest</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈrest/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if the police arrest someone, the person is taken to a police station because the police think they have done something illegal: ► see thesaurus at catch</div><ul class=\"examples\"><li><em>He was arrested and charged with murder.</em></li><li><strong><em>arrest somebody for something</strong>: Her father was arrested for fraud.</em></li><li><em>I got arrested for careless driving.</em></li><li><strong><em>arrest somebody in connection with something</strong>: Five youths were arrested in connection with the attack.</em></li><li><strong><em>arrest somebody on charges/suspicion of (doing) something</strong>: He was arrested on suspicion of supplying drugs.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> to stop something happening or to make it happen more slowly:</div><ul class=\"examples\"><li><em>The drug is used to arrest the spread of the disease.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>literary</em> if something arrests you or arrests your attention, you notice it because it is interesting or unusual:</div><ul class=\"examples\"><li><em>The mountains are the most arresting feature of the glen.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">when the police take someone away and guard them because they may have done something illegal:</div><ul class=\"examples\"><li><em>The police made several arrests.</em></li><li><em>A man is under arrest (=the police are guarding him) following the suspicious death of his wife.</em></li><li><strong><em>place/put somebody under arrest</strong> (=arrest someone)</em></li><li><em>He sued the police for wrongful arrest (=when someone who is not guilty is arrested).</em></li></ul></div></div>","401":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧riv‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈraɪvəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> when someone or something arrives somewhere <em>OPP departure</em>:</div><ul class=\"examples\"><li><em>Only the timely arrival of the police prevented the situation from becoming worse.</em></li><li><em>Traffic problems account for one third of late arrivals.</em></li><li><strong><em>arrival at/in</strong>: Shortly after our arrival in London, Lisa was attacked.</em></li><li><strong><em>on arrival</strong>: A deposit is payable on arrival (=when you arrive).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the arrival of something</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the time when a new idea, product etc is first used or discovered:</div><ul class=\"examples\"><li><em>The demand for phone numbers has increased since the arrival of mobile phones.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the time when an event or period of time starts to happen:</div><ul class=\"examples\"><li><em>The arrival of winter can make many people feel depressed.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> someone who has just arrived in a place:</div><ul class=\"examples\"><li><em>New arrivals were greeted with suspicion.</em></li><li><em>Late arrivals will not be admitted to the theatre.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>arrivals</strong> the place at an airport where people arrive when they get off a plane:</div><ul class=\"examples\"><li><em>the arrivals lounge</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>new arrival</strong> a baby who has just been born</div></div>","402":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧rive</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈraɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[get somewhere]</strong> to get to the place you are going to:</div><ul class=\"examples\"><li><em>Give me a call to let me know you’ve arrived safely.</em></li><li><strong><em>arrive in/at</strong>: What time does the plane arrive in New York?</em></li><li><strong><em>arrive late/early</strong>: He arrived late as usual. / By the time the police arrived on the scene, the burglars had fled.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[be delivered]</strong> if something arrives, it is brought or delivered to you <em>SYN come</em>:</div><ul class=\"examples\"><li><em>The card arrived on my birthday.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[happen]</strong> if an event or particular period of time arrives, it happens <em>SYN come</em>:</div><ul class=\"examples\"><li><em>When her wedding day arrived, she was really nervous.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[something new]</strong> if a new idea, method, product etc arrives, it begins to exist or starts being used:</div><ul class=\"examples\"><li><em>Since computers arrived, my job has become much easier.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[be born]</strong> to be born:</div><ul class=\"examples\"><li><em>Sharon’s baby arrived just after midnight.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>arrive at a decision/solution/compromise etc</strong> to reach a decision, solution etc after a lot of effort:</div><ul class=\"examples\"><li><em>After much consideration, we have arrived at a decision.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[success]</strong> <strong>somebody has arrived</strong> used to say that someone has become successful or famous:</div><ul class=\"examples\"><li><em>When he saw his name painted on the door he knew he’d arrived!</em></li></ul></div>","403":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧ro‧gance</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈærəɡəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">when someone behaves in a rude way because they think they are very important:</div><ul class=\"examples\"><li><em>I couldn’t believe the arrogance of the man!</em></li></ul></div>","404":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧ro‧gant</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈærəɡənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">behaving in an unpleasant or rude way because you think you are more important than other people: ► see thesaurus at proud</div><ul class=\"examples\"><li><em>He was unbearably arrogant.</em></li><li><em>an arrogant attitude</em></li></ul></div>","405":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧row</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈærəʊ $ ˈæroʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a weapon usually made from a thin straight piece of wood with a sharp point at one end, that you shoot with a bow</div><div class=\"sense\"><span class=\"snum\">2</span> a sign in the shape of an arrow, used to show direction:</div><ul class=\"examples\"><li><em>Follow the arrows to the X-ray department.</em></li></ul></div>","406":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ɑːt $ ɑːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the use of painting, drawing, sculpture etc to represent things or express ideas:</div><ul class=\"examples\"><li><em>the Museum of Modern Art in New York</em></li><li><em>an example of early Indian art</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[plural, uncountable]</span> objects that are produced by art, such as paintings, drawings etc:</div><ul class=\"examples\"><li><em>an art exhibition</em></li><li><em>an art critic</em></li><li><em>an arts and crafts fair</em></li><li><em>The exhibition features works of art by Picasso and Matisse.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> the skill of drawing or painting:</div><ul class=\"examples\"><li><em>He’s very good at art.</em></li><li><em>an art teacher</em></li><li><em>art college</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the arts</strong> <span class=\"gram\">[plural]</span> art, music, theatre, film, literature etc all considered together:</div><ul class=\"examples\"><li><em>Government funding for the arts has been reduced.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>arts</strong> (also the arts) <span class=\"gram\">[plural]</span> subjects you can study that are not scientific, for example history, languages etc → humanities</div><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[countable, uncountable]</span> the ability or skill involved in doing or making something:</div><ul class=\"examples\"><li><em>Television is ruining the art of conversation.</em></li><li><em>Writing advertisements is quite an art (=it is difficult to do).</em></li><li><strong><em>have/get something down to a fine art</strong> (=do something very well): I’ve got the early morning routine down to a fine art.</em></li></ul></div>","407":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧te‧fact</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːtəfækt $ ˈɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">an object such as a tool, weapon etc that was made in the past and is historically important: ► see thesaurus at thing</div><ul class=\"examples\"><li><em>ancient Egyptian artefacts</em></li></ul></div>","408":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧ti‧cle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːtɪkəl $ ˈɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[newspaper/magazine]</strong> a piece of writing about a particular subject in a newspaper or magazine</div><ul class=\"examples\"><li><strong><em>article on/about</strong>: an article on environmental issues</em></li><li><em>The paper’s leading article (=the main article) described the government as weak.</em></li><li><em>newspaper articles</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[object]</strong> <em>formal</em> a thing, especially one of a group of things <em>SYN item</em>: ► see thesaurus at thing</div><ul class=\"examples\"><li><em>household articles</em></li><li><em>She only took a few articles of clothing with her.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[law]</strong> a part of a law or legal agreement that deals with a particular point:</div><ul class=\"examples\"><li><em>Article 1 of the constitution guarantees freedom of religion.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[grammar]</strong> <em>technical</em> a word used before a noun to show whether the noun refers to a particular example of something or to a general example of something. In English, ‘the’ is called the definite article and ‘a’ and ‘an’ are called the indefinite article.</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>articles</strong> <em>British English</em> an agreement by which someone finishes their training, especially as a lawyer, by working for a company</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>an article of faith</strong> something that you feel very strongly about so that it affects how you think or behave</div></div>","409":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧tic‧u‧late</span><span class=\"meta-item\"><strong>IPA:</strong> /ɑːˈtɪkjəleɪt $ ɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> <em>formal</em> to express your ideas or feelings in words:</div><ul class=\"examples\"><li><em>Many people are unable to articulate the unhappiness they feel.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to pronounce what you are saying in a clear and careful way:</div><ul class=\"examples\"><li><em>He was so drunk that he could barely articulate his words.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive]</span> <em>technical</em> if something such as a bone in your body is articulated to another thing, it is joined to it in a way that allows movement</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>articulate something with something</strong> <em>formal</em> if one idea, system etc articulates with another idea, system etc, the two things are related and exist together:</div><ul class=\"examples\"><li><em>a new course that is designed to articulate with the current degree course</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧tic‧u‧late</span><span class=\"meta-item\"><strong>IPA:</strong> /ɑːˈtɪkjələt $ ɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> able to talk easily and effectively about things, especially difficult subjects <em>OPP inarticulate</em>:</div><ul class=\"examples\"><li><em>bright, articulate 17-year-olds</em></li><li><em>a highly articulate speaker</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> writing or speech that is articulate is very clear and easy to understand even if the subject is difficult</div></div></div>","410":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧ti‧fi‧cial</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɑːtɪˈfɪʃəl◂ $ ˌɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[usually before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not real or not made of natural things but made to be like something that is real or natural <em>SYN false</em> <em>OPP natural</em>:</div><ul class=\"examples\"><li><em>artificial flowers</em></li><li><em>artificial light</em></li><li><em>artificial fertilizers</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an artificial situation or quality exists because someone has made it exist, and not because it is really necessary:</div><ul class=\"examples\"><li><em>artificial distinctions</em></li><li><em>artificial barriers of gender and race</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> artificial behaviour is not sincere – used to show disapproval <em>OPP genuine</em>:</div><ul class=\"examples\"><li><em>an artificial smile</em></li></ul></div>","411":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> art‧ist</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːtɪst $ ˈɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who produces art, especially paintings or drawings: → make-up artist at make-up(1)</div><ul class=\"examples\"><li><em>an exhibition of paintings by local artists</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a professional performer, especially a singer, dancer, or actor:</div><ul class=\"examples\"><li><em>Many of the artists in the show donated their fee to charity.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>informal</em> someone who is extremely good at something: → con artist</div><ul class=\"examples\"><li><em>He’s an artist in the kitchen.</em></li></ul></div>","412":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ar‧tis‧tic</span><span class=\"meta-item\"><strong>IPA:</strong> /ɑːˈtɪstɪk $ ɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relating to art or culture:</div><ul class=\"examples\"><li><em>artistic work</em></li><li><em>Opinion about the artistic merit of his paintings has been mixed.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> good at painting, drawing, or producing beautiful things:</div><ul class=\"examples\"><li><em>John is very artistic.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> an artistic arrangement, design etc looks attractive and has been done with skill and imagination:</div><ul class=\"examples\"><li><em>food presented in an artistic way</em></li></ul></div>","413":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> art‧work</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɑːtwɜːk $ ˈɑːrtwɜːrk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> drawings and photographs that are specially prepared to be in a book, magazine, or advertisement</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> paintings and other objects produced by artists</div></div>","414":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">preposition</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /əz; strong æz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used when you are comparing two people, things, situations etc</div><ul class=\"examples\"><li><strong><em>as... as</strong>: Tom’s not as old as you, is he? / an old woman with hair as white as snow / Some of the doctors are paid almost twice as much as the nurses. / We work as hard as any other team in England.</em></li><li><em>Please let me know your decision as soon as possible (=as soon as you can).</em></li><li><em>His last album sold half a million copies and we hope this one will be just as (=equally) popular.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to say what job, duty, use, or appearance someone or something has:</div><ul class=\"examples\"><li><em>As a parent, I feel that more should be done to protect our children.</em></li><li><em>A flat stone was used as a table.</em></li><li><em>Dad dressed up as Santa Claus.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to say what someone thinks or says a person or thing is:</div><ul class=\"examples\"><li><em>The problem is regarded as serious.</em></li><li><em>The result of last week’s election will be seen as a victory for the right-wing government.</em></li><li><em>He’s described as being in his late teens, tall, and of slim build.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> when someone was in a particular age group:</div><ul class=\"examples\"><li><em>As a young man, Eliot had studied art in Paris.</em></li><li><em>I’ll take you to all the places I loved as a girl.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">conjunction</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used in comparisons</div><ul class=\"examples\"><li><strong><em>as... as</strong>: They want peace as much as we do. / Helen comes to visit me as often as she can. / I can’t run as fast as I used to.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in the way that someone says or that something happens, or in the condition something is in:</div><ul class=\"examples\"><li><em>Do as I say!</em></li><li><em>We’d better leave things as they are until the police arrive.</em></li><li><em>The money was repaid, as promised.</em></li><li><em>He did not need to keep moving house, as his father had.</em></li><li><em>Roberta was late as usual (=in the way that she usually was).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to say that what you are saying is already known or has been stated before:</div><ul class=\"examples\"><li><em>David, as you know, has not been well lately.</em></li><li><em>As I explained on the phone, your request will be considered at the next meeting.</em></li><li><em>As Napoleon once said, attack is the best method of defence.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> while or when:</div><ul class=\"examples\"><li><em>I saw Peter as I was getting off the bus.</em></li><li><em>As time passed, things seemed to get worse.</em></li><li><em>Just as the two men were leaving, a message arrived.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> used to state why a particular situation exists or why someone does something: ► see thesaurus at because</div><ul class=\"examples\"><li><em>As it was getting late, I turned around to start for home.</em></li><li><em>We asked Philip to come with us, as he knew the road.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> though:</div><ul class=\"examples\"><li><em>Unlikely as it might seem, I’m tired too.</em></li><li><em>Try as she might, Sue couldn’t get the door open.</em></li><li><em>As popular as he is, the president hasn’t always managed to have his own way.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>as for somebody/something</strong> used when you are starting to talk about someone or something new that is connected with what you were talking about before:</div><ul class=\"examples\"><li><em>Kitty’s got so thin. And as for Carl, he always seems to be ill.</em></li><li><em>You can ask the others, but as for myself, I’ll be busy in the office.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>as yet</strong> <span class=\"gram\">[used in negatives]</span> until and including the present time – used to say that something has not happened although it may happen in the future:</div><ul class=\"examples\"><li><em>We’ve had no word from Colin as yet.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>as if.../as though...</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> in a way that makes it seem that something is true or that something is happening:</div><ul class=\"examples\"><li><em>It sounds as though she’s been really ill.</em></li><li><em>Gary was behaving as though nothing had happened.</em></li><li><em>Mrs Crump looked as if she was going to explode.</em></li><li><em>Beckworth shook his head as if to say ‘Don’t trust her’.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to emphasize that something is not true or will not happen:</div><ul class=\"examples\"><li><em>She said she’d never speak to me again. As if I cared (=I do not care at all).</em></li><li><em>‘Don’t try any funny business, now.’ ‘As if I would.’</em></li><li><strong><em>As if!<em>spoken</em></strong> </em>informal<em>: He asked if I’d go out with him. As if (=it is extremely unlikely that I would go out with him)!</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>it’s not as if</strong> used to say that something cannot be the explanation for a situation or someone’s behaviour because it is not true:</div><ul class=\"examples\"><li><em>Why do they never go on holiday? I mean it’s not as if they’re poor is it?</em></li><li><em>I don’t know why you’re so frightened of her, it’s not as if she’s got any power over you.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>as it is</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> because of the situation that actually exists – used when that situation is different from what you expected or needed:</div><ul class=\"examples\"><li><em>They hoped to finish the kitchen by Friday, but as it is they’ll probably have to come back next week.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> already:</div><ul class=\"examples\"><li><em>Just keep quiet – you’re in enough trouble as it is.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>as from/of something</strong> starting from a particular time or date and continuing:</div><ul class=\"examples\"><li><em>As from today, you are in charge of the office.</em></li><li><em>As of now, there will be no more paid overtime.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>as against something</strong> in comparison with something:</div><ul class=\"examples\"><li><em>Profits this year are $2.5 million as against $4 million last year.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>as to something</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> concerning something:</div><ul class=\"examples\"><li><em>Frank was very uncertain as to whether it was the right job for him.</em></li><li><em>advice as to which suppliers to approach</em></li><li><em>He kept his rivals guessing as to his real intentions.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>formal</em> used when you are starting to talk about something new that is connected with what you were talking about before:</div><ul class=\"examples\"><li><em>As to our future plans, I think I need only say that the company intends to expand at a steady rate.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>as it were</strong> used when describing someone or something in a way that is not quite exact:</div><ul class=\"examples\"><li><em>Jim Radcliffe became our idol, as it were, the man we all wanted to be.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>as is/was/does etc</strong> <em>formal</em> used to add that what you have said is also true of someone or something else:</div><ul class=\"examples\"><li><em>Eve’s very tall, as was her mother.</em></li><li><em>I voted Labour, as did my wife.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>as you do</strong> <em>British English</em> <em>spoken</em> in the way that people usually do something or how they normally behave – often used humorously by people after they have mentioned doing something strange or unusual:</div><ul class=\"examples\"><li><em>We talked, exchanged email addresses and phone numbers, as you do on planes.</em></li><li><em>I was driving a Ferrari through town yesterday – as you do – when I saw an old school friend outside the cinema.</em></li></ul></div></div>","415":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧cend</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsend/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive]</span> <em>formal</em> to move up through the air <em>OPP descend</em>:</div><ul class=\"examples\"><li><em>The plane ascended rapidly.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> <em>written</em> to climb something or move to a higher position <em>OPP descend</em>: RegisterAscend is used mostly in literary or technical contexts. In everyday English, people usually say climb or go up:· We started to climb the mountain.· She slowly went up the stairs.</div><ul class=\"examples\"><li><em>Without a word, he began to ascend the stairs.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> <em>written</em> to lead up to a higher position <em>OPP descend</em>:</div><ul class=\"examples\"><li><em>The road ascends steeply from the harbour.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive, transitive]</span> <em>formal</em> to move to a more important or powerful job:</div><ul class=\"examples\"><li><em>The number of women decreases as you ascend the professional hierarchy.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>ascend the throne</strong> to become king or queen</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>in ascending order</strong> if a group of things are arranged in ascending order, each thing is higher, or greater in amount, than the one before it</div></div>","416":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧cer‧tain</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌæsəˈteɪn $ ˌæsər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>formal</em> to find out something <em>SYN establish</em>:</div><ul class=\"examples\"><li><em>A postmortem was ordered to try to ascertain the cause of death.</em></li><li><strong><em>ascertain whether/what/how etc</strong>: Tests were conducted to ascertain whether pollution levels have dropped.</em></li><li><strong><em>ascertain that</strong>: Police had ascertained that the dead man knew his killer.</em></li><li><strong><em>ascertain something from somebody/something</strong>: You should ascertain the level of insurance cover from the car rental company.</em></li></ul></div>","417":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /æʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the soft grey powder that remains after something has been burned:</div><ul class=\"examples\"><li><em>cigarette ash</em></li><li><em>The house burnt to ashes.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>ashes</strong> <span class=\"gram\">[plural]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the ash that remains when a dead person’s body is burned:</div><ul class=\"examples\"><li><em>His ashes were scattered at sea.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a situation in which something is completely destroyed:</div><ul class=\"examples\"><li><em>The organization has risen from the ashes to become very successful.</em></li><li><em>All her hopes and dreams had turned to ashes.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> a tree that is common in Britain and North America, or the wood from this tree</div></div>","418":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧shamed</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈʃeɪmd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[not before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> feeling very sorry and embarrassed because of something you have done</div><ul class=\"examples\"><li><strong><em>ashamed of/at</strong>: I felt ashamed of the things I’d said to him.</em></li><li><strong><em>be ashamed to do something</strong>: I’m ashamed to admit that I’ve never read any of his books.</em></li><li><strong><em>ashamed that</strong>: She felt ashamed that she had missed her sister’s wedding.</em></li><li><strong><em>deeply/bitterly/thoroughly ashamed</strong>: Alan was deeply ashamed when he remembered what he’d said.</em></li><li><em>Everyone cries sometimes – it’s nothing to be ashamed of.</em></li><li><strong><em>be/feel ashamed of yourself</strong>: You should be ashamed of yourself.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> feeling uncomfortable because someone does something that embarrasses you</div><ul class=\"examples\"><li><strong><em>ashamed of</strong>: Many children feel ashamed of their parents.</em></li><li><strong><em>ashamed to be/do something</strong>: Their behaviour makes me ashamed to be British.</em></li></ul></div>","419":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧side</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsaɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> kept to be used later:</div><ul class=\"examples\"><li><em>I’ve been setting aside a few pounds each week.</em></li><li><em>One of the rooms was set aside for a yoga class.</em></li><li><em>Try to set aside a few hours a week for exercise.</em></li><li><em>Could you put this cake aside for me?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> moved to one side or away from you:</div><ul class=\"examples\"><li><em>He pushed his half-eaten salad aside and left.</em></li><li><em>He stepped aside to let Katherine go in first.</em></li><li><em>Mark drew me aside and explained the problem.</em></li><li><em>She swept her thick hair aside.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> left to be considered or dealt with later, or not considered and dealt with at all:</div><ul class=\"examples\"><li><em>He brushed aside criticisms of his performance.</em></li><li><em>Leaving aside the heat, we really enjoyed our holiday.</em></li><li><em>You must put aside your pride and call her.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[only after noun]</span> used to show that something you have just said is not as important as what you are going to say next:</div><ul class=\"examples\"><li><em>These problems aside, we think the plan should go ahead.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>aside from somebody/something</strong> <em>especially American English</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> except for <em>SYN apart from</em>:</div><ul class=\"examples\"><li><em>Aside from Durang’s performance, the actors are ordinary.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> in addition to:</div><ul class=\"examples\"><li><em>In the poetry competition, aside from Hass, are four other entrants.</em></li></ul></div>","420":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ɑːsk $ æsk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[question]</strong> <span class=\"gram\">[intransitive, transitive]</span> to speak or write to someone in order to get an answer, information, or a solution:</div><ul class=\"examples\"><li><em>‘What’s your name?’ she asked.</em></li><li><em>Don’t ask him – he won’t know.</em></li><li><em>That kid’s always asking awkward questions.</em></li><li><strong><em>ask who/what/where etc</strong>: I asked him where he lived.</em></li><li><strong><em>ask somebody something</strong>: We’ll have to ask someone the way to the station.</em></li><li><strong><em>ask somebody if/whether</strong>: Go and ask Tom whether he’s coming tonight.</em></li><li><strong><em>ask (somebody) about something</strong>: Visitors usually ask about the history of the castle.</em></li><li><strong><em>ask around</strong> (=ask in a lot of places or ask a lot of people): I’ll ask around, see if I can find you a place to stay.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[for help/advice etc]</strong> <span class=\"gram\">[intransitive, transitive]</span> to make a request for help, advice, information etc:</div><ul class=\"examples\"><li><em>If you need anything, you only have to ask.</em></li><li><strong><em>ask somebody to do something</strong>: Ask John to mail those letters tomorrow.</em></li><li><strong><em>ask to do something</strong>: Karen asked to see the doctor.</em></li><li><strong><em>ask for</strong>: Some people find it difficult to ask for help.</em></li><li><strong><em>ask somebody for something</strong>: He repeatedly asked Bailey for the report.</em></li><li><strong><em>ask (somebody) if/whether you can do something</strong>: Ask your mom if you can come with us.</em></li><li><strong><em>ask that</strong>: Was it too much to ask that he be allowed some privacy?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[price]</strong> <span class=\"gram\">[transitive]</span> to want a particular amount of money for something you are selling:</div><ul class=\"examples\"><li><em>How much is he asking?</em></li><li><strong><em>ask $50/$1,000 etc for something</strong>: He’s asking £2,000 for his car.</em></li><li><em>They’re asking a fortune for that house.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[invite]</strong> <span class=\"gram\">[transitive usually + adverb/preposition]</span> to invite someone to your home, to go out with you etc</div><ul class=\"examples\"><li><strong><em>ask somebody to do something</strong>: Let’s ask them to have dinner with us some time.</em></li><li><strong><em>ask somebody out</strong> (=ask someone, especially someone of the opposite sex, to go to a film, a restaurant etc with you): Jerry’s too scared to ask her out.</em></li><li><strong><em>ask somebody in</strong> (=invite someone into your house, office etc): Don’t leave them standing on the doorstep – ask them in!</em></li><li><strong><em>ask somebody over/round</strong> (=invite someone to come to your home): We must ask our new neighbours over for a drink.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[demand]</strong> <span class=\"gram\">[transitive]</span> if you ask something of someone, you want them to do it for you:</div><ul class=\"examples\"><li><em>It would be better if he cooperated, but perhaps I’m asking too much.</em></li><li><strong><em>ask something of somebody</strong>: You have no right to ask anything of me. / Expecting the children to do an hour’s homework after school is asking a lot of them.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>I/you can’t/couldn’t ask for a better something</strong> (also I/you can’t/couldn’t ask for more) used to say that you are very happy with what you have or with a situation:</div><ul class=\"examples\"><li><em>I couldn’t ask for a better boss.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>be asking for trouble</strong> to do something that is very likely to have a bad effect or result:</div><ul class=\"examples\"><li><em>Saying that to a feminist is just asking for trouble.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>ask yourself something</strong> to think carefully and honestly about something:</div><ul class=\"examples\"><li><em>You have to ask yourself where your responsibilities really lie.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>be somebody’s for the asking</strong> <em>informal</em> if something is yours for the asking, you can have it if you want it:</div><ul class=\"examples\"><li><em>The job was hers for the asking.</em></li></ul></div>","421":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧sleep</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsliːp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[not before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> sleeping <em>OPP awake</em>:</div><ul class=\"examples\"><li><em>Quiet! The baby’s asleep.</em></li><li><strong><em>fast/sound asleep</strong> (=sleeping deeply)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>fall asleep</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to begin to sleep:</div><ul class=\"examples\"><li><em>Grandad fell asleep watching TV.</em></li><li><em>One in seven road accidents is caused by drivers falling asleep at the wheel (=falling asleep while driving).</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>literary</em> used to mean that someone dies, when you want to avoid saying this directly</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>half asleep</strong> very tired or not completely awake:</div><ul class=\"examples\"><li><em>Still half asleep, Jenny began to make the kids’ breakfast.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> an arm or leg that is asleep has been in one position for too long, so you cannot feel it properly</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>asleep at the wheel/switch</strong> not paying attention to a situation, so that something bad happens:</div><ul class=\"examples\"><li><em>Several publishers were asleep at the switch, and missed the book’s potential.</em></li></ul></div>","422":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧pect</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæspekt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> one part of a situation, idea, plan etc that has many parts</div><ul class=\"examples\"><li><strong><em>aspect of</strong>: Dealing with people is the most important aspect of my work. / Alcoholism affects all aspects of family life.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> the direction in which a window, room, front of a building etc faces:</div><ul class=\"examples\"><li><em>a south-facing aspect</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular, uncountable]</span> <em>literary</em> the appearance of someone or something:</div><ul class=\"examples\"><li><em>The storm outside gave the room a sinister aspect.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable, uncountable]</span> <em>technical</em> the form of a verb in grammar that shows whether an action is continuing, or happens always, again and again, or once:</div><ul class=\"examples\"><li><em>‘He sings’ differs from ‘He is singing’ in aspect.</em></li></ul></div>","423":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧pi‧ra‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌæspəˈreɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable usually plural, uncountable]</span> a strong desire to have or achieve something <em>SYN ambition</em>:</div><ul class=\"examples\"><li><em>a high level of political aspiration</em></li><li><strong><em>aspiration of</strong>: the aspirations of the working classes</em></li><li><strong><em>aspiration for</strong>: their hopes and aspirations for the future</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> <em>technical</em> the sound of air blowing out that happens when some consonants are pronounced, such as the /p/ in ‘pin’</div></div>","424":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧pire</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈspaɪə $ əˈspaɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to desire and work towards achieving something important</div><ul class=\"examples\"><li><strong><em>aspire to</strong>: college graduates aspiring to careers in finance</em></li><li><strong><em>aspire to do something</strong>: At that time, all serious artists aspired to go to Rome.</em></li></ul></div>","425":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧pirin</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæsprɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural aspirin or aspirins)</span></div><div class=\"entry-body\"><div class=\"sense\">a medicine that reduces pain, inflammation, and fever</div></div>","426":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sas‧sin</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsæsɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who murders an important person:</div><ul class=\"examples\"><li><em>Kennedy’s assassin is assumed to have been Lee Harvey Oswald.</em></li></ul></div>","427":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sas‧sin‧ate</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsæsəneɪt $ -səneɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to murder an important person: ► see thesaurus at kill</div><ul class=\"examples\"><li><em>a plot to assassinate the president</em></li></ul></div>","428":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sas‧sin‧a‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /əˌsæsəˈneɪʃən $ əˌsæsənˈeɪ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the act of murdering an important person</div><ul class=\"examples\"><li><strong><em>assassination of</strong>: the assassination of Anwar Sadat</em></li><li><em>He narrowly escaped an assassination attempt (=when someone tries but fails to kill someone else).</em></li></ul></div>","429":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sault</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsɔːlt $ əˈsɒːlt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the crime of physically attacking someone: ► see thesaurus at crime</div><ul class=\"examples\"><li><em>a case of robbery and assault</em></li><li><strong><em>for assault</strong>: He was jailed for assault.</em></li><li><strong><em>sexual/indecent assault</strong>: victims of indecent assault</em></li><li><strong><em>assault on/against</strong>: sexual assaults on women</em></li><li><em>Several soldiers have been charged with assault.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> a military attack to take control of a place controlled by the enemy</div><ul class=\"examples\"><li><strong><em>assault on</strong>: an unsuccessful assault on the enemy lines</em></li><li><em>The refugee camp came under assault again last night.</em></li><li><em>a powerful assault rifle</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> a strong spoken or written criticism of someone else’s ideas, plans etc <em>SYN attack</em></div><ul class=\"examples\"><li><strong><em>assault on</strong>: an assault on the capitalist system</em></li><li><strong><em>under assault</strong>: Traditional family values are increasingly under assault.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> an attempt to achieve something difficult, especially using physical force</div><ul class=\"examples\"><li><strong><em>assault on</strong>: an assault on Mt Everest (=an attempt to climb it)</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to attack someone in a violent way: ► see thesaurus at attack</div><ul class=\"examples\"><li><em>Two men assaulted him after he left the bar.</em></li><li><strong><em>sexually/indecently assault</strong>: He was found guilty of indecently assaulting a student.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>literary</em> if a feeling, sound, smell etc assaults you, it affects you in a way that makes you uncomfortable or upset:</div><ul class=\"examples\"><li><em>The noises and smells of the market assaulted her senses.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to strongly criticize someone’s ideas, plans etc</div><div class=\"sense\"><span class=\"snum\">4</span> to try to do something very difficult:</div><ul class=\"examples\"><li><em>a task force to assault the problems</em></li></ul></div></div>","430":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sem‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsembəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> if you assemble a large number of people or things, or if they assemble, they are gathered together in one place, often for a particular purpose: ► see thesaurus at collect, meet</div><ul class=\"examples\"><li><em>A large crowd had assembled outside the American embassy.</em></li><li><em>He looked around at the assembled company (=all the people who had come there).</em></li><li><em>She had assembled a collection of her favourite songs.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to put all the parts of something together:</div><ul class=\"examples\"><li><em>The aircraft will continue to be assembled in France.</em></li></ul></div>","431":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sem‧bly</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsembli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\">(plural assemblies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a group of people who are elected to make decisions or laws for a particular country, area, or organization:</div><ul class=\"examples\"><li><em>the General Assembly of the Church of Scotland</em></li><li><em>the speaker of the California state assembly</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> the meeting together of a group of people for a particular purpose</div><ul class=\"examples\"><li><strong><em>assembly of</strong>: an assembly of reporters</em></li><li><em>Police have imposed conditions on public assemblies.</em></li><li><em>Restrictions on freedom of assembly have gradually been relaxed.</em></li><li><em>an assembly point (=a place where people go in a particular situation)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> a regular meeting of all the teachers and students of a school</div><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> the process of putting the parts of something together:</div><ul class=\"examples\"><li><em>instructions for assembly</em></li></ul></div>","432":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sert</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsɜːt $ -ɜːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to state firmly that something is true:</div><ul class=\"examples\"><li><em>French cooking, she asserted, is the best in the world.</em></li><li><strong><em>assert that</strong>: He asserted that nuclear power was a safe and non-polluting energy source.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>assert your rights/independence/superiority etc</strong> to state very strongly your right to something:</div><ul class=\"examples\"><li><em>Native Americans asserting their rights to ancestral land</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>assert yourself</strong> to behave in a determined way and say clearly what you think:</div><ul class=\"examples\"><li><em>Women began to assert themselves politically.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>assert itself</strong> if an idea or belief asserts itself, it begins to influence something:</div><ul class=\"examples\"><li><em>National pride began to assert itself.</em></li></ul></div>","433":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧ser‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsɜːʃən $ -ɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">something that you say or write that you strongly believe ► see thesaurus at claim</div><ul class=\"examples\"><li><strong><em>assertion that</strong>: the assertion that house prices are falling</em></li><li><strong><em>assertion of</strong>: her assertion of independence</em></li><li><strong><em>assertion about</strong>: her assertions about the murder of her father</em></li><li><em>She makes very general assertions about marriage in the poem.</em></li></ul></div>","434":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧ser‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsɜːtɪv $ -ɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">behaving in a confident way, so that people notice you ► see thesaurus at confident</div></div>","435":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sess</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈses/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make a judgment about a person or situation after thinking carefully about it <em>SYN judge</em></div><ul class=\"examples\"><li><strong><em>assess the impact/extent/effectiveness etc of something</strong>: a report to assess the impact of advertising on children</em></li><li><strong><em>assess what/how etc</strong>: The technique is being tried in classrooms to assess what effects it may have.</em></li><li><strong><em>be assessed as something</strong>: Many of the adults were assessed as having learning difficulties.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to calculate the value or cost of something</div><ul class=\"examples\"><li><strong><em>be assessed at something</strong>: The value of the business was assessed at £1.25 million.</em></li></ul></div>","436":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sess‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsesmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a process in which you make a judgment about a person or situation, or the judgment you make</div><ul class=\"examples\"><li><strong><em>assessment of</strong>: What’s Michael’s assessment of the situation?</em></li><li><em>a reading assessment test</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a calculation about the cost or value of something:</div><ul class=\"examples\"><li><em>a tax assessment</em></li></ul></div>","437":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧set</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæset/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[usually plural]</span> the things that a company owns, that can be sold to pay debts</div><ul class=\"examples\"><li><strong><em>in assets</strong>: a corporation with $9 billion in assets</em></li><li><em>the value of a company’s assets</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[usually singular]</span> something or someone that is useful because they help you succeed or deal with problems <em>OPP liability</em>:</div><ul class=\"examples\"><li><em>A sense of humor is a great asset in this business.</em></li><li><strong><em>be an asset to somebody/something</strong>: I think Rachel would be an asset to the department.</em></li></ul></div>","438":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sign</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsaɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to give someone a particular job or make them responsible for a particular person or thing</div><ul class=\"examples\"><li><strong><em>assign somebody a task/role</strong>: I’ve been assigned the task of looking after the new students.</em></li><li><strong><em>assign somebody to something</strong>: Jan’s been assigned to the Asian Affairs Bureau.</em></li><li><strong><em>assign somebody to do something</strong>: Madison was assigned to investigate a balloon accident.</em></li><li><strong><em>assign somebody something</strong>: Assign each student a partner.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to give a particular time, value, place etc to something:</div><ul class=\"examples\"><li><em>How much time have you assigned for the meeting?</em></li><li><strong><em>assign something to something</strong>: A code was assigned to each batch of work.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to give money, equipment etc to someone to use</div><ul class=\"examples\"><li><strong><em>assign something to somebody</strong>: A personal bodyguard had been assigned to her.</em></li><li><strong><em>assign somebody something</strong>: They assigned me a small room.</em></li></ul></div>","439":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sign‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsaɪnmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a piece of work that is given to someone as part of their job</div><ul class=\"examples\"><li><strong><em>on an assignment</strong>: She’s gone to Italy on a special assignment.</em></li><li><strong><em>on assignment</strong>: He was killed while on assignment abroad.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a piece of work that a student is asked to do:</div><ul class=\"examples\"><li><em>a history assignment</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> when people are given particular jobs to do</div><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> something such as a place to sit, piece of equipment etc that you are given to use for a particular purpose:</div><ul class=\"examples\"><li><em>an aeroplane seat assignment</em></li></ul></div>","440":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sist</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsɪst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to help someone to do something ► see thesaurus at help</div><ul class=\"examples\"><li><strong><em>assist (somebody) with/in something</strong>: You will be employed to assist in the development of new equipment.</em></li><li><strong><em>assist somebody to do something</strong>: We want to assist people to stay in their own homes.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to make it easier for someone to do something: RegisterIn everyday English, people usually say help rather than assist:· We’ll help in any way we can.· They have special software to help them process invoices.</div><ul class=\"examples\"><li><em>They had no maps to assist them.</em></li></ul></div>","441":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sist‧ance</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsɪstəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">help or support:</div><ul class=\"examples\"><li><em>We offer financial assistance to students.</em></li><li><em>Can I be of any assistance (=can I help you)?</em></li><li><strong><em>with the assistance of somebody/something</strong>: We’ve rebuilt the theatre with the assistance of the National Lottery.</em></li></ul></div>","442":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sis‧tant</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsɪstənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><strong>assistant manager/director/cook etc</strong> someone whose job is just below the level of manager etc</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who helps someone else in their work, especially by doing the less important jobs:</div><ul class=\"examples\"><li><em>a clerical assistant</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> a shop assistant</div></div></div>","443":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧so‧ci‧ate</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsəʊʃieɪt, əˈsəʊsi- $ əˈsoʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to make a connection in your mind between one thing or person and another</div><ul class=\"examples\"><li><strong><em>associate somebody/something with something</strong>: I don’t associate him with energetic sports.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be associated (with somebody/something)</strong> RegisterIn everyday English, people usually say something comes with or goes with something rather than is associated with it:· There are some problems that go with this way of doing things.</div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be related to a particular subject, activity etc:</div><ul class=\"examples\"><li><em>problems associated with cancer treatment</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> (also associate yourself with somebody/something) to show that you support someone or something:</div><ul class=\"examples\"><li><em>He did not associate himself with the pro-democracy movement.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>associate with somebody</strong> to spend time with someone, especially someone that other people disapprove of:</div><ul class=\"examples\"><li><em>I don’t like these layabouts you’re associating with.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧so‧ci‧ate</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsəʊʃiət, əˈsəʊsi- $ əˈsoʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who you work or do business with <em>SYN colleague</em>:</div><ul class=\"examples\"><li><em>one of his business associates</em></li></ul></div></div>","444":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧so‧ci‧a‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /əˌsəʊsiˈeɪʃən, əˌsəʊʃi- $ əˌsoʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> an organization that consists of a group of people who have the same aims, do the same kind of work etc: → housing association ► see thesaurus at organization</div><ul class=\"examples\"><li><em>the Association of Master Builders</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> a relationship with a particular person, organization, group etc</div><ul class=\"examples\"><li><strong><em>association with</strong>: his close association with the Green Party</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in association with somebody/something</strong> made or done with another person, organization etc:</div><ul class=\"examples\"><li><em>concerts sponsored by the Arts Council in association with local businesses</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> a connection or relationship between two events, ideas, situations etc</div><ul class=\"examples\"><li><strong><em>association between</strong>: the strong association between the disease and middle-aged women</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> a feeling or memory that is related to a particular place, event, word etc:</div><ul class=\"examples\"><li><em>Scotland has all kinds of happy associations for me.</em></li></ul></div>","445":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sume</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsjuːm $ əˈsuːm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to think that something is true, although you do not have definite proof <em>SYN presume</em> GRAMMARIn more formal English, you say it is assumed that something is true: · It is assumed that the person is innocent.</div><ul class=\"examples\"><li><strong><em>assume (that)</strong>: I didn’t see your car, so I assumed you’d gone out.</em></li><li><strong><em>it seems/is reasonable to assume (that)</strong>: It seems reasonable to assume that the book was written around 70 AD.</em></li><li><strong><em>somebody can safely assume that</strong> (=it is almost certain): I think we can safely assume that interest rates will go up again soon.</em></li><li><strong><em>let us/let’s assume (that)</strong> (=used when thinking about a possible event or situation and its possible results): Let us assume for a moment that we could indeed fire her. Should we?</em></li><li><strong><em>somebody/something is assumed to be (doing) something</strong>: The rest of the system is assumed to be functioning well.</em></li><li><strong><em>assume the worst</strong> (=think that the worst possible thing has happened): When it got to midnight and Paul was still not back, I began to assume the worst.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>assume control/responsibility etc</strong> <em>formal</em> to start to have control, responsibility etc or to start in a particular position or job:</div><ul class=\"examples\"><li><em>Whoever they appoint will assume responsibility for all financial matters.</em></li><li><em>He assumed power in a bloody coup in 1990.</em></li><li><em>Jim Paton will assume the role of managing director.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>assume a manner/air/expression etc</strong> <em>formal</em> to behave in a way that does not show how you really feel, especially in order to seem more confident, happy etc than you are <em>SYN put on</em>:</div><ul class=\"examples\"><li><em>Andy assumed an air of indifference whenever her name was mentioned.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> to start to have a particular quality or appearance <em>SYN take on</em>:</div><ul class=\"examples\"><li><em>These relationships assume great importance in times of crisis.</em></li><li><em>The problem is beginning to assume massive proportions.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> to be based on the idea that something else is correct <em>SYN presuppose</em></div><ul class=\"examples\"><li><strong><em>assume (that)</strong>: The theory assumes that both labour and capital are mobile.</em></li><li><em>Coen’s economic forecast assumes a 3.5% growth rate.</em></li></ul></div>","446":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sump‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsʌmpʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> something that you think is true although you have no definite proof → assume</div><ul class=\"examples\"><li><strong><em>assumption that</strong>: A lot of people make the assumption that poverty only exists in the Third World. / My calculations were based on the assumption that house prices would remain steady.</em></li><li><strong><em>assumption about</strong>: People make a lot of assumptions about me.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> <em>formal</em> when someone starts to have control or power</div><ul class=\"examples\"><li><strong><em>assumption of</strong>: the assumption of responsibility</em></li></ul></div>","447":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sur‧ance</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈʃʊərəns $ əˈʃʊr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a promise that something will definitely happen or is definitely true, made especially to make someone less worried:</div><ul class=\"examples\"><li><em>Despite my repeated assurances, Rob still looked very nervous.</em></li><li><strong><em>give/seek/receive an assurance (that)</strong>: He gave an assurance that the work would be completed by Wednesday.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> a feeling of calm confidence about your own abilities, or that you are right about something:</div><ul class=\"examples\"><li><em>the calm assurance with which she handled the horse</em></li><li><em>‘Jack will never agree to that,’ he said with assurance.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> <em>British English</em> <em>technical</em> insurance, especially to provide money when someone dies SYN insurance<em>American English</em></div></div>","448":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sure</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈʃʊə $ əˈʃʊr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to tell someone that something will definitely happen or is definitely true so that they are less worried <em>SYN reassure</em> → rest assured at rest2(5) ► see thesaurus at promise</div><ul class=\"examples\"><li><strong><em>assure somebody that</strong>: Her doctor has assured us that she’ll be fine.</em></li><li><em>The document is genuine, I can assure you.</em></li><li><strong><em>assure somebody of something</strong>: The dealer had assured me of its quality.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make something certain to happen or to be achieved <em>SYN ensure</em>:</div><ul class=\"examples\"><li><em>Excellent reviews have assured the film’s success.</em></li><li><strong><em>assure somebody (of) something</strong>: A win on Saturday will assure them of promotion to Division One.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>assure yourself</strong> <em>formal</em> to check that something is correct or true</div><ul class=\"examples\"><li><strong><em>assure yourself that</strong>: Tim waited a moment to assure himself that he was not being followed.</em></li><li><strong><em>assure of</strong>: I took steps to assure myself of her guilt.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the sum assured</strong> <em>formal</em> the amount of insurance money to be paid out when someone dies</div></div>","449":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧sured</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈʃʊəd $ əˈʃʊrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> confident about your own abilities <em>SYN self-assured</em>:</div><ul class=\"examples\"><li><em>an assured manner</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be assured of something</strong> if you are assured of something, you will definitely get it or achieve it:</div><ul class=\"examples\"><li><em>His victory means that he is now assured of a place in the final.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> certain to happen or to be achieved:</div><ul class=\"examples\"><li><em>Her political future looks assured.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the assured</strong> <em>British English</em> <em>technical</em> someone whose life has been insured</div></div>","450":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> asth‧ma</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæsmə $ ˈæzmə/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a medical condition that causes difficulties in breathing</div></div>","451":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧ton‧ish</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈstɒnɪʃ $ əˈstɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to surprise someone very much <em>SYN amaze</em>:</div><ul class=\"examples\"><li><em>Her reply astonished me.</em></li><li><em>It astonished him that she had changed so little.</em></li><li><em>What astonishes me most is his complete lack of fear.</em></li></ul></div>","452":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧ton‧ished</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈstɒnɪʃt $ əˈstɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">very surprised about something <em>SYN amazed</em> ► see thesaurus at surprised</div><ul class=\"examples\"><li><strong><em>astonished to see/find/hear/learn etc</strong>: We were astonished to find the temple still in its original condition.</em></li><li><strong><em>astonished by/at</strong>: I was astonished by the result.</em></li><li><strong><em>astonished (that)</strong>: I’m astonished that you should even think such a thing!</em></li></ul></div>","453":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧ton‧ish‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈstɒnɪʃɪŋ $ əˈstɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">so surprising that it is difficult to believe <em>SYN amazing</em>: ► see thesaurus at surprising</div><ul class=\"examples\"><li><em>an astonishing decision</em></li><li><em>their astonishing success</em></li></ul></div>","454":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧ton‧ish‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈstɒnɪʃmənt $ əˈstɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">complete surprise <em>SYN amazement</em></div><ul class=\"examples\"><li><strong><em>in astonishment</strong>: She stared at him in astonishment.</em></li><li><strong><em>to somebody’s astonishment</strong>: To my astonishment, the car was gone.</em></li></ul></div>","455":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧tro‧naut</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæstrənɔːt $ -nɒːt, -nɑːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who travels and works in a spacecraft</div></div>","456":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧tron‧o‧my</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈstrɒnəmi $ əˈstrɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the scientific study of the stars and planets → astrology</div></div>","457":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> as‧tute</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈstjuːt $ əˈstuːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">able to understand situations or behaviour very well and very quickly, especially so that you can get an advantage for yourself <em>SYN clever</em>:</div><ul class=\"examples\"><li><em>an astute politician</em></li><li><em>astute investments</em></li></ul></div>","458":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧sy‧lum</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈsaɪləm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> protection given to someone by a government because they have escaped from fighting or political trouble in their own country → political asylum</div><ul class=\"examples\"><li><strong><em>apply for/seek/be granted asylum</strong>: He has been granted asylum in France.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> <em>old use</em> a mental hospital</div></div>","459":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ət; strong æt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to say exactly where something or someone is, or where something happens:</div><ul class=\"examples\"><li><em>They live at 18 Victoria Street.</em></li><li><em>Does this train stop at Preston?</em></li><li><em>I was waiting at the bus stop.</em></li><li><em>Liz and her friend sat down at a corner table.</em></li><li><em>Turn left at the church.</em></li><li><em>We’ll meet at Harry’s (=at Harry’s house).</em></li><li><em>I spent an unpleasant hour at the dentist’s.</em></li><li><em>Dad’s at work (=in the place where he works).</em></li><li><strong><em>at the top/bottom/end etc (of something)</strong>: At the top of the stairs, she paused.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to say what event or activity someone is taking part in:</div><ul class=\"examples\"><li><em>I met my wife at a disco.</em></li><li><em>The matter was discussed at a meeting of the finance committee.</em></li><li><em>I’m sorry, Pam’s at lunch just now.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to say that someone is studying somewhere regularly:</div><ul class=\"examples\"><li><em>Is Jessica still at school?</em></li><li><em>Hulme was a student at Oxford in the 1960s.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used to say exactly when something happens:</div><ul class=\"examples\"><li><em>The film starts at 8 o&#x27;clock.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> during a particular period of time:</div><ul class=\"examples\"><li><em>My husband often works at night.</em></li><li><em>We go to Midnight Mass at Christmas.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> used to say which thing or person an action is directed towards or intended for:</div><ul class=\"examples\"><li><em>He gazed up at the sky.</em></li><li><em>You don’t have to shout at me.</em></li><li><em>The older girls used to throw stones at me.</em></li><li><em>The course is aimed at those aged 16 or over.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> used to say what or who causes an action or feeling:</div><ul class=\"examples\"><li><em>The children all laughed at his jokes.</em></li><li><em>I’m surprised at you!</em></li><li><em>Dad got really mad at me for scratching the car.</em></li><li><em>her distress at having to leave</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> used to say which subject or activity you are talking about when you say whether someone is skilful, successful etc or not:</div><ul class=\"examples\"><li><em>Barbara’s getting on really well at her new job.</em></li><li><strong><em>good/bad etc at (doing) something</strong>: I’ve always been good at maths. / Matt’s bad at handling people.</em></li><li><em>He’s an expert at making things out of junk.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> used to say that someone or something is in a particular state:</div><ul class=\"examples\"><li><em>two nations at war</em></li><li><em>Many children are still at risk from neglect or abuse.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> used to show a price, rate, level, age, speed etc:</div><ul class=\"examples\"><li><em>old books selling at 10 cents each</em></li><li><em>You should have more sense at your age.</em></li><li><em>The Renault was travelling at about 50 mph.</em></li><li><em>Amanda rode off at a gallop.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>at your best/worst/most effective etc</strong> used to say that, at a particular time, someone or something is as good, bad etc as they can be:</div><ul class=\"examples\"><li><em>The garden is at its best in June.</em></li><li><em>This was Federer at his most powerful.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> used to say what someone tries to touch, or keeps touching:</div><ul class=\"examples\"><li><em>I clutched at the rope.</em></li><li><em>George was just picking at his food.</em></li><li><em>Sarah took another sip at her wine.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> used to say what someone tries to do:</div><ul class=\"examples\"><li><em>the student’s first attempt at a piece of research</em></li><li><em>They were so beautiful that I decided to have a go at growing them.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> because of what someone has said:</div><ul class=\"examples\"><li><em>Chapman visited Austria at the invitation of his friend, Hugo Meisl.</em></li><li><em>At my suggestion, Bernard went to see his former teacher.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>while I’m/you’re etc at it</strong> <em>spoken</em> used to suggest that someone should do something while they are doing something else:</div><ul class=\"examples\"><li><em>I’m just going for a cup of coffee. Shall I bring you one while I’m at it?</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>be at it again</strong> <em>informal</em> if you say that someone is at it again, you mean that they are doing something you disapprove of, which they have done before:</div><ul class=\"examples\"><li><em>She’s at it again, interfering in other people’s business.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>at that</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> also or besides:</div><ul class=\"examples\"><li><em>It’s a new idea, and a good one, at that.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> after something is said:</div><ul class=\"examples\"><li><em>Tess called him a liar and at that he stormed out of the room.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>be where it’s at</strong> <em>old-fashioned</em> <em>informal</em> used to say that a place or activity is very popular, exciting, and fashionable</div></div>","460":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ath‧lete</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæθliːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who competes in sports competitions, especially running, jumping, and throwing:</div><ul class=\"examples\"><li><em>a professional athlete</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who is good at sports and who often does sports:</div><ul class=\"examples\"><li><em>I was a natural athlete as a kid.</em></li></ul></div>","461":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ath‧let‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /æθˈletɪk, əθ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> physically strong and good at sport:</div><ul class=\"examples\"><li><em>a tall athletic man</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> relating to athletics:</div><ul class=\"examples\"><li><em>athletic ability</em></li></ul></div>","462":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ath‧let‧ics</span><span class=\"meta-item\"><strong>IPA:</strong> /æθˈletɪks, əθ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>British English</em> sports such as running and jumping SYN track and field<em>American English</em></div><div class=\"sense\"><span class=\"snum\">2</span> <em>American English</em> physical activities such as sports and exercise</div></div>","463":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧las</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈætləs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a book containing maps, especially of the whole world → road atlas</div></div>","464":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧mo‧sphere</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈætməsfɪə $ -fɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the feeling that an event or place gives you:</div><ul class=\"examples\"><li><em>The hotel had a lovely relaxed atmosphere.</em></li><li><em>The atmosphere at home was rather tense.</em></li><li><strong><em>atmosphere of</strong>: An atmosphere of optimism dominated the conference.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> if a place or event has atmosphere, it is interesting:</div><ul class=\"examples\"><li><em>The castle was centuries old and full of atmosphere.</em></li><li><em>The match was lacking in atmosphere.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the atmosphere</strong> the mixture of gases that surrounds the Earth</div><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> the mixture of gases that surrounds a planet</div><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable usually singular]</span> the air inside a room:</div><ul class=\"examples\"><li><em>a smoky atmosphere</em></li></ul></div>","465":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧om</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈætəm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the smallest part of an element that can exist alone or can combine with other substances to form a molecule:</div><ul class=\"examples\"><li><em>carbon atoms</em></li><li><strong><em>atom of</strong>: two atoms of hydrogen</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a very small amount of something – used for emphasis</div><ul class=\"examples\"><li><strong><em>atom of</strong>: There isn’t an atom of truth in it.</em></li></ul></div>","466":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧tom‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈtɒmɪk $ əˈtɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relating to the energy produced by splitting atoms or the weapons that use this energy:</div><ul class=\"examples\"><li><em>atomic power</em></li><li><em>an atomic submarine</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> relating to the atoms in a substance:</div><ul class=\"examples\"><li><em>atomic weight</em></li></ul></div>","467":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧tach</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈtætʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to fasten or connect one object to another <em>SYN fix</em></div><ul class=\"examples\"><li><strong><em>attach something to something</strong>: Attach a recent photograph to your application form. / a small battery attached to a little loudspeaker</em></li><li><strong><em>the attached form/cheque/leaflet etc</strong>: Please fill in and return the attached reply slip.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be attached to somebody/something</strong> to like someone or something very much, because you have known them or had them for a long time:</div><ul class=\"examples\"><li><em>It’s easy to become attached to the children you work with.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>attach importance/significance etc to something</strong> to believe that something is important:</div><ul class=\"examples\"><li><em>People attach too much importance to economic forecasts.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive, transitive]</span> if blame attaches or is attached to someone, they are responsible for something bad that happens:</div><ul class=\"examples\"><li><em>No blame can be attached to Roy for the incident.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[intransitive, transitive]</span> if a quality, feeling, idea etc attaches or is attached to a person, thing, or event, it is connected with them</div><ul class=\"examples\"><li><strong><em>attach to</strong>: It’s easy to let the emotions attached to one situation spill over into others.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be attached to something</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to work for part of a particular organization, especially for a short period of time:</div><ul class=\"examples\"><li><em>He was attached to the foreign affairs department of a Japanese newspaper.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to be part of a bigger organization:</div><ul class=\"examples\"><li><em>The Food Ministry is attached to the Ministry of Agriculture.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <span class=\"gram\">[transitive]</span> to connect a document or file to an email so that you can send them together → attachment</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>attach yourself to somebody</strong> to join someone and spend a lot of time with them, often without being invited or welcome:</div><ul class=\"examples\"><li><em>A young man from Canada had attached himself to Sam.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>attach a condition (to something)</strong> to allow something to happen, but only if someone agrees to do a particular thing or accept a particular idea:</div><ul class=\"examples\"><li><em>When approving a merger, the commission can attach conditions.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>attach a label to somebody/something</strong> to think of or describe someone or something as being a particular thing, especially in a very general way:</div><ul class=\"examples\"><li><em>You can’t really attach a label to this type of art.</em></li></ul></div>","468":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧tach‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈtætʃmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a feeling that you like or love someone or something and that you would be unhappy without them</div><ul class=\"examples\"><li><strong><em>attachment to/for</strong>: a child’s attachment to its mother</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a part that you can put onto a machine to make it do a particular job:</div><ul class=\"examples\"><li><em>The vacuum cleaner has various attachments.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> belief in and loyalty towards a particular idea, organization etc</div><ul class=\"examples\"><li><strong><em>attachment to/for</strong>: old people’s attachment to traditional customs</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> a document or file that is sent with an email message:</div><ul class=\"examples\"><li><em>I’ll send the spreadsheet as an attachment.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable, uncountable]</span> when you fasten or connect one thing to another, or the thing that you use to do this:</div><ul class=\"examples\"><li><em>Hooks were fixed to the wall for the attachment of the ropes.</em></li><li><em>the attachments that secure your boots firmly to the skis</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>on attachment</strong> working for a particular organization, especially for a short period of time:</div><ul class=\"examples\"><li><em>He was sent on attachment to their offices in Hong Kong.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <span class=\"gram\">[countable, uncountable]</span> <em>law</em> a situation in which part of the money someone earns or money that is owed to them is taken by a court of law and used to pay their debts</div><div class=\"sense\"><span class=\"snum\">8</span> <span class=\"gram\">[countable]</span> <em>technical</em> a piece of paper fastened to a document such as an insurance agreement, which shows a special condition of the agreement</div></div>","469":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧tack</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈtæk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[violence against somebody/something]</strong> <span class=\"gram\">[countable]</span> an act of violence that is intended to hurt a person or damage a place</div><ul class=\"examples\"><li><strong><em>attack on</strong>: There have been several attacks on foreigners recently.</em></li><li><em>a bomb attack</em></li><li><em>a knife attack</em></li><li><em>an arson attack (=an attempt to destroy a building using fire)</em></li><li><em>victims of racial attacks</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[in a war]</strong> <span class=\"gram\">[countable, uncountable]</span> the act of using weapons against an enemy in a war:</div><ul class=\"examples\"><li><em>The attack began at dawn.</em></li><li><strong><em>attack on</strong>: the attack on Pearl Harbor</em></li><li><strong><em>be/come under attack</strong>: Once again we came under attack from enemy fighter planes.</em></li><li><em>Rebel forces launched (=started) an attack late Sunday night.</em></li><li><strong><em>air/missile/nuclear etc attack</strong>: the threat of nuclear attack</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[criticism]</strong> <span class=\"gram\">[countable, uncountable]</span> a strong and direct criticism of someone or something</div><ul class=\"examples\"><li><strong><em>attack on</strong>: The magazine recently published a vicious personal attack on the novelist.</em></li><li><strong><em>be/come under attack</strong> (=be strongly criticized): The company has come under fierce attack for its decision to close the factory.</em></li><li><strong><em>go on the attack</strong> (=start to criticize someone severely)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[illness]</strong> <span class=\"gram\">[countable]</span> a sudden short period of suffering from an illness, especially an illness that you have often → heart attack</div><ul class=\"examples\"><li><strong><em>attack of</strong>: I had a bad attack of flu at Christmas.</em></li><li><em>He died after suffering a severe asthma attack.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[emotion]</strong> <span class=\"gram\">[countable]</span> a short period of time when you suddenly feel extremely frightened or worried and cannot think normally or deal with the situation</div><ul class=\"examples\"><li><strong><em>panic/anxiety attack</strong>: Her heart began to pound frantically, as if she were having a panic attack.</em></li><li><strong><em>attack of</strong>: a sudden attack of nerves</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[attempt to stop something]</strong> <span class=\"gram\">[countable, uncountable]</span> actions that are intended to get rid of or stop something such as a system, a set of laws etc</div><ul class=\"examples\"><li><strong><em>attack on</strong>: The new measures were seen by many as an attack on the Scottish way of life.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[sport]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[countable, uncountable]</span> an attempt by a player or group of players to score goals or win points</div><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[singular]</span> <em>British English</em> the players in a team that are responsible for trying to score goals or win points SYN offense<em>American English</em> → defence</div><ul class=\"examples\"><li><strong><em>in attack</strong>: Heath will play alongside Smith in attack.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[damage]</strong> <span class=\"gram\">[countable, uncountable]</span> when something such as a disease, insect, or chemical damages something:</div><ul class=\"examples\"><li><em>Unfortunately, the carved ceilings have suffered woodworm attack over the years.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[use violence]</strong> <span class=\"gram\">[intransitive, transitive]</span> to deliberately use violence to hurt a person or damage a place:</div><ul class=\"examples\"><li><em>She was attacked while walking home late at night.</em></li><li><em>His shop was attacked by a gang of youths.</em></li><li><em>Snakes will only attack if you disturb them.</em></li><li><strong><em>attack somebody/something with something</strong>: He needed 200 stitches after being attacked with a broken bottle.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[in a war]</strong> <span class=\"gram\">[intransitive, transitive]</span> to start using guns, bombs etc against an enemy in a war:</div><ul class=\"examples\"><li><em>Army tanks attacked a village near the capital on Sunday.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[criticize]</strong> <span class=\"gram\">[transitive]</span> to criticize someone or something very strongly: ► see thesaurus at criticize</div><ul class=\"examples\"><li><em>Last year Dr Travis publicly attacked the idea that abortion should be available on demand.</em></li><li><strong><em>attack somebody for (doing) something</strong>: Newspapers attacked the government for failing to cut taxes.</em></li><li><strong><em>strongly/bitterly/savagely etc attack somebody/something</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[damage]</strong> <span class=\"gram\">[transitive]</span> if something such as a disease, insect, or chemical attacks something, it damages it:</div><ul class=\"examples\"><li><em>a cruel disease that attacks the brain and nervous system</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[begin doing]</strong> <span class=\"gram\">[transitive]</span> to begin to do something in a determined and eager way:</div><ul class=\"examples\"><li><em>She immediately set about attacking the problem.</em></li><li><em>Martin attacked his meal (=started eating) with vigour.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[sport]</strong> <span class=\"gram\">[intransitive, transitive]</span> to move forward and try to score goals or win points → defend:</div><ul class=\"examples\"><li><em>Brazil began to attack more in the second half of the match.</em></li></ul></div></div>","470":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧tack‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈtækə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a person who deliberately uses violence to hurt someone:</div><ul class=\"examples\"><li><em>Her attacker then dragged her into the bushes.</em></li><li><em>a sex attacker</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a member of a sports team whose job is to move forward and try to score goals or win points → defender</div></div>","471":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧tain</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈteɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to succeed in achieving something after trying for a long time:</div><ul class=\"examples\"><li><em>More women are attaining positions of power.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to reach a particular level, age, size etc:</div><ul class=\"examples\"><li><em>Share prices attained a high of $3.27.</em></li><li><em>After a year she had attained her ideal weight.</em></li></ul></div>","472":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧tain‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈteɪnmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> success in achieving something or reaching a particular level <em>SYN achievement</em>:</div><ul class=\"examples\"><li><em>a low level of educational attainment</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> something that you have succeeded in achieving or learning, such as a skill <em>SYN achievement</em>:</div><ul class=\"examples\"><li><em>a society remarkable for its cultural attainments</em></li></ul></div>","473":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧tempt</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈtempt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an act of trying to do something, especially something difficult</div><ul class=\"examples\"><li><strong><em>attempt to do something</strong>: All attempts to control inflation have failed.</em></li><li><strong><em>attempt at (doing) something</strong>: her feeble attempts at humour</em></li><li><strong><em>at the first/second etc attempt</strong>: She passed her driving test at the first attempt.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>make no attempt to do something</strong> to not try to do something at all:</div><ul class=\"examples\"><li><em>He made no attempt to hide his anger.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>an attempt on somebody’s life</strong> an occasion when someone tries to kill a famous or important person:</div><ul class=\"examples\"><li><em>She has already survived two attempts on her life.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to try to do something, especially something difficult ► see thesaurus at try</div><ul class=\"examples\"><li><strong><em>attempt to do something</strong>: In this chapter I will attempt to explain what led up to the revolution.</em></li><li><strong><em>attempt something</strong>: Weather conditions prevented them from attempting the jump.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>attempted murder/suicide/rape etc</strong> an act of trying to kill or harm someone, kill yourself etc:</div><ul class=\"examples\"><li><em>He pleaded guilty to attempted murder.</em></li></ul></div></div>","474":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧tend</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈtend/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to go to an event such as a meeting or a class: RegisterIn everyday English, people usually say go (to) or come (to) instead of attend:· I didn’t go to the parents’ meeting.· Please let us know if you can’t come.</div><ul class=\"examples\"><li><em>Only 12 people attended the meeting.</em></li><li><em>Please let us know if you are unable to attend.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to go regularly to a school, church etc:</div><ul class=\"examples\"><li><em>I am the first child in my family to attend college.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> <em>formal</em> to happen or exist at the same time as something:</div><ul class=\"examples\"><li><em>the peculiar atmosphere which attends such an event</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> to look after someone, especially because they are ill: GRAMMAR Attend is often passive in this meaning.</div><ul class=\"examples\"><li><em>On his deathbed the General was attended by several doctors.</em></li></ul></div>","475":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧tend‧ance</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈtendəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the number of people who attend a game, concert, meeting etc:</div><ul class=\"examples\"><li><em>We have an average attendance of 4,000 fans per game.</em></li><li><em>Last year’s fair saw attendance figures of 32,000.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> when someone goes to a meeting, class etc, or an occasion when they go</div><ul class=\"examples\"><li><strong><em>attendance at</strong>: Most courses involve an average of eight hours&#x27; attendance at college each week.</em></li><li><em>The doctor will have a record of her attendances.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be in attendance (at something)</strong> <em>formal</em> to be at a special or important event:</div><ul class=\"examples\"><li><em>Over 2,000 people were in attendance at yesterday’s demonstration.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be in attendance on somebody</strong> <em>formal</em> to look after someone or serve them</div></div>","476":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧ten‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈtenʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[listen/look/think carefully]</strong> <span class=\"gram\">[uncountable]</span> when you carefully listen to, look at, or think about someone or something:</div><ul class=\"examples\"><li><em>My attention wasn’t really on the game.</em></li><li><em>She tried to pay attention to what he was saying.</em></li><li><em>If you paid more attention in class, you might actually learn something!</em></li><li><em>Scott sat down at his desk and turned his attention to the file he had in front of him.</em></li><li><em>As a society we need to give more attention to the needs of older people.</em></li><li><em>Now he’s gone, I can give you my undivided attention.</em></li><li><em>This game is fun and is sure to keep the attention of any young student.</em></li><li><em>They listened to the speech with close attention.</em></li><li><em>Attention to detail is essential in this job.</em></li><li><em>During the lecture Sarah’s attention began to wander.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[interest]</strong> <span class=\"gram\">[plural, uncountable]</span> the interest that people show in someone or something:</div><ul class=\"examples\"><li><em>She was flattered by all the attention he was giving her.</em></li><li><strong><em>attract/receive/enjoy attention</strong>: a player who quickly attracted the attention of several clubs / The exhibition received little attention in the press.</em></li><li><strong><em>public/media/press attention</strong>: Her case attracted a great deal of media attention.</em></li><li><strong><em>hold/keep somebody’s attention</strong> (=make someone stay interested and keep reading, listening, watching etc): The book holds the reader’s attention right to the very end.</em></li><li><em>Rob loves being the centre of attention (=the person who everyone is interested in, listens to etc).</em></li><li><em>She spent a lot of time trying to avoid the attentions (=romantic interest) of her boss.</em></li><li><em>The man then turned his attentions to (=became romantically interested in) her sister.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[notice]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <strong>attract/catch/get somebody’s attention</strong> to make someone notice you, especially because you want to speak to them or you need their help:</div><ul class=\"examples\"><li><em>She waved to attract the attention of the waitress.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>get attention</strong> to make someone notice you and be interested in what you are doing:</div><ul class=\"examples\"><li><em>Children often misbehave in order to get attention.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> <strong>draw/call attention to something</strong> (also focus attention on something) to make people notice and be concerned or think about something:</div><ul class=\"examples\"><li><em>The purpose of the article was to draw attention to the problems faced by single parents.</em></li><li><em>We wanted to focus public attention on this matter.</em></li><li><em>He left quietly to avoid drawing attention to himself.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">d)</span> <strong>divert/distract/draw attention from something</strong> to make people stop being concerned about something such as a social problem:</div><ul class=\"examples\"><li><em>All this talk of war is just an attempt to draw attention away from the serious economic problems that face our country.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">e)</span> <strong>bring something to somebody’s attention</strong> to tell someone, especially someone in authority, about something such as a problem:</div><ul class=\"examples\"><li><em>The matter was first brought to my attention earlier this year.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">f)</span> <strong>come to somebody’s attention</strong> if something such as a problem comes to the attention of someone in authority, they find out about it:</div><ul class=\"examples\"><li><em>It came to my attention that Jenny was claiming overtime pay for hours she had not worked.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">g)</span> <strong>escape your attention</strong> if something escaped your attention, you did not notice it:</div><ul class=\"examples\"><li><em>This fact had not escaped the attention of the authorities.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[repair/cleaning]</strong> <span class=\"gram\">[uncountable]</span> something you do to repair or clean something:</div><ul class=\"examples\"><li><em>The bike’s in fairly good condition, but the gears need a bit of attention.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[care]</strong> <span class=\"gram\">[uncountable]</span> things that you do to help or to take care of someone or something:</div><ul class=\"examples\"><li><em>Pets need a lot of care and attention.</em></li><li><em>Anyone who comes into contact with these chemicals should seek urgent medical attention.</em></li><li><em>Your plants look like they could do with a bit of attention.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>stand to/at attention</strong> if soldiers stand to attention, they stand up straight in neat lines</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>attention!</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to ask people to listen to important information that is being announced, especially on a loudspeaker (=piece of equipment used to make sounds louder):</div><ul class=\"examples\"><li><em>Attention, please! Could passenger Marie Thomas please proceed to Gate 25 immediately.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used when ordering a group of soldiers to stand up straight in neat lines</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>for the attention of somebody</strong> used on the front of an official letter when you want a particular person to read it or deal with it:</div><ul class=\"examples\"><li><em>Letters should be marked ‘for the attention of Joe Benson’.</em></li></ul></div>","477":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧tic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈætɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a space or room just below the roof of a house, often used for storing things:</div><ul class=\"examples\"><li><em>a small attic room</em></li></ul></div>","478":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧ti‧tude</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈætɪtjuːd $ -tuːd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the opinions and feelings that you usually have about something, especially when this is shown in your behaviour:</div><ul class=\"examples\"><li><em>As soon as they found out I was a doctor, their whole attitude changed.</em></li><li><strong><em>attitude to/towards</strong>: The people have a very positive attitude to life.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> <em>informal</em> a style of dressing, behaving etc that shows you have the confidence to do unusual and exciting things without caring what other people think</div><ul class=\"examples\"><li><strong><em>with attitude</strong>: a coat with attitude</em></li></ul></div>","479":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧tor‧ney</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈtɜːni $ -ɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a lawyer</div></div>","480":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧tract</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈtrækt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make someone interested in something, or make them want to take part in something</div><ul class=\"examples\"><li><strong><em>attract somebody to something</strong>: What attracted me most to the job was the chance to travel.</em></li><li><strong><em>attract attention/interest etc</strong>: The story has attracted a lot of interest from the media.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be attracted to somebody</strong> to feel that you like someone and want to have a sexual relationship with them:</div><ul class=\"examples\"><li><em>I’m not usually attracted to blondes.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to make someone like or admire something or feel romantically interested in someone:</div><ul class=\"examples\"><li><em>I guess it was his eyes that attracted me first.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> to make someone or something move towards another thing:</div><ul class=\"examples\"><li><em>Leftover food attracts flies.</em></li><li><em>low rents designed to attract new businesses to the area</em></li></ul></div>","481":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧trac‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈtrækʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a feeling of liking someone, especially in a sexual way:</div><ul class=\"examples\"><li><em>The attraction between them was almost immediate.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> something interesting or enjoyable to see or do:</div><ul class=\"examples\"><li><em>The beautiful beaches are the island’s main attraction (=most popular place, activity etc).</em></li><li><strong><em>tourist attraction</strong> (=a place that many tourists visit)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> a feature or quality that makes something seem interesting or enjoyable</div><ul class=\"examples\"><li><strong><em>attraction of</strong>: Being your own boss is one of the attractions of owning your own business.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable, uncountable]</span> <em>technical</em> a force which makes things move together or stay together:</div><ul class=\"examples\"><li><em>the gravitational attraction between the Earth and the Moon</em></li></ul></div>","482":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧trac‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈtræktɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who is attractive is good looking, especially in a way that makes you sexually interested in them: ► see thesaurus at beautiful</div><ul class=\"examples\"><li><em>an attractive young woman</em></li><li><em>Women seem to find him attractive.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> pleasant to look at:</div><ul class=\"examples\"><li><em>Kitchen utensils should be attractive as well as functional.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> having qualities that make you want to accept something or be involved in it ► see thesaurus at good</div><ul class=\"examples\"><li><strong><em>attractive to</strong>: a political movement that is attractive to young people</em></li><li><strong><em>attractive offer/proposition/package etc</strong>: I must say, it’s a very attractive offer.</em></li></ul></div>","483":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧tri‧bute</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈtrɪbjuːt $ -bjət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">attribute at‧tri‧bute 1 / əˈtrɪbjuːt $ -bjət / ●○○ AWL verb Word Origin Verb Table Examples Thesaurus Collocations attribute something to somebody/something phrasal verb 1 to believe or say that a situation or event is caused by something: The fall in the number of deaths from heart disease is generally attributed to improvements in diet. 2 if people in general attribute a particular statement, painting, piece of music etc to someone, they believe that person said it, painted it etc: a saying usually attributed to Confucius 3 to believe or say that someone or something has a particular quality: One should not attribute human motives to animals. — attribution / ˌætrəˈbjuːʃ ə n / noun [uncountable]</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> at‧tri‧bute</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈætrəbjuːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a quality or feature, especially one that is considered to be good or useful:</div><ul class=\"examples\"><li><em>What attributes should a good manager possess?</em></li></ul></div></div>","484":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧typ‧i‧cal</span><span class=\"meta-item\"><strong>IPA:</strong> /eɪˈtɪpɪkəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">not typical or usual</div></div>","485":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> auc‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɔːkʃən $ ˈɒːk-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a public meeting where land, buildings, paintings etc are sold to the person who offers the most money for them</div><ul class=\"examples\"><li><strong><em>at auction</strong>: The house was sold at auction.</em></li><li><strong><em>put something up for auction</strong> (=try to sell something at an auction): This week 14 of his paintings were put up for auction.</em></li><li><strong><em>auction house</strong> (=a company that arranges auctions)</em></li></ul></div>","486":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> au‧di‧ence</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɔːdiəns $ ˈɒː-, ˈɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a group of people who come to watch and listen to someone speaking or performing in public:</div><ul class=\"examples\"><li><em>The audience began clapping and cheering.</em></li><li><strong><em>audience of</strong>: an audience of 250 business people</em></li><li><em>One member of the audience described the opera as ‘boring’.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable also + plural verb]</span> <em>British English</em> the people who watch or listen to a particular programme, or who see or hear a particular artist’s, writer’s etc work:</div><ul class=\"examples\"><li><em>The show attracts a regular audience of about 20 million.</em></li><li><strong><em>target audience</strong> (=the type of people that a programme, advertisement etc is supposed to attract)</em></li><li><em>Goya was one of the first painters to look for a wider audience for his work.</em></li><li><em>The book is not intended for a purely academic audience.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a formal meeting with a very important person</div><ul class=\"examples\"><li><strong><em>audience with</strong>: He was granted an audience with the Pope.</em></li></ul></div>","487":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> au‧di‧to‧ri‧um</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɔːdəˈtɔːriəm $ ˌɒː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural auditoriums or auditoria /-riə/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the part of a theatre where people sit when watching a play, concert etc</div><div class=\"sense\"><span class=\"snum\">2</span> <em>American English</em> a large building used for concerts or public meetings</div></div>","488":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> aug‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ɔːɡˈment $ ɒːɡ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>formal</em> to increase the value, amount, effectiveness etc of something:</div><ul class=\"examples\"><li><em>Any surplus was sold to augment their income.</em></li></ul></div>","489":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> Au‧gust</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɔːɡəst $ ˈɒː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the eighth month of the year, between July and September</div><ul class=\"examples\"><li><strong><em>next/last August</strong>: I was there last August.</em></li><li><strong><em>in August</strong>: My birthday’s in August.</em></li><li><strong><em>on August 6th</strong>: The new store opened on August 6th.</em></li><li><strong><em>on 6th August<em>British English</em></strong>: He arrived at Berwick on 6th August 1823.</em></li><li><strong><em>August 6<em>American English</em></strong>: We’ll expect you to call August 6.</em></li></ul></div>","490":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ɑːnt $ ænt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the sister of your father or mother, or the wife of your father’s or mother’s brother:</div><ul class=\"examples\"><li><em>Aunt Mary</em></li></ul></div>","491":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> au‧ra</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɔːrə/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a quality or feeling that seems to surround or come from a person or a place</div><ul class=\"examples\"><li><strong><em>aura of</strong>: The building retains an aura of mystery.</em></li></ul></div>","492":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> aus‧tere</span><span class=\"meta-item\"><strong>IPA:</strong> /ɔːˈstɪə, ɒ- $ ɒːˈstɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> plain and simple and without any decoration:</div><ul class=\"examples\"><li><em>the church’s austere simplicity</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who is austere is very strict and serious – used to show disapproval:</div><ul class=\"examples\"><li><em>Her father is a very austere man.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> an austere way of life is very simple and has few things to make it comfortable or enjoyable:</div><ul class=\"examples\"><li><em>Cuthbert led an austere life of prayer and solitude.</em></li></ul></div>","493":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> au‧then‧tic</span><span class=\"meta-item\"><strong>IPA:</strong> /ɔːˈθentɪk $ ɒː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> done or made in the traditional or original way <em>SYN genuine</em>: ► see thesaurus at genuine</div><ul class=\"examples\"><li><em>authentic French food</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a painting, document, book etc that is authentic has been proved to be by a particular person <em>SYN genuine</em>: RegisterIn everyday English, people usually say that something is real or the real thing rather than authentic:· This is real Indian cooking.· How do you know if the picture is the real thing?</div><ul class=\"examples\"><li><em>an authentic work by Picasso</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> based on facts:</div><ul class=\"examples\"><li><em>an authentic account</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used to describe a copy that is the same as, or as good as, the original:</div><ul class=\"examples\"><li><em>Actors dressed in authentic costumes re-enact the battle.</em></li></ul></div>","494":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> au‧thor</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɔːθə $ ˈɒːθər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who has written a book <em>SYN writer</em>:</div><ul class=\"examples\"><li><em>Nothomb is a Belgian author.</em></li><li><strong><em>author of</strong>: He was the author of two books on China.</em></li><li><em>It’s clear that the author is a woman.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> the person who starts a plan or idea <em>SYN initiator</em></div><ul class=\"examples\"><li><strong><em>author of</strong>: the author of the state reforms</em></li></ul></div>","495":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> au‧thor‧i‧tar‧i‧an</span><span class=\"meta-item\"><strong>IPA:</strong> /ɔːˌθɒrəˈteəriən◂ $ ɒːˌθɑːrəˈter-, əˌθɔː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">strictly forcing people to obey a set of rules or laws, especially ones that are wrong or unfair: ► see thesaurus at strict</div><ul class=\"examples\"><li><em>an authoritarian government</em></li><li><em>Critics claim his management has become too authoritarian.</em></li></ul></div>","496":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> au‧thor‧i‧ta‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ɔːˈθɒrətətɪv, ə- $ ɒːˈθɑːrəteɪtɪv, əˈθɔː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an authoritative book, account etc is respected because the person who wrote it knows a lot about the subject:</div><ul class=\"examples\"><li><em>the most authoritative work on English surnames</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> behaving or speaking in a confident determined way that makes people respect and obey you:</div><ul class=\"examples\"><li><em>He has a commanding presence and an authoritative voice.</em></li></ul></div>","497":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> au‧thor‧i‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ɔːˈθɒrəti, ə- $ ɒːˈθɑː-, əˈθɔː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W1 AWL</span><span class=\"meta-item\">(plural authorities)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[power]</strong> <span class=\"gram\">[uncountable]</span> the power you have because of your official position</div><ul class=\"examples\"><li><strong><em>the authority to do something</strong>: Only the president has the authority to declare war.</em></li><li><strong><em>authority over</strong>: Several countries claim authority over the islands.</em></li><li><strong><em>in authority</strong>: I need to speak to someone in authority (=who has a position of power).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the authorities</strong> <span class=\"gram\">[plural]</span> the people or organizations that are in charge of a particular country or area:</div><ul class=\"examples\"><li><em>an agreement between the US and Colombian authorities</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[organization]</strong> <span class=\"gram\">[countable]</span> an official organization or a government department that has the power to make decisions, and has particular responsibilities:</div><ul class=\"examples\"><li><em>the local authority</em></li><li><em>East Sussex Education Authority</em></li><li><em>the San Diego Water Authority</em></li><li><em>Welsh health authorities face a £13m deficit this year.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[expert]</strong> <span class=\"gram\">[countable]</span> someone who knows a lot about a subject and whose knowledge and opinions are greatly respected ► see thesaurus at expert</div><ul class=\"examples\"><li><strong><em>authority on</strong>: Mr Li is a leading authority on Chinese food.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[permission]</strong> <span class=\"gram\">[countable, uncountable]</span> official permission to do something</div><ul class=\"examples\"><li><strong><em>under the authority of somebody</strong>: The attack took place under the authority of the UN Security Council.</em></li><li><strong><em>without somebody’s authority</strong>: No one may enter without my authority.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>authority figure</strong> someone who has a position of power, especially because of their job:</div><ul class=\"examples\"><li><em>teenage rebellion against authority figures</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[personal quality]</strong> <span class=\"gram\">[uncountable]</span> a quality in the way you speak or behave which makes people obey you:</div><ul class=\"examples\"><li><em>Jack’s air of quiet authority</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>I have it on good authority</strong> used to say that you are sure that something is true because you trust the person who told you about it</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>speak with authority</strong> to be sure of what you are saying, because of your knowledge or experience</div></div>","498":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> au‧thor‧i‧za‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɔːθəraɪˈzeɪʃən $ ˌɒːθərə-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">official permission to do something, or the document giving this permission <em>SYN authority</em>:</div><ul class=\"examples\"><li><em>You need special authorization to park here.</em></li><li><em>Children may not leave the building without the authorization of the principal.</em></li></ul></div>","499":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> au‧thor‧ize</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɔːθəraɪz $ ˈɒː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to give official permission for something: ► see thesaurus at allow</div><ul class=\"examples\"><li><em>an authorized biography</em></li><li><strong><em>authorize somebody to do something</strong>: Napoleon III authorized Haussmann to rebuild Paris.</em></li></ul></div>","500":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> au‧to‧bi‧og‧ra‧phy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɔːtəbaɪˈɒɡrəfi $ ˌɒːtəbaɪˈɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(plural autobiographies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[countable, uncountable]</span> a book in which someone writes about their own life, or books of this type → biography ► see thesaurus at book</div></div>","501":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> au‧to‧mat‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɔːtəˈmætɪk◂ $ ˌɒː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an automatic machine is designed to work without needing someone to operate it for each part of a process → manual:</div><ul class=\"examples\"><li><em>an automatic weapon</em></li><li><em>an automatic gearbox</em></li><li><em>My camera is fully automatic.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> something that is automatic always happens as a result of something you have done, especially because of a rule or law:</div><ul class=\"examples\"><li><em>Littering results in an automatic fine.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> done without thinking, especially because you have done the same thing many times before:</div><ul class=\"examples\"><li><em>Practise the breathing techniques until they become automatic.</em></li></ul></div>","502":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> au‧to‧mat‧i‧cally</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɔːtəˈmætɪkli $ ˌɒː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> as the result of a situation or action, and without you having to do anything more:</div><ul class=\"examples\"><li><em>Join now and you will automatically receive 50% off your first purchase.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> without thinking about what you are doing:</div><ul class=\"examples\"><li><em>Of course I automatically said yes.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> by the action of a machine, without a person making it work:</div><ul class=\"examples\"><li><em>The doors opened automatically as we approached.</em></li></ul></div>","503":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> au‧to‧mo‧bile</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɔːtəməbiːl $ ˈɒːtəmoʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>American English</em> a car:</div><ul class=\"examples\"><li><em>the automobile industry</em></li></ul></div>","504":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> au‧ton‧o‧mous</span><span class=\"meta-item\"><strong>IPA:</strong> /ɔːˈtɒnəməs $ ɒːˈtɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an autonomous place or organization is free to govern or control itself <em>SYN independent</em></div><ul class=\"examples\"><li><strong><em>an autonomous region/state/republic etc</strong>: Galicia is an autonomous region of Spain.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> having the ability to work and make decisions by yourself without any help from anyone else <em>SYN independent</em></div></div>","505":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> au‧ton‧o‧my</span><span class=\"meta-item\"><strong>IPA:</strong> /ɔːˈtɒnəmi $ ɒːˈtɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> freedom that a place or an organization has to govern or control itself <em>SYN independence</em>:</div><ul class=\"examples\"><li><em>campaigners who want greater autonomy for Corsica</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the ability or opportunity to make your own decisions without being controlled by anyone else <em>SYN independence</em>:</div><ul class=\"examples\"><li><em>Teachers are given considerable individual autonomy.</em></li></ul></div>","506":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> au‧tumn</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɔːtəm $ ˈɒː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the season between summer and winter, when leaves change colour and the weather becomes cooler:</div><ul class=\"examples\"><li><em>autumn mists</em></li></ul></div>","507":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧vail‧a‧bil‧i‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /əˌveɪləˈbɪləti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the state of being able to be used, bought, or found</div><ul class=\"examples\"><li><strong><em>availability of</strong>: the availability of affordable housing</em></li><li><em>Rooms are offered subject to availability (=only if they are available).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the state of being able to do something because you have enough time:</div><ul class=\"examples\"><li><em>He has been asked about his availability to take part in the competition.</em></li></ul></div>","508":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧vail‧a‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈveɪləbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something that is available is able to be used or can easily be bought or found: RegisterIn everyday English, people usually say that a book, record etc is out rather than available:· His new album is out now.</div><ul class=\"examples\"><li><em>Tickets are available from the box office.</em></li><li><strong><em>available to</strong>: Not enough data is available to scientists.</em></li><li><strong><em>available to do something</strong>: Funds are available to assist teachers who want to attend the conference.</em></li><li><strong><em>available for</strong>: No figures are available for the number of goods sold.</em></li><li><strong><em>available in</strong>: There are plenty of jobs available in the area.</em></li><li><strong><em>readily/widely available</strong> (=very easy to obtain): Parking is readily available near the station entrance.</em></li><li><em>Meetings were held to update employees as soon as new information became available.</em></li><li><em>Further building can continue when money is made available.</em></li><li><em>Every available space on the wall was covered in pictures.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[not before noun]</span> someone who is available is not busy and has enough time to talk to you:</div><ul class=\"examples\"><li><em>Collins was not available for comment on Thursday night.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> someone who is available does not have a wife, boyfriend etc, and therefore may want to start a new romantic relationship with someone else</div></div>","509":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> av‧a‧lanche</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈævəlɑːntʃ $ -læntʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a large mass of snow, ice, and rocks that falls down the side of a mountain:</div><ul class=\"examples\"><li><em>Two skiers were killed in the avalanche.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>an avalanche of something</strong> a very large number of things such as letters, messages etc that arrive suddenly at the same time:</div><ul class=\"examples\"><li><em>The school received an avalanche of applications.</em></li></ul></div>","510":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> av‧e‧nue</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈævənjuː $ -nuː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>Avenue</strong> used in the names of streets in a town or city:</div><ul class=\"examples\"><li><em>Fifth Avenue</em></li><li><em>Shaftesbury Avenue</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a possible way of achieving something:</div><ul class=\"examples\"><li><em>The president wants to explore every avenue towards peace in the region.</em></li><li><em>There are many avenues open to researchers.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>British English</em> a road or broad path between two rows of trees, especially one leading to a big house:</div><ul class=\"examples\"><li><em>a tree-lined avenue</em></li></ul></div>","511":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> av‧e‧rage</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈævərɪdʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the average amount is the amount you get when you add together several quantities and divide this by the total number of quantities:</div><ul class=\"examples\"><li><em>The age of the candidates ranged from 29 to 49 with an average age of 37.</em></li><li><em>The average cost of making a movie has risen by 15%.</em></li><li><em>Last winter was colder than average.</em></li><li><em>The cars were being sold at an average price of $11,000.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an average amount or quantity is not unusually big or small:</div><ul class=\"examples\"><li><em>They have an average-size front garden and a large rear garden.</em></li><li><strong><em>of average height/build/intelligence etc</strong>: He was in his late twenties and of average height.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> having qualities that are typical of most people or things: ► see thesaurus at normal</div><ul class=\"examples\"><li><em>The average American has not even thought about next year’s election.</em></li><li><em>In an average week I drive about 250 miles.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> neither very good nor very bad</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> the amount calculated by adding together several quantities, and then dividing this amount by the total number of quantities</div><ul class=\"examples\"><li><strong><em>average of</strong>: The average of 3, 8, and 10 is 7. / Each person raised an average of £60 to plant an acre of trees.</em></li><li><em>The December figures brought the annual average for 2001 up to 10.6 per cent.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>on average</strong> based on a calculation about how many times something usually happens, how much money someone usually gets, how often people usually do something etc:</div><ul class=\"examples\"><li><em>On average, men still earn more than women.</em></li><li><em>Nearly 80% of Swiss citizens on average turn out to vote.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> the usual level or amount for most people or things:</div><ul class=\"examples\"><li><em>Streets in the town centre are wider than the average.</em></li><li><strong><em>above/below average</strong>: The school’s eighth-graders are above average in science.</em></li><li><em>The murder rate in the city has risen to four times the national average.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[linking verb]</span> to usually do something or usually happen a particular number of times, or to usually be a particular size or amount:</div><ul class=\"examples\"><li><em>The water in the lake is not particularly deep, averaging about 12 metres.</em></li><li><em>The airport averages about a thousand flights a month.</em></li><li><em>Inflation averaged just under 2.8% per year.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to calculate the average of figures:</div><ul class=\"examples\"><li><em>The rate of growth was averaged over a period of three years.</em></li></ul></div></div>","512":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧vert</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈvɜːt $ -ɜːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to prevent something unpleasant from happening:</div><ul class=\"examples\"><li><em>The tragedy could have been averted if the crew had followed safety procedures.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>avert your eyes/gaze etc</strong> to look away from something so that you do not see it:</div><ul class=\"examples\"><li><em>Henry averted his eyes as she undressed.</em></li></ul></div>","513":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧void</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈvɔɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to prevent something bad from happening:</div><ul class=\"examples\"><li><em>Road safety is taught to young children to avoid road accidents.</em></li><li><em>It is important to take measures to avoid the risk of fire.</em></li><li><strong><em>avoid doing something</strong>: The refugees left to avoid getting bombed.</em></li><li><em>Alan narrowly avoided an accident.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to stay away from someone or something, or not use something:</div><ul class=\"examples\"><li><em>Everyone seemed to be avoiding Nick.</em></li><li><em>She carefully avoided his eyes (=did not look directly at his face).</em></li><li><em>Pregnant women should avoid certain foods such as raw eggs.</em></li><li><em>Why did you speak to him? You usually avoid him like the plague (=try hard to avoid him).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to deliberately not do something, especially something wrong, dangerous, or harmful:</div><ul class=\"examples\"><li><em>There are ways of legally avoiding taxes.</em></li><li><strong><em>avoid doing something</strong>: You should avoid over-spending in the first half of the year.</em></li></ul></div>","514":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧wait</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈweɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to wait for something: ► see thesaurus at wait</div><ul class=\"examples\"><li><em>Several men are awaiting trial for robbery.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if a situation, event etc awaits you, it is going to happen in the future:</div><ul class=\"examples\"><li><em>A terrible surprise awaited them at Mr Tumnus’ house.</em></li></ul></div>","515":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧wake</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈweɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[not before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not sleeping:</div><ul class=\"examples\"><li><em>I hope he’s awake now.</em></li><li><em>She was still only half awake when I brought her a cup of coffee.</em></li><li><em>How do you stay awake during boring lectures?</em></li><li><em>Emma lay awake half the night, worrying.</em></li><li><em>The noise brought him wide awake (=completely awake).</em></li><li><em>To keep themselves awake (=stop themselves from going to sleep) they sat on the floor and told each other stories.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be awake to something</strong> to understand a situation and its possible effects <em>SYN be aware of something</em>:</div><ul class=\"examples\"><li><em>Too few people are awake to the dangers of noise pollution.</em></li></ul></div>","516":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧wak‧en</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈweɪkən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to wake up or to make someone wake up: RegisterIn everyday English, people usually use wake up rather than awaken:· She was woken up by the phone ringing.</div><ul class=\"examples\"><li><em>She was awakened by a noise at two in the morning.</em></li><li><em>Bill slept a little until he was awakened to take his turn on guard.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> if something awakens an emotion, interest, memory etc it makes you suddenly begin to feel that emotion etc:</div><ul class=\"examples\"><li><em>Early involvement in music can awaken an interest that will last a lifetime.</em></li></ul></div>","517":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧ward</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈwɔːd $ -ɔːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something such as a prize or money given to someone to reward them for something they have done:</div><ul class=\"examples\"><li><em>The movie has won a number of awards.</em></li><li><em>an award-winning restaurant</em></li><li><strong><em>award for</strong>: the award for best student</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> something, especially money, that is officially given to someone as a payment or after a legal decision:</div><ul class=\"examples\"><li><em>the teachers’ pay award</em></li><li><em>an award for unfair dismissal</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to officially give someone something such as a prize or money to reward them for something they have done: ► see thesaurus at give</div><ul class=\"examples\"><li><em>Moodie has been awarded a golf scholarship at the University of Hawaii.</em></li><li><strong><em>award somebody something</strong>: The judge awarded me first prize.</em></li><li><strong><em>award something to somebody</strong>: A Nobel Prize was awarded to Waksman in 1952.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to officially decide that someone should receive a payment or a formal agreement</div><ul class=\"examples\"><li><strong><em>award somebody something</strong>: The government awarded a German company the contract.</em></li><li><strong><em>award something to somebody</strong>: £45,000 was awarded to a typist with an injured hand.</em></li></ul></div></div>","518":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧ware</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈweə $ əˈwer/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1 AWL</span><span class=\"meta-item\"><span class=\"gram\">[not before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if you are aware that a situation exists, you realize or know that it exists</div><ul class=\"examples\"><li><strong><em>aware of</strong>: The children are aware of the danger of taking drugs.</em></li><li><em>Mr Braley has been made aware of the need for absolute secrecy.</em></li><li><strong><em>aware that</strong>: Were you aware that Joe had this problem with his knee?</em></li><li><strong><em>well/fully/acutely aware</strong>: They were well aware that the company was losing money.</em></li><li><em>As you are aware, a fee will be charged annually.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if you are aware of something, you notice it, especially because you can see, hear, feel, or smell it</div><ul class=\"examples\"><li><strong><em>aware of</strong>: She was aware of a tall dark figure watching her. / He was aware of the wind in his face.</em></li><li><strong><em>aware that</strong>: Bill became aware that he was still holding his glass.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> understanding a lot about what is happening around you and paying attention to it, especially because you realize possible dangers and problems</div><ul class=\"examples\"><li><strong><em>politically/socially/environmentally etc aware</strong>: the socially aware novels of Dickens / We should promote environmentally aware and responsible science.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>so/as far as I am aware</strong> <em>spoken</em> used when you are saying something that you think is true, although you might be wrong because you do not know all the facts:</div><ul class=\"examples\"><li><em>As far as I am aware, they are a happily married couple.</em></li></ul></div>","519":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧ware‧ness</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈweənəs $ əˈwer-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> knowledge or understanding of a particular subject or situation</div><ul class=\"examples\"><li><strong><em>environmental/political/social awareness</em></strong></li><li><em>Health officials have tried to raise awareness (=improve people’s knowledge) about AIDS.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the ability to notice something using your senses</div><ul class=\"examples\"><li><strong><em>awareness of</strong>: an artist’s awareness of light and color</em></li></ul></div>","520":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> a‧way</span><span class=\"meta-item\"><strong>IPA:</strong> /əˈweɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to say that someone leaves a place or person, or stays some distance from a place or person:</div><ul class=\"examples\"><li><em>Go away!</em></li><li><em>Dinah was crying as she drove slowly away.</em></li><li><strong><em>away from</strong>: Stay away from the fire.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> towards a different direction:</div><ul class=\"examples\"><li><em>She turned away and stared out of the window.</em></li><li><em>Charley blushed and looked away, embarrassed.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> if someone is away from school, work, or home, they are not there <em>SYN absent</em>:</div><ul class=\"examples\"><li><em>Simon is away with flu.</em></li><li><em>Kate is away on holiday.</em></li><li><strong><em>away from</strong>: You must bring a note from your parents if you’ve been away from school.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used to say how far it is to a place or thing</div><ul class=\"examples\"><li><strong><em>five miles/ten feet etc away</strong>: Geneva is about 20 miles away.</em></li><li><em>There’s another hotel not far away.</em></li><li><strong><em>away from</strong>: She was sitting ten feet away from the microphone.</em></li><li><strong><em>five minutes/two hours etc away</strong>: The beach is only five minutes away (=it only takes five minutes to get there).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> if an event is two days, three weeks etc away, it will happen after that period of time has passed:</div><ul class=\"examples\"><li><em>Christmas is only a month away.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> used to say how close someone is to achieving something or experiencing something</div><ul class=\"examples\"><li><strong><em>away from</strong>: At one stage, they were just two points away from victory.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> into or in a safe or enclosed place:</div><ul class=\"examples\"><li><em>Put your money away, I’m paying.</em></li><li><em>Thousands of archaeological treasures are being kept hidden away.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> used to show that something disappears or is removed:</div><ul class=\"examples\"><li><em>The music died away.</em></li><li><em>Ruben gave all his money away to charity.</em></li><li><em>Support for the Democrats has dropped away.</em></li><li><em>Cut away all the dead wood.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> used to emphasize that an action continues:</div><ul class=\"examples\"><li><em>Sue was singing away to herself in the bath.</em></li><li><em>They’ve been hammering away all day.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> used to say that someone spends the whole of a period of time doing something:</div><ul class=\"examples\"><li><em>You can dance the night away in one of Benidorm’s many discos.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> if a team is playing away, it is playing a game at its opponent’s field or sports hall <em>OPP at home</em>:</div><ul class=\"examples\"><li><em>Liverpool are playing away at Everton on Saturday.</em></li></ul></div>","521":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ɔː $ ɒː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a feeling of great respect and liking for someone or something:</div><ul class=\"examples\"><li><em>He felt great awe for the landscape.</em></li><li><strong><em>with/in awe</strong>: Kate gazed at the statue with awe.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be/stand in awe of somebody</strong> (also hold somebody in awe) to admire someone and have great respect for them and sometimes a slight fear of them:</div><ul class=\"examples\"><li><em>All of the neighbours were a little in awe of my mother.</em></li><li><em>The villagers hold them in awe and think of them as gods.</em></li></ul></div>","522":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> awe‧some</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɔːsəm $ ˈɒː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> extremely impressive, serious, or difficult so that you feel great respect, worry, or fear:</div><ul class=\"examples\"><li><em>an awesome responsibility</em></li><li><em>the awesome sweep of the scenery</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>especially American English</em> <em>informal</em> very good:</div><ul class=\"examples\"><li><em>Their last concert was really awesome.</em></li></ul></div>","523":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> aw‧ful</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɔːfəl $ ˈɒː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> very bad or unpleasant <em>SYN terrible</em>: ► see thesaurus at bad, horrible</div><ul class=\"examples\"><li><em>The weather was awful.</em></li><li><em>He is a pretty awful driver.</em></li><li><em>That fridge smells awful.</em></li><li><em>The last six months have been awful for her.</em></li><li><em>I’ve stopped believing most of what he says. Isn’t that awful?</em></li><li><em>I’m sure Suzy is dead but the awful thing is not knowing how it happened.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> <em>spoken</em> used to emphasize how much or how good, bad etc something is:</div><ul class=\"examples\"><li><em>An awful lot of people (=a large number of people) died in the war.</em></li><li><em>He made me feel an awful fool.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>look/feel awful</strong> to look or feel ill:</div><ul class=\"examples\"><li><em>She’s lost a lot of weight and she looks awful.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>literary</em> making you feel great respect or fear</div></div>","524":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> awk‧ward</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɔːkwəd $ ˈɒːkwərd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> making you feel embarrassed so that you are not sure what to do or say <em>SYN difficult</em>: ► see thesaurus at embarrassed</div><ul class=\"examples\"><li><em>I hoped he would stop asking awkward questions.</em></li><li><em>There was an awkward moment when she didn’t know whether to shake his hand or kiss his cheek.</em></li><li><em>an awkward silence</em></li><li><em>A laugh can help people over an awkward situation.</em></li><li><em>Philip’s remarks put her in an awkward position (=made it difficult for her to know what to do).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> not relaxed or comfortable:</div><ul class=\"examples\"><li><em>She liked to dance but felt awkward if someone was watching her.</em></li><li><em>Geoff looked uneasy and awkward.</em></li><li><em>Make sure that the baby is not sleeping in an awkward position.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> difficult to do, use, or deal with: ► see thesaurus at difficult</div><ul class=\"examples\"><li><em>It’ll be awkward getting cars in and out.</em></li><li><em>The new financial arrangements were awkward to manage.</em></li><li><em>A good carpenter can make a cupboard to fit the most awkward space.</em></li><li><em>She was afraid he was going to ask an awkward question.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> not convenient:</div><ul class=\"examples\"><li><em>I’m sorry to call at such an awkward time but I won’t keep you a minute.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> an awkward person is deliberately unhelpful <em>SYN difficult</em></div><ul class=\"examples\"><li><strong><em>awkward about</strong>: The staff wanted to go home and they were getting awkward about a meeting starting so late.</em></li><li><em>an awkward customer (=person who is difficult and unhelpful)</em></li></ul></div>","525":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /æks/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a tool with a heavy metal blade on the end of a long handle, used to cut down trees or split pieces of wood → pickaxe</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>the axe</strong> <em>informal</em> if someone gets the axe, they are dismissed from their job:</div><ul class=\"examples\"><li><em>A hundred workers are facing the axe in a cost-cutting exercise.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the axe</strong> <em>informal</em> if a plan, system, or service gets the axe, someone gets rid of it:</div><ul class=\"examples\"><li><em>MPs know there will be cuts in public spending but do not know on which department the axe will fall.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>have an axe to grind</strong> to have a strong personal opinion about something which is the reason why you do something:</div><ul class=\"examples\"><li><em>I need objective advice from someone with no axe to grind.</em></li></ul></div>","526":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ax‧is</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈæksɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural axes /-siːz/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the imaginary line around which a large round object, such as the Earth, turns:</div><ul class=\"examples\"><li><em>The Earth rotates on an axis between the north and south poles.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a line drawn across the middle of a regular shape that divides it into two equal parts</div><div class=\"sense\"><span class=\"snum\">3</span> either of the two lines of a graph, by which the positions of points are measured</div><ul class=\"examples\"><li><strong><em>the vertical/horizontal axis</em></strong></li></ul></div>"};